-- 경기도의회 행정사무감사 회의록(경기연구원 관련) 이관 데이터 (자동 생성: tools/import_audit.py)
-- 게시판 코드 audit. 여러 번 실행해도 중복되지 않습니다.
insert into public.boards (code,name,members_only,admin_only_write) values ('audit','행정사무감사',false,true) on conflict (code) do nothing;
create unique index if not exists posts_legacy_idx on public.posts ((attachments->>'legacy_id')) where attachments ? 'legacy_id';
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2005.11.17. 목요일] 경기개발연구원 — 기획위원회 2005년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제6대 경기도의회 기획위원회</b> · 2005년도 행정사무감사(2005. 11. 17. ~ 2005. 11. 25.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=3297" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2005년도 행정사무감사
</p>
<h4>기획위원회 회의록 
</h4>제 1 호
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일  시 : 2005년 11월 17일(목)
</p>
<p>장  소 : 경기개발연구원회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시21분 감사개시)
</p>
<p><b>○ 위원장 정인영 </b> 좌석을 정돈하여 주시기 바랍니다.  지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조 규정에 의하여 경기개발연구원에 대한 2005년도 행정사무감사를 시작하겠습니다.  
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기개발연구원 부원장을 비롯한 임직원 여러분!  안녕하십니까?  기획위원회 감사위원장 정인영입니다.  오늘은 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다.  여러분께서도 잘 아시는  바와 같이 지방의회의 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2006년도 예산안 심사자료 및 정보획득을 통해 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다 할 수 있습니다.  따라서 감사위원 여러분께서는 도민을 대표하여 도비 출연기관인 경기개발연구원의 운영실태를 감사하는 것인 만큼 심도있는 감사활동으로 소기의 성과를 거둘 수 있게 되기를 기대합니다.  아울러 감사에 임하는 위원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기를 당부드립니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다.  감사를 받는 부원장 및 실ㆍ부장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 합니다.  증인선서의 취지와 관계 규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2005년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 
</p>
<p style="padding-left:1.2em">  만약 증인이 허위증언을 한 때에는 지방자치법 제36조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법규정에 의하여 500만원 이하의 과태료가 부과될 수 있음을 알려드립니다.  그러면 먼저 증인 출석여부를 확인하겠습니다.  피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. 
</p>
<p style="padding-left:2.4em">    (일동기립)
</p>
<p style="padding-left:1.2em">  부원장 나왔습니까?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네. 
</p>
<p><b>○ 위원장 정인영 </b> 기획조정실장 나왔습니까?
</p>
<p><b>○ 기획조정실장 성현찬 </b> 네.
</p>
<p><b>○ 위원장 정인영 </b> 사무처장 나왔습니까?
</p>
<p><b>○ 사무처장 이강수 </b> 네. 
</p>
<p><b>○ 위원장 정인영 </b> 자치행정연구부장 나왔습니까?
</p>
<p><b>○ 자치행정연구부장 이용환 </b> 네.
</p>
<p><b>○ 위원장 정인영 </b> 도시지역계획연구부장 나왔습니까?
</p>
<p><b>○ 도시지역계획연구부장 김제국 </b> 네. 
</p>
<p><b>○ 위원장 정인영 </b> 교통정책연구부장 나왔습니까? 
</p>
<p><b>○ 교통정책연구부장 조응래 </b> 네.
</p>
<p><b>○ 위원장 정인영 </b> 환경정책연구부장 나왔습니까? 
</p>
<p><b>○ 환경정책연구부장 이정임 </b> 네.
</p>
<p><b>○ 위원장 정인영 </b> 경제사회연구부장 나왔습니까? 
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 네.
</p>
<p><b>○ 위원장 정인영 </b> 동북아지역연구부장 나왔습니까? 
</p>
<p><b>○ 동북아지역연구부장 김동성 </b> 네.
</p>
<p><b>○ 위원장 정인영 </b> 다음은 선서요령을 설명드리겠습니다.  선서는 증인을 대표해서 부원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에서 오른손만 들어주시면 되겠습니다.  그러면 선서를 해주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 선서!  본인은 경기도의회가 지방자치법 제36조, 동법시행령 제16조제1항 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 소관업무에 대한 2005년도 행정사무감사를 실시함에 있어서 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법시행령 제17조의4제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제18조의 규정에 의하여 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다.
</p>
<p style="padding-left:1.2em">  2005년 11월 17일 경기개발연구원 부원장 김태승.
</p>
<p><b>○ 위원장 정인영 </b> 앉아 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (일동착석)
</p>
<p style="padding-left:1.2em">  그러면 부원장 나오셔서 간부소개와 업무보고를 해주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 안녕하십니까?  경기개발연구원 부원장 김태승입니다.  원장님의 사고로 제가 업무보고를 대신 드리게 된 점 널리 양해해 주시기 바라며 보고에 앞서 원장님의 불미스러운 일로 위원 여러분께 심려를 끼쳐드려 대단히 죄송합니다.  이번 사태로 저희 임직원들은 심기일전하여 경기도의 싱크탱크로서 거듭나도록 최선의 노력을 다해 나가겠습니다.  다시 한번 사과의 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  오늘 존경하는 정인영 위원장님과 위원님 여러분을 모시고 금년도 주요업무 추진사항과 내년도 연구사업계획을 보고드리게 된 데 대해서 감사의 말씀을 드립니다.  저는 지난 3월 10일자로 부원장에 취임한 이후 현재까지 짧은 기간이었지만 연구원이 신속한 도정지원을 할 수 있도록 임직원들과 함께…….
</p>
<p><b>○ 박영신 위원 </b> 위원장님!  박영신입니다.
</p>
<p><b>○ 위원장 정인영 </b> 네, 의사진행발언입니까?
</p>
<p><b>○ 박영신 위원 </b> 네, 의사진행발언입니다.  2005년도 주요업무보고가 지금 위원님들께 다 배부돼 있죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 박영신 위원 </b> 맨 뒷면에 보면 간부명단이 나와 있습니다.  지금 원장이 있어요, 없어요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 없습니다. 
</p>
<p><b>○ 박영신 위원 </b> 그러면 이 주요업무보고는 누가 작성했어요? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 저희 사무처에서 작성했습니다. 
</p>
<p><b>○ 박영신 위원 </b> 주요업무보고를 다시 수정할 때까지 감사를 중단해 주시기 바랍니다.  여기 보면 원장 한현규로 돼 있는데 한현규 씨가 지금 원장이에요, 아니에요? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 정말 죄송합니다.
</p>
<p><b>○ 박영신 위원 </b> 원장이에요, 아니에요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 현재 상태는 사직을 한 상태입니다.  
</p>
<p><b>○ 박영신 위원 </b> 언제 사직했어요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 11월 10일자로 사직했습니다. 
</p>
<p><b>○ 박영신 위원 </b> 오늘 며칠이에요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 오늘은 11월 17일입니다.
</p>
<p><b>○ 박영신 위원 </b> 언제 사직했어요?  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 11월 10일자로…….
</p>
<p><b>○ 박영신 위원 </b> 사직한 지 며칠 됐어요? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 1주일 됐습니다. 
</p>
<p><b>○ 박영신 위원 </b> 경기개발연구원이 원장이 사직한 지 1주일이 됐는데 아직도 원장을 한현규라고 쓴다는 게 말이 됩니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 죄송합니다.  이것은 바로 수정하도록 하겠습니다.
</p>
<p><b>○ 박영신 위원 </b> 지금 수정해 놓고 보고하세요.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 알겠습니다.
</p>
<p><b>○ 위원장 정인영 </b> 지금 존경하는 박영신 위원께서 2005년 주요업무보고 자료와 관련해서 간부명단에 한현규 전 원장이 표기되고 있으므로 이것을 수정 후 감사를 속개하자고 하는 의견이 있습니다.  위원님들 여기에 대해서 동의하십니까? 
</p>
<p style="padding-left:2.4em">    (「동의합니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  동의하면 수정이 될 때까지 잠시 감사중지를 선포합니다. 
</p>
<p class=''ar''>(10시28분 감사중지)
</p>
<p class=''ar''>(10시40분 감사계속)
</p>
<p><b>○ 위원장 정인영 </b> 좌석을 정돈하여 주시기 바랍니다.  감사를 계속하겠습니다.  그러면 부원장 나오셔서 간부소개와 업무보고를 해주시기 바랍니다.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 업무보고 자료가 제대로 갖춰지지 못한 점 정말 죄송하게 생각합니다.  저희들이 10월 31일자를 기준으로 해서 자료를 만들다 보니까 이런 실수를 했습니다.  다시 한 번 죄송하다는 말씀을 드리고 양해를 부탁드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그러면 보고에 앞서 우리 연구원의 간부를 소개해 드리겠습니다.  먼저 성현찬 기획조정실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이강수 사무처장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이용환 자치행정연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김제국 도시지역계획연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  조응래 교통정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이정임 환경정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김군수 경제사회연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동성 동북아지역연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  참고로 동북아지역연구부는 10월에 경기도의 동북아 협력 및 발전전략 연구를 전담 수행하기 위해 신설된 조직입니다.  
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 지금부터 우리 연구원의 주요업무를 보고드리겠습니다.  보고드릴 순서는 배부해 드린 유인물을 중심으로 일반현황, 재정운용, 2005년도 연구사업 추진상황, 2006년도 연구사업계획에 대해서 중요사항 중심으로 간략히 보고드리겠습니다.  먼저 유인물 1페이지 일반현황은 저희 연구원은 ’95년에 개원 후 10주년이 되었으며 2004년 6월 23일 현 청사로 이전하였습니다.  연구원의 주요기능은 도정의 비전제시와 정책개발을 위하여 기획조정실, 자치행정연구부 등 6개 연구부가 경기도 수요에 맞게 다양하고 깊이있는 전문적인 연구를 수행하고 있습니다.  보다 자세한 사항은 배부해 드린 유인물을 참고하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음 2페이지입니다.  본원의 기구는 1실 1센터 1처 6부이고 10월말 현재 인력은 박사급 연구직 50명을 포함해 71명이 근무하고 있습니다.  연구직 총 정원은 63명으로 13명이 결원이나 현재 추가 박사인력을 선발하기 위해 채용 중에 있습니다.  참고로 2, 3일 전에 채용이 끝나서 6명이 추가로 채용 예정상태입니다.
</p>
<p style="padding-left:1.2em">  다음 3페이지의 시설 및 물자현황을 보고드리겠습니다.  먼저 청사는 2004년 6월 23일부터 경기도공무원교육원 6층에서 12층까지 대지 9,190평에 건평 1,656평을 사용 중입니다.  연구에 필요한 장서는 3만 2,000권 정도를 보유하고 있으며 주로 최신의 국내외 전문서적 및 경기도 관련 자료로 구성되어 있습니다.  참고로 장서 이외에 이메일 정보 등을 이용해서 필요한 자료를 채워나가고 있습니다.  또한 저희 연구원의 자료실은 일반시민, 학생, 공무원은 물론 사계의 전문가에 이르기까지 언제든지 방문하여 이용이 가능하도록 개방되어 있으며 본원 홈페이지를 통해서 소장자료에 대한 검색뿐만 아니라 신간자료에 대한 정보를 제공하여 정보지식의 공유를 확대하고 보다 질 높은 서비스를 제공하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음 4페이지 재정운용 상황에 대해서 보고드리겠습니다.  먼저 올해의 총 예산 규모는 444억 1,000만원으로 이중 일반회계가 174억 8,200만원, 기금관리특별회계가 269억 2,800만원입니다.  일반회계의 주요 세입재원으로는 전입금 12억 2,800만원, 수탁용역사업수입 8억 500만원, 도비출연금 97억 5,000만원, 전체 일반회계 예산의 55.8%입니다.  환급금 2억 5,700만원, 이월금 51억 9,100만원 등이며 주요 세출항목으로는 연구사업비가 전체의 84.5%인 147억 7,500만원이고 기관운영비가 10.4%인 18억 1,400만원, 청사유지비가 4.6%인 7억 9,700만원 등입니다.  4페이지 아래의 기금관리특별회계의 수입ㆍ지출내역은 유인물을 참조하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음 5페이지의 기금조성 운용사항은 총 기금 조성액은 257억원이고 그중 57.2%인 147억원을 도에서, 15.4%인 39억원은 시ㆍ군에서 출연하였으며 나머지는 2개 은행의 출연금과 자체적립금으로 구성되어 있습니다.  기금예치 상황을 보면 이자율 및 예금의 종류를 고려하여 분산 예치를 원칙으로 운영하고 있으며, 5페이지 표에서 보시는 바와 같이 현재 기금 257억원은 7개 금융기관 11종의 상품으로 적립하고 있습니다.  자세한 유치내역은 유인물을 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 6페이지의 금년도 연구사업 추진상황 중 주요실적을 보고드리겠습니다.  민선3기 후반기의 도정 주요 현안과제와 참여정부의 국정 추진과제 등에 대하여 탄력적으로 대응하고 실효성있는 연구성과물을 도출하였으며 신속하고 시의성있는 도정정책개발 기능 강화에 역점을 두고 연구사업을 나름대로는 열심히 추진해 왔습니다.  올해는 이러한 기본방침을 토대로 경기도 정책과 밀착된 연구수행을 위해 경기도가 추진하고 있는 각종 정책 및 사업에 대해 상시 수용 및 자문하는 과제를 채택하거나 전문인력을 지원하였고 주요시책과는 다소 거리가 있으나 도민의 삶의 질 향상과 관련된 과제를 발굴하거나 경기도 및 각 시ㆍ군에서 요구하는 연구사업을 수행했으며또한 연구원이 주도적으로 때로는 경기도 정책방향에 맞추어 상시 발생하는 현안에 대해 대응하면서 금년에는 수도권 대책에 대한 정책방향 설정, 지방분권 및 지방간 상생발전을 위한 정책 발굴 및 집행을 주도적으로 추진해 왔습니다.
</p>
<p style="padding-left:1.2em">  이어서 7페이지부터 8페이지까지의 연구사업실적에서 보시는 바와 같이 올해도 여러 도정현안에 체계적으로 신속히 대응하기 위해 전 연구원이 최선을 다해 왔습니다.  이슈와 동향, Policy Brief, 포럼 운영, 정책세미나 개최 등을 통하여 도정 주요시책 및 정책개발에 즉시 대응 지원해 왔습니다.  또한 저희 경기도의 최대 현안인 수도권 규제완화와 발전전략 수립에도 연구역량을 결집해 왔습니다.  이와 관련해서는 수도권 대책 태스크포스팀을 구성 및 운영함으로써 수도권 발전전략, 북부지역 발전전략 등을 수행했습니다.  얼마 전 당정이 발표한 대기업 8개 첨단업종 수도권 공장 신증설 허용은 비록 미흡하기는 하지만 도의회 의원님, 경기도, 그리고 연구원이 합심하여 부단히 문제제기를 하고 함께 노력을 한 결과물이라고 생각하고 저희들 나름대로는 비록 미흡하지만 나름대로 뿌듯하게 생각하고 있습니다.  앞으로도 저희 연구원은 국가와 경기도의 경쟁력과 직결된 이러한 수도권 규제완화 정책과 논리개발에 더욱 박차를 가해 나갈 계획입니다.  그 외에도 금년 저희 연구원은 지방분권과 상생발전, 경제살리기와 지역경쟁력 강화, 개원 10주년 기념사업을 연초 목표한 대로 추진하였거나 해오고 있습니다.
</p>
<p style="padding-left:1.2em">  9페이지로 넘어가겠습니다.  2005년도 연구사업 총괄을 간략히 보고드리겠습니다.  연구사업은 현재 120건을 완료하였고 133건을 추진 중에 있어 당초 계획대비 98%를 추진 중에 있습니다.  연말까지는 목표한 대로 차질없이 완료할 수 있을 것으로 예상되며 각 연구사업의 세부 추진상황을 10페이지부터 24페이지까지 간략히 보고드리겠습니다.  10페이지의 기본연구과제는 23개 과제를 수행하고 있으며 이 중에서 1개 과제는 이미 끝나고 지금 현재는 22개 과제가 수행되고 있습니다.  오존경보제 운영 개선방안을 완료했고 나머지 재정조정제도 변화에 따른 합리적인 재원배분방안 연구 등 22개 과제는 연구 중에 있습니다.  11페이지부터 13페이지까지의 수탁연구과제 추진상황은 전년도에서 이월된 30개 과제와 금년도에 신규로 위탁받은 36개 과제를 포함한 총 66건 중에서 “과천 지식정보타운 개발계획수립 및 타당성 조사 연구용역” 등 23건을 완료했고 7건은 현재 중지된 상태이고 평택항권 경제자유구역지정 개발계획수립의 관련계획 및 대상지 여건분석 등 36건을 현재 추진 중에 있습니다.
</p>
<p style="padding-left:1.2em">  14페이지로 넘어가겠습니다.  14페이지부터 16페이지까지의 정책연구과제는 47건 중에 경기북부지역 발전촉진을 위한 규제완화 특례법안 제정 논리개발 및 대응방안 등 29건을 완료했고 수도권 첨단 대기업 공장 신ㆍ증설 허용에 따른 파급효과 분석 등 18건을 추진 중에 있습니다.  16페이지로 넘어가겠습니다.  16페이지부터 17페이지까지의 위탁연구과제 28건 중에 수도권과 비수도권의 상생을 위한 국토전략 등 4건은 완료했고 나머지 24건은 추진 중에 있습니다.
</p>
<p style="padding-left:1.2em">  18페이지로 넘어가겠습니다.  18페이지의 협약연구과제 6건 중 읍ㆍ면ㆍ동 연찬회 1건은 완료했고 나머지 5건은 추진 중에 있으며 지역연구과제는 오산시는 완료해서 현재 인쇄 중이며 화성시는 현재 연구 중에 있습니다.  연구원 개원 10주년 기념사업으로 추진 중인 GRI 정책연구총서 총 12권으로 구성돼 있는데 기타연구과제를 25건 수행해 왔는데 이중 7건은 완료하였으며 나머지 18건은 추진 중에 있습니다.
</p>
<p style="padding-left:1.2em">  20페이지로 넘어가겠습니다.  20페이지의 정기간행물 발간사업은 연구원이 발행하고 있는 경기논단 등 3건은 정기적으로 발행하고 있으며 2005년도 워크숍 자료집과 해외출장보고서도 발간할 예정입니다.  번역사업 2종은 추진 중에 있습니다.  다음 21페이지부터 23페이지까지의 정책세미나 및 정책포럼 사업과 관련 현재까지 정책세미나는 22회를 추진하였고 남북포럼, 교육포럼, 동북아포럼 등 경기도정 관련 주요 이슈에 대해 각계 전문가를 모시고 대안을 모색하는 포럼은 지금까지 13회 개최한 바 있습니다.  자세한 내역은 유인물을 참조하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  24페이지로 넘어가겠습니다.  24페이지의 연구사업 연도별 수행현황은 역시 유인물을 참조하여 주시기 바랍니다.  이어서 25페이지의 2006년도 연구사업계획을 보고드리겠습니다.  내년도 연구사업계획의 기본방침은 동북아경제권의 중심, 지식기반산업의 거점화 등 경기도정 목표달성과 공공기관 지방이전대응, 민선4기 시대에 따른 지방분권화 추진 및 수도권 발전대책 등 경기도의 주요 현안정책 연구사업을 역점적으로 추진하고 정책연구사업에 보다 많은 역량을 발휘할 수 있는 시스템으로 연구인력과 예산을 중점 편성하여 도정목표와 현안에 신속히 대처해 나갈 계획입니다.
</p>
<p style="padding-left:1.2em">  이어서 26페이지부터 28페이지에서 보시는 바와 같이 이러한 기본방침을 토대로 내년도 연구사업계획은 동북아경제중심 수도권전략 수립, 3만불 달성과 산업ㆍ경제발전 선도, 경쟁력있는 도시개발 및 관리, 민선4기 출범과 자치역량 강화, 쾌적한 삶의 환경 조성, 안전하고 편리한 교통환경 조성, 선진 교육ㆍ문화ㆍ복지 구현, 동북아시대 및 남북교류 선도, 연구조성사업 다양화와 연구역량 강화 등에 역점을 두고 이에 따른 각종 과제와 연구사업을 적극 추진해 나갈 계획입니다.  구체적인 연구사업계획은 26페이지부터 28페이지를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  29페이지로 넘어가겠습니다.  29페이지에 있는 내년도 연구사업계획 총괄은 유인물을 역시 참조해 주시면 감사하겠습니다.  참고로 기본연구과제 같은 경우는 금년도에 23개 과제를 수행했는데 내년에는 2개 과제를 더 추가해서 수행하겠습니다.  다음은 30페이지부터 43페이지까지의 기본연구과제 추진계획을 보고드리겠습니다.  기본연구과제는 아까 말씀드린 대로 25개 과제를 계획했으며 기본연구과제 현황과 세부사업계획 현황은 31페이지부터 43페이지까지의 유인물을 참조해 주시기 바랍니다.  참고로 기본연구과제 선정과정에서는 도청과 도의회에 있는 각계의 여러 전문가들의 의견들을 참조했음을 말씀드립니다.
</p>
<p style="padding-left:1.2em">  44페이지로 넘어가겠습니다.  다음으로 44페이지의 수탁연구과제 추진계획을 보고드리겠습니다.  수탁연구과제는 금년도에서 이월될 과제를 포함해서 내년도의 신규 수탁연구과제를 부서당 9건 내외인 약 50개 과제를 수행할 예정입니다.  다음 45페이지의 정책연구과제와 위탁연구과제 추진계획을 보고드리겠습니다.  정책연구과제는 경기도로부터 긴급 요청되는 시의성있는 과제와 연구원에서 중요하다고 판단되어 추진하는 자체 추진과제 등 총 82개 과제를 수행할 계획입니다.  이는 올해보다 양적으로 약 27%인 22건이 늘어난 것입니다.  이처럼 앞서 보고드린 바와 같이 내년도에는 경기도 정책현안 중심의 정책과제를 수행하는데 연구시스템을 집중해 나갈 계획입니다.  위탁연구과제는 민선4기 출범과 함께 도래할 각종 연구수요와 도정현안에 대비해서 학회 등 외부 전문연구기관과의 공동연구 확대를 통한 소기의 목적달성을 위해 사업량을 대폭 늘린 약 20개 사업을 계획하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음 46페이지의 지역연구과제 추진계획을 보고드리겠습니다.  지역연구과제는 특정 현안이 발생하고 있는 경기도내의 시와 군을 대상으로 1건을 추진할 예정입니다.  다음 47페이지의 정기간행물 발간사업 추진계획을 보고드리겠습니다.  정기간행물은 올해와 같이 경기논단 4회, GRI 뉴스레터 12회, 경기도 경제동향과 전망 12회, 그리고 연구원 안내책자를 발간할 계획입니다.  이외에도 비정기간행물로 Policy Brief 등은 수시로 발간할 예정입니다.
</p>
<p style="padding-left:1.2em">  다음 48페이지부터 49페이지까지의 연구조성사업계획을 보고드리겠습니다.  당면문제 및 학술적 성격의 대내외적인 여론선도를 위해 15회의 정책세미나를 추진할 계획입니다.  정책포럼은 기 보고드린 바와 같이 남북포럼, 교육포럼을 내실있게 운영하고 연구성과 홍보를 위해 주요 정책현안 중심의 정책동향 조사 분석과 홍보, 연구원 이미지 홍보를 위해 내년도 신규사업으로 초ㆍ중ㆍ고생 초청 연구원 견학 학ㆍ연네트워크 사업을 적극 추진할 예정입니다.
</p>
<p style="padding-left:1.2em">  50페이지로 넘어가겠습니다.  끝으로 2004년도 행정사무감사 처리요구사항 조치결과를 보고드리겠습니다.  2004년 11월 26일 행정사무감사시 처리요구 사항은 4건이었고 이를 개선하기 위해 저희 나름대로 최선을 다해 왔습니다.  먼저 작년에 위원님들께서 각종 규제 중 법을 개정해야 될 사항은 연구원에서 연구과제를 통해 검토한 후 정책대안을 주기 바란다는 요구사항을 말씀하셨습니다.  이에 대해서 그간 수도권의 각종 규제에 대해 총체적이고 합리적인 대안으로 수도권의 성장관리 차원의 연구를 수행하였으며 특히 수도권의 계획관리 방안을 수립하고 이를 적극 홍보하였고 수도권 공장 신증설규제의 개선방안에 대한 효과분석을 수행했습니다.  그외 구체적인 조치결과는 배부해 드린 유인물을 참고하여 주시기 바랍니다.  이상으로 2005년도 주요업무보고를 모두 마치겠습니다.  경청해 주셔서 대단히 감사합니다.
</p>
<p>(업무보고서는 끝에 실음)
</p>
<p><b>○ 위원장 정인영 </b> 부원장 수고하셨습니다.  다음은 질의답변 순서가 되겠습니다.  감사의 원활한 진행을 위해 질의답변은 일문일답 식으로 진행하도록 하겠습니다.  질의에 앞서 위원장으로서 한 가지 부탁의 말씀을 드리겠습니다.  위원님들의 질의사항 중 부원장이 답변이 어려울 경우 담당 실ㆍ부장 등 실무자가 답변해도 좋습니다.  다만 사전에 위원장에게 동의를 얻은 후 발언대로 나와 소속과 직, 성명을 분명히 밝히고 답변을 해주시기 바랍니다.  그러면 질의하실 위원께서는 거수로 신청해 주시기 바랍니다.  김영복 위원 질의해 주시기 바랍니다.
</p>
<p><b>○ 김영복 위원 </b> 가평 출신 김영복 위원입니다.  시간 관계상 인사는 생략하고 바로 질의로 들어가겠습니다.  업무보고 11쪽을 봐주시기 바랍니다.  여기 보면 수탁업무가 있는데 오염총량제 계획수립이 우리 군에서 해서 완료가 됐는데 본 위원이 질의하려고 하는 내용은 우리가 처음에 연구원에서 기본 틀을 가지고 도의 입장에서 어느 방향으로 가야 되나 하는 그런 큰 틀에서 갔어야 되는데 이 방향이 틀려지지 않았나 해서 그런 내용 쪽으로 질의를 드려보겠습니다. 
</p>
<p style="padding-left:1.2em">  사실 몇 년 전만 해도 오염총량제 계획에 대해서 민선3기 들어오기 전에, 2기 때 팔당상수원특별법 만들 당시에는 우리 도에서 큰 틀에서 팔당상수원의 지역주민을 보호하고 같이 공동으로 가기 위한 그런 쪽에서 많이 대변을 해주셨습니다.  그런데 민선3기 들어오면서부터 우리 도의 사업과 관련이 돼서 그런지 몰라도 방향이 다른 데로 가서 오염총량제를 실시해야 되는 것처럼 지금 방향이 가고 있지 않나 본 위원은 봅니다.  그래서 질의를 드리는데요.  담당자께 답변을 부탁드립니다.  오염총량제 계획이 본 위원이 보기에는 우리 도에서 지금 실행하고 있는 사업 중에서 남양주 같으면 실학박물관, 양평 같으면 영어마을 이런 것이 환경부의 환경영향평가에서 오염총량제를 수용하지 않으면 안 받아들이겠다고 해서, 이 환경영향평가를 미루고 있어서 그런지 몰라도, 그 지역에서도 그 사업을 또 하려고 했었는지 몰라도 오염총량제를 받아들이게끔 유도해 나가는 연구가 되지 않았나 보는데 답변을 부탁드립니다.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 간단히 제가 아는 선에서 말씀드리겠습니다.  오염총량제라는 게 실제로 경기도 입장에서 보면 상당히 어려운 문제임에도 불구하고 중앙정부인 환경부의 입장에서는 오염총량제의 확대시행을 계속 진행하고 있습니다.  실제로 환경부의 입장에서 보면 2008년도에 지금 오염총량제를 진행하고 있는 광주시 외에 다른 시ㆍ군까지 확대할 예정인 것으로 알고 있습니다.  따라서 그에 대해서 우리 연구원에서 그에 대응하여 이것이 맞는지 틀리는지 시작해서 추가적인 연구가 필요하다고 생각하고 그것을 내년도에 시행하도록 하겠고요.  또한 그것과 더불어서 지금 11페이지에 나와 있는 가평군이나 여주군 같은 경우에 각종 수탁과제 같은 경우도 실제로 환경부에서 추진하고 있는 상황에 대해서 각 시ㆍ군 입장에서 어떻게 대응할 것인가에 대해 좀더 구체적인 대안을 내기 위한 연구라고 이해해 주시면 고맙겠습니다.  그러니까 오염총량제를 받는다, 안 받는다 이전에 어쨌든 실무 입장에서 보면 구체적으로 실제 경우에 따라서는 오염총량제가 시행됐을 때 아무 대안 없이 있다가 문제가 생기기보다는 그것들을 미리 준비하는 부분들은 있어야 될 거라고 생각하고 그것과 관련해서 지금 과제를 시행하고 있는 것으로 알고 있습니다. 
</p>
<p><b>○ 김영복 위원 </b> 부원장님, 거기에 대해서 잘 모르시는 것 같습니다.  연구담당 쪽에서 답변을 부탁드립니다.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 방금 담당 박사가 왔으니까……. 
</p>
<p><b>○ 김영복 위원 </b> 본 위원이 알기로는 민선2기하고 3기에 들어서면서 이 방향이 틀려졌다는 겁니다.  민선3기 최초에는 그런 방향이 아니었습니다.  환경부와 지역주민 간의 팔당상수원특별법을 만들 당시에는 2005년도까지 팔당상수원을 1급수로 만들기로 하고 그 지역에서도 지켜가면서 깨끗이 하려고 노력은 했어요.  그런데 2005년도 전인 2003년도부터 환경부가 그런 쪽으로 몰고 가고 있습니다.  그런데 거기에 동조를 하는 것은 우리 도입니다.  우리 도가 민선3기 들어오면서 그 사업에 관계된 게 그런 오염총량제를 미리 알고 대처를 했어야 하는데 실학박물관이 어디입니까?  남양주 조암면 팔당상수원 수변구역 안에 사업을 하려고 해서 문제가 됐지 않습니까?  이런 문제라든가, 또 어느 면적 이상이면 환경영향평가를 받게끔 돼 있는데 지금 양평의 영어마을도 그런 현상이 벌어졌다는 겁니다.  그러니까 접근을 어느 방향에서 보느냐에 따라 틀리거든요.  그런데 본 위원이 봤을 적에 우리 도에서 너무 사업만 하려고 해서 이런 오염총량제 방향으로, 우리 환경부 쪽으로 가는 것 아닌가, 31개 시ㆍ군 중에 7개 시ㆍ군이 있지만 그 지역주민도 경기도민이 아니냐 이것을 대변했어야 되고 기본 큰 틀에서 처음부터 갈 방향에 대한 설정이 있었으면 거기에 맞춰갔어야 되지 않냐 이런 겁니다. 
</p>
<p><b>○ 환경정책연구부 이기영 </b> 안녕하십니까?  환경정책연구부 이기영입니다.  총량관리제에 대해서 저희 연구원에서 대응한 것에 대해서 간단하게 말씀드리겠습니다.  우선 총량관리제를 시작할 때 ’98년 한강특별대책위에서부터 시작했는데 거기에 따라서 환경부에서 총량관리제를 어떻게 하겠다는 그런 계획을 냈었습니다.  그래서 제가 기본과제로 해서 거기에 대한 문제점들을 지적하고 어떻게 하면, 사실 처음에는 비판적인, 완전히 거부하는 입장은 아니고 어떻게 하면 제대로 갈 수 있는지 거기에 대해서 안을 제시했고요.  그리고 지금은 저희가 실제로 가평군하고 여주군에 대해서 오염총량관리계획을 수립하고 있습니다.  저희가 이 계획을 수립하는 것은 어떤 면에서는 한계에 있는 거지요.  그러니까 환경부에서 내린 지침 그리고 정책에 대해서 그대로 따라가는 그런 입장에서 하고 있습니다만 실질적으로 저희가 계획을 수립하면서 거기에 대한 문제점이라든지 각 경기도나 시ㆍ군에서 어떻게 하면 이 제도를 이용해서 각 지역이 발전할 수 있는지 여기에 대해서 사실은 더 중점적으로 고려하고 있다고 보시면 타당합니다.  그리고 실제로 저희가 광주시 같은 경우에 매년 이행평가보고서를 제출하고 있습니다.  그래서 그 보고서의 평가에 대해서 저도 같이 참여하는데 환경부에서 주장했던 내용들이 모순이 있다는 그런 사실들이 조금씩 밝혀지고 있습니다.  그래서 앞으로는 일단 저희 같은 경우에는 환경부 제도권에서 오는 제도이기 때문에 사실은 거부하기 어려운 입장입니다.  그렇지만 각 시ㆍ군에서 주장하시는, 그러니까 예를 들어서 총량관리제에 대한 대응방안으로 나왔던 게 총량관리제보다는 처리시설을 제대로 확충하면 수질에 별로 문제가 없다는 두 가지 주장이었습니다.  그런데 이행평가보고서에 의하면 시ㆍ군에서 말하는 주장들이 설득력 있게 나오는 그런 결과가 지금 나오고 있거든요.  그래서 저희가 그런 방향에 대해서 잘 모니터링을 해서 앞으로 대응을 하게 된다면 괜찮지 않을까 그렇게 생각하고 있습니다. 
</p>
<p><b>○ 김영복 위원 </b> 시간관계상 제가 보는 방향하고 여태까지 진행돼 왔던 그런 것을 말씀드리고 또 한 가지는 특히 연구과제 중에서, 이제 들어가셔도 좋겠습니다.  연구과제 중에서 정책연구과제에 대한 중요성인데요.  잘 아시다시피 이번에 한현규 경기개발연구원장과 연루된 사업에 대해서 여쭤보겠습니다.  업무보고 15쪽에 보면 정책연구과제 중에서 판교 메모리얼파크 조성의 타당성 분석 및 기본구상 수립에 대한 것을 발주기관인 노인복지과에서 해서 우리 연구원에서 2005년도 3월부터 2005년도 6월까지 해서 완료했지 않습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 김영복 위원 </b> 거기에 보면 우연인지 몰라도 이번에 거기 사업에 대해서 사전에 그쪽 지역 주민들하고 여기, 본 위원은 연구원에 대한 성과물을 믿습니다만 지금 지역 주민들은 방향이 그거 말고 다른 쪽으로 갔어야 되지 않냐 이런 주장을 해왔었습니다.  그런데 그것을 지금에 와서 한현규 원장님이 이번에 불미스러운 그런 일이 있으면서 그 사업이 그 사건과 맞물려 있다는 겁니다.  또 그때 당시 연구원에 근무를 하셨고.  여기에 대해서 답변하실 게 있으면 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 이것도 제가 답변하고요, 만일 부족하다고 생각되면 담당자를 불러서 추가로 말씀드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  실제로 이 과제 같은 경우를 보시면 저희는 양해의 말씀을 구하고 싶은 것은 저희들 입장에서는 이 과제를 수행함에 있어서 특정입지를 정해놓고 그 입지에 특정사업을 시행하는 게 맞느냐 틀리느냐를 저희들이 연구하게 됩니다.  간단히 이야기하면 판교 메모리얼파크의 구체적인 입지가 어디다 아니면 거기가 메모리얼파크가 좋냐 다른 것이 좋냐가 아니라 이 과제의 성격은 특정입지에 메모리얼파크가 들어서는 게 타당하겠느냐 타당하지 않겠느냐라는 과제였다는 점을 말씀드리고 싶고요.  두 번째로 말씀드리고 싶은 것은 실제로 저희 연구원 내부에서도 그런 의견들은 충분히 있다고 생각합니다.  뭐냐면 보통 납골당, 공동묘지 이렇게 가다보면 굉장히 혐오시설로 이야기가 됩니다.  그러다보니까 주민들이 살고 있는 곳으로부터 가급적 멀리 떨어진 곳에 들어가게 되고 그러다보니까 여러 가지로, 간단하게 얘기하면 성묘부터 시작해서 여러 가지로 문제가 생깁니다.  그런 점에서 최근에 전반적으로 분위기가 일고 있듯이 이 납골당이나 공동묘지 같은 것을 “보다 주민 친화적인 것으로 만들어보는 방법은 없겠는가” 거기에 포인트를 두고 저희들은 연구를 수행해 왔습니다.  그리고 실제로 그 부분에 대해서는 저희 연구원에서도 그만한 입지와 그만한 계획이 있다고 한다면 그것을 추진해서 나쁘지는 않다고 결론을 내렸고 그것에 대해서 구체적인 추진방안을 어느 정도 여러 가지 시나리오를 가지고 검토해서 답을 내는 상태가 이 과제의 내용이 되겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 그런데 판교 메모리얼파크 조성 타당성에 대해서 그때 지역주민이 위치선정 얘기했던 좋은 방안하고 우리 연구원에서 했던 방안하고 좀 틀리지 않습니까, 방향이.  그런데 마침 여기에 이번에 사건이 연루돼 있지 않습니까?  이런 부분입니다.  그래서 본 위원은 무슨 얘기를 드리려고 하냐면 특히 아까 수탁과제도 그렇지만 도에 관련된 사업이라든가 이런 관계하고 또 특히 정책과제에서는 우리 경기도에 대한 어떤 방향인데 이런 것을 잘 짚어가야지 이게 잘못하면 오해도 살 수 있고 이거 누가 옳다 그르다고 얘기할 수가 없습니다.  일단 연루가 돼 있지 않습니까?  그래서 앞으로 정책과제를 할 적에는 그런 것을 확실하게 소신을 가지고 해주시기를 바라겠습니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 김영복 위원 </b> 지금 시간 관계상 저희가 간략하게, 5분만 더 쓰겠습니다.  그래서 본 위원이 보니까 거기에 앞으로 경기방문의 해 사업성과 평가 및 백서라든가 이런 것도 용역이 들어와 있는데 이런 것을 경기도에서 자꾸만 수탁과제로 줬지만 여기에서 정말 정확한 평가를 내려주셔야 됩니다.  왜냐하면 이것을 경기도에서 성과로 띄우려고 할 수도 있습니다.  누구나 지방자치시대에 그런 것이 보이거든요.  그래서 앞으로 연구원에서는 소신껏 연구를, 수탁과제든 정책과제든 발휘해 주시기 바라겠습니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 알겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 그 다음에는 동북아연구부도 신설됐고 그런데 학ㆍ연네트워크 구축운영을 해서 나름대로 앞으로 동북아의 최고 싱크탱크 연구기관으로 남기 위해서 연구를 하고 있습니다.  그래서 그런 것은 저희가 잘 하셨다고 칭찬을 드리고, 저는 여기에 관련돼서 지금 중국 쪽에 대해서는 연구를 많이 하고 있는데 경기도에 자매결연 도시가 있습니다.  그것을 보면 중국의 요령성이라든가 광동성 그리고 일본의 가나가와현, 미국의 유타주하고 스페인의 카탈루니아하고 호주 퀸스랜드주 이런 데가 있거든요.  그런데 우리 연구원에서 학ㆍ연네트워크 구축한 것을 보면, 감사자료를 보면 우리, 캐나다의 도시연구소 CUI하고 중국 산동사회과학원하고 이렇게 하고 있는데 앞으로 이것은 도와 연관된 사업이지만 도에서 안 할 적에 자체의 우리 경기도의 정책방향을 올바로 끌어가고 자료를 바로 바로 해서 경기도가 바른 방향으로 가기 위해서는 자매결연도시에 대한 것도 자체연구가 필요하지 않나.  그런데 본 위원이 다 조사를 해본 결과 여기에 대해서 연구해서 나온 게 없는 것으로 알고 있습니다.  답변을 부탁드립니다.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 방금 김영복 위원님께서 사실 저희들이 하지 못하고 있는 것을 정확하게 지적해 주신 것 같습니다.  사실은 저희가 국내외적으로 약 10개 기관과 학ㆍ연네트워크를 구축하고 있습니다만 그것을 경기도에서 자매결연을 맺은 주하고 연결해서 하고 있지 못합니다.  그리고 하고 있는 게 국제적으로는 캐나다하고 중국 산동사회과학원 뿐인데 실제로 그 부분에 대해서는 앞으로 저희 연구원에서도 금년도에 동북아지역연구부도 신설하고 했습니다.  그것과 관련해서 경기도에서 자매결연을 맺은 각종 주와 국가들과 어떻게 더 긴밀하게 협력을 맺을 것인가 이런 부분에 대해서는 보다 집중적인 연구를 바로 내년부터 시행할 수 있도록 최선을 다하겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 그러나 우리 도에서 어떤 일을 급하게 자문을 구할 적에 정확히, 그것처럼 중요한 게 어디 있습니까?  말만 자매결연을 경기도에서 맺었지 우리 행정 쪽이나 의회 차원에서도 접근할 수가 없습니다.  제대로 모르고.  그렇게 해서 어떤 성과가 있겠습니까?  그래서 정책방향을 해주시기를 바라고요.  마지막으로 업무자료 24쪽에 연구사업 연도별 수행현황을 보면 지금 너무 정책적으로 과제가 편중되는 것 아닌가.  2006년도의 연구사업계획서도 아까 보고했었습니다만 그런 쪽으로 가고 있습니다.  그래서 그게 잘 되면 괜찮지만 잘못될 수도 있다.  그래서 본 위원은 정말 연구원이 가야 될 기본방향은 기본연구과제가 자료에 보면 올해 2004년도에 23건입니다.  그런데 연구진이 ’98년도나 ’99년도에 비해서 많이 늘어났는데도 불구하고 기본연구과제는 ’98년도 25건, ’99년 27건이나 2004년도의 23건이나 별 차이가 없습니다.  이런 기본연구과제가 충실히 돼야 어떤 정책방향이라든가 연구원으로서 해야 될 그런 목적달성이 아닌가.  앞으로도 그걸 자료로 해서 방향을 설정하시지 않을까 이렇게 보거든요.  그래서 거기에 대해서는 어떻게 생각하시는지 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 김영복 위원님께서 다시 한 번 저희들 마음속에서 하고 싶었던 이야기이고 저희들이 원하고 바라는 이야기를 해주신 것 같습니다.  사실은 저희들 나름대로도 연구원이 긴 호흡을 가지고 계속적으로 창조적인 과제를 하려고 한다면 저희들 나름대로의 기본연구과제가 굉장히 중요하다고 생각합니다.  그래서 나름대로는 금년에 23개에서 내년도에 2개 더 늘렸습니다만 사실 인력에 비해서는 박사 2인당 하나 꼴로 기본연구과제를 수행하고 있습니다.  이것도 굉장히 부족합니다.  다만, 하나 저희들이 안타까운 것은 뭐냐면 지금 현재 그렇게 기본연구과제를 하면서 정책과제를 수행하다보니까 어떤 문제가 생기냐면 금년도 같은 경우 저희 연구원 박사 1인당 과제책임이 4개 과제, 공동으로 들어가는 것까지 합치면 8개 내지 9개 과제를 수행하고 있습니다.  이렇게 하다보니까, 이것은 다른 연구기관하고 비교하면 거의 두 배 수준이거든요.  그리고 연구 부담이 굉장히 커졌습니다.  그러다보니까 저희들이 기본적으로 해야 될 기본적인 과제인 기본연구과제에 소홀히 하고 있는데 이 부분에 대해서는 저희 연구인력도 확충하고 또 연구의 방향도 보다 기본적인 연구과제를 중심으로 해나갈 수 있도록 하겠습니다.  다만 내년도에는 앞의 업무보고에서도 말씀드렸습니다만 민선4기로 교체되는 과정이기 때문에 정책과제가 더 늘어날 것이라고 생각합니다.  그럼에도 불구하고 내년도에도 기본과제 25개 잡아놓은 것에 대해서는 최선을 다해서 거기에 중심을 맞춰서 연구를 수행하도록 하겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 그래서 본 위원이 얘기하고 싶은 것은 뭐냐면 이런 기본방향 틀이 잘 돼야 나중에 정책과제가 잘 나오지 않냐.  아까도 제가 사업에 대해서 한두 개 예를 들었습니다만 도에서 정책과제를 줄 적에 책임을 회피하려고 이쪽 연구원에다 줄 수도 있습니다, 방향을 설정 못 하니까.  그런 것을 정확히 하기 위해서 말씀드리는 거예요.  그래서 2006년도 계획안을 보면 정책의 품질을 향상시킨다고 얘기하셨는데 말로만이 아니라 연구결과의 질, 제도를 위배하는 그런 흐름이 가지 않게끔 하셔야 되고요.  우리 동북아에서 최고의 연구기관이 되겠다고 하셨는데 이래서 동북아의 최고 연구기관으로, 싱크탱크로서 남을 수 있겠습니까?  그것 좀 잘 해주시기 바라겠습니다.  마지막으로 질의드리면서 마치겠습니다.  답변 바랍니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 기본연구과제를 수행하는 데 있어서 최선을 다해서 수행해야 된다는 것을 저희들도 깊이 공감하고 있고요.  나름대로 하나만 저희들이 노력했던 것을 소개드린다면 금년도부터 기본과제 23개 과제에 대해서 연구원 차원의 연구심의회를 착수연심회는 중간에 있습니다만 최종연심회를 해서 연구의 퀄리티를 높이도록 하고 있습니다.  이게 좀더 성숙된다면 내년도부터는 좀더 질 높은 연구가 될 수 있다고 믿고 그것을 위해서 앞으로도 꾸준히 최선의 노력을 다해 나가겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 그래서 저희가 행정감사 하다보니까 잘한 것을 칭찬을 많이 해드려야 되는데 못해 드리고 어떤 문제점이라든가 앞으로 대안 쪽으로 얘기를 드렸는데 그렇다고 우리 연구진에서 저희가 나쁜 쪽으로 몰아가는, 못한다는 쪽은 아닙니다.  그래서 발전이 많이 되고 있는데 힘 좀 내시고 기본을 튼튼히 하는 그런 연구기관으로 남기 바랍니다.  이상입니다.
</p>
<p><b>○ 위원장 정인영 </b> 김영복 위원 수고하셨습니다.  다음 질의하실 위원 거수로 신청해 주시기 바랍니다.  이건희 위원 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이건희 위원 </b> 광주 출신 이건희 위원입니다.  지금까지 경기개발연구원이 경기비전2006부터 2020까지 수많은 경기도정의 나아갈 방향이라든지 분명한 좌표를 제시해 왔고 동북아 중심의 세계 속의 경기도를 만들어 가는데도 가장 큰 핵심 싱크탱크 역할을 해왔습니다.  제가 기획위원회 3년째 이제 와서 연구원의 정관이라든지 인사보수규정에 관련해서 먼저 1차적으로 한 가지를 묻겠고요.  또 한 가지로는 우리 경기개발연구원의 인력운영에 관해서 두 가지 질의만 하겠습니다.  그리고 또다시 시간이 되면 다른 위원님 하신 다음에 다시 기회를 갖도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  지금 여러분들 잘 아시다시피 지금까지 해온 업적과 성과에 비해서 한현규 원장의 그런 불미스러운 원장 사임으로 인해서 11월 10일에 사직을 하셨는데 차기 원장은 언제쯤 임명될 거라고 생각하는지에 대해서 간단하게 단답형으로 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그것은 이사회에서 결의할 사항이기 때문에 제가 답변드리기는 어렵습니다만 지금 진행된 사항으로 보면 아마 한현규 전 원장 퇴임 후 3주 이내에 새로 원장을 임명하도록 보통 규정은 돼 있습니다.  그렇기 때문에 그 규정 내에 새로운 원장이 임용되는 것으로 저는 알고 있습니다. 
</p>
<p><b>○ 이건희 위원 </b> 연구원의 원장이라든지 부원장 그리고 사무처장이라든지 이런 분들이 연구 외의 다른 목적으로 연구원장에 임명돼서는 안 된다는 생각을 다시 하게 되고요.  먼저 했었던 이철규 원장님도 국회의원 출마로 인해서 사임하게 됐고 이번에는 어떤 좋지 않은 불미스러운 일로 인해서 본의 아니게 사직을 하게 됐는데 제가 이 말씀을 왜 드리냐면 이 원을 끌고 나가는 원장중심체제로 돼 있고 물론 도정과 손 지사라든지 여러 가지 같이 가야 될 입장인데 지금 보게 되면 한현규 원장이 임명되고 그 다음에 현재 김태승 부원장이 지난 3월에 임명됐습니다.  그랬을 때 갑작스럽게 원장님이 이렇게 유고되고 다시 부원장이 이것을 끌어나갈 때 이 두 분들이 과연 지속적으로 이 연구활동을 하게끔 리드해 나갈 수 있겠는가 하는 문제를 제기 하고요.
</p>
<p style="padding-left:1.2em">  제가 이렇게 질의드리겠습니다.  지금 현재 정관 인사규정에 보면 원장, 부원장, 사무처장을 외부에서 영입하게 돼 있는데, 제가 봤을 때 원장만큼은, 물론 도정에 지사 당선자와 동행한다는 의미에서 정책적인, 거기까지는 인정할 수 있겠지만 부원장이나, 지금 김태승 부원장님이 잘못해서 이런 질의드리는 것은 아닙니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 감사합니다.
</p>
<p><b>○ 이건희 위원 </b> 부원장이라든지 사무처장 이런 부분들은 자체 정관 인사규정을 바꿔서라도 자체승진해야 된다고 보는데 거기에 대해서는 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 이건희 위원님께서 굉장히 귀중한 질의를 해주셨는데요.  실제로 저희 연구원이 설립된 지 10년입니다.  10년이면 사람 나이로는 어린 나이입니다만 연구원 입장에서 보면 굉장히 성숙한 나이가 됐습니다.  따라서 이 정도 나이가 되면 이제 연구원 원내에서 자체적으로 연구원 경영까지도 책임질 나이가 됐다고 생각합니다.  그런 점에서 이건희 위원께서 말씀하신 대로 이제 저희 연구원도 내부적으로 행정이든 연구분야든 간에, 예를 들면 제가 지금 담고 있는 연구원 부원장 자리도 제 개인적인 희망이기도 합니다만 저 그만둘 때는 연구원 내부에서 승진해서 연구원이 보다 안정화되고 자체적으로 자기순환구조를 가질 수 있도록 하는 게 맞다고 저는 생각하고요.  앞으로 이런 것이 필요하다면 제가 이사회에, 그리고 제가 말할 기회가 있는 곳에 가서 이게 반드시 필요하다고 말씀드리도록 하겠습니다.
</p>
<p><b>○ 이건희 위원 </b> 지금까지 해온 것에 대해서는 감사를 중점적으로 이따가 하겠지만 지금 현재 여기 규정에 보게 되면 467페이지 21조에 이사회는 연구원에 물론 예산결산, 재산의 취득ㆍ처분 등 그리고 정관에 대한 개정을 하게 돼 있고 그 외에 많은 것은 생략하겠고요.  470페이지 제8장 보칙에 보면 “정관의 변경”은 “이 정관을 변경하고자 할 때는 이사회의 의결을 거쳐 경기도지사의 승인을 얻어서 이것을 바꿔나갈 수 있다”고 하는데 우리 지사님과 원장을 통해서 임명받으신 김태승 부원장께서는 여기에 대해서, 이번 행정감사를 통해 지적된 이 부분에 대해서 지사님께 아니면 이사회에 제 의견을, 이와 같은 것을 상정해서 바꿔나갈 용의가 있습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 저희 연구원의 정기 이사회가 12월로 잡혀져 있습니다.  거기에는 이사장이 바로 경기도지사이시기 때문에 경기도지사를 포함한 모든 이사들이 참여하실 거라고 생각합니다.  그때 가서 만일 저한테 그런 기회가 주어진다면 저는 제 나름대로 적극적으로 이런 제도의 개편 필요성에 대해서 충분히 제 의견을 개진하도록 하겠습니다. 
</p>
<p><b>○ 이건희 위원 </b> 그리고 연구원들의 인력운영에 관해서 한 가지 더 질의를 하겠습니다.  지금 현재 저희 연구원에 있는 인원수가 한 150여명 되지 않습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이건희 위원 </b> 그런데 여기에 일반 업체로 말하거나 회사로 말하면 정규직이 한 70여명 정도 되고 과반수가 넘는 인원이 말 그대로 계약직입니다.  계약직 종류가 초빙연구원, 비상임연구원, 비상임정책연구원, 위촉직으로 돼 있는데 제가 어저께 위촉직 되시는 모 연구원하고 통화해 보니까 그리고 여기 나와 있는 자료를 보니까 한 달에 급여가 150～160만원뿐이 안 됩니다.  물론 이분들이 유수의 대학, 대학원까지 나오고 그랬는데 물론 우리 경기도정의 프로젝트로 봤을 때 어떤 정해져있는 환경, 교육부분 이런 것이 아닌 그때그때 올라오는 현안들도 많고 과제가 바뀔 때마다 인력수요 충원을 달리 해야 될 거라는 생각을 갖습니다만 이렇게 초빙, 위촉에 대해서 너무 많은 것을 하다보면 이 연구과제에 대해서 어떤 책임감이라든지 경기도정을 움직여 나가는 데 필요한 자료를 만드는 데서 주인의식 같은 것이 결여돼서 어떤 이는 과제물에 대한 부실한 면이 있을 수 있다 이런 생각이 드는데 거기에 대해서 말씀을 한번 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 이것도 저희 연구원 입장에서는 아픈 이야기인데요.  저희 연구원의 현재 구조가 정규직이 연구직, 관리직 포함해서 71명이고요.  그 다음에 소위 계약직이 78명입니다.  실제로 계약직이 오히려 정규직보다 더 많은 상황입니다.  또한 이건희 위원님께서 지적해 주신 것처럼 계약직의 처우수준이 경력에 따라서 연구원 같은 경우는 150에서 180정도를 받고 있습니다.  실제 사회적으로 보면 본인들이 거의 대부분 석사학위 소유자이기 때문에 본인들이 받은 사회적 교육에 비해서 굉장히 나쁜 열악한 환경인 것만은 틀림없고요.  이 부분에 대해서 저희들 나름대로 사실은 연구원 내부적으로도 굉장히 많은 고민을 합니다.  그래서 지금 현재도 저희 연구원 내부에 이런 처우문제와 관련해서 어떤 공통의 답을 찾아보기 위해서 정규직뿐만 아니라 계약직까지 다 포함된 태스크포스팀을 운영해서 금년 말까지 답을 내도록 노력하고 있습니다.  그리고 저희들 나름대로 굉장히 알고 있고, 하지만 또 실제로 기존에, 죄송한 얘기지만…….
</p>
<p><b>○ 이건희 위원 </b> 됐고요.  그러니까 지금 현재 이런 초빙, 비상임연구원이라든지 위촉 직원들에 대해서 지금 제가 보니까 관리규정이라든지 정관을 보니까 한 원장에 대해서 권한이 너무 많이 돼 있지 않나.  물론 이게 도정에 관련한 연구소와 일반 연구소와는 다른 측면이 있습니다만 그러면 이것을 과연 이사회에서 지금 제가 지적했던 원장 외에 부원장이라든지 사무처장이라든지 이런 부분에 대한 자체승진 문제나 그리고 연구원들 여러 부분이 있지만 그분들에 대한 제 임용규정 같은 것들이 제가 봤을 때는 명확하지가 않아요.  어떤 분을 또 재위임하고 필요에 의해서 이런 것들이 명확하지 않기 때문에 어쩌면 우리가 내년도에도 97억 정도의 예산을 지원하고 있고 작년도에도 그보다 조금 적은 돈을 지원했다는 것으로 알고 있는데 이런 많은 예산을 들여서 세계 속에 중심되는 경기도, 우리가 사실 4분의 1 정도 되는 중심체이고 제일 큰 연구소를 자부하면서 이런 것들이 명확하지 않아서, 저는 이게 어떤 효율적인 운영을 떠나서 어떻게 하면 이게 중단되지 않을까 하는 그리고 차질없이 과제 수행하려면 이러한 부분에 대해서 명확한 규정을 바꾸든지 정관을 바꾸는 그런 노력을 자체에서 해야 될 것으로 알고 있는데 거기에 대해서 답변해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 이건희 위원님께서 지적하신 사항의 본뜻은 제가 정확하게 알겠고요.  다만, 저희 이사회의 토의사항 범위는 없습니다.  따라서 이게 만일 중요한 문제라고 생각한다면 이사들께서 의견개진을 하시고 그것에 대해서 저희 연구원에 충분히 권고 내지는 명령을 할 수 있다고 생각합니다.  그런 문제가 발생해서 권고명령이 있다면 저희들 입장에서는 적극적으로, 저희들이 수동적이나 피동적으로 마지못해서 하는 것이 아니라 적극적으로 비정규직 문제에 대해서 처리해 나가도록 노력하겠고요.  다만, 두 가지만 말씀드린다면 비정규직의 재계약만큼은 저희 규정에 정확하게 돼 있습니다.  계약직의 계약이 끝나면 그것에 대해서 평가를 하고 평가결과에 따라서 다음 과제의 재계약 여부를 결정하게 돼 있고요.  또 한 가지만 더 말씀드리면 이것은 경우에 따라서 이건희 위원님께서 지적해 주신 바로 그 계약직 직원들이 좀 서운해 할까봐 말씀드립니다만 저희 연구원의 비정규직들이 비정규직이기 때문에 책임감이 없거나 아니면 주인의식을 갖지 않고 일하고 있다고는 저는 절대 생각하지 않습니다. 
</p>
<p><b>○ 이건희 위원 </b> 저도 거기까지는 생각 안 했는데 그런 것들이 좀더 나아질 수 있다는 생각이 들고요.  하여튼 제가 두 가지 지적한 사항에 대해서 확실하게 다음 이사회 때라든지 이런 것을 명확하게 해서 우리 경기개발연구원에서 무수히 많이 연구하고 과제 정리하고 앞으로 향후문제도 큰 광교테크노밸리 같은 R&D지구 조성 이런 방안이라든지 아니면 심지어 제 지역의 광주비전2020 중장기 종합발전계획 등 수많은 과제들을 전 분야에서 하고 계시는데 이번 일로 인해서 경기개발연구원이 불명예스러운 것은 우리 경기도 전체가 불명예스럽다는 생각도 갖습니다.  저도 의원으로서 그런 부분에 대해서 부끄럽게 생각하는 것이 있는데 앞으로 좀더 우리 경기개발연구원이 의지를 가지고, 그런 일이 또다시 일어나지 않겠지만 함께 잘 해서 이런 일이 없도록 하고 경기개발연구원이 더 성숙됐으면 하는 바람입니다.  저는 이상으로 마치겠습니다. 
</p>
<p><b>○ 위원장 정인영 </b> 이건희 위원 수고하셨습니다.  다음 질의하실 위원께서는 질의해 주시기 바랍니다.  이흥규 위원 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이흥규 위원 </b> 이흥규 위원입니다.  먼저 원장님 관계로 해서 우리 직원들이 많이 의기소침해졌으리라 믿으면서 그동안 많은 업적을 내주신 경기개발연구원이 본연의 자세로 돌아가서 더욱 열심히 해주실 것을 당부드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그러면 먼저 우리 부원장님께 질의를 드리겠습니다.  경기개발연구원의 부원장제도가 없어졌다가 다시 생긴 것을 알고 계시지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 임용된 후에 들었습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 왜 없어졌는지 아십니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그것은 잘 모르겠습니다.  
</p>
<p><b>○ 이흥규 위원 </b> 그러면 사무처장님 나오셔서 답변해 주시겠어요?
</p>
<p><b>○ 사무처장 이강수 </b> 사무처장 이강수입니다.
</p>
<p><b>○ 위원장 정인영 </b> 발언대로 나와서 소속과 직, 성명을 밝히고 답변해 주시기 바랍니다.
</p>
<p><b>○ 사무처장 이강수 </b> 사무처장 이강수입니다.  부원장제도가 계속 있었는데 그동안에 부원장을 마땅한 사람을 오랫동안 선임하지 못하고 공석으로 있었던 관계로 해서 중간에 이 제도를 없앤 것으로 알고 있습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 사무처장님 말씀 맞아요?  다시 한 번 확실하게 얘기해 주세요.
</p>
<p><b>○ 사무처장 이강수 </b> 제도가 그동안에 있었는데…….
</p>
<p><b>○ 이흥규 위원 </b> 모르시면 정확하게 모른다고 말씀해 주시고요.  대충 추정해서 답변하시지 말고 확실히 답변해 주시기 바랍니다. 
</p>
<p><b>○ 사무처장 이강수 </b> 제가 오기 전의 일이었습니다.  그래서 사실은 확실하게 알지 못합니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그게 낫겠지요.  2004년도 7월 28일에 제42차 임시이사회에서 경기도정 및 연구운행에 따른 자문과 지원을 위하여 상임자문위원 직제를 신설하면서 부원장과 고문직제를 폐지했습니다. 
</p>
<p><b>○ 사무처장 이강수 </b> 네, 맞습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그렇게 답변해 주셔야지 어떻게 공석이었기 때문에 부원장제도를 폐지했다는 답변은 동떨어진 얘기지요.  
</p>
<p><b>○ 사무처장 이강수 </b> 상임자문위원제도의 신설과 부원장제도의 폐지가 반드시 매치되는 것이라고 꼭 볼 수는 없었던 것 같습니다.  
</p>
<p><b>○ 이흥규 위원 </b> 그때 이사회에서 결정된 것은 맞지요?  그것은 아시고 계십니까?  
</p>
<p><b>○ 사무처장 이강수 </b> 네, 그렇습니다.  
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 2004년도 7월 28일에 임시이사회에서 상임자문위원 직제를 신설하면서 부원장과 고문 직제를 폐지 의결했습니다.  그런데 2005년도 3월 5일 불과 7개월만에 임시이사회에서 연구원 내부를 원활히 통제하고 원장의 대외적인 활동을 도울 수 있도록 각 연구부서를 총괄해 통제할 수 있는 부원장 직제를 다시 신설했습니다.  부원장 직제를 부활시킨 정당한 사유는 무엇인지 처장님 답변하실 수 있겠어요?
</p>
<p><b>○ 사무처장 이강수 </b> 이사회의 결정사항이었고 지금 가지고 계신 자료 외에 제가 다른 덧붙일 말씀은 없습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그러면 어떻게 행정의 연속인데 있는 직제를 없애고 또 7개월만에 다시 생기느냐, 이 부분은 누가 답변해 주시겠습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 제가 말씀드리겠습니다.  부원장 직제 신설여부에 대해 답변의 한계가 있음을 우선 양해를 해주셨으면 감사하겠습니다.  저희들이 하필이면 이 안에 이사회에 들어갈 자격이 있는 사람이 한 명도 없기 때문에 이사회에서 어떤 취지를 가지고 그렇게 결의를 했는지 알 길은 없으나 저희들 나름대로 판단하기는 그렇다고 생각합니다.  제도가 생겼다가 없어졌고 다시 생길 수 있는 부분들이 경우에 따라서 존재할 수는 있을 텐데 저희 연구원 같은 경우는 실제로 제가 들어와서 듣기에 작년 7월에 상임자문위원이 생겼다가 금년 연초에 전 한현규 원장의 업무수행 과정 속에서 부원장의 필요성이 있다라는 한현규 원장의 건의가 있었다고 들었습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 부원장님 답변 잘 들었습니다.  물론 직제라고 하는 것이 폐지됐다 생길 수도 있습니다.  그런데 문제는 연구원 내부를 원활히 통제하고 원장의 대외적 활동을 도울 수 있도록 각 연구부를 총괄해서 통제할 수 있는 부원장 직제를 다시 신설했는데 외부인사를 기용했거든요.  이게 도저히 앞뒤가 맞지 않는다.  죄송한 질의입니다만 우리 부원장님께서는 손학규 지사님과 어떤 관계시죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 예전부터 알고 지내는 사이입니다.
</p>
<p><b>○ 이흥규 위원 </b> 어떻게 알고 계신지 구체적으로 말씀할 수 없겠습니까?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 1993년부터 1996년까지 손학규 의원이 초선의원 시절에 거기 보좌진으로 있었습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 네, 감사합니다.  아무튼 이 부분이 당초 목적대로 내부를 원활히 통제하고자 했는데 외부인사를 영입했다는 부분이 납득이 가지 않고요.  경기개발연구원 인사관리 규정에 부원장은 직원으로서 이사장의 승인을 얻어 원장이 임용하는 것으로 되어 있고 직원의 신규임용은 공개채용시험에 의한 일반임용을 원칙으로 하되 인사위원회의 심의를 거쳐 특별임용도 가능하도록 되어 있습니다.  직원의 신규임용은 자격기준에 근거하여 임용하도록 되어 있는데 사무처장, 연구직 등은 신규임용 자격기준을 마련하여 동 기준에 의거 임용하고 있으나 부원장에 대한 신규임용 자격기준은 제반자료를 검토한 바 마련되어 있지 않습니다.  이 부분에 대해서는 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 부원장도 저희 연구원의 직제규정상으로는 직원이기 때문에 일반연구원의 채용절차를 준용한다고 저는 생각하고 있습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 부원장제도를 새로 만들면서 그 부분을 만들지도 않고 사람을 지정해 놓고 부원장 직제를 편성했다고 하는 부분이 증명이 되는 것이죠.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 아니요.  지금 저희 정관에는 정확하게 원장을 제외한 나머지는 직원으로 돼 있고요.  직원의 임용규정이 있습니다.  지금 이 위원님께서 말씀하신 대로 직원은 보통 정규채용을 하고 필요한 경우에 특채로 하도록 돼 있습니다.  
</p>
<p><b>○ 이흥규 위원 </b> 그러면 2005년 3월 10일자로 신규임용된 현 부원장님은 어떤 자격기준을 근거로 특별채용 했는지…….
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 제가 제 말씀을 드려야 될지 어떨지는 모르겠습니다만 저는 제 나름대로 과거에 다른 직장에도 있었습니다만 연구기관에 15년 동안 근무했습니다.  국토연구원, 교통개발연구원에 근무를 했고요.  아마 저희 연구원 이사회에서 저를 임용했을 때는 우리 연구원 부원장으로서 자격기준이 있다고 생각해서 임용한 것으로 저는 알고 있고요.  저는 이 연구원에 와서 연구원 부원장으로서 제가 할 일에 대해서 최선을 다했다고 생각합니다. 
</p>
<p><b>○ 이흥규 위원 </b> 부원장님이 자격이 없다고 하는 부분이 아니라 연구기관에 계신 것도 제가 자료검토 했고요.  충분한 자격이 있으신 것은 인정합니다.  그러나 채용을 할 적에는 공정하게 공개채용을 해야 하는데 그렇지 못한 점을 지적해 드리는 겁니다.  아무튼 그 부분은 이 정도까지만 하고요.  경기개발연구원의 기능은 업무보고에 의하면 도정의 중ㆍ장기 비전제시와 정책개발 지원에 있다라고 되어 있습니다.  그러면 한류우드와 관련해서 질의드리겠습니다.  한류우드 관련 용역위탁기관은 경기도가 맞습니까, 경기관광공사가 맞습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 담당 실무자한테 답변드리도록 하겠습니다.
</p>
<p><b>○ 이흥규 위원 </b> 그렇게 하시죠.
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 경기개발연구원 경제사회연구부 김흥식입니다.  지금 질의주신 내용은 계약의 주체는 경기관광공사가 맞습니다.  경기관광공사에서 3억원의 예산을 책정해서 저희 연구원기관과 수의계약으로써 계약을 했습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그러면 경기관광공사가 위탁기관이다 이거죠?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 네.
</p>
<p><b>○ 이흥규 위원 </b> 경기도하고는 어떤 관계가 있습니까? 
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 그것은 본질적으로 경기도와 경기관광공사의 어떤 관계라는 것은 저희 연구기관과 마찬가지로 경기관광공사는 산하기관으로서 돼 있는 부분이고, 물론 경기관광공사와 마찬가지로 경기도도 한류우드에 주체적으로 참여할 수 있는 기관이기 때문에 긴밀한 협조관계로 이루어져 있다고 생각하고 있습니다.
</p>
<p><b>○ 이흥규 위원 </b> 본 위원이 자료를 살피다 보니까 경기도가 주관인지 경기관광공사가 주관인지 아니면 경기개발연구원이 주관인지 이 부분이 혼돈이 되더라고요.
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 저희가 정책적으로 한류우드의 활성화라든가 부지공급계획과 관련돼서 정책적인 연구를 하는 책임을 맡고 있고요.  경기관광공사가 일부 한류우드에 선도호텔이라든가 이런 쪽에 주체적인 사업을 주도적으로 하려는 계획을 갖고 있는 부분이 있습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 알았고요.  주관이 뚜렷하지 못하고 서로 한류우드를 가지고 자기가 전부 주관인 것인 양 생각하는 것이 본 위원이 자료를 검토해 봤을 때는 그렇고요.  용역중간보고서가 몇 개가 있습니까? 
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 중간보고서가 8월, 9월에 1권, 2권해서 두 차례 중간보고서가 유인이 됐습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 본 위원이 경기도가 관광공사로 보낸 자료에 보면 1차 중간보고서가 9월 2일, 2차 중간보고서가 9월 21일, 3차 중간보고서가 9월 26일 이렇게 있었는데 3차 중간보고서는 어디로 갔습니까? 
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 3차 중간보고서는 보고서 형태로 나간 것은 아니고요.  파일 형태로 해서 가편집 형태로 지금 나가 있는, 공식적으로 나가있는 부분은 아닙니다. 
</p>
<p><b>○ 이흥규 위원 </b> 3차 중간보고서를 달라고 하니까 없다고 하는데 왜 자료를 안 주시는 거죠?  
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 지금 그 부분에 있어서는 일단 2차 중간보고 결과에 따라서 조금 보안이 돼 있는 그런 부분이었기 때문에…….
</p>
<p><b>○ 이흥규 위원 </b> 어떤 보안에 의해서 위원이 자료요구를 했는데 자료제출을 못하냐  이거죠.  “이러이러해서 자료제출을 못합니다”가 아니라 “없다”고 했거든요.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 자료요구와 관련해서 제가 간단하게 답변드리겠습니다.  정말 죄송한 이야기인데요.  많은 분들이 저희 연구원의 수탁용역보고서를 저희한테 보통 달라고 말씀하십니다.  하지만 저희도 수탁이라고 하는 것은 공기업과 수탁을 하든 도하고 수탁을 하든 간에 그것은 계약행위이기 때문에 그 과제보고서가 중간보고서가 됐든 최종보고서가 됐든 그것은 소유기관이 위탁기관이 됩니다.  그렇기 때문에 저희의 의무상 그게 대외비로 돼 있든 공개된 보고서든 간에 보고서를 주는 것은 위탁기관의 허가를 맡아야 됩니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그것은 변명에 지나지 않는 게 뭐냐 하면 1차, 2차 중간보고서는 주셨지 않습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 만약 위원님께 드렸다면 저희 연구원이 실수한 겁니다. 
</p>
<p><b>○ 이흥규 위원 </b> 부원장님, 그렇게 하실 거예요?  위원이 자료요구 하는데 그것에 대한 자료를 못 준다는 얘기입니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 자료요구는 정말 죄송하지만 수탁과제에 대해서는 저희들이 철저하게 관리해야 된다고 생각합니다.  
</p>
<p><b>○ 이흥규 위원 </b> 조금 전에 실무진께서 경기도와 경기관광공사, 경기개발연구원의 관계가 어떤 관계라고 대답하셨죠?  제가 질의하는 것은 1차, 2차, 3차가 있는데 3차 보고서를 달라고, 제가 처음에는 보고서를 달라고 의뢰를 했더니 1차, 2차가 와서 제가 서류를 들춰보니까 3차 보고서가 또 나오더라고요.  그래서 3차 보고서를 달라고 요청을 했습니다.  “3차 보고서는 아직 나오지 않았습니다”, “없습니다”라고 했거든요.  그러면 제가 이것은 공문에 의한 거거든요.  경기도가 공문을 발송한 내용이거든요.  경기도에 있는 직원이 아무 것도 안 보고 했을리는 없다 이거죠.  그러면 경기개발연구원은 위원한테는 없다고 했는데 있는 것이 증명된 것 아닙니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 3차 보고서는 있을 거라고 저는 정황적으로 판단을 하는데요.  만일 3차 보고서를 위원님께서 필요하시다고 한다면 저희가 경기관광공사에 확인 후에, 드려도 좋다고 이야기하면 드리도록 하겠습니다.
</p>
<p><b>○ 이흥규 위원 </b> 위원장님, 그러면 보고서 올 때까지 기다려야 됩니까? 
</p>
<p><b>○ 위원장 정인영 </b> 보고서 관계는 지금 부원장이 답변을 잘못하고 있는 것 같습니다.  위탁기관의 승인을 받아서 줘야 되지만 의회에서 자료를 요구할 때는 경기도뿐만 아니라 산하기관과 시ㆍ군 포함해서 요청하는 것이기 때문에 어떠한 자료도 위원에게는 제출해야 되는 것으로 알고 있습니다.  그래서 제출해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 제가 과문한 탓인지 모르겠습니다만 실제로 제가 그전에 있던 직장이 국토연구원인데요.  거기에서도 수탁과제에 대해서는 발주처의 허가를 득하지 않은 상태에서는 실제로 국회에도 보고서를 제출 안 해왔습니다.   
</p>
<p><b>○ 이흥규 위원 </b> 이것이 경기도와 무관한 다른 연구과제라고 한다면 부원장님 말씀이 맞겠죠.  이것은 경기도와 밀접한 관계가 있고 많은 주민들이 의혹을 갖고 있는 문제거든요.  이 문제를 가지고 위원이 자료요구를 한다는데 그렇게 얘기하시는 것은 문제가 있지 않습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 위원님의 취지를 정확히 알기 때문에 제가 충분히 이해를…….
</p>
<p><b>○ 이흥규 위원 </b> 그렇다면 1차, 2차 자료를 준 근거는 무엇이고 그것에 따라 달라는 겁니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 취지를 제가 충분히 이해를 하기 때문에 만일 위원님께서 필요하시다고 한다면 제가…….
</p>
<p><b>○ 이흥규 위원 </b> 제가 왜 그걸 보고싶냐면 여기 공문에 보면 “1차 중간보고서와 3차 중간보고서 간에는 동일한 용역이라고 보기 어려울 정도로 현저한 내용 차이가 있음” 이렇게 돼 있거든요.  그런데 어떻게 이걸 안 보냐고요.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 지금 필요하시다고 그러신다면 경기관광공사…….
</p>
<p><b>○ 이흥규 위원 </b> 이것은 의도적으로 위원의 행정사무감사를 막고자 하는 그런 의도가 충분하게 있다.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 다시 한 번 말씀드리지만 지금 만일 필요하시다고 한다면 제가 경기관광공사하고 지금 당장이라도 문의해서 발주기관에서 허가를 하면 바로 드리도록 하겠습니다.
</p>
<p><b>○ 이흥규 위원 </b> 물론 당장 주셔야 되겠고요.  위원이 귀신입니까?  지금 자료를 금방 준다고 해서 기술적인 부분을 금방 보고 행정사무감사를 하는 부분이, 저는 사실 귀신띠가 아니거든요.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 죄송합니다. 
</p>
<p><b>○ 이흥규 위원 </b> 이렇게 위원의 행정사무감사를 막는다고 한다면 우리 도의원들이 의정활동을 어떻게 하느냐 이겁니다.  사실 보좌인력도 없이 이 자료 다 못 봤습니다.  잠깐만 봐도, 제가 전문지식이 없는 위원 입장에서 잠깐만 봐도 오해가 가는 부분이 많이 있다 이겁니다.  그런 부분을 전문가 집단인 경기개발연구원에서 우리 일반인이 쉽게 이해할 수 있도록 자료요구 했으면 담당연구원이든 해서 무엇을 궁금해 하는지, 그래서 질의도 줄여주고 하는 것이 적극적인 자세이지 자료 달라면 “그래, 하려면 해봐라”하고 주고 중요한 자료는 안 주고 이것이 과연 경기개발연구원의 당당한 자세냐 이겁니다.  자료를 주실 때까지 감사중지를 요구하겠습니다.
</p>
<p><b>○ 위원장 정인영 </b> 이흥규 위원님께서 감사중지를 요청하셨습니다.  잠시 10분간…….
</p>
<p><b>○ 함진규 위원 </b> 의사진행발언 있는데요.  
</p>
<p><b>○ 위원장 정인영 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 이흥규 위원님 말씀은 상당히 타당성이 있습니다.  그렇지만 다른 준비하신 위원들도 계시기 때문에 다른 준비하신 위원들은 하는 게 좋지 않겠습니까? 
</p>
<p><b>○ 위원장 정인영 </b> 지금 의사진행발언으로 함진규 위원께서 감사를 계속 하자고 하는 의견이 있었습니다.  현실적으로 자료를 요청해서 도착할 때까지는, 원칙은 위탁기관의 자료는 열람하도록 돼 있습니다.  그리고 외부위탁이 아니고 전부 경기도의 산하단체이기 때문에 그런 자료들은 충분히 제출해야 된다고 보는데 지금 현실적으로 자료가 온다고 하더라도 많은 시간이 할애되기 때문에 이흥규 위원님께서 양해해 주신다면 이 문제는 오후에 다시 한 번 다루기로 하고 계속 감사를 해주셨으면 좋겠습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 제가 계속 하겠습니다.  그러면 1차와 3차와의 중간보고서가 현저한 내용 차가 있다는데 그 내용을 설명해 주십시오. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그것은 실무자한테 설명하도록 하겠습니다.
</p>
<p><b>○ 이흥규 위원 </b> 네, 설명해 주세요.
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 경제사회연구부 김흥식입니다.
</p>
<p><b>○ 이흥규 위원 </b> 답변하기 전에 1차 용역을 할 때 경기개발연구원의 연구원이 몇 명이었습니까? 
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 연구진을 말씀하시는 겁니까? 
</p>
<p><b>○ 이흥규 위원 </b> 책임연구원들이요.
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 책임연구원은 우리가 수탁과제 등 과제수행을 할 때 연구책임은 한 사람이 되고 공동연구원이 참여하게 돼 있습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 연구책임자하고 공동연구자가 총 몇 명이었습니까?  
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 실질적으로 연구에 투입된 연구원은 4명이, 책임연구원 한 사람 하고 공동연구원 네 사람, 원내에서 박사급이 네 사람 참여하고 있습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 본 위원이 알고 있기로는 책임연구원하고 공동연구원 5명 해서 6명 아닙니까? 
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 지금 석사급이 한 사람이 있고요.  그리고 박사급이 공동연구원으로 4명, 그리고 책임연구원 한 사람 해서…….
</p>
<p><b>○ 이흥규 위원 </b> 본 위원이 알고 있기는 1차 중간보고 나올 적에 연구원이 6명이었는데 2차 보고서 나올 때는 5명으로 된 것 같은데 빠져나간 연구원은 누구입니까?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 실질적으로 연구원에 투입된 것은 제가 연구책임을 맡고 있고요.  공동연구원은 박기완, 그 다음에 자치행정부에 조성호 박사, 경제사회부에 이정훈 박사, 그리고 위촉연구원으로서 최민정, 손나주 이렇게 있습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 또 한 분은요?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 성영조 박사하고 문미성 박사가 원래 연구진에 포함이 돼 있습니다.  원내에서 실질적인 서류상에서는 문미성 박사와 성영조 박사가 참여하고 있는 것으로 돼 있고 실질적으로 연구에 참여하고 있는 박사는 조성호 박사, 박기완 위원, 그리고 이정훈 박사, 저 그리고 최민정, 손나주 이렇게 돼 있습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 1차 연구수립용역을 할 때에 연구진과 지금 2차 연구진의 차이점이 없습니까?  차이점이 있는 것으로 알고 있는데.
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 저희가 1차 때는 실질적인 연구에 참여를 하고 있는 박사들 위주로 기입이 돼 있고요.  두 번째는 저희가 착수계를 제출할 때, 사실 계약하고 착수계를 제출할 때는 기간이 짧기 때문에 연구진을 완전하게 구성하기가 상당히 힘이 듭니다.  그래서 서류상에 우선은 우리가 그때 연구가 4개월로 단기간에 이루어져야 되는 상황이었기 때문에 실제적으로 서류상에서는 실질적으로 연구에 참여하고 있는 사람과 달리 연구진을 편성하는 경우가 있는데요.  그래서 지금 경기관광공사에서 요구하기는 서류상에 연구진으로 해서 보고서에도 유인을 해달라 그렇게 해서 1차 때와 2차 때의 연구진이 조금 차이가 있는 그런 상황입니다. 
</p>
<p><b>○ 이흥규 위원 </b> 차이나는 연구진 관계를 서류로 제출해 주시고요.  자료제출을 준비하는 동안에 차이점을 설명해 주시죠.
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 가장 큰 차이점이라고 그러면, 가장 중요한 부분이 될 수도 있고요.  한류우드 용지공급과 관련된 부분하고 사업자 공모방안에 대한 검토부분이 가장 큰 차이가 있다고 생각하고 있습니다.  저희 연구진에서 검토하기는 사업자 공모방식에서 가장 중요한 전제조건으로써는 여섯 가지 정도를 저희가 가지고 연구진행을 시켰고요.  여섯 가지 기준이라는 것은 한류시설의 활성화 방안이라든가 특혜논란 방지문제, 그 다음에 개발이익의 환수 부분이 가장 중요한 핵심적인 내용이었기 때문에 그 부분에 있어서 사실은 단일안으로 2차 보고 때는 제출이 됐었고요.  3차 때는 경기도에서 보완해 달라는, 대안의 검토를 다양하게 해달라 그래서 사업공모방안에 대해서 세 가지 대안방식을 제출하게 된 것입니다. 
</p>
<p><b>○ 이흥규 위원 </b> 바로 그점이 본 위원이 궁금하게 생각하는 것이거든요.  경기개발연구원은 연구원인데 연구원에서는 사실 이러이러한 부분이 있어서 연구를 비교해줘야 되고 주관부서에서 그 중에 어느 것을 하나 채택해야 되는데 경기개발연구원은 그 중에서 한 가지만 주장을 했다는 얘기죠.  한 가지만 주장을 했고 그것을 경기도가 다른 것을 비교해줘라 해서 그 다음에 나온 거죠?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 1차적인 것은 대안에 검토부분이 없었고요.  
</p>
<p><b>○ 이흥규 위원 </b> 아니, 본 위원이 얘기하는 것에 맞는지 안 맞는지만 얘기해 주세요.  
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 1차적으로는 대안의 검토가 하나의 최적방안만 제시가 됐었고 그 다음에 중간보고회를 거치면서 경기관광공사와 경기도에서 다른 대안의 검토를 제시해 달라고 해서 세 가지 방안이…….
</p>
<p><b>○ 이흥규 위원 </b> 네, 알겠습니다.  그러면 박기완 연구원께서는 여기에 언제 투입된 겁니까? 
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 지금 시작부터 같이 공동연구로 참여하고 있습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 박기완 연구원이 몇 월에 입사했죠?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 저희가 작년에는, 지금 저희 연구원에 연구원제가 있어서, 작년에는 없었는데 작년부터 아마 근무한 것으로 제가 확실한 내용은 잘 모르겠습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 사무처장님 답변해 주세요.  박기완 연구원이 언제 입사했는지요?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 제가 전해듣기로는 2004년 10월부터 근무했다고 지금 얘기를 하고 있습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 처음부터 관계가 된 겁니까?  
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 용역 시작은 올해 6월부터 원래는 10월까지 한류우드에 관련된 부분이 용역기간이었기 때문에 처음부터 연구원의 공동연구로 투입이 됐던 것입니다. 
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 그러면 지금 SPC 방식이 성공한 예가 있습니까?  경기개발연구원에서 주장하는 방식이 SPC 방식이라고 그러는데 성공한 예요.
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 성공여부보다 저희는 어떤 프로젝트 베이스에 따라서 사실은 사업공모방식도 좀 달라져야 된다고 생각을 하고 있었기 때문에 SPC 방식이 아까 사업공모방식의 기본전제가 되는 그런 부분에 있어서 한류의 활성화라든가 사업기관의 어떤 단축을 통해서 활성화시킬 수 있는 최적의 방안으로써 하나의 안으로 제시했던 그런 부분입니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그것이 하나의 안이 아니라 경기개발연구원은 그것을 결정지어서 넘겨줬거든요.  다른 부분은 연구를 안 하고 그것 하나만 결정해줬으니까 문제가 있다고 보는 겁니다.  연구원이라고 한다면 그것 뿐만 아니라 다른 것도 다 연구를 해서 그 중에서 하나를 채택하게끔 해주는 것이 연구라고 볼 텐데 경기개발연구원은 다른 것은 얘기를 안 하고 그것만 주장을 해서 경기도가 그러면 다른 것도 비교해서 넘겨줘라 라고 해서 3차 보고서 나온 것 아닙니까? 
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 저희가 생각하고 있기로는 매달 저희가 보고서 형태로 제출이 되고 있었고요.  그리고 초기에는 1주일 단위로 연구진 관계관 회의를 했었고 그 다음에 9월부터 2주에 한 번씩 회의를 통해서 의견을 수렴하고 있었기 때문에 그와 같은 부분에 있어서 저희 연구진이 기본적으로 여건이라든가 개발여건이라든가 다른 여러 가지 환경에 대한 검토를 거친 다음에 이와 같은 부분에 대해서 우리가 안을 제시했고요.  그렇기 때문에 2주 단위로 한 번씩 연구진 회의를 했기 때문에 그와 같은 부분에 있어서 보완해야 될 부분은 항상 저희가 보완해서 제출했던 것으로…….
</p>
<p><b>○ 이흥규 위원 </b> 그 부분은 어느 한 쪽에서 일방적으로 주장해서 이렇게 왔다고 봐야죠.  왜냐하면 본 위원이 자료를 살펴보니까 대한국토도시계획학회에서도 사업구도설정에 대해서 SPC 방식이 수입목적의 상가개발에 적용된 사례가 있으나 국가나 지방자치단체의 공공목적의 개발사업에 적용한 예는 없다고 나와 있거든요.  그런 부분을 경기개발연구원이 다른 공공시설에 한 번도 적용 안한 부분을 경기개발연구원이 주장을 했다는 부분도 이해가 안 가지만 할 수도 있겠죠, 학자니까.  할 수도 있는데 그것 하나만 주장했다는 얘기죠.  그것과 다른 것을 비교검토해서 이것이 낫다라고 주장한 것이 아니라 그 부분을 검토 안 했다고 하는 부분이죠.  
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 1차적인 것은 대안에 대한 검토가 미흡했던 부분은 저희 연구진에서 인정했고요.  그렇기 때문에 위탁기관에서 보완을 요청했기 때문에 그래서 저희가 실질적인 어떤 내용은 여러 가지 대안의 검토까지 포함해서 중간보고서 형태로…….
</p>
<p><b>○ 이흥규 위원 </b> 사실 박사님 입장에서 더 자세한 얘기하기 쉽지 않으리라 믿습니다.  제가 충분하게 이해를 하고요.  이 부분은 경기개발연구원이 본연의 자세를 벗어나서 한류우드 사업의 주체가 되고자 하는 그런 의도가 있었다고 보는 것이죠.  그렇기 때문에 경기개발연구원장에 손학규 도지사의 최측근을 앉혀놓고 그래도 박사님들이 말을 잘 안 들으니까 그 다음에 부원장까지 앉혔고 그래도 잘 안 되니까 책임정책연구원을 여기다 해서 강력하게 그 의견을 따라서 이대로 간 것이 아니냐.  답변하기 곤란하시겠죠, 그 부분은?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 모르겠습니다.  그 부분에 대해서 제가 말씀드릴 수 있는 부분까지만 말씀드리겠습니다.  저희 연구자의 입장에서 사실 그런 부분까지 고려해서 연구를 진행시키고 있지는 않았습니다.  지금까지 그렇게 해오지도 않았고요.  저희가 그런 부분에 있어서, 위탁기관에서 요구했던 부분에 대해 사전에 어떤 대안검토라든가 이런 부분이 좀 미흡했던 부분은 인정을 하고요.  그 이후에 연구관계관 회의를 통해서 제시됐던 문제점에 대해서 시정하려고 최선의 노력을 하고 있고 최선의 사업공모방식이 어떤 것인가에 대해서 공동연구진과 함께 노력을 계속 하고 있습니다.  
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 경기개발연구원이 연구원 본연의 자세로 돌아갔으면 하는 그런 주문을 하고 싶습니다.  이것이 우리 박사님께서 순수한 의미에서 그렇게 연구를 하셨다고 하더라도 지금 결과론적인 얘기지만 전 원장이신 한현규 원장님이 지금 이렇게 된 마당에서 보면 무관하다고 단정지을 수 없는 것 아닙니까?  박사님들 말씀 그대로 받아들이고 싶습니다.  그러나 그렇게 생각하는 것이 일반 경기도민들의 생각입니다.  그래서 경기개발연구원이 정치기관의, 어느 도지사의 하수기관으로 전락하지 마시고 연구원 본연의 자세로 돌아가 주시기를 부탁드리겠습니다.  그리고 부원장님 하실 말씀 있으세요? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그 부분에 대해서 제가 간단히 조금만 답변드리겠습니다.  
</p>
<p><b>○ 이흥규 위원 </b> 네, 답변해 보시지요.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 여러 가지 많은 오해와 억측이 있을 수 있고 그 다음에 그 부분들이 저희들한테 지적되는 것에 대해서 저희들은 달게 받아들이고요.  모든 것에 대해서 저희들이 연구내용적으로 잘못된 것이 있으면 최선을 다해서 책임을 지고 앞으로 개선해 나가겠습니다.  다만 전임 원장과 관련된 얘기들이 되고 있습니다만 실제로 한류우드과제 같은 경우는 지금 과제가 종료되지도 않은 상태입니다.  따라서 지금부터라도 이 위원님 말씀대로 대안이 제대로 형성이 안 돼 있다면, 실제로 저도 그 내용은 계속 보고받아서 알고 있습니다만 이 대안이 맞는지 저 대안이 맞는지 장단점을 맞춰서 객관적인 답을 가지고 결론을 내도록 하겠습니다.
</p>
<p><b>○ 이흥규 위원 </b> 네.  연구기관은 손학규 도지사님이 도정을 펼치는 데 있어서 객관성 있고 보편타당성 있게 갈 수 있게끔 잘못되지 않도록 연구를 해줘야 되는데, 그것을 비교검토해서 연구자료를 줘야 되는데 어느 한 가지를 해서 연구자료를 냈다는 부분은 커다란 문제점이 있다고 봅니다.  그 부분을 더군다나 경기도나 일반 도민들도 많은 이의제기를 했음에도 불구하고 경기개발연구원은 계속 주장했다는 부분, 그리고 이거와 관련해서, 부원장님이 더 이상 얘기 안 하시니까 저도 더는 안 들어가겠습니다만 이 부분에 대해서 도민들의, 지금 부원장님 말씀대로 많은 억측, 그것이 억측일지 사실일지 모르지만 아무튼 많은 구설수가 있다는 것은 사실입니다.  이와 같이 아까 이건희 위원님도 잠깐 말씀하셨습니다만 판교IT의 메모리얼파크인가 거기의 부지문제에서도 경기개발연구원은 유난스럽게 한 지역만 가지고 고집을 했다고 하는 얘기도 있습니다.  이런 것을 봤을 때 경기개발연구원이 빨리 본연의 자세로 돌아가기를 촉구합니다.  이상입니다.
</p>
<p><b>○ 위원장 정인영 </b> 이흥규 위원 수고하셨습니다.  위원님들께 양해말씀을 드리겠습니다.  행정사무감사 기간 중 중식시간이 되었습니다.  따라서 중식 후에 계속 감사하고자 하는데 이의 없습니까?
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 중식과 휴식을 위하여 14시까지 감사를 중지하겠습니다. 
</p>
<p class=''ar''>(12시05분 감사중지)
</p>
<p class=''ar''>(14시04분 감사계속)
</p>
<p><b>○ 위원장 정인영 </b> 좌석을 정돈해 주시기 바랍니다.  감사를 계속하겠습니다.  계속해서 감사 질의답변을 진행토록 하겠습니다.  그러면 질의하실 위원 계시면 거수로 신청하여 주시기 바랍니다.  장정은 위원 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 장정은 위원 </b> 성남 출신 장정은 위원입니다.  지금 현재 여러 가지로 행정사무감사 자료 준비해 주신다고 고생 많으셨고요.  오전에 답변해 주신다고 고생 많으셨는데 제가 경기개발연구원에 대해서는 굉장히 기대를 갖고 와봤습니다.  와봤는데 여러 가지 자료부분에서는 충분히 준비를 하신 것 같지만 제가 봐서는 이 자료를 통해서 볼 수 있는 내용들이 많지 않은 것 같아요.  그 부분이 안타깝고요.  제가 기획위원회에 있기 전에 보사환경여성위원회에서 위원을 하고 있었는데 지금은 우리 경기도 보건정책에 대해서 여쭤보겠습니다.  보건정책에 대해서 우리 경기개발연구원에서 어떤 정책을 연구해야 되느냐 라든지 어떤 정책을 우리 경기도에서 해야 된다 라든지 그런 연구성과는 전혀 없고요.  거기에 대해서 몇 가지 질의드립니다.
</p>
<p style="padding-left:1.2em">  2004년, 2005년 연구과제 추진실적이나 연구실적 그리고 2006년도 연구수행계획을 검토해 봐도 장애인 복지정책이나 노인문제나 그 외에 소외되기 쉽거나 취약한 계층에 대한 연구가 전혀 없거든요.  실질적으로 부서도 없는 것 같아요.  아무리 찾아봐도 보건복지에 대한 컨셉이 전혀 없다는 것에 대해서 어떻게 받아들여야 될지, 우리 경기도의 복지정책은 정말 필요 없는 것을 하고 있는 건지, 또 우리 경기개발연구원에서 거기에 대한 관심이 없는 건지, 아까 제가 한 분한테 여쭤봤더니 연구원을 못 구해서 아직 안 됐다는 이야기를 하는데 참 가슴이 답답하거든요.  실질적으로 전년도 행정사무감사에도 이 이야기가 나온 것으로 알고 있습니다.  저희 동료 위원님께서 질의를 한 것으로 알고 있고요.  그때 원장님께서 연구원이 부족해서 채용해서 해결하겠다고 하셨는데 1년이 지난 지금 상황에서는 작년과 달라진 게 하나도 없다고 봐지거든요.  이 부분에 대해서 답변 좀 해주시겠습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 장정은 위원님께서 말씀하신 그 부분에 대해서 정말 송구스럽게 생각합니다.  저희들 나름대로도 2004년 중반기까지는 보건복지 쪽 담당 박사가 있었는데 그 박사가 나가고 난 다음에 저희들 나름대로는, 우선 저희 입장에서 복지분야 없이 경기개발연구원이 존재할 수 있다고 생각하지 않습니다.  그렇기 때문에 복지분야가 반드시 필요하다고 생각하고 있고 최근에 가족여성연구원이 생겼습니다만 그것과 무관하게, 그것과 보완적인 차원에서도 복지분야의 연구직이 반드시 필요하다고 생각합니다.  다만, 담당하던 박사가 나가고 난 다음에 그 후로 저희가 여섯 번에 걸쳐서 복지분야의 연구자를 찾기 위해서 공채 및 특채를 실시했습니다.  간단히 얘기하면 2004년 10월에 한 번 했고요, 2005년 1월, 2005년 5월, 2005년 9월, 또 최근 해서 여섯 번을 실시했는데 그때마다 많게는 18명, 적게는 한 명씩 지원했는데 정말로 적임자가 없었습니다.  저희들이 최근에는 너무나 안 돼서 특채, 소개를 받아서라도 채용해 보려고 했는데 오신 분들이 어떤 분이었냐면 아주 특정하게 호스피스 담당하시는 분이었거나 뭐 이런 분이다보니까 채용을 못하고 있었는데 다행히 엊그저께 끝난 공채과정에서 복지행정 전반에 대해서 상당한 지식을 가진 박사학위 소유자를 한 명 찾았습니다.  그래서 저희들이 내부적으로는 잠정적으로 면접과정을 거쳐서 합격을 내정해 놨습니다만 아직 발표를 하지 않고 있는 상태입니다.  따라서 그 박사가 소정의 절차를 거쳐서 저희 연구원에 들어오게 된다면 그것에 맞춰서, 솔직히 말씀드리겠습니다.  해당 박사가 없으니까 내년도…….
</p>
<p><b>○ 장정은 위원 </b> 부원장님, 죄송한데 지금 말씀은 대충 무슨 말씀인지 알겠고요.  시간 관계상 제가 하고 싶은 말씀을 조금 드리겠습니다.  중요한 것은 지금 박사 1명, 연구사 경험이 있는 호스피스 다 이야기 하셨는데 지금 우리 경기도의 심각한 문제가 뭔지 아십니까?  경기도 보건복지는 그림이 없다는 거예요.  그때마다 외국에서 어떤 좋은 게 있다면 들여와서 일시적으로 사용했다가 폐지시켜 버리고, 전혀 경기도 밑그림이 없는 보건복지가, 지금 보건복지위원회에서도 하고 있는 게 전혀 밑그림이 없다는 거예요.  거기에 대해서 우리 경기개발연구원에서는 좀더 체계적으로 저소득, 취약계층, 장애인, 노인들이 어떠한 상황에서든 자기가 도움을 받을 수 있는, 본인이 그런 상황에 처했을 때 어디 가서 도움을 받느냐.  만약 노인이 사실은 아프다고 해서 병원에 들어가셨다가 나와서 시스템이 없다는 거예요.  앞으로 대한민국을 전체적으로 이야기할 게 아니고 우리 경기도가 그래도 인구수가 가장 많고 정말 대한민국에서는 제1의 도시라고 이야기한다면 그 부분에 대해서 우리가 예민하게 생각해 봐야 되지 않을까 생각하고요.
</p>
<p style="padding-left:1.2em">  아까 여성능력개발원 이야기하셨는데 여성능력개발원이 따로 나가 있는 것도 되게 웃긴 거예요, 실질적으로 본 위원이 생각할 때.  지금 여성회관 안에 있지요?  그게 사실은 경기개발연구원에 들어와서 여성능력개발원이 같이 조인이 된다든지, 정책을 하는 사람이 같이 모여있는 거지 어떻게 다 떨어져 있습니까?  사실 여기에 자리가 없다고 그래서 여성회관으로 가있는데 여성문제하고 복지부분하고는 부원장님께서 어떻게 구분하시는지 모르지만 굉장히 다릅니다.  제가 말씀드리고 싶은 것은 여성정책을 지금 강조하는 것이 아니고 보건복지정책입니다.  지금 복지부분에서 호스피스 이야기하시고 장애인복지, 노인복지 이야기하시는데 그 복지 말고 보건에도 시스템에 문제가 있다는 거지요.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그것에 대해서 답변을 드리겠습니다.  장 위원님 지적하신 말씀 정확하게 그대로 저희도 이해하고 있습니다.  그림이 없다는 것 바로 그런 점 때문에 저희가 사람을 뽑으면서 우선 급한 대로, 제일 급한 게 뭐냐면 종합적인 그림을 그릴 사람이 필요하다고 생각하고 있습니다. 
</p>
<p><b>○ 장정은 위원 </b> 네, 맞습니다.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그렇기 때문에 어느 특정 복지분야에 한정된 사람이 들어와서는 곤란하겠다고 생각했습니다.  그러다보니까 사람을 뽑는데 아주 특정분야에 굉장히 구체적인 일을 하고 있는 사람이 뽑혀서는 안 되겠다는 생각을 했고 …….
</p>
<p><b>○ 장정은 위원 </b> 아니요, 굉장히 죄송합니다.  보건복지정책은 전문가 입장에서 굉장히 필요한 거지만 우리 경기도나 경기개발연구원에서도 좀더 연구를 하셔서 전체적인 경기복지의 그림을 만들 수 있도록 노력하셔야 되고 그 세부적인 것은 누구 박사 한 분, 석사 한 분이 중요한 게 아닙니다.  제가 여기 조직표를 보면 여기에 사실 보건복지 조직이 없다는 자체도 우리 경기도의 아픔입니다.  실질적으로 우리 경기 일천만 도민이 가장 피부로 느낄 수 있는 부분이 복지부분이라고 생각하거든요.  그래서 이 기구 자체에 정말 보건복지부분을 한 파트 떼어주실 의향은 없으십니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그것은 제가 떼어준다고 해서 떼어지는 것은 아니고요.  다시 말씀드리겠습니다.  복지분야를 무슨 박사 한 명 뽑아가지고 그것으로 끝내겠다고 생각하지는 않습니다.  그렇기 때문에 앞으로 복지분야의 수요가 계속 늘어날 것이기 때문에 그 분야는 앞으로 계속 확충을 해야 할 것입니다.  다만 우선 급한 대로 장정은 위원님 말씀하신 대로 큰 그림부터 우선 그려 나가자는 생각을 하고 있고 실제로 그것을 위해서 지금 추진하고 있는 경기도의료원 같은 경우에도 외부 인사들까지 동원해서 저희들 나름대로 그림을 그리려고 노력하겠습니다. 
</p>
<p><b>○ 장정은 위원 </b> 지금 우리 경기개발연구원이 최고의 연구기관이라고 아까 자부하셨지요?  그 연구기관이 10년이나 경기도의 정책을 위해서 노력하신 노고에 대해서 잘 알고 있습니다만 이 부분에 대해서 너무나도 관심을 안 가진 것에 대해서 저는 꼬집어 물어보고 싶고요.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 알겠습니다.
</p>
<p><b>○ 장정은 위원 </b> 행정사무감사자료 119페이지 보면 18건의 연구과제가 있는데 이 가운데 5건 정도 외에 나머지는 짧게 3년에서 9년 정도 지난 과거의 자료인데 이런 과거의 연구자료들을 현재 수도권규제정책에 대응할 수 있는지 한번 여쭤보고 싶거든요.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 규제정책이라는 게 사실은 오래 전에 된 것도 있고 최근에 한 것도 있습니다만 실제로 수도권의 규제라는 게 아마 역사적으로 보면 5년, 10년 사이에 처리되는 게 아닐 겁니다.  그렇기 때문에 저희는 저희들 나름대로 계속적으로 연구를 했고 연구하면서 그 전에 됐던 것 중에서 해결된 건 해결된 대로 해결되지 않은 것은 해결되지 않은 대로 연구과제를 두고 그러면서 좀더 구체적으로 생기는 부분에 대해서는 계속적으로 연구를 해왔고요.  실제로 규제와 관련된 직접적인 연구 이전에 각각의 분야에서 연구를 하면서 그것이 규제에 어떻게 걸리는가 하는 부분, 규제 때문에 뭐가 안 되고 있는가 하는 부분은 모든 연구과제에서 다 검토를 하고 있습니다.  그러니까 저희들이 모든 보고서를 만들 때 마지막에 제도개선사항을 이야기하는데 거기 내용 중에서 규제라는 부분이 빠진 적이 없습니다.  그렇기 때문에 그런 부분들은 규제 그 자체를 가지고 보고서 하나가 나왔다 안 나왔다로 보지 마시고 모든 과제들 속에서 어떤 내용들이 우리들 나름대로 체크되고 있는가를 봐주시면 감사하겠습니다. 
</p>
<p><b>○ 장정은 위원 </b> 네, 알겠습니다.  저희가 지금 현재 위탁하는 부분이 있잖아요.  외부에 위탁해서 위탁사업하고 있는 부분에 대해서 잠깐 여쭤볼게요.  전문성이 필요한 특정과제거나 위탁이 더 유리하다고 판단되는 경우에 외부 위탁연구를 하는 것으로 알고 있는데 연구과제를 연구원들이 다 해결하기는 어렵다고 보고요.  장기적으로 보자면 인원도 보강해야 되고 여러 가지 이유가 있다고 보고, 의뢰한 용역사업 중 재위탁한 과제가 한 31건이었다고 보는데 위탁기간 선정은 어떤 기준으로 결정하시는 건지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 위탁기간은 해당연구자가 그 과제 전체를 최종적으로, 우선 자치단체 과제기간에 정해지겠지요.  그중에서 마무리를 하기 위해서 최소한 필요한 조건, 그 다음에 위탁과제에 참여하는 인력 이런 것들을 고려해서 판단합니다.  특별한 따로…….
</p>
<p><b>○ 장정은 위원 </b> 다른 기준은 없습니까?  전혀 보강되는 기준도 없고.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 장정은 위원 </b> 네, 알겠습니다.  감사합니다.  이상으로 질의 마치겠습니다. 
</p>
<p><b>○ 위원장 정인영 </b> 장정은 위원 수고하셨습니다.  다음 질의할 위원께서는 질의하여 주시기 바랍니다.  박영신 위원 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 박영신 위원 </b> 이천 출신 박영신 위원입니다.  전임 원장님이 어려움이 있어서 연구원에서 여러 가지 어려움이 많고 특히 행정사무감사 때 그런 일이 있어서 직원들이 여러 가지로 어려움이 많겠다 해서 저는 처음에 오면서 ‘많은 격려를 해줘야 되겠다’ 이런 생각을 하고 왔는데 처음에 주요업무보고에도 우리 한현규 원장이 간부명단에 포함돼 있고 또 지금 이 자료에도 보면 709페이지에 심의위원회 명단에도 심의위원으로 한현규 원장의 이름이 있고 기금관리위원으로 아직도 이 자료에는 살아있습니다.  그래서 내가 오히려 ‘야, 연구원 직원들이 여러 가지 어려움에 행정사무감사 하느라고 고생했다’ 하는 위로의 말을 해주려고 생각했었는데 오히려 ‘야, 이 연구원에서 너무 준비가 소홀하지 않았나’ 하는 생각을 했습니다.  누군가가 한 번 정도 생각을 하고, 간부가 아니라도 누군가가 한 번 정도 봤으면 얼른 눈에 띄는 일인데 결론적으로 ‘연구원에 박사는 많아도 사람은 없다’ 그런 생각이 들고 좀 착잡합니다.  연구원이 뭐하는 데입니까?  연구원에 사람이 없어요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 박 위원님, 정말 죄송합니다.  자료를 만들고 준비가 소홀한 부분은 연구원 전체를 대표해서 제가 우선 사과를 드리겠습니다.  저희들 나름대로 연구원 내에서는 상상하지 못했던 일들을 겪으면서…….
</p>
<p><b>○ 박영신 위원 </b> 다른 기관 같으면 하루 전에 인사발령난 것도 얼른 지웁니다.  일주일 전의 인사발령이 살아있다는 게 말이 됩니까?  연구원 자체가 기강이 아직도 해이해져 있다는 얘기예요.  봉급 타는 사람은 많아도 일하는 사람은 하나도 없다는 얘기입니다.  인원이 뭐가 필요해요?  박사가 뭐 필요합니까?  다시 한 번 대오각성하시고 뭔가 우리 연구원이, 정말 우리가 경기도를 이끌어가는 그런 지식인들이 모인 연구원이 뭔가 달라야 되겠다 하는 변화된 모습을 원합니다. 
</p>
<p style="padding-left:1.2em">  작년에 제가 행정사무감사 때, 요새 뭐 중국, 인도 쪽이 한국하고 교역량도 많이 늘어나고 또 우리 한국이 앞으로 여러 가지 경제성장을 하려고 하면 특히 중국하고는 여러 가지 활동이 활발해야 된다 그런 생각으로 중국에 대한 전문가들이 필요하다 그런 말씀을 드린 적 있습니다.  우리 경기도가 광동성하고 자매결연을 맺었는데 그 광동성 성장이 경기도를 방문했을 때 그 광동성 성장을 수행한 광동성 직원들을 만났어요.  그 사람들이 한국말을 엄청 잘 하더라고.  저는 연변에 있는 우리 교민인 줄 알았어요.  “당신 우리 교민이냐” 그랬더니 그냥 순수한 중국 사람입니다, 한족.  그런데 경기도하고 자매결연을 맺어서 경기도 업무하고 관계되는 사람들은 한국말을 한국사람보다 더 잘 합니다.  그러면 우리 경기도와 관계되는 공무원 또 연구원에 관계되는 직원들이 정말 그 사람들처럼 중국말을 준비했는가.  제가 집행부 쪽의 누구 간부한테도 한번 설명했지만 중국 사람들은 그렇게 준비가 철저합니다.  그래서 우리 연구원에서도 그런 준비를 거듭 잘 해주십사 하는 부탁을 드리고.
</p>
<p style="padding-left:1.2em">  국가에서는 현재 국가균형발전에 대한 여러 가지 계획을 세우고 있고 또 현재 공공기관 이전까지 하여튼 초법적으로 하고 있습니다.  경기도는 반대하고 지금 의회가 앞장서서 공공기관 이전반대를 하고 있는데 경기도는 경기도 안에 또 균형적인 발전이 필요한 것 아닙니까?  그런데 거꾸로 경기도의 일부지역은 편중돼서 여러 가지 개발이 이루어지고 있고 거꾸로 가평에나 양평, 연천, 이천, 여주, 안성 같은 데는 현재 인구도 증가가 정체돼 있고 또 새로운 발전적인 요인 이런 게 둔화돼 있어서 지역의 여러 가지 경제여건이 엄청 어려워지고 있습니다.  그런데 이런 점에 대해서 연구원에서 경기도 안의 균형발전에 대한 어떤 생각을 가지고 계신지 우리 부원장님 설명해 주세요.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 먼저 중국, 인도 쪽부터 간단히 말씀드리겠습니다.  중국, 인도에서도 중국 전문가 부분을 굉장히 저희들도 중요하게 생각하고 바로 그런 점에서 동북아지역연구부라는 것을 설립에서 내년도에 소위 중국, 인도, 일본 이런 쪽의 전문가를 세 명 정도 더 충원할 예정입니다.  금년 중에도 실제로 중국인보다 중국어를 더 잘하는 중국어 전문가 한 명을 이미 초빙한 상태이고요.  
</p>
<p style="padding-left:1.2em">  그 다음에 경기도내 균형발전 말씀을 하셨습니다.  실제로 저희들도 이 부분에 대해서는 굉장히 심각하게 생각하고 있습니다.  전국적으로 따져서 호남, 강원 이쪽의 발전을 이야기하지만 똑같은 형태가 바로 경기도에서 나타나고 있다.  이에 경기도의 동부지역이고 경기도의 북부지역이라고 생각합니다.  저희들 나름대로 경기북부지역에 대해서는 어느 정도 연구도 하고 연구보고를 했습니다만 솔직히 말씀드려서 경기동부에 대해서는 구체적인 팩트를 가지고 하는 연구 외에 종합적인 그림은 경기도 전체를 그리는 그림 외에는 그려본 적이 없다는 아쉬움이 있습니다.  따라서 이 부분에 대해서도 저희들이 내년도 과제 중에서는 경기동부만을 특별히 대상으로 하는 종합발전계획 같은 것을 구상해서 추진해 나가도록 하겠습니다. 
</p>
<p><b>○ 박영신 위원 </b> 하여튼 그 지역의 주민들은 지금 여러 가지로 어려움에 처해 있고 더군다나 그게 여러 가지 경기도에 대한 불만으로 커지고 있다는 점 유념해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 박영신 위원 </b> 우리 부원장님 수고하셨고요.  이정훈 박사님 자리에 계신가요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 바로 내려오도록 하겠습니다.
</p>
<p><b>○ 박영신 위원 </b> 이정훈 박사님은 여기 답변석에 있으면 안 될 분이에요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 아니요.  저희들이 우선 간부들만 내려와 있었기 때문에요.  
</p>
<p><b>○ 박영신 위원 </b> 이정훈 박사님은요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 바로 내려오도록 하겠습니다.  위에 대기하고 있을 겁니다. 
</p>
<p><b>○ 박영신 위원 </b> 이정훈 박사님 좀 제가 답변석에 부탁드리고요.  그러면 이정훈 박사님이 오실 동안 2005년도 연구사업 추진현황 중에서 경기도가 추진하는 여러 가지 사업 중에서 경기도남북협력기금에 대한 대북사업에 여러 가지 분석이 돼 있습니다.  그런데 지금 우리 남북교류가, 특히 북한이 어렵고 북한을 잘 살게 해야 된다는 것은 다 맞습니다.  그런데 저는 어떤 점에서 ‘야, 이게 지방자치단체가 해야 될 일인가, 국가에서 해야 될 일하고 지방자치단체에서 해야 될 일은 어느 정도 경계선이 있어야 되는 것 아닌가’ 그런 생각을 합니다.  그런데 지금 특히 경기도가 앞장서서 남북교류협력기금을 조성하고 있고 또 지금 남북교류협력을 엄청 증대시키고 있습니다.  그런데 우리 부원장님은 남북교류협력에 대해서 경기도가 어떻게 발걸음 해야 되는가 하는 점을 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 개인적인 소견으로 말씀을 드리겠습니다.  남북교류문제에 대해서 저는 우선 첫째로 교류채널이 좀 다양화돼야 되겠다는 생각을 합니다.  물론 전체적인 틀과 흐름과 본류는 중앙정부에서 국가적으로 추진해 나가야 되겠습니다만 지자체 단위에서 아주 실무적이고 실질적으로 할 수 있는 것, 민간단위에서 할 수 있는 것 이런 것들도 있을 수 있고 그 부분이 계속적으로 진행돼야지 국가 차원에서 문제가 생겼을 때 그것을 우회하면서 끊임없이 교류를 진행할 수 있는 통로를 만들 수 있다고 생각합니다.  물론 그 지자체 차원의 교류형태가 국가의 흐름을 넘어서거나 아니면 국가의 흐름과 반대로 나가거나 방향을 틀리게 해서는 안 된다고 생각하고, 그런 점에서 경기도에서 하고 있는 것들이 제대로 국가의 흐름과 맞추어서 가고 있는가 하는 부분들을 우리 연구원에서 계속적으로 분석해야 된다고 생각합니다. 
</p>
<p style="padding-left:1.2em">  두 번째로 이 교류가 어떤 형태로 돼야 되겠냐는 점에서는 그런 생각을 합니다.  이게 일방적으로 지금까지는 지원형태였습니다.  그래서 어떤 사람들은 표현을 “퍼주기” 라고 이야기합니다.  그러나 천만다행히 경기도에서 지금 추진하고 있는 교류는 형식적으로 퍼주기처럼 보이지만 그것이 북한사회 구조 자체를 우리 사회와 유사한 것으로 맞춰가는 쪽에 포인트를 맞추고 있다고 생각합니다.  이런 것들은 길게 보면 장기적으로 북한사회를 점점 우리하고 동화시키는 것이고 그런 점에서 이것들이 좀더 정밀하고 구체적으로 짜여져 가면서 양의 문제가 아니라 내용적으로 적극적으로 진행됐으면 좋겠다고 생각하고 있습니다. 
</p>
<p><b>○ 박영신 위원 </b> 이정훈 박사님 오셨나요?  부원장님 수고하셨습니다. 
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 경제사회연구부의 이정훈입니다. 
</p>
<p><b>○ 박영신 위원 </b> 이정훈 박사님을 모신 것은 지금 2005년이 경기방문의 해입니다.  맞아요?
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 네, 맞습니다. 
</p>
<p><b>○ 박영신 위원 </b> 우리 박사님이 경기방문의 해에 대해서 연구를 하셨지요?
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 방문의 해에 대해서 지금 평가백서연구를 진행하고 있습니다.  9월 중순부터 시작했습니다. 
</p>
<p><b>○ 박영신 위원 </b> 박사님 모신 이유는 2003년도부터 2005년도 경기방문의 해를 위해서 많은 예산을 투입하고 지사님을 비롯해서 우리 집행부, 의회까지 합쳐서 2005년도 경기방문의 해를 전 세계적으로 했습니다. 
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 네, 그렇습니다. 
</p>
<p><b>○ 박영신 위원 </b> 그런데 지방자치단체가 그렇게 하는 게 극히 드문 경우거든요.  그러면 지금 2005년도, 실제 경기방문의 해입니다.  그런데 금년 우리 경기방문의 해에 세계 각국에서 많은 외국인들이 와있어야지요. 그렇지요?  그렇습니까, 안 그렇습니까? 
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 그것은 제가 여기서 대답할 사항은 아닌 것 같고요. 
</p>
<p><b>○ 박영신 위원 </b> 아니, 일반적인 상식으로 봐서 계속 몇 년 동안 예산을 들여서 2005 경기방문의 해를 크게 했단 말이에요.  그거 맞습니까, 안 맞습니까? 
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 네, 그것은 했지요.  
</p>
<p><b>○ 박영신 위원 </b> 예산이 얼마 들어갔는지 아십니까? 
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 150억 정도 잡혀있는 것으로…….
</p>
<p><b>○ 박영신 위원 </b> 150억 예산 들여서 연인원이 지사님부터 실국장, 의회 의원까지 다 다니면서 경기방문의 해 리본까지 다 나눠주고 그랬습니다. 
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 네, 그랬습니다. 
</p>
<p><b>○ 박영신 위원 </b> 그러면 경기방문의 해에 전 세계인이 경기도를 많이 와야지요.  그렇지요?
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 그 부분에 대해서…….
</p>
<p><b>○ 박영신 위원 </b> 아니, 맞아요?  그래야 되는 것 아닙니까? 
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 그 부분은 제가 말씀드릴 사안이 아니고 저도 그 과정에 대해서 지금 평가를 하면서 이게 제대로 됐는지 안 됐는지를 보는 입장이거든요.  그러니까 위원님께서, 상식적으로 많은 분들께서 방문의 해를 하면 사람들이 많이 와야 된다고 생각하는데 실제로는 그렇지 않고요.  데이터를 보면, 지금 정확한 데이터는 집계가 어렵습니다만 그렇게 많이 늘어난 것 같지는 않습니다, 현재 상황으로 보면요.
</p>
<p><b>○ 박영신 위원 </b> 문제는 2003년, 2004년도는 경기방문의 해라고 경기도 전체가 들썩거리면서 홍보를 무지하게 했습니다.  150억 이상을 썼어요.
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 전체 올해 예산까지가 150억입니다.
</p>
<p><b>○ 박영신 위원 </b> 그런데 결론적으로 2005년도 경기방문의 해에는 2004년도만큼 경기방문의 해에 대해서 홍보도 없고 그 여러 가지가 외침이 없습니다.  왜 그렇지요?
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 제가 파악하고 있는 것은 이 계획 속에서 공사 나름대로는 일을 해나가고 있는데 그 성과나 그런 부분에 대해서 아직 저는 평가를 하고 있는 입장이기 때문에 제가 말씀드릴 수 있는 그런 사안은 아닌 것 같습니다.  그것은 공사에서 대답을 해야 될 부분이겠지요.
</p>
<p><b>○ 박영신 위원 </b> 박사님이 알고 있는 그동안 150억이라는 막대한, 더 많은 돈을, 예산편성만 그런데, 그렇게 써가면서 결과적으로 여러 가지 성과가 있었다고 생각하시는지 또 2005년도에 와서 그게 경기방문의 해 소리가 그 전 해인 2004년, 2003년도에는 2005년 경기방문의 해라고 아치로 크게 세워졌습니다.  그러면 금년도에도 아치로 크게 세우고 으?으? 하는 게 보여야 하는데 금년에 이게 경기방문의 해가 그냥 보이지 않게 없어져 버렸어요.   
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 제가 파악하는 바로는 해외홍보에 상당히 초점을 많이 맞춘 것으로 자료들이 나오고 있거든요.  실제로 일본이나 중국이나 외국의 신문에도 많이 보도가 돼 있고요.  그런 측면에서는 일단 국내에도 홍보를 했지만 해외홍보에 주안점을 뒀던 것 같고요.  
</p>
<p style="padding-left:1.2em">  그 다음에 지방자치단체의 방문의 해가 경기도가 공식적으로는 처음입니다.  그래서 내년도에 제주도에서 그것을 가지고 가는데, 처음이기 때문에 아직 제가 볼 때는 시행착오도 있는 것 같고요.  그러면서도 도 집행부하고 관광공사에서는 나름대로 계획을 세워서 전문가들하고 일을 했는데 지금 위원님께서 질의하시는 사항들에 대해서는 저도 거기에 그러한 의문들을 가지면서 지금 연구를 하고 있는 사항이기 때문에 제가 이 자리에서 시원한 대답을 드리기는 조금 어려운 사항인 것 같습니다.  죄송합니다.  제가 연구가 좀더 진행이 되면 별도로 위원님께 말씀드리겠습니다. 
</p>
<p><b>○ 박영신 위원 </b> 저는 경기도의 여러 가지 정책이라든지 이벤트 같은 게 계획성이 있고 정말 여러 가지 종합적으로 검토한 후에 시행이 돼야 되는데 특히 2005년도 방문의 해 같은 경우가 그렇게 충분한 준비없이 많은 예산만 낭비한 게 아닌가하는 그런 우려적인 생각을 가지고 있습니다.  그래서 박사님 생각은 어떻고 앞으로 이 평가는 아직 결론은 안 났지만 어떤 식으로 결론이 날 것 같은지 마저 마무리 말씀을 해주시죠.
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 지금 우리 도를 포함해서 우리나라에서 축제나 이벤트들이 대단히 많이 열리고 있습니다.  1년에 축제만 해도 800여개가 열리고 있고 또 앞으로 경기도를 시작으로 해서 내년, 후년 해서 매년 지방자치단체의 방문의 해가 열리는데요.  그러한 이벤트나 캠페인의 문제점이 지금 위원님께서 말씀하신 부분하고 저도 똑같이 공감하는 바입니다.
</p>
<p style="padding-left:1.2em">  정확하게 사전에 계획을 해서 집행이 돼야 됨에도 불구하고 사실은 미진한 부분들이 있고요.  또 미진하다고 하더라도 그 행사가 끝난 다음에 거기에 대해서 정밀한 검토와 반성을 통해 이후에 실수 혹은 미진함을 되풀이 하면 안 되는데 사실은 그런 것들이 어떻게 보면 똑같은 실수를 계속 혹은 똑같은 미진함을 계속 반복하는 경향들이 있어왔고 그런 측면에서 저는 이번 평가를 통해서 잘잘못을 가리기보다는 그동안의 진행과정에 대해서 객관적이고 냉철하게 점검을 해서 앞으로 우리 경기도에서 하는 일에 시정해야 될 부분들, 그 다음에 앞으로 경기도 관광이 나아가야 될 구체적인 비전들을 제시하는 계기로 삼고자 하고요.
</p>
<p style="padding-left:1.2em">  또 차제에 제주도나 다른 지역들이 경기도의 이런 과정과 평가를 모델로 삼아서 더욱더 내실있는 행사가 될 수 있는 하나의 매뉴얼로써 이 연구를 진행하고자 합니다. 
</p>
<p><b>○ 박영신 위원 </b> 수고하셨습니다.  이정훈 박사님 고맙습니다.  위원장님 제 질의를 마치겠습니다. 
</p>
<p><b>○ 위원장 정인영 </b> 박영신 위원 수고하셨습니다.  이건희 위원께서 보충질의 해주시기 바랍니다.
</p>
<p><b>○ 이건희 위원 </b> 저도 경기방문의 해와 관련해서 박영신 위원님이 하신 질의에 대해 한두 가지만 더 의문점이 있어서 질의하겠습니다.  지금 이정훈 박사님께서 경기도권 관광개발계획이라는 그런 연구를 언제부터 하셨냐면 2005년 6월부터 내년도 2월까지 하게 돼 있고 지금 그와 거의 병행해서 경기방문의 해의 사업성과 평가백서를 2005년 9월부터 내년도 11월까지 완성할 계획으로 잡고 있는데 경기방문의 해로 결정해서 우리가 150억원이라는 돈을 투여해서 해외홍보를 했든 대내외적으로 홍보를 하는 데 있어서, 물론 4차 경기도 관광계획을 지금 하고 있는 건데 그전에 숙박업소라든지 아니면 예를 들어서 수원 화성을 유네스코 지정 세계문화유산으로 개발을 지금 마쳤고 경기도 광주에 있는 경기도립공원 남한산성이라든지 아니면 세계도자기엑스포, 아니면 용인민속촌이라든지 에버랜드 이렇게 해서 외국인들이나 내국인들이 정말 경기도에 방문을 해야 되겠다는 그런 1일 관광코스가 됐든 2박 3일이 됐든 그런 숙소라든지 이런 것들을 명확하게 준비해 놓고 외국인들을 오라고 해야지 지금 그렇지 못한 상태에서 경기방문의 해로 정했다는 것은 시기적으로 이런 것들이 적절치 않았지 않았나하는 생각인데요.  그러면 경기방문을 하라고 해서 지금 우리가 파주 LCD부터 시작해서 이제서 이의동개발이라든지 숙소라든지 여러 가지 호텔 같은 것을 이제 지으려고 계획을 하고 있는데 그러면 지금까지 경기방문의 해를 정해서 어떤 것을 보러오라고 주안점으로 했던 것이 무엇입니까?  거기에 대해서 답변해 주시죠.
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 제가 방문의 해 당사자가 아니라서 아는 범위내에서 말씀드리겠습니다. 
</p>
<p><b>○ 이건희 위원 </b> 아니, 경기관광공사에서 이 박사님한테 경기관광개발계획이라든지 이런 것에 대해서 용역을 다 줘서 하셨잖아요.  그러면 여기에서 이 박사님 말고 경기방문의 해와 관련해서 관광지에 대해서 더 잘 아시는 분 계신가요?
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 그러니까 제 말씀은 경기방문의 해에 대해서 지금 제가 평가작업을 하고 있는 입장에 있고요.  그 다음에 권역관광계획은 사실 또 조금 다릅니다.  권역관광계획은 문화관광부에서 모든 시ㆍ도에 대해 5년마다 한 번씩 하도록 하고 있는 법정계획입니다.  그래서 그 맥락이 조금 다르다는 부분도 말씀드리는 것이고요.  제가 아는 한에서, 왜냐하면 제가 경기방문의 해를 계획을 하고 집행하는 입장이 아니기 때문에 혹시 그 부분에 대해서 정확한 대변이 안 될 수 있다는 부분에서 사전에 그런 말씀을 드리는 것이고요.  그리고 위원님 질의하시는 부분들에 대해서 아는 한에 대해서 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  아마도 경기방문의 해가 지정된 배경에 대해서는 일단 한번 이런 것들을 계기로 해서 경기도 관광이 사실 대단히 열악합니다.  어떤 측면이냐하면 대부분이 경기도의 민속촌이나 에버랜드나 DMZ를 다녀와도 그것이 경기도의 어디를 다녀왔다고 사람들이 인식하지 않고 ‘그냥 서울 주변에 어디를 다녀왔다’, 그냥 서울권으로 인식이 됩니다.  그것이 첫 번째 문제고요.  두 번째는 관광산업을 일으키면 지역내에 경제적인 파급효과가 있어야 되는데 대부분이 서울에 머물면서 1일 관광을 다녀오게 되는 거거든요.  그런 상황에서 경기도 관광이 열악한데 경기방문의 해에서는 그런 부분들을 장기적으로 개선하기보다는 조금 더 경기도의 이미지, 담당자들의 얘기를 들어보면 그렇습니다.  경기도의 존재 의미와 이미지들을 좀더 대량으로 부각시키기 위해서 그러한 이벤트가 필요했다라는 판단을 했고요.  또 그러기 위해서 당장 준비 가능한 인프라를 중심으로 해서 손님들의 수용태세를 구축하는 작업을 하는 것들을 제가 자료를 통해서 봤습니다.
</p>
<p><b>○ 이건희 위원 </b> 네, 됐습니다.  이것은 제가 본 질의도 아니고 박영신 위원님 질의에 제가 궁금해서 질의드리는 것은 뭐냐하면 경기도권 관광개발계획을 이종원 박사님이 계획을 하셨는데 물론 이 주체는 저희가 지금 여기서 장기적으로 논의할 사항은 아니에요.  경기관광공사든 문화정책 다른 부서에서 할 수 있는 건데 제가 여쭤보고 싶은 것은 뭐냐하면 경기방문의 해를 이렇게 설정해 놓고 이런 많은 예산을 투여하고 했는데 실질적으로 우리 경기도에서 무엇을 보여주고 어떤 숙박시설이라든지 어느 코스라든지 주안점이 주로, 포인트가 뭐였었냐.  물론 경기방문의 해를 지정한 시점하고 우리가 준비한 것하고 맞지 않았다.  그래서 외국관광객이 더 많아야 되는데도 불구하고 전년도나 금년도에 별 차이가 없었다는 말씀을 드리는 겁니다.  거기에 대해 구체적으로 내용을 잘 모르시면 제가 여기서 질의를 종결하겠습니다.
</p>
<p><b>○ 경제사회연구부 이정훈 </b> 그러면 제가 답변드릴 수 있는 부분만 드릴게요.  방문의 해 사업을 보면 특정하게 경기도의 어떤 부분들을 보여주겠다라기보다는 예를 들어서 경기도의 12개 대표축제, 그 다음에 DMZ, 화성, 에버랜드를 포함한 기존에 제대로 정비가 됐다고 생각하는 또 인기가 있는 관광지에 대한 투어코스의 개발, 그 다음에 그런 부분들을 수용할 수 있는 식당 인프라의 정비, 또 통역이나 안내 서비스의 강화, 그 다음에 언론들을 통한 대내외적인 홍보 이러한 부분들이 사업의 중요한 골간으로 형성이 돼 있었고요.  그 다음에 인터넷의 정비라든가 지금 말씀드린 부분 대부분이 일상적인 관광정책에서 수행되는 내용들인데, 말하자면 경기방문의 해라는 것을 설정해서 보다 더 집중적으로 하겠다는 그런 의도로써 저는 해석을 하고 그런 부분들에 대해서 지금 파악을 하고 있습니다. 
</p>
<p><b>○ 이건희 위원 </b> 잘 알겠고요.  지금 말씀하신 축제나 투어코스, 관광코스도 제대로 정해져 있지 못했고 숙박시설이라든지 경기도의 특성을 명확하게 홍보를 못한 상태에서 경기방문의 해가 시행됐다는 생각이 많이 듭니다.  잘 알겠습니다. 
</p>
<p><b>○ 위원장 정인영 </b> 이건희 위원 수고하셨습니다.  다음 질의하실 위원 질의해 주시기 바랍니다.  김대원 위원 질의해 주시기 바랍니다.
</p>
<p><b>○ 김대원 위원 </b> 의왕 출신 김대원 위원입니다.  저희들에게 제출한 자료를 기준으로 해서 세 가지로 요약해서 질의드리겠습니다.  제가 요구한 자료 중에 2005년도 주요 시책 및 내년도 계획 부분하고 2006년도 연구과제 수행계획하고 그리고 2004년도 행정사무감사 지적사항과 조치내용 3건을 같은 내용이라서 같이 하겠습니다.  간단하게 단답형으로 질의하겠습니다.  혹시 부원장님이나 제가 요구한 자료를 제출한 기조실장이나 자료를 제출하기 전에 혹시 한 번씩 읽어보신 적이 있나요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 저희들 나름대로 계속 중복해서 검토를 하고…….
</p>
<p><b>○ 김대원 위원 </b> 읽어보셨어요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 김대원 위원 </b> 그러면 질의해도 답변하실 수 있겠네요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 최선을 다하겠습니다.
</p>
<p><b>○ 김대원 위원 </b> 2005년도 주요시책을 보면 여섯 가지 정도로 요약이 됩니다.  경기개발연구원이 개원 10주년을 기념해서 정책연구총서를 발간하고, 두 번째 지방분권 및 지역간 상생발전 부분과 세 번째 수도권의 합리적인 대책, 네 번째 한류우드 공감대 조성 그리고 중요한 것은 다섯 번째인데 상대적으로 소외된 북부지역 발전전략 그리고 현재 이슈화 되어 있는 오염총량관리제 등 주요시책 이렇게 여섯 가지가 있는 것으로 돼 있습니다, 올해 주요시책으로는.  그러면 시책 여섯 가지 중에 현재 완료된 시책과 진행 중인 시책이 어떤 부분들입니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 우선 GRI 정책연구총서부터 말씀드리겠습니다.  GRI 정책연구총서는 아까 업무보고 때도 말씀드렸듯이 12권으로 12월 말에 발간될 예정이고 지금 초안과 최종안이 만들어진 상태에서 그걸 지금 수정 중입니다.
</p>
<p><b>○ 김대원 위원 </b> 여섯 가지 주요시책 중에 완료된 것과 진행 중인 것을 구분해서 해주세요.  하나는 안돼 있다손 치고 나머지 부분은요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 이 모든 것들이 언제 완료했다라고 이야기할 수 있는 게 아니라요.  연구과제를 이런 것과 관련해서 추진했는데 실제로 보면 이 모든 것들이 연구과제 진행상황으로 보면 완료됐다라고 이야기할 수 있는 부분은 없습니다. 
</p>
<p><b>○ 김대원 위원 </b> 그러면 연결해서요, 같은 맥락입니다.  왜 이런 질의를 드렸느냐 하면 2006년도 연구과제 수행계획을 제가 자료요구 했는데 보면 원래의 주요시책과 대동소이하다는 겁니다.  그러다 보니까 지금 경기개발연구원장이 공석인 상태로 내년도 계획수립도 제대로 하지 못했지 않느냐라는, 원래 똑같은 상황의 연구계획을 가지고 있다면 내년도 계획도 아직 못 잡은 것 아니에요?  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 꼭 그런 것은 아니고요.  실제로 이미 2006년도 연구과제 같은 경우는 저희들이 9월부터 2006년도 주요과제 목표를 시작합니다.  그래서 저희들 같은 경우는 이미 10월 초순에 나름대로 워크숍까지 거쳐서 연구원들의 전체적인 총의를 모아가지고 만들어낸 게 2006년도 연구수행계획입니다.
</p>
<p><b>○ 김대원 위원 </b> 그런데 2005년과 대동소이하다는 점은 자료로 보면 그런데요.  그런데 단 문구만 하나 틀린 게 하나 있어요.  다섯 번째 부분 “상대적으로 소외된 북부지역 발전전략”이라고 그랬는데 상대가 어디입니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 경기도 내에서, 아까 다른 위원님께서 말씀하신 바와 같이 경기도내 균형발전 문제가 또 분명히 제기되고 있는 것이고요.
</p>
<p><b>○ 김대원 위원 </b> 아니, 현재 저희들이 남부와 북부로 분류했을 때는 2청에서 관리하는 북부 10개 도시를 북부지역이라고 그러는 것 아니에요?  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다.
</p>
<p><b>○ 김대원 위원 </b> 그리고 나머지 21개 시와 상대적으로 소외돼 있다는 건지 안 그러면 북부지역 내에서 특정 시가 소외돼 있다는 것인지 그 부분에 대해서 어떻게 생각하세요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 남부지역과의 관계라고 저는 이해하고 있습니다.
</p>
<p><b>○ 김대원 위원 </b> 남부 어떤 지역하고요?  남부 어떤 지역과 어떤 지역이 기준으로 봤을 때 소외돼 있냐고요.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 실제로 인구의 집중도나 그 다음에 GRP의 차이 같은 것들은 분명히 존재한다고 생각합니다. 
</p>
<p><b>○ 김대원 위원 </b> 인구의 집중도로 따지면 동부지역인 양평과 북부지역인 고양을 한 번 비교해 보셨어요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 구체적인 부분에서 그렇게 말씀하신다면 실제로 연구적으로 따져놓고 보면 저희들이 경기도에 관심을 안 가지고 연구를 하지 않는 부분은 없습니다.  
</p>
<p><b>○ 김대원 위원 </b> 그러니까 말이 어 다르고 아 다른데 2006년도 연구과제에 보면 북부지역 발전을 위한 연구이고 2005년도에 보면 소외된 북부지역이에요.  1년 사이에 소외가 해소된 거예요?  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 2006년도 저희가 지금 세우고 있는 연구사업계획에 “소외”를 뺐다 넣었다라는 게 저희들이 그냥 말장난하자고 한 것은 아니라고 생각을 합니다.  실제로 저희가 2005년하고 2006년하고 비교했을 때 저희들 나름대로 생각하는 건 2005년 같은 경우는 가장 중요했었던 것이 소위 수도권대책이었고요.  그 다음 두 번째가 지역간 상생발전 이런 것들이었다고 생각합니다.  실제로 2006년도로 넘어가면서 보다 더 중점을 두고자 하는 것이 뭐냐하면 소위 동북아 대도시권으로써의 수도권문제, 그 다음에 민선4기 출범에 따른 자치역량 문제 이런 것들이 저희 연구과제의 중심이 될 것이라고 생각하고 있습니다. 
</p>
<p><b>○ 김대원 위원 </b> 2004년도 행정사무감사 때 지적사항 중에 남부와 북부지역에 대해서 지적한 내용에 대해서 읽어보신 적 있나요?  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 2004년도의 지적사항에 대해서 제 나름대로 개략적으로 검토를 한 바 있습니다. 
</p>
<p><b>○ 김대원 위원 </b> 그러니까 계속 남부, 북부 소외 해가지고 북도신설이라든가 거기에  대한 대응방안으로 경기개발연구원에서 특별 도 추진까지 자꾸 이렇게 확대해석해서 하는 부분들인데 이런 부분을 봉합해서 나가야 될 부분인데 아주 연구하는 연구기관에서까지 소외된 북부지역이라고 명칭을 아예 해서 한다면 북부지역주민들은 진짜로 소외돼 있는 것으로 생각하고 또 남부지역 중에는 북부지역 도대체 어느 도시를 기준으로 그러는 건지, 연구과제를 보면 양주시와 동두천시가 지금 포함돼 있는데 그 2개 시가 소외돼 있다는 겁니까, 북부 전체가 소외됐다는 거예요? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 김대원 위원님이 하시는 말씀의 말뜻을 이제 정확하게 이해하겠습니다.  사실은 “소외된”이라는 표현 자체가 별로 과학적이지 못한 경우이고 더군다나 “소외된”이라는 걸 외부에서 이야기한다고 해서 그걸 우리가 그대로 쓰고 있다라는 것 자체가 사실은 저희들이 문제라고 생각합니다.  그 부분은 앞으로 시정을 하겠습니다.  다만 저희들 나름대로는 북부지역 같은 경우에 금년도에 어떤 과제들을 수행했냐 하면 그럼에도 불구하고 북부지역은 다른 지역에 비해서 상대적으로 소위 전략산업이라고 이야기할 수 있는 것이 없다라고 생각했습니다.  그래서 북부지역의 전략산업이 뭐가 될 수 있을까 이런 것들을 중심으로 해서 그러면 그 전략산업을 키우기 위해서 뭘 어떻게 해야 될 것인가 하는 부분에 대한 연구는 집중적으로 해왔습니다. 
</p>
<p><b>○ 김대원 위원 </b> 그것도 연계해서 과제를 보면 보통 예산배분율로 보면 기본연구와 정책연구 그리고 위ㆍ수탁연구 이렇게 크게 분류를 하면 세 가지로 분류를 할 수 있단 말이에요.  그런데 예산배분 비율을 보면 기본연구가 약 30%, 그리고 정책연구가 50%, 그리고 위탁연구가 일부 이렇게 돼 있는데 기본연구가 지금 경기개발연구원의 주요지표로 삼는 자료로 인용될 수 있는, 기본연구가 충실하면 위ㆍ수탁연구 같은 경우에는 위탁기관에, 존경하는 김영복 위원도 아까 지적했습니다만 위탁기관의 입맛에 맞게 그냥 개발해주는 역할, 논리를 개발해주는 역할을 우리 경기개발연구원이 수행을 해서 면책 내지 면피용으로 간다라는 이런 부분으로 흐른단 말이에요.  그러다보니까 현재 역사도 짧고 인용할 기준이 없다보니까 기본연구가 부실했다고 보는데 어떻게 생각하세요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 김대원 위원님께서 말씀하신 부분에 대해서 부분적으로 저희도 수긍을 하면서 앞으로 이런 부분들이 안 돼야 된다고 생각하지만 그럼에도 불구하고 제가 말씀드리고 싶은 것은 그렇습니다.  저희들은 기본연구 과제가 저희 연구원의 중심이라는 부분에 대해서는 저희도 한 치의 흔들림이 없습니다.  실제로 기본연구 예산이 30%라고 이야기 하지만 과제 갯수하고 대비를 해보면 기본과제는 일반적으로 과제기간도 10개월 내지 11개월에 1과제당 예산도 다른 정책연구과제의 3배 이상을 투여하면서 하고 있고요.  기본연구과제가 25개인 데 비해서 정책연구과제는 내년 같은 경우 70개 이상을 생각하면서 예산을 짜다보니까 정책연구과제가 많아졌다고 말씀드리고 싶고, 하지만 이 정책연구과제도 소홀히 할 수 없는 부분은 경기도에서 현안이 터졌을 때 그것에 대해서 직접 즉각즉각 답을 하려면 이 정책연구가 그냥 그대로 없어지고 안 그러면 축소될 수 있는 부분은 아니라고 생각합니다.  다만, 위ㆍ수탁과제의 문제입니다.  위ㆍ수탁과제의 경우 물론 저희들 나름대로 전체 경상예산에서 일부를 또 저희가 버려야 되는 부분이 있기 때문에 저희들이 수탁을 안 할 수도 없고 또 다른 한편으로 보면 위ㆍ수탁과제를 통해서 저희가 경기도내에 있는 각종 시ㆍ군의 정보들을 얻을 수 있기 때문에 그것으로써의 장점은 있습니다.  다만 그 수탁과제를 수행하면서 그 위탁업체의 의사와 뜻에 따라서 맞추어지는 연구가 돼서는 안 된다고 저희는 생각하고 있습니다. 
</p>
<p style="padding-left:1.2em">  실질적으로 그런 부분들 때문에 저희 나름대로도 그 부분에 대해서, 지금까지 그래왔다는 뜻이 아니라 이럴 가능성이 존재한다라고 생각을 했기 때문에 내년부터는 수탁과제를 함에도 불구하고 그 수탁과제가 우리 연구원의 입장과 맞느냐 안 맞느냐를 전체 연구원의 연구위원회를 통해서 이것들을 걸러서 앞으로 수탁과제도 받고 그 다음 수탁과제 결과도 연구위원회를 통해 내용을 걸러서 내도록 지금 계획을 세우고 있습니다.
</p>
<p><b>○ 김대원 위원 </b> 그래서 아까 제가 처음에 지적했듯이 기본연구, 그러니까 경기개발연구원에 노하우 축적이 없기 때문에, 그러면 결과적으로 기본연구라는 게 뭐냐, 기본연구가 지역연구가 될 것입니다.  수탁과제가 국가정책 부분도 해당이 되겠습니다만 그것은 극소수이고 거의 지역부분에 해당된 수탁물이 과제물로 들어오는데 그러다 보면 기본 지역연구가 충실한 자료로 확보가 돼 있었을 경우에는 수탁자의 입맛에 맞지 않게, 지금 경기개발연구원의 기조가 이렇게 가기 때문에 이 부분은 경기개발연구원의 목소리를 낼 수 있는, 기본이 갖춰져 있었기 때문에 가능한 얘기인데 기본 자체가 갖춰지지 않을 경우에는 외압에 휩쓸릴 수 있고 또 정책과제 연구도 그렇습니다.  정책과제 연구도 지금 민선시대로 접어들면서 3기를 지납니다만 시대 과정에 따라가지고 운영권자가 정책을 내놨을 때 그 정책의 입맛에 맞도록 여기서는 논리개발을 해주는 그런 역할을 한단 말이에요.  그리고 작년도 지적사항 중에 경기도 정책과 반하는 과제물이 나왔을 때 대응이 뭐냐라고 했었어요.  그러다 보니까 지금 조직적으로 어찌 보면 검토하는 그런 제도로 제가 답변서를 받았는데 그러다 보면 어떤 학자적인 양심이나 실제 연구의 결과물과 반하는 내용이 나왔을 때는 통제에 의한 방법으로밖에 안 될 것 아니에요?  그러니까 기본연구에 지금도 과제물 대비 예산배정은 많다고 그러지만 그래도 더 예산을 풍부하게 배정하셔서 지역중심의 기본연구를 충실히 해놨을 때 그 지역에서 일어난 사항들이 지금 뜨거운 감자로 대두되거든요.  그러다 보면 지금 민선시대이다 보니까 민선시대의 장의 입맛에 맞는 수탁을 받았을 때도 논리적으로 대응할 수 있는, 그리고 또 거꾸로 얘기를 하겠습니다.  경기도 정책과 수탁기관의 정책과 경기개발연구원의 결론이 셋 다 틀렸을 때는 어떻게 조정을 하겠어요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 저희들 나름대로는 그렇게 생각을 합니다.  우선 가장 근본적으로 저희는 연구자 집단이고 연구자 집단은 중립적이고 객관적이어야 된다고 생각합니다.  그렇기 때문에 우리의 의견과 우리 의사와 어긋난 의견이 이를 테면 발주처 내지는 경우에 따라서는 경기도 전체 도정하고 어긋날 수도 있을 겁니다.  하지만 그런 문제가 생겼을 때 예를 들면 그것을 우리가 무조건 고집을 세우고 떠들어가지고 그것을 사회문제화 할 이유도 또한 없다고 생각합니다.  그렇기 때문에 우리는 우리의 원칙을 견지해 나가되 경기도 도정에서 어떤 상치되는 문제가 생겼다고 한다면 그것의 최종적인 결론이 날 때까지 끊임없는 커뮤니케이션을 해야 된다고 생각합니다. 
</p>
<p><b>○ 김대원 위원 </b> 아니, 수탁물은 수탁을 받았을 때 납품기일이 정해져 있지 않습니까? 
