<p><b>○ 김대원 위원 </b> 그러다 보면 이것은 실제적으로 일어났는지 아닌지는 모르겠습니다만 그런 조정역할을 거치기 위해서 보통 보면 납품기일을 연기시키는 예도 있고 수탁기관에 제 날짜에 납품 못하는 예도 사실은 있다고 들었거든요.
