<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김대원 위원 </b> 실제로 있는 것도 사실이고요.  그런 상황이 왕왕 일어난단 말이에요.  그것을 완전하게 대처하기 위해서는 어떤 정치적인 상황이 변동되더라도 경기개발연구원 자체로서 살아남기 위한 부분을 갖추려면 이런 기본연구에 더 충실해야 된다.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김대원 위원 </b> 네, 이상이고요.  한 가지만 더 덧붙여서 말씀드리면 이런 사태가 곧 우리 경기개발연구원의 책임자의 불미스런 상황에 같이 맞아떨어졌다는 겁니다.  그래서 올해 과제 중에 오염총량관리제 부분 때문에 광주시의 하수물량 배정에 대해서 경기개발연구원에서 광주시로부터 수탁을 받아서 납품한 부분이 있죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
