<p><b>○ 김대원 위원 </b> 그리고 보안상의 이유인지 뭔지 하여간 납품을 하고 나서도 대외비로 결정돼서 공개 안 하는 과제물들이 있죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김대원 위원 </b> 올해 기준으로 몇 건 정도 됩니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 지금 대외비 자료가 현재 상태에 26건이 있습니다.
</p>
<p><b>○ 김대원 위원 </b> 대외비는 글자 그대로 대외비니까 의회감사규칙에 의하면 비공개로 의원은 열람할 수 있게 돼 있거든요.  그렇게 돼 있지요?  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네. 
</p>
<p><b>○ 김대원 위원 </b> 그런데 예를 들어서 민감한 사항, 현재 진행 중인 사항, 예를 들어서 판교IT업무지구 같은 경우에는 결과가 나오지 않는 중간 정도의 사항도 있을 것이고 그리고 수탁과제로 이미 납품이 끝난 상황 이런 부분도 있는데 대외비 해제기준은 어디이고 언제까지 대외비로 관리하십니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 저희들이 정책과제나 기본과제의 대외비 부분은 보통의 경우에 도와 협의해서 대외비로 할 것이냐 말 것이냐, 왜냐하면 정책과제라는 게 도의 정책하고 연관된 것이기 때문에 그렇게 되고요.  수탁과제 같은 경우는 발주기관의 요구에 의해서 저희들이 결정합니다.  따라서 수탁과제는 그 발주기관에서 대외비로 해달라면 소위, 표현이 그래서 죄송합니다만 갑과 을의 관계에서 을의 입장이기 때문에 그것을 저희들 마음대로 어떻게 할 수가 없습니다.  실제로 광주시 과제 같은 경우는 광주시의 요구에 의해서 대외비로 분류가 돼 있고 따라서 광주시에서 어느 시점에 가서 대외비를 해제하라고 하면 저희는 해제를 하게 되는 것입니다. 
</p>
<p><b>○ 김대원 위원 </b> 알겠습니다.  그래서 수탁이라는 것은 글자 그대로 “우리가 돈을 이 과정에 얼마 줄 테니까 이 돈을 가지고 우리를 위해서 이러한 연구를 해 주십시오” 하는 부분이니까 결과적으로 연구에 대한 판권은 수탁기관이 갖는 것은 맞습니다.  계약원칙에도 맞는데 그 부분이 주요사안이 돼서 대외비라고 했던 부분들이 언론에 먼저 공개되더라는 얘기예요.  어떻게 여기에는 아직 납품도 안 된 사안이 광주지역의 예를 들어서 지방신문 같은 데에서는 먼저 배정되고 먼저 언론에 공개되고 나중에 결과를 까놓고 보면 그렇게 되더라는 얘기예요.  그래서 경기개발연구원이 과연 대외비 부분을 얼마만큼 충실히 대외비할 수 있는 그런 정보안정에 대해서 시스템을 가지고 있습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 저희들은 나름대로 어떻게 판단하냐면 기본과제, 정책과제, 수탁과제를 통틀어서 과제 진행 중인 것에 대해서는 자문회의라는 형식을 통해서 전문가들의 의견을 듣는 것 외에 별도로 진행 중인 과제를 외부에 공개하지는 않습니다.  두 번째로 지금 광주시 의견이 나왔습니다만 수탁과제 같은 경우는 그 발주처의 의견이 있지도 않은 상태에서 그것을 만약에 저희들이 공개했을 때 그것은 소위 과제수행의 신의성실의 원칙에 어긋난다고 생각하기 때문에 그 부분에 대해서는 저희들 나름대로 굉장히 엄격하게 관리하고 있습니다.  참고로 이번에 광주 건 같은 경우에는 그렇습니다.  저희 한현규 원장 사건이 터지고 나서 바로 그 직후에 이게 그 건과 저희가 했던 과제하고 연결돼 있다라는 것이 확인되니까 광주시에서 실제로 경기도 기자실에 와서 저희들이 수행했던 과제의 결과만을 공식적으로 기자들한테 발표를 한번 한 적이 있었습니다.  그것 때문에 그 후로 언론에서 결과에 대해서는 공식적으로 이야기하기 시작했습니다. 
</p>
<p><b>○ 김대원 위원 </b> 그러니까 대외비가 이미 지나버린 것 아니에요.  공개되고 나서 무슨 대외비…….
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그것은 광주시에서 그렇게 한 것이기 때문에, 발주처에서 한 것이기 때문에 저희들이 그것을 가지고 “대외비로 하라고 해놓고 왜 그랬냐”라고 저희들이 따질 수 없는 것 아니겠습니까? 
</p>
<p><b>○ 김대원 위원 </b> 알겠습니다.  서면으로 스물여섯 가지를 했지 않습니까, 현재.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다.
</p>
<p><b>○ 김대원 위원 </b> 스물여섯 가지 대외비 목록을 제출해 주시고요.
