<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇게 하겠습니다.  
</p>
<p><b>○ 김대원 위원 </b> 하여간 경기개발연구원이 지금 현재 속으로는 ‘초상집에 와서 칼부림할 일은 없는 상황’으로 생각하는데요.  지금 부원장님이나 처장님 같은 경우에는 임명직이라 그렇겠지만 나머지 실제 실무자 여러분들께서는 외부 부분과 정말로 단절해서 본연의 경기개발연구원의 자세로 돌아가서 지금 현재와 같은 2005년도 연장선상에서 연구과제를 만들 게 아니라 정말 경기개발연구원을 위한 그런 과제들을 지금부터라도 설정해서 2006년도는 아시다시피 4대 동시지방선거가 있고 그리고 선거의 결과에 따라서 경기도의 정책기조가 충분히 달라질 소지도 있으니까 그런 부분도 감안하셔서 지금 현재 예산배정을, 2006년도 연구과정 자체에 예산배정을 전부다 해놨을 때 7월 1일 이후에 새로운 집행부하고 상의해서 정책과제를 다시 제안해 왔을 때 예산이 없어서 못한다라든가 그런 수요에 충족하지 못하는 상황이 안 일어날 수 있도록 지금부터라도 충분히 준비하시는 그런 기간이 되기를 빌겠습니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 열심히 노력하겠습니다.
</p>
<p><b>○ 김대원 위원 </b> 이상으로 질의 마치겠습니다. 
</p>
<p><b>○ 위원장 정인영 </b> 김대원 위원 수고하셨습니다.  다음 질의하실 위원 질의해 주시기 바랍니다.  이효선 위원 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이효선 위원 </b> 부원장께서 처음에 임용됐을 때 조직원들의 반발이 있었고 집단사퇴 이후에 새로운 간부가 임용된 것으로 알고 있습니다.  어쨌든 그 이후에 무난하게 그 직을 수행해서 전체의 융화를 하시는 데 일익을 담당하셔서 감사하게 생각하고요.  몇 가지 질의하겠습니다.  본인이 작년에 얘기했던 중에 “연구원을 전국적으로 뽑았으면 좋겠다” 그랬는데 지금 자료에 보면 석사급이 2004년도 75명 중에 전북대 1명, 중국 상해대 1명, 경북대 하나 뽑았어요.  그리고 2005년도에는 98명 중에 경북대 하나하고 중국 대학교 하나밖에 없습니다, 석사급이.  그리고 자료요청한 것을 제가 아까 받아봤는데 조선일보하고 동아일보에 광고를 냈더라고요.  그 광고비용이라면 박사급에 보면 42명 중에 강원대학교 하나, 전북대 하나, 영남대 하나, 경북대 하나로 돼 있습니다.  중요한 것은 어떻게 어프로치(approach)하느냐에 따라 결과는 틀려집니다.  동아일보하고 조선일보에 광고 냈지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이효선 위원 </b> 그 광고비용이면 다른 지방신문에 광고를 다 낼 수 있습니다.  예를 들면 경기도 오면 몇 개 신문, 그리고 각 대학에 협조를 구해서 공고를 직접 가서 할 수도 있고요.  이러한 협조를 하지 않고 경기도가 경기개발연구원을 운영하는 것들을 보면, 학력을 보면 전부 다 서울 근교예요.  말이 경기도지 서울 쪽으로 틈만 나면 도망갈 사람들만 뽑아놨어요.  그래서 앞으로 계획은 어떤지 묻고 싶습니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 우선 간단히 말씀드리면 저희는 지금 광고에 나와 있듯이 실제로 지금까지 인력을 충원하면서 국내와 국외, 수도권과 지방대학 출신을 차별하지 않도록 최선의 노력을 다해왔습니다.  실제로 이 광고를 조선일보하고 동아일보에 냈습니다만 저희 연구원에 박사나 석사를 응시하는 사람들은 뭘 보고 오냐면 이렇게 저희들이 광고를 내면 학술진흥재단에 신고를 합니다.  그러면 거기에 인터넷으로 뜹니다.  그것을 보고 오는 응시자가 훨씬 많습니다.  훨씬 많은 것이 아니라 거의 대부분이 그것을 보고 옵니다.  동아일보나 조선일보가…….
</p>
<p><b>○ 이효선 위원 </b> 잠깐만.  훨씬 많은데 지방대학 사람들이 지원을 안 했을까요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 지방대학 출신들이 나름대로 지원을 합니다.  나름대로 지원을 한 그 후부터 저희들은 사실 학력 그런 부분에 대해서 일체 고려하지 않고 세미나를 통해서 능력에 따라서 뽑습니다.  
</p>
<p><b>○ 이효선 위원 </b> 제가 작년에 요구했던 것은 여기 있는 분이 얼마나 능력이 있어서, 박사급이나 석사급이 어떠한 기준에 의해서 왔는지 모르지만 글로벌 3만불시대에 세계 속의 한국을 부르짖는 경기도의 정책이 맞다면 각 도의 정서가 중요하다는 거예요.  여기 계신 분들 중에서 지방에서 태어났는데 서울의 유명대학을 다닌 사람들은 부모를 잘 났거나 아니면 공부를 잘 해서 장학생일 경우도 있습니다.  하지만 지역을 떠나지 못하는 가정형편, 홀어머니를 모신다든가 이런 분들에게 기회의 균등, 평등을 주기 위해서라도 그런 기회를 부여하자는 겁니다.  그래서 지금 경기도만이라도 경기도만의 정책이 아닌 전국적인 정책, 각 정책들이 ‘아, 경기도는 8개도를 다, 16개 시ㆍ도를 포괄하고 가는구나’라는 것들을 인식할 수 있는 방법은 그 지방의 대표적인 대학의 학자 출신들을 초빙해서 그들과 같이 이 통합문제는 논해야 된다는 겁니다.  제가 요구했던 사항은 그건데 지금 바로 이 상황은 인터넷 본다는데 인터넷 안 보는 사람도 있어요, 바빠서.  연구하다보면 그것 안 볼 수도 있습니다.  그리고 현직에 있는 사람은 안 볼 수도 있습니다.  그러면 우리가 각 학교나 이런 데 하면 우수한 인재, 그 지역의 정서를 경기도 정책에 입안할 수 있는 방법을 얘기한 거지 내가 고향이 제주도인데 연세대학교 나왔다고 해서 제주도 정서를 갖고 있냐, 그렇지 않다는 겁니다.  제일 예민한 사춘기에 거기에서 대학을 다닌 사람이 그 지역정서의 아픔을 압니다.  그런 뜻에서 얘기한 거고요.  내년에 충원할 때는 꼭 그렇게 해주시기 바랍니다.  중앙지로 하지 말고 그 돈이면 16개 시ㆍ도에, 서울ㆍ경기 뺀 다른 시ㆍ도의 대표 지방지에다, 지방지도 살릴 겸해서 거기다 광고 내는 것이 맞지 않나 하는 생각이 듭니다.  그거고요.  여기도 우리가 정책포럼을 하는데요, 사회포럼은 없어졌나요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 지금 거의 진행이 안 되고 있습니다. 
</p>
<p><b>○ 이효선 위원 </b> 존재합니까, 없어졌습니까? 
