<p><b>○ 경기개발연구원부원장 김태승 </b> 사회포럼은 현재 포럼의 구성은 형성돼 있는데 포럼 구성원들의 참여도가 낮아서 실제로 포럼에 대해서 간단히 말씀드리면 지금 굉장히 활발하게…….
</p>
<p><b>○ 이효선 위원 </b> 잠깐만요.  묻지 않은 것은 답변하지 마요.
