<p><b>○ 이효선 위원 </b> 사회포럼을 개최할 시도는 해봤나요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 나름대로는 몇 번에 걸쳐서 시도를 했었습니다.  특히 그전에 상임자문위원으로 계시던 지금 영어문화원 원장이신 이수영 원장께서 계실 때는 사회포럼을 활성화시키기 위해서 나름대로 많은 노력을 하셨었습니다. 
</p>
<p><b>○ 이효선 위원 </b> 그 자자한 송호균 교수지요? 
