<p><b>○ 경기개발연구원부원장 김태승 </b> 실제로 오거나 하면 그날에 굉장히 여러 가지 일이 있다고 하면서 날짜가 안 잡히니까, 그 날짜 자체를 잡지 못하는 경우가 몇 번 있었습니다. 
</p>
<p><b>○ 이효선 위원 </b> 제가 알기로 2년여 정도 사회포럼을 안 하는데 그 2년간 한국사회가 문제점이 없었나요?  아주 융합이 잘 되고 발전지향적이고 경기도 정책이나 중앙정부의 정책이 국민의 호응을 받고 ‘야, 이건 사회문제 없다, 진짜 발전적인 나라다’라고 국민이 생각했습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 해야 될 일은 굉장히 많이 있다고 생각합니다. 
</p>
<p><b>○ 이효선 위원 </b> 교육포럼은 몇 번 했지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 교육포럼은 거의 매달 한 번씩 하고 있습니다. 
</p>
<p><b>○ 이효선 위원 </b> 그런데 사회적인 문제를 봉합시키고 그것을 치료해 나가는 것도 정치의 최대 목적 아닙니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이효선 위원 </b> 경기개발연구원은 순수학문보다는 그래도 경기도 정책과 같이 가는 그런 연구소 아닙니까? 
