<p><b>○ 이효선 위원 </b> 빠른 시일 내에 사회포럼 한번 여세요.  그래서 지금 국민이 아파하는 부분, 국민이 불안해 하는 부분 이런 것들을 우리가 토론해 내는 그런 경기개발연구원이 돼야지 쓸데없는 것, 글쎄 쓸데없는 것은 안 하겠지만 우선순위를 빨리 잘 정하는 것이 그 단체의 발전과 연결돼 있지요?
