<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 이효선 위원 </b> 교육포럼에 있어서 쭉 몇 가지 올해 하셨는데 경기도에는 평준화ㆍ비평준화지역이 있어요, 그렇지요?
