<p><b>○ 이효선 위원 </b> 우리 국민은, 세상은 정부를 보기를, 중앙정부가 됐는 지방정부가 됐는 진실성과 정직성입니다.  그렇지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 이효선 위원 </b> 그런데 이번에 평등지역이 비평등지역보다 우수하다는 논문이 발표됐어요.  그로 인한 뒷말이 많습니다.  그렇지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 이효선 위원 </b> 경기도도 이런 것들에 대한 논의를 한번 해볼 때가 됐지 않았나.  특히 경기도에는 비평준화지역이 많습니다.  그래서 그 지역의 NGO라든가 일부 단체에서 평준화를 부르짖는데 거기에 타당성조사 같은 것도 해봐야 되고요.  우리가 샘플링을 좀 적게 할 수 있을 거예요, 경기도는.  제가 속해 있는 광명이나 이런 데는 지금 비평준화지역입니다.  그리고 항상 얘기하지만 수능시험도 자기네 동네서 안 보고 다른 동네 가서 보는 아주 웃기는 동네가 경기도입니다.  이런 것들을 연구하여 발표해서 정책에 입안할 수 있는 것들을 만들어 내는 것이 경기개발연구원의 목적이라고 생각합니다.  그것을 한번 해보시고요.
