<p><b>○ 경기개발연구원부원장 김태승 </b> 남북포럼 같은 경우는 실제로 남북교류협력사업, 특히 경기도에서 하고 있는 남북교류협력사업들의 평가를 하기도 하고요.  가장 최근에 있었던 것은 남북포럼에서 소위 비무장지대에 발전소를 설립하는 것이 타당한가 타당치 않은가에 대해서 그 분야 전문가를 불러다가 토론해 봤습니다.  
</p>
<p><b>○ 이효선 위원 </b> 몇 달 전까지 남북교류특위가 있었어요.  지금 폐지됐는데, 의회에.  그런데 도에는 남북교류협력위원회라고 180억 정도 남은 돈을 심의하고 결정하는 단체가 있습니다.  그렇지요?
