</p>
<p><b>○ 이효선 위원 </b> 저도 남북포럼에 몇 번 참석을 해본 적이 있습니다.  전반기 남북교류위원장을 했을 때.  그런데 보면 학자들의 성향이 필드에서 느끼는 감이 없다는 겁니다.  예를 들면 남북문제 전문가라고 하는 경남대학교의 북한대학원교수 누구를 지칭 안 하겠습니다만 독일과 한국을 비교해요.  독일은 지방자치가 완벽히 구성된 나라입니다.  우리는 그렇지 않거든요.  그런 것을 갖고 막 얘기해서 제가 따지기도 했지만 이게 남북포럼이 남북포럼으로 끝나면 안 되고 끝난 결과물이 있어야 된다는 거예요.  돈 들이고 시간 들여서 경기개발연구원에서 남북포럼했는데 이러한 문제점이 있고 이것에 대한 실제는 어떻게 됐고 실제로 언제부터 했는데 지금은 뭐다라는 결과물이 나와야 되는데 그렇지 못하다는 겁니다.  결과가 도출되지 않은 것들은 자본주의에서는 연구의 대상이 아니에요.  그렇다고 이게 뭐 전문기자, 한겨레신문기자, 누구누구 불러서 하는 것도 좋지만 그것을 그것으로 끝날 것이 아니라 같이 협의하고 결과물 도출해 내고 그것이 국민들이 만족해하는 정책적인 결과가 나와야 됩니다.  그렇지요? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다.
