<p><b>○ 이효선 위원 </b> 포럼이라는 게 그럴 때 필요한 것이 아닌가 하는 생각이 듭니다.  그리고 지금 초상집 얘기도 하고 그러는데 그것은 별로 관심 없는 얘기고요.  한현규 원장이 잡혀간 것은 본인의 문제지 여러분의 문제는 아니지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
