<p><b>○ 이효선 위원 </b> 여러분이 그분이 무슨 돈 받아 먹는데 협조하지는 않았지요?  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 전혀 그런 적 없습니다. 
</p>
<p><b>○ 이효선 위원 </b> 그러면 전혀 없이 행동해야 됩니다. 
