<p><b>○ 이효선 위원 </b> 위축되지 말고 오히려 공격적으로 대응해야 됩니다.  “우리 경기개발연구원과 한현규 원장과 동일시하지 말라”라고 언론플레이를 해야 됩니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 알겠습니다.
