<p><b>○ 이효선 위원 </b> 그리고 거기 검찰에서 왔을 때도 당당하게 해야 되고요.  지금 이것이 청와대까지 연결됐다 이런 말도 나오는데 내가 알기로는 오포지역에 건설업체 5개가 있는데 어떻게 배분하면 좋겠냐고 연구용역을 준 것 같은데 결론은 여기 경기개발연구원에서 5개 업체를 동등하게 주라고 결론 내려서 용역이 나간 것으로 알고 있습니다.  만약에 그때 한현규 원장이 단 한마디라도 모 업체를 잘해주라는 말을 들은 적이 있나요?
