<p><b>○ 이효선 위원 </b> 학자라고 해서 다 선비가 아닙니다.  이제 현실의 선비는 공격적으로 자기의 의무를 다하고 자기 권리는 찾는 그런 당당함 속에 선비의 모습이 보이는 거예요.  그렇지 않습니까?  그래서 다행스러운 것은 부원장님이 오실 때는 말이 많았는데 지금은 그나마 조직원들한테 인정받고 덕망있는 분으로 인정받는다고, 제가 잘못 들었는지 모르겠지만 그렇게 들었습니다만.  이게 뒤돌아서 웃을 문제가 아니에요.  본인이 아는 것 아니야.  뒤 보고 웃으면 웃음이 될지 찡그릴지 어떻게 알아요.
