<p><b>○ 이효선 위원 </b> 그거 고치시고요.  제가 개인적으로 부탁 두 가지 하고 말겠습니다.  언제는 광명시가, 제가 속해 있기 때문에 말씀드리는데 34만 8,000에서 32만 8,000으로 2만명이 최근 8, 9년 사이에 인구가 줄었습니다.  그 원인분석을 한번 해서 저한테 제출해 주시기 바라고요, 문제점이 뭔지.  또 하나는 지금 노동자 문제가 상당히 첨예하게 대두되고 있습니다.  지금 청와대에서 그런 “님을 위한 행진곡”을 합창하는 그런 시대지만 지금 공무원노조가 끼치는 영향이 상당히 큽니다.  그렇지요?  그래서 공무원노조가 결성된 이후에 공무원의 근무자세는 어떻게 변했나, 전과 후가.  그리고 공무원의 바람직한 근무자세는 어떤 것인가.  그리고 이제 민주주의 실현을 위해서는 공무원이 권력과 직위의 압력에 굴하지 않고 자기 일을 했을 때 인사적 불이익을 당하지 않는 것이 민생구현의 목적이고 노동조합 결성의 목적이라고 봅니다.  여기에 대한 것을 간단하게 리포트 형식으로 해서 저한테 제출해 주시고요.  그리고 공무원에 대해서 우리가 그들을 적으로 생각하지 말고 동지로 봐야 되거든요.  이제는 결성됐고 어느 누구도 그 존재를 무시할 수 없는데 집행부가 공무원을 어떻게 상대해야 되느냐는 것도 연구해서 공무원노조와, 집행부가 바뀌더라도 집행부가 어떻게 해야 지방정부가 성공하는지를 서울은 서울대로 전국은 전국이지만 경기도만이라도 31개 시ㆍ군의 노조결성문제 또 각 노와 집행부의 문제 이런 것들을 분석해서 지금 근무하는 지사의 남은 임기 동안, 아니면 앞으로 당선된 지사의 정신 마인드를 고치는 데 역할을 해주셔서 집행부와 노동조합이 같이 살 수 있는 길, 그로 인하여 ‘아, 진짜 민주사회가 실현됐구나’ 하는 것을 국민이 느끼게끔 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 노동자문제, 공무원노조 이 문제는 저희 내부에 사실 마땅한 연구자가 없습니다만 유관 연구기관들과 협의해서 최대한 가능한 답을 만들어 보내도록 하겠습니다. 
</p>
<p><b>○ 이효선 위원 </b> 우리가 고정관념을 깨야 될 것은 “노동자분야는 노동전문 박사가 해야 된다” 그 고정관념을 깨야 됩니다.  박사학위는 그 학문을 연구할 자격을 부여한 거지 마스터 자격증을 준 것은 아닙니다.  그렇지요?
