<p><b>○ 이효선 위원 </b> 경제학이면 중소기업, 소기업, 대기업을 공부한 사람이 있을 테고 경영방법을 연구한 사람이 있을 테고 미국식방법, 어디 이게 많지요?  그것을 다 연구한 사람이면 여기 수백만 명 써야 됩니다, 연구원이 개발하려면.  부원장도 자세가 틀렸잖아.  “전문가가 없으니까 못한다, 다른 데로 연구…….” 그렇게 하면 안 돼요.  사회학을 공부하신 분이라든가 경영학을 공부하신 분 중에서도 노동경제를 공부하지도 않았는데 부전공으로 한 사람 있지 않습니까?  그런 사람들 시켜서 하세요.
