<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 저희들 내부에서 찾아보겠습니다만 저희들보다 더 잘하는 사람이 있을 수 있으니까 그 사람들 찾아서 확인하도록 하겠습니다. 
