<p><b>○ 위원장 정인영 </b> 좌석을 정돈해 주시기 바랍니다.  감사를 계속하겠습니다.  계속해서 감사 질의답변을 진행토록 하겠습니다.  질의하실 위원 계시면 거수로 신청해 주시기 바랍니다.  정금란 위원 질의해 주시기 바랍니다. 
