<p><b>○ 정금란 위원 </b> 정금란 위원입니다.  먼저 금번 행정사무감사 준비와 각종 자료를 작성하느라 수고해 주신 김태승 부원장님 이하 관계 직원 여러분께 이 자리를 빌어 감사하게 생각합니다. 
</p>
<p style="padding-left:1.2em">  먼저 111페이지 자료를 보면 수탁용역사업이 있지요?  거기에 대해서 말씀드리겠습니다.  수탁용역사업 건수가 2004년도에는 17건이고 2005년도에는 5건으로 나타나있습니다.  그런데 이 건수 중에서 경기개발연구원 측의 귀책사유로 연장되거나 일시중지하여 의뢰기관으로부터 양해를 얻지 못해서 지연된 건수가 26건 있다고 그러셨지요? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 과업중지된 총 건수가 26건입니다.
</p>
<p><b>○ 정금란 위원 </b> 그 자료를 주실 때 지체상금을 어떻게 보상했는지 그런 것까지도 자료요청할 때 해주셨으면…….
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇게 하겠습니다만 사실 지체상금을 물은 적이 한 번도 없기 때문에…….
