<p><b>○ 정금란 위원 </b> 없어요?  네, 알았습니다.  그러면 그런 이유가 발생하면 연구원에게도 책임이 따라야 되는데 그런 부분에 대해서는 어떻게 조치하고 계십니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 저희들 나름대로는 실제로 지금까지 진행된 바로는 그 과제를 수행함에 있어서 저희들이 늦게 했거나 아니면 잘못해서 과업이 중지되거나 지연된 사례는 없습니다.  그러다보니까 주로 발주기관 사정에 따라서 과업중지 내지는 과업연장을 하게 되고 그렇게 됩니다만 만일의 경우에 저희 연구원의 귀책사유로 해서 과제책임자의 잘못 등으로 인해서 지체상금을 물게 되거나 그렇게 되면 저희 내규에 의해서 두 가지 형태로 진행됩니다.  내규에 의해서 징계를 하고 또한 지체상금에 대해서 본인이 일정부분 책임을 지도록 그렇게 하고 있습니다. 
</p>
<p><b>○ 정금란 위원 </b> 그리고 자료의 397페이지 보면 연구결과물의 언론매체에 보도된 실적에 대해서 여쭤볼게요.  경기개발연구원에서 연구한 결과물이 금년 한해 동안 언론매체에 보도된 건수가 총 90여건으로 이 중에 지방지에 69건, 중앙지 및 YTN 등의 전국방송에 21건으로 나타나 있거든요.  물론 보도된 내용이 좋은 쪽으로 게재가 됐을 것이라고 생각합니다.  그렇다면 지방지보다는 중앙지에 더 많이 보도가 됐으면 하는 그런 아쉬움이 있고요.  또 알찬 내용이나 좋은 내용이라는 연구 결과문이 중앙지나 YTN 쪽에, 전국 방송국에 더 많이 보도돼서 전국의 민간기업이나 국영기업 또 국가기관, 더 나아가서는 타 시ㆍ도의 지방자치단체까지 경기개발연구원을 신임하게 됨으로써 경기개발연구원의 위상 제고에도 크게 보탬이 되어 이로 인해 연구용역사업 확대에 크게 기여할 것으로 본 위원은 생각됩니다.  앞으로 언론매체의 보도에 상당한 관심을 갖고 힘써주셨으면 하는 그런 생각을 갖고 있는데 어떻게 생각하시는지와 아니면 다른 계획이 있으시면 답변을 해주셨으면 좋겠습니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 감사합니다.  지방ㆍ중앙이라는 것들은 저희들도 사실은 저희의 연구성과가 외부적으로 인정받는 증표가 바로 그런 것이기 때문에 그런 것들은 저희들도 적극 장려하고 있고 저희들이 연구결과가 끝나면 반드시 보도자료를 내도록 돼 있습니다.  특히 저희 연구원 같은 경우는 실제로 서울시정개발연구원이 있습니다만 지자체 연구기관 중에서 가장 큰 연구기관입니다.  또한 더불어서 저희 연구기관의 지향 자체가 분권에 대한 한국의 대표적인 연구기관, 그 다음에 대도시권 연구기관에서는 한국의 대표적인 연구기관이 되고자 합니다.  그런 점에서 앞으로 이런 부분들이 인정을 받을 수 있도록 더 해야 될 텐데 이것과 관련해서 가장 기본적인 것은 연구의 질을 어떻게 높이느냐가 문제일 거라고 생각합니다.  그래서 그 부분에 대해서 우선 집중하고 또한 더불어서 저희들 연구성과가 좀더 광범위하게 인정받고 알려질 수 있도록 하기 위해서 신문이나 언론에 홍보되는 것도 있지만 각종 세미나나 각종 학회에 저희 박사들이 나가서 연구성과를 발표할 수 있는 기회를 최대한 확대하도록 노력하고 있고 앞으로 더욱 더 노력하도록 하겠습니다. 
</p>
<p><b>○ 정금란 위원 </b> 연구용역사업이 확대될 수 있도록 많이 노력해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 노력하겠습니다. 
</p>
<p><b>○ 정금란 위원 </b> 그리고 연구사업비 지출내역에 대해서 303페이지에 보면 미수행과제가 있는데, 연구사업비 중에요.  발생사유가 어디 있습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 이것은 제가 들어오기 전 일이라서 정확하게 모르겠는데…….
</p>
<p><b>○ 기획조정실장 성현찬 </b> 기조실장 성현찬입니다.  저도 올해 임용돼서 자세히 모르겠는데 작년에 지역연구를 저희가 1년에 한 2건 정도를 수행하고 있습니다.  그런데 작년의 경우는 저희가 시ㆍ군에서 먼저 의사를 받고요.  그 다음에 저희가 적절하다고 판단되는 시ㆍ군을 선정해서 지역연구를 하게 되는데 작년에는 1건 외에 두 번째 건에 대해서는 시ㆍ군에서 요청사항도 없고 그래서 저희가 선정하지 못해서 1건으로 완료했던 사항입니다.
</p>
<p><b>○ 정금란 위원 </b> 아, 그래서 이게 그냥 남아있는 거군요.
</p>
<p><b>○ 기획조정실장 성현찬 </b> 네, 그렇게 되겠습니다. 
</p>
<p><b>○ 정금란 위원 </b> 그러면 매년 이렇게 잡아놓는 것은 얼마나 잡아놓습니까? 
</p>
<p><b>○ 기획조정실장 성현찬 </b> 저희가 그래서 내년에도 잡아놨습니다만 1건으로 해서 줄였습니다.  지금까지 실적도 있고 해서 대부분의 지역연구 시ㆍ군을 어느 정도 했다고 생각했고 그래서 2004년도의 실적을 가지고 올해에는 지역연구 2건을 하고 있고 내년에는 1건 정도로 예산을 잡아놓고 있습니다.  그래서 시기나 시ㆍ군의 요청사항에 따라 적절히 조절하고 있습니다. 
</p>
<p><b>○ 정금란 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 정인영 </b> 정금란 위원 수고하셨습니다.  다음 질의하실 위원 질의하여 주시기 바랍니다.  함진규 위원 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 함진규 위원 </b> 우선 김태승 원장직무대행으로 불러야 되나요? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 부원장으로 부르시면 됩니다. 
</p>
<p><b>○ 함진규 위원 </b> 부원장으로 불러도 되겠습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 2005년 3월 10일에 취임하셨지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다.
</p>
<p><b>○ 함진규 위원 </b> 그러면 대략 8개월 정도 되신 거네요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 함진규 위원 </b> 실례되는 말씀인지 모르지만 업무는 완전히 어느 정도 파악이 되셨지요? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 부족하지만 나름대로 그렇게 생각하고 있습니다. 
</p>
<p><b>○ 함진규 위원 </b> 감사를 처음 준비해 보셨지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 함진규 위원 </b> 감사 준비하느라고 고생이 많으셨고요.  또 지금 제가 파악하고 있기로는 한 50여명, 연구원 중에 박사분들이 42명 정도 되시는 것으로 알고 있는데 그분들을 포함해서 연구원 직원 여러분께도 감사 준비하시느라고 고생이 많았다는 말씀을 드리고 싶습니다. 
</p>
<p style="padding-left:1.2em">  저는 맨 마지막에 하다보니까 사실 제가 일정부분을 생각나는 대로 메모하고 준비를 했습니다만 이미 다른 위원님들이 똑같은 자료와 시각을 가지고 하다보니까 거의 다 말씀들을 많이 하셔서 제가 딱히 드릴 말씀은 많지 않습니다만 그러나 똑같은 내용이라 하더라도 제가 보는 시각이 또 틀리기 때문에 중첩되는 부분이라 하더라도 제 소신껏 질의를 하겠습니다.
</p>
<p style="padding-left:1.2em">  그동안 경기개발연구원이 경기도 정책을 집행하는데 상당히 중추적인 역할을 굉장히 많이 했다고 저는 나름대로 보고 있습니다.  사실 본 위원이 보기에 집행부 공무원들이 아무리 좋은 생각을 갖고 있다 하더라도 바쁜 업무 속에서 그런 아이디어를 사실 꼼꼼히 챙긴다든가 하는 것이 상당히 어렵습니다.  그래서 연구원이 발족된 것으로 알고 있고 그런 취지에 많이 부합을 했다고 봅니다. 
</p>
<p style="padding-left:1.2em">  그러나 여러 위원님들이 지적을 하셨지만 이번 불미스러운 일로 인해서 상당히 연구원의 이미지가 실추된 것이 있는 게 아닌가 하는 생각이 이유야 어찌됐든 간에 듭니다.  그렇다고 해서 계속 위상이 흔들려서는 안 된다고 생각하고 있고 다행이라는 말을 쓸 수는 없지만 어쨌든 그게 개인적인 일로 그렇게 언론 지상에 보도가 되고 또 경기개발연구원이 아까 이효선 위원님도 말씀하셨지만 관련이 안 됐다고 하니까 참 다행인 거고요.  그분이 아까 좋은 말씀을 다 하셨기 때문에, 그렇다 하더라도 제가 보기에는 저 개인적인 소견인지는 모르겠지만 뭔가 어수선하고 체계적이지 못한 면이 있지 않겠느냐 이런 생각이 듭니다.  솔직한 심정이고요.  앞으로 다행히도 관련이 없다고 그러니까 심기일전해서 어떤 적극적인 역할을 많이 해주셨으면 하는 거고요.
</p>
<p style="padding-left:1.2em">  그 다음에 지금 김태승 원장님 직무대행이라고 제가 불렀지만 부원장이라고 말씀하셔서, 개인적인 사항을 질의해도 괜찮겠습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 다름이 아니고 여기 오시기 전에 이미 자료를 통해서 보았습니다만 교통개발연구원인가요?  거기 근무하셨죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 함진규 위원 </b> 아까 근무하신 지 15년이라고 하셨죠?  거기만 근무하신 경력이 그렇습니까?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그 이전에 국토연구원에도 있었습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그걸 다 포함해서 그렇습니까?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다.
</p>
<p><b>○ 함진규 위원 </b> 그러면 15년 연구경력 정도면 연구원 중에서는 경력이 있다고 봐야 되는 건가요?  어떻게 생각하시는지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 주변에 있는 사람들 입장에서 보면, 저희 연구원으로 비교를 하겠습니다.  저희 연구원의 선임연구원 이상급하고 경력이 거의 비슷하다고 판단하고 있습니다. 
</p>
<p><b>○ 함진규 위원 </b> 선임연구원이요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 그러면 저는 자료를 갖고 있어서 파악이 되고 있지만 혹시라도 모르시는 분이 계실까봐 제가 한번 말씀을 드리겠는데 연구원을 굳이 5단계로 구분하고 있죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 처음에 들어와서 연구원이 있고 그 다음에 책임연구원이 있고 그 다음에 연구위원이 있고 그 다음에 선임연구원, 수석연구원 이렇게 돼 있죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 5단계로 돼 있는 것으로 저도 이 자료를 보지 않고는 외람된 말씀인지 모르겠지만 잘 모르겠습니다.  “수석”, “선임” 정도는 아는데 헷갈려 가지고 제가 한번 말씀드렸고요.  죄송하지만 전공을 뭘 하셨습니까?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 학부 때부터 계속 경제학을 해왔습니다. 
</p>
<p><b>○ 함진규 위원 </b> 박사학위도 그러면 경제학을 하신 건가요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 왜 제가 이런 말씀을 드리냐 하면 정기감사가 11월에 있으니까 부원장님이 오시면서 제가 외부에서 듣고 있기로는 상당히 경기개발연구원이 소용돌이라고 그럴까요, 그렇게 표현해도 되는지 모르겠는데 상당히 소용돌이가 많았던 것으로 알고 있습니다.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 크고 작은 일이 있다고 보도를 통해서 알았습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그래서 기존에 계셨던 연구원들이 일괄 보직들을 사퇴하고 그런 것도 알고 계시죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇게 들었습니다. 
</p>
<p><b>○ 함진규 위원 </b> 익히 알고 계신 문제지만 왜 그랬다고 생각하십니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 솔직히 편안히 말씀드리겠습니다.  제 커리어가 15년이라고 이야기 하지만 또 아까 말씀드린 바와 같이 제 커리어가 지금 우리 연구원의 시니어급 이상의 연구원들보다 그 이상의 커리어를 가지고 있다고 할 수 없습니다.  그렇기 때문에 그런 상태에서라면 아까 김영복 위원님께서 말씀해 주셨습니다만 부원장 직제가 있고 부원장 직제가 제대로 돌아가려고 한다면 아마 내부에서 승진하는 게 더 타당했을지도 모르겠습니다.  다만 그 부분에 대한 이사회의 판단이 지금 당장 내부에서 승진하는 것보다는 외부에서 수혈을 통해서 뭔가 새로운 기운을 불어넣고 싶다고 해서 저를 뽑았겠습니다만 그로부터 발생하는 내부의 안타까움은 있었을 것이고요.  저는 그 부분에 대해서 제 나름대로 충분히 수긍하고 인정하고 있습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그래서 본 위원이 파악하기에는 원장께서도 외부에서 취임을 하셨고 또 부원장도 외부에서 취임을 하다보니까 아무리 연구원이지만 조직의 생리라고 그럴까요 어떤 위계라고 그럴까요, 아마 그런 것 때문에 많이 반발하셨던 것으로 제가 알고 있습니다.  지금은 많이 수습이 됐나요, 어떻게 된 건가요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 두 가지로 말씀드리겠습니다.  우선 많이 반발이라고 하는데요.  그 반발이라는 것은 제가 판단하기에는 크지 않았다고 생각하고요.  두 번째로 실제로 저희 연구원에 있는 모든 구성원들이 굉장히 강한 애원심을 가지고 있다고 생각합니다.  연구원이 연구원으로서의 기능을 유지하기 위해서는 설령 약간의 불만이 있다고 하더라도 그것을 스스로 통제하고 조절하는 능력을 가지고 있다고 생각합니다.  그 덕분에 저도 제 나름대로 그 이후로는 큰 문제없이 다른 연구원 구성원들하고 동화해서 연구원 발전을 위해서 노력하고 있다고 생각합니다. 
</p>
<p><b>○ 함진규 위원 </b> 그래서 본 위원도 상당히 우려스러운 관점에서 바라보았습니다.  그것이 왜 그러냐하면 저희 위원회 소관이기 때문에 봤지만 그러나 시간이 흐르면서 지금 부원장님 말씀하신 대로 제가 몇 개월이 지난 후에 다시 의견을 들었을 때 그래도 계신데 제가 이런 말씀을 드려서 조금 죄송합니다만 그래도 상당히 소탈하게 잘 하신다는 말씀을 들어서 처음에 제가 우려했던 것보다는 상당히 그런 걱정이 줄었습니다.  다만 제가 말씀드리고 싶은 것은 부원장이 생각하시기에 본 위원의 생각인지 모르겠지만 어느 연구원이든지 원장은 자격기준을 보니까 특별한 게 없습니다.  없죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 이사회에서 결정을 하고, 정관을 알고 계시죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 정관을 보니까 원장에 대한 자격 또는 부원장에 대한 자격은 없는 것으로 알고 있습니다.  그렇죠?  그렇게 알고 계시죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그런데 대부분 원장인 경우에는 이것이 어떤 순수한 학술단체가 아니기 때문에 정관에도 연구원에 대한 목적이 2조에 나와 있습니다.  여러 가지 제가 다 말씀드릴 수는 없는데 경기도와 관련된 핵심은 조사분석이나 연구활동을 통해서 지역균형개발과 지역경제 향상, 이것은 순수한 학술단체라고만 보기에는 그런 거거든요.  그래서 어차피 지사하고 원장하고 코드라는 것은 좀 그렇지만 맞는 사람이 갈 수밖에 없거든요.  어떻게 생각하십니까?  그 부분에 대해서는.  자격은 없지만 우리가 일반적인 관점에서 보면 우리 경기도뿐만 아니라 서울시정개발연구원도 마찬가지이고 중앙정부의 연구기관도 저는 마찬가지라고 보거든요.  그것에 대해서 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 아무래도 연구원의 이사장이 도지사이기 때문에 도지사께서 적당하다고 하는 사람을 이사들의 의견을 물어서 임명하신다고 생각합니다. 
</p>
<p><b>○ 함진규 위원 </b> 그래서 그 부분은 지사하고 같이 갈 수밖에 없고 또 집행부의 어떤 정책수립이라든가 제안, 조사 같은 것을 통해서 갈 수밖에 없는데 그게 왜곡되는 경우도 사실 있다고 저는 봅니다.  그렇게 말씀드리고 싶고요.
</p>
<p style="padding-left:1.2em">  그 다음에 부원장 같은 경우에는 아까 다른 위원들이 말씀해 주셨지만 있다가 다시 없다가 다시 부활시킨 것 아닙니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇게 들었습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그런데 숫자가 없어요.  부원장에 대한 숫자가 없고 지금 정관에 보면 어떤 내용이 있냐면 부원장은 25조에 보면 원장을 보좌하고 원장이 사고시에는 그 직무를 대행한다고 나와 있거든요.  그리고 26조에 보면 부원장은 임기 2년으로 돼 있죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 함진규 위원 </b> 부원장은 26조2항에 보면 연구직을 겸할 수 있다.  2005년 3월 5일로 돼 있습니다.  그런데 연구활동은 못하시죠?  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 과제 한두 개는 연구진으로 참여도 하고 있습니다. 
</p>
<p><b>○ 함진규 위원 </b> 하십니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 더군다나 지금은 원장이 유고 상태이기 때문에 지금 원의 내부적인 일 또는 외부적인 일만 하더라도 아마 시간이 없을 것으로 알고 있고요.  그래서 부원장은 어차피 연구직을 겸할 수 있다.  제가 이 조항을 유추해석한다면 좀 그렇지만 감히 적극적으로 해석을 해보면 연구직이라는 게 포괄적인 의미일 수도 있지만 학위소지자를 말하는 것 아닌가요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 우리 연구원의 관례에 의하면 연구직이라고…….
</p>
<p><b>○ 함진규 위원 </b> 연구직을 겸할 수 있다고 돼 있습니다.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 연구직이라고 한다면 아무래도 학위 소유자인 경우가 통례일 것입니다. 
</p>
<p><b>○ 함진규 위원 </b> 그래서 저번에 본인이 취임하실 때 내부적인 연구원들의 반발도 있고, 본 위원은 그 반발 때문에 꼭 그렇게 제도적인 말씀을 드리는 것은 아니고요.  오히려 연구직을 겸할 수 있다라는 26조2항이 있기 때문에 저는 부원장을 오히려 2명으로 두는 것은 어떤가 하는 생각을 해봅니다.  왜 그러냐 하면 연구직을 겸할 수 있기 때문에, 지금 문제가 되는 것은 연구를 겸하지 않고 그냥 원장을 보좌하는 입장에만 있기 때문에 어떻게 보면 정확한 말씀이 될는지 모르겠습니다만 인력낭비라고까지는 볼 수 없지만 그래도 연구직을 겸하면서 상시 다른 연구원과 같이 100% 활동을 할 수는 없겠지만 아까 말씀하신 대로 서너 개의 중요한 과제에 참여한다든가 하는 방법으로 할 수 있다고 보거든요.  그리고 왜 이런 말씀을 드리냐면 내부승진도 무시할 수 없는 겁니다, 아무리 연구원이라 하더라도.  또 그렇다고 해서 내부승진만을 주장해서는 또 안 된다고 봐요.  외부의 유능한 인재도 발탁해야 되거든요.  그게 연구원 발전에도 저는 도움이 된다고 봅니다.  그렇기 때문에 부원장제를 연구과제와 같이 26조2항에 의해서 수행하면서 하면 그것은 인력낭비도 아니고 예산낭비도 아니라고 봅니다.  연구원 직책을 겸해서 같이 하는데 뭐가 문제 있겠습니까?  그래서 그 부분에 대해서 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 두 가지 답변을 드려야 할 것 같습니다.  첫 번째로 부원장을 두 명으로 하는 문제와 관련해서 저희 연구원의 총원이 위촉ㆍ계약직까지 다 포함해서 150명쯤 됩니다.  보통 150명쯤 되는 조직에서 소위 조직관리를 위한 관리자의 입장에서 보면 평균적으로 2명을 쓰고 있는 경우가 가장 일반적인 통례이고요.  사실은 그런 점에서 보면 부원장을 둘씩 두어서 할 이유가 있겠는가.  다만 연구직을 겸한다고 돼 있으니까 그것을 겸하면서 하면 할 수 있겠지만 오히려 부원장이 둘이 됨으로써 통할하는 구조가 더 복잡해질 가능성이 없지 않겠는가라는 생각을 하고요.
</p>
<p><b>○ 함진규 위원 </b> 말씀 도중에 죄송한데요.  그것은 역할분담의 문제기 때문에 부원장을 2명 두면서 지금 공교롭게도 원장의 유고 사태가 발생했는데 연구를 하다가 이런 외부적인 문제가 발생될 때는 외부 부원장, 내부 부원장 둘 수 있는 겁니다.  그러면 외부에서 유능한 인재를 발탁하더라도 내부적으로 연구원들을 뭘 알아야 통제할 것 아닙니까?  물론 본인을 두고 하는 말씀은 아닌데 내부적으로 연구하는 사람들이라는 게, 죄송한 말씀인지 모르지만 상당히 학문 연구하는 사람들이 어떻게 보면 고지식한 면도 있고 또 순수한 면도 있습니다.  그런 부분에 대해서는 어떤 숨통을 터주는 것도 저는, 아까 연구직과 겸한다는 것을 분명히 말씀드렸습니다만 그런 것을 통해서 활로를 찾을 수가 있고 나머지 지금과 같이 이런 유고 상황이 생겼을 경우에 그것을 전담해서 하는 역할분담의 문제인 것이지 중첩되는 그런 부분은 저는 아니라고 생각하거든요.  그래서 그런 관점에서 간단하게 말씀해 주세요.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그 부분에 관해서 말씀드린다고 하더라도 실제로 제가 연구직을 겸하고 있는 것도 부원장으로서 단순히 관리직 업무만 하기에는 시간이 너무 남기 때문에 제가 연구원에 기여하려면 연구직도 겸해야 될 것입니다.  그만큼 150명 인원의 관리자는 2명 이상이 필요치 않다고 생각하고요.  다만 그럼에도 불구하고 이미 앞에서 김영복 위원님이 질의하실 때 말씀드렸습니다만 우리 연구원이 이제 10년이 됐습니다.  10년쯤 됐으면 그 연구원의 관리를 자생적으로 할 수 있는 시간은 충분히 됐다고 생각하고 그런 점에서 앞으로 제 개인적인 희망은 연구원의 부원장은 내부에서 나와야 된다고 생각합니다. 
</p>
<p style="padding-left:1.2em">  세 번째로 하나만 더 말씀드리겠습니다.  외부인력의 충원은 사실은 연구자의 충원, 그 연구자가 성장해서 연구원 내부에서 관리직으로 순환해 가는 것 그걸로써 족하다고 생각합니다.  관리자를 굳이 원장 이외에 부원장까지 외부에서 충원해서 둘로 만들 필요가 있겠는가라고 생각합니다.  다만 이 모든 것은 이사회에서 결정할, 저희 연구원의 정관에 대한 사항이기 때문에 제가 이렇다 저렇다라고 제 개인적인 의견 이외에는 말씀드릴 수가 없습니다. 
</p>
<p><b>○ 함진규 위원 </b> 제가 한 가지 부언해 드리고 싶은 것은 원장의 임기는 3년이고 부원장의 임기는 2년으로 돼 있는 것 알고 계시죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 함진규 위원 </b> 공교롭게도 원장, 부원장 임기도 틀리고 또 솔직히 말씀드려서 임기를 다 채우지 못하거든요.  그것이 왜 그러냐하면 제가 아까 지사하고 원장하고는 보통 임기를 같이 가는 경우가 많다고 말씀드렸는데 사실 원장 임기가 한현규 원장이 지금 계셨어도 3년의 임기를 다 채우지는 못하는 걸로 알고 계시죠?  어떻게 생각하세요?  역대 원장님들이 지사 임기가 끝나면서 다 같이 못 갔습니다.  그거 알고 계신가요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그것은 그렇다고 들었습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그렇기 때문에 원장과 부원장이 동시에 민선3기면 3기, 4기면 4기하고 같이 임기가 끝나버리거든요.  그러면 물론 연구원에 기존에 있던 기관요원들이 다 알아서 하시겠지만 그 부분에 공백이 생길 수도 있습니다.  그렇기 때문에 제가 기존에 있던 연구원 중에서 그런 식으로 같이 겸하면 어떻겠냐 하는, 그런 제도로 가면 어떤 공백이 있을 수 없다.  그래서 제가 말씀을 드렸기 때문에 참고를 해주셨으면 합니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 알겠습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그것은 그 정도만 말씀드리고요.  그 다음에 지난번 제2자유로 건설문제와 관련돼서 본 위원이 아니면 본 위원 지역구의 다른 의원이 저한테 요청해 왔어요.  경기개발연구원이 본 위원의 유관기관이다 보니까 저한테 그랬는데 어제 제가 도정질문을 했지만 제2자유로 건설문제를 여기서 용역을 맡아서 하고 계신가요?  어떻게 하고 계시죠?  아시는 분이 누구시죠?  조 박사님이 말씀해 주세요.
</p>
<p><b>○ 교통정책연구부장 조응래 </b> 교통정책연구부의 조응래입니다.  제2자유로 관련해서 지금 저희 연구원에서 연구용역하는 것은 없고요.  단지 지난번에 주택공사에서 제2자유로 운정지구와 관련해서 제2자유로 건설방안에 대한 자문회의를 개최했습니다.  그래서 그때 자문회의 할 때 유시균 박사가 참석을 했습니다. 
</p>
<p><b>○ 함진규 위원 </b> 본 위원이 듣고 알고 있기로는 지금 노선 선정문제와 관련돼서 어제 도정질문도 저 말고 교육위원회 김의호 의원께서도 하셨는데 고양, 파주지역에 상당히 예민한 문제 중의 하나로 지금 부각돼서 있는 상태거든요.  그런데 제가 조 박사님한테 한번 전화를 드렸었죠?  그래서 제가 깊이는 모르겠지만 동료의원한테 들은 바로는 여기에 투표권을, 경기개발연구원 박사님이 투표를 한다고 그러는데 제가 알고 있는 바로는 같은 경기도내 자치단체지만 두 지역이 대립하고 있는 상태에서 과연 경기도 연구원으로서 정책조언이라든가 이런 것은 소신 대로 할 수 있다고 보는데 과연 투표행위까지 참여하는 것이 바람직하냐 거기에 대해서 제가 의문점을 많이 가졌고 타 지역 타 분야의 연구원들도 투표를 한다고 이렇게 말씀하셨거든요.  어떻게 된 겁니까? 
</p>
<p><b>○ 교통정책연구부장 조응래 </b> 그 자문회의에서 투표를 통해서 결정할 수 있는 그런 내용은 아니고요.  그 내용은 뭐냐면 운정1지구가 있고 그 다음에 운정2지구로 확장을 하면서 기존의 제2자유로 노선문제가 운정2지구가 만들어지면서 노선을 어떻게 결정할 것인지 하는 내용인데 지금 광역교통개선대책이라는 걸 수립하도록 돼 있습니다.  그리고 광역교통개선대책의 수립권자는 도지사입니다.  그런데 현재 광역교통개선대책을 도지사가 직접 수립하는 게 아니라 사업시행자가 계획을 수립해서 도지사께 보고해서 최종적으로 결정하는 이런 형태로 돼 있습니다.  그러니까 주택공사에서 자문회의를 한다는 것 자체는 어느 노선이 가장 바람직한지를 자문을 통해서 가장 바람직한 대안이 무엇인지를 파악하는 것이지 그 자문회의에서 뭘 결정한다든지 이런 권한은 전혀 없습니다.  그렇기 때문에 그 자문회의 결과를 통해서 도지사께서 최종적으로 판단하는 과정을 거치도록 돼 있습니다. 
</p>
<p><b>○ 함진규 위원 </b> 자문에만 응한다면 상관이 없다고 본 위원은 보는데 그것이 자칫 잘못해서 양 지역의 분쟁에 우리 연구원이 들어가서 혹시 또 그런 중요한 행위에 자문이 아닌 그런 형태로 관련돼 있다고 해서 상당히 제가 우려스러웠고요.  지금 박사님이 나와 계십니까? 
</p>
<p><b>○ 교통정책연구부장 조응래 </b> 유시균 박사는 지금 대기 중에 있습니다만 제가 그 내용은 다 잘 알고 있습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그래서 어쨌든 본 위원이 말씀드리고 싶은 것은 미묘한 사안에 대해서는 자극할 수 있는 것은 안 해주셨으면 좋겠고, 다만 아까 말씀드린 대로 의견개진이라고 할까요 이런 것은 할 수 있다고 보는데 그런 부분에 대해서는 각별한 유의를 해주셨으면 좋겠습니다. 
</p>
<p><b>○ 교통정책연구부장 조응래 </b> 네, 알겠습니다.
</p>
<p><b>○ 함진규 위원 </b> 이상입니다.  감사합니다.  북부지역 연구와 관련돼서 제가 자료를 보니까 북부지역 연구가 지금 15건 정도 있더라고요.  북부지역의 직접적인 계획이든 아니면 다른 연구든 간에 토털 “북부”자 들어간 게 15건 되는데 총 지금까지 연구 건수가 얼마나 되죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 저희 연구원의 전체 연구 건수가 금년도에 122건 정도 됩니다. 
</p>
<p><b>○ 함진규 위원 </b> 그 정도 되죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 적다고 볼 수는 없습니다만 해당 북부지역에 대해 여기서도 말씀이 있었습니다만 북부지역 도의원들이 특히 경기개발연구원 말고 경기지방공사라고 있습니다.  거기 역할론에 대한 질타가 굉장히 많았어요.  수익된 사업만 한다 이런 사업내용이 있었는데 문제는 경기개발연구원에서도 사실상 정책수립을 해서 그것이 지방공사하고 연결될 수 있는 그런 연결고리가 제가 15건을 보니까 별로 많지 않았던 것 같아요.  그래서 그 부분에 대해서는 향후에 정책집행하고 연결될 수 있는 부분들을 더 연구하실 용의는 없는지, 그리고 제가 나중에 다른 항목으로 질의를 드리려고 했습니다만 늘 감사 때도 말씀을 드렸어요.  수차에 걸쳐서 저도 기획위원회 4년차 있다 보니까 말씀을 많이 드렸습니다만 우리 경기도의회하고 사실상 정기, 부정기적인 세미나나 정책토론회 같은 것을 많이 권장했거든요.  그런데 본 위원이 보기에는 조금 형식논리에 치우친 감이 있지 않았나 이런 생각이 들고 사실 중요한 경기개발연구원의 정책소스 같은 것이 자체개발이라든가 또는 도의 위임을 받아서 또는 각 자치단체의 요청에 의해서 발굴되는 경우도 많이 있지만 사실 104명 도의원이 각 지역, 경기도 31개 시ㆍ군에 대한 모두라고 하기엔 그렇지만 개략적인 정책이슈라든가 이런 문제에 대해서는 어느 정도 알고 있는 편이거든요.  그게 이제 아까 제가 말한 정책토론회라든가 세미나 같은 게 크든 작든 활성화가 안 되다 보니까 많이 놓치는 경우가 있어요.  그래서 저는 지난 행정감사든 다른 기회있을 때마다 그런 말씀을 드렸는데 그게 상당히 미진했다고 생각이 들고요.  지금 저희들 임기도 7, 8개월 남아있는 시점에서 향후에 제가 말씀드린 대로 그런 부분에 더 유기적인 어떤 세미나나 정책토론회를 할 용의는 없는지 그것을 한번 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 두 가지에 대해서 답변드리겠습니다.  실제로 저희들이 북부지역 연구를 주로 중점적으로 해온 게 두 가지 형태로 진행됐습니다.  주로 남북관계 속에서 북부지역의 역할, 그 다음에 북부지역 자체의 발전방안, 사실은 바로 어제 저희들이 회의를 했습니다만 북부지역의 전략산업이 무엇인가 이런 연구도 했는데 실제로 그 과정에서 항상 북부지역의 발전에 있어서 문제가 되고 있는 게 결국은 인프라 문제이고 산업단지 문제였습니다.  소위 교통시설의 문제이고 산업단지, 국가 산단이든 지방 산단이든 바로 이런 인프라 문제가 북부지역 발전에 있어서 가장 저해요인이고 그것이 실질적으로 앞으로 향후 지방공사 역할하고도 연결될 수 있을 거라고 생각합니다.  따라서 이런 북부지역의 인프라나 산업단지와 관련된 연구를 내년도에도 좀더 추가 확정해서 진행하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  그 다음에 두 번째로 정책토론회를 말씀하셨는데 정말 죄송스럽게 생각합니다.  굳이 도의원님들과 저희들만의 정책토론회가 아니라 여러 가지 우리 연구원과 관련돼서 진행되고 있는 정책토론회에서 그것과 관련된 도의원 여러분들을 모시고 귀중한 의견을 듣는 것이 저희들로서는 당연하고 마땅한 일이며 또한 아이디어 얻는 차원에서도 중요한 일이었는데 그 부분에 대해서 저희들이 서운한 감이 없지 않아 있었습니다.  따라서 앞으로 진행되는 모든 정책토론회에 대해서는 도의원님들 중에서 어떤 분을 모실 수 있겠는가를 우선 한번 고민하는 고민거리 중에 하나로 놓고 저희들이 진행하도록 하겠습니다.
</p>
<p><b>○ 함진규 위원 </b> 아울러서 말씀드리고 싶은 것은 북부와 관련해서 부원장님이 잘 아시다시피, 북부지역에서 근무를 하셨었죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그리고 그 지역에 그린벨트지역이 상당히 많고 거의가 다 군사보호지역이기 때문에 이중삼중으로 규제를 받고 있는 겁니다.  그러다보니까 연구원 연구실적에도 보면 자발적인 연구정책과제도 있고 위탁, 수탁, 여러 가지가 있지 않습니까?  그런데 제가 파악을 못해서 그런지 모르겠습니다만 군사보호시설 관련돼서 제가 어제도 말씀을 드렸지만 철책선 제거문제라든가 군부대 이전문제라든가 사격장 이전문제라든가에 관해서는 그렇게 많지가, 거의 전무한 실정으로 파악하고 있거든요.  그래서 이런 부분에 대해서 향후에 이게 굉장히 건축, 주택, 이것의 신축문제가 아닌 그런 부분이 상당히 앞으로도 대두될 것이 거든요, 북부지역에서는.  그래서 그런 부분에 대해서 앞으로 중점적으로 연구를 할 용의는 없는지 그것을 말씀해 주시고요.
</p>
<p style="padding-left:1.2em">  아울러 참고로 말씀드리고 싶은 것은 군부대는 특성상 아직까지도, 제가 여기서 냉전체제 해체니 무슨 자유와 관련된 뭐니 그런 말씀은 드리고 싶지 않습니다, 여러분이 더 잘 아시다시피.  그래서 상당히 큰 이슈로 떠오를 문제이기 때문에 아주 성급한 과제 중에 하나가 아닌가 생각을 하고요.  군부대 답변은 항상 그렇습니다.  안보상의 논리를 내세우고 있거든요.  안보상의 논리 때문에 우리 행정기관에서도 감히 접근할 수 없는 성역이 되고 있거든요.  그런 안보상의 이유를 우리가 깬다는 것은 그렇지만 유독 개성공단 왔다갔다 하고 평양공단 수많은 물자가 왔다갔다 하고 말이지요.  그런데도 항상 내세우는 것은 초지일관 안보논리입니다.  우리 고양시 같은 경우에는 특히 더 그런데요.  그래서 그런 부분에 대해서 우리 도의원들이 다른 어떤 책이나 자료를 통해서도 볼 수 있지만 사실은 정확하게 연구원에서 연구용역과제로 채택해서 우리가 숙지할 수 있는 이런 안보논리를 내면 “그것은 아니다”라고 하는 말을 할 수 있는 논리무장이 있어야 되거든요.  그런 부분에 대해서 앞으로 연구하실 용의는 없는지 말씀해 주세요.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 사실 군사시설보호구역이 개발제한구역, 상수원보호구역과 합쳐서 경기도의 3대 규제구역 중에 하나인데 이 중에서 함 위원님께서 정확하게 지적하셨듯이 전국적으로 보나 경기개발연구원 입장에서 보나 군사시설보호구역에 대한 연구가 제일 적을 겁니다.  왜냐하면 개발제한구역이나 상수원보호구역은 제도로써 접근이 가능합니다.  함 위원님께서도 말씀하셨듯이 그러나 군사시설보호구역은 소위 안보라는, 제도하고는 좀 무관한 논리로 정해진 부분이 있기 때문에 굉장히 어려운데 그럼에도 불구하고 이제 군사시설보호구역이 문제가 된다고 한다면 그 부분에 대해서 정말로 본격적으로 검토하고 논의할 때가 되지 않았나 싶습니다.  저희들이 가능한 범위 내에서 최대한 군사시설보호구역에 대한 연구ㆍ검토도 집중해서 나가도록 노력하겠습니다. 
</p>
<p><b>○ 함진규 위원 </b> 한 가지 더 말씀드리고 싶은 것은 통일문제와 관련되는데 제가 지금 자료를 찾아보니까, 최용환 박사님 지금 여기 계신가요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 지금 아마 위에 대기하고 있을 겁니다. 
</p>
<p><b>○ 함진규 위원 </b> 이분이 2005년 7월 15일부터 금년도 12월 15일까지, 그러니까 지금 현재 진행 중인 것 같네요.  “북한경제 재건을 위한 남북교류와 경기도의 역할” 해서 정책연구를 하고 계신 것으로 알고 있는데 이 부분에 대한 것도 많지가 않은 것 같아요.  제가 아까 말씀드린 북부지역 군사보호시설 해제문제와 관련돼서, 아울러 북한문제도 강원도하고 우리만 유일하게 접해있지 않습니까?  활발히 교류가 이루어지고 있는데 여기에 대한 것도 상당히 좀 부족해서 아울러 이 부분도 관심을 가져주셨으면 좋겠고요.
</p>
<p style="padding-left:1.2em">  그 다음에 문화재 관련을 말씀드리고 싶은 게 제가 도정질문을 하면서 내용이 너무 방대할 것 같고 저번에 한 번 했기 때문에 이번에는 뺐습니다만 경기도가 사실 문화재가 굉장히 많이 있습니다.  제가 집행부에도 많은 촉구를 하고 예산확보를 말씀드렸습니다만 경기도 재정여건상 상당히 적극적으로 대응을 못하고 있는 실정입니다만 문화재가 굉장히 경기도에 많이 산재해 있음에도 불구하고 관리상태가 지금 엉망이에요.  TV나 신문 이런 것을 통해서 많이 보셨겠지만 지금 한심한 수준입니다, 어떻게 보면.  국가 문화재 역시 마찬가지이고 도 문화재 역시 마찬가지입니다.  그래서 심지어는 제가 기억이 납니다만 작년에 질의했을 때 파주의 호로고로성 같은 아주 유명한 고구려 역사문제와 관련된 중요한 유적지가 있는데도 불구하고 모 신문 또는 TV에서도 상당히 기자가 그것을 발표하고 그러더라고요.  보니까 정말 거기에 야채 심어 먹고 벽돌 몇 장 이리저리 굴러다니고 그러면서 우리가 중국에 가서 고구려 역사가 어떠니 암만 떠들어봤자 한심한 겁니다.  그래서 제가 집행부에도 많은 촉구를 했지만 사실 집행부 쪽에서도 막연합니다, 어떻게 보면.  아까 제가 말씀드렸듯이 재정여건, 여러 가지 인력수급문제라든가 이런 것 때문에.  그러면 그 역할이 너무 부담이 큰지 모르겠지만 우리 경기개발연구원 쪽에서도 그런 부분에 대해서는 좀 집행부에 많은 어떤 토대를 제공해 줘야 되지 않을까 하는 생각이 듭니다.  그래서 앞으로 향후 그 부분에 대해서 연구하실, 중점적으로 채택하실 용의가 있는지 하고, 아까 관리상태 말씀드렸지만 지금 각 지방자치단체한테 그냥 도 문화재도 방치한다든가 지방 문화재 같은 것은 그냥 맡겨놓고 일임하고 있는 상태인데 거기는 재정이라고 넉넉하겠습니까, 전문가도 없고요.  그래서 그런 역할을 해야 된다고 보는데 어떻게 생각하시는지 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 두 가지로 답변드리겠습니다.  우선 남북교류와 관련해서는 저희들이 이 분야에 대해서는 빠짐없이, 끊임없이 연구를 해야 된다고 생각하고요.  당장 12월초에도 이미 진행되고 있는 남북경제특구법과 관련된 세미나도 하고 저희들이 그 과제를 진행하겠고 내년에도 계속 추진하도록 하겠습니다.  저희 동북아지역연구부가 중국 및 동북아시아 연구뿐만 아니라 남북교류연구도 같이 하게 될 거라고 생각합니다. 
</p>
<p style="padding-left:1.2em">  두 번째, 문화재 관련인데요.  실제로 수도권이라는 것 자체가 삼국시대 때부터 여러 가지가 겹쳐있기 때문에 많은 문화재가 있습니다.  특히 그 중에서 지정문화재는 그나마 나은데 비지정문화재들은 그냥 그대로 방치된 상태입니다.  따라서 이것을 뭔가 관리할 수 있는 대안을 만들어내야 되는데 이 분야에 대해서도 경기문화재단하고 협조해서, 실제로 경기문화재단에서 경기도 내의 각종 문화재에 대한 현황파악이 끝나있는 상태인 것으로 알고 있습니다.  그것들을 어떻게 관리할 것인지에 대해서는 저희들도 저희들 나름대로 열심히 생각해 보고 과제로 한번 추진하도록 노력해 보겠습니다. 
</p>
<p><b>○ 함진규 위원 </b> 부언해서 말씀드리면 연구과제를 중점적으로 연구하고 그런 발표라든가 세미나를 한다면 집행부 쪽에도 아마 많은 주의를 환기시켜 주고 관심을 가질 수 있는 그런 계기가 되지 않을까 해서 말씀을 드렸고요.
</p>
<p style="padding-left:1.2em">  나머지는 연구원 내부적인 문제를 말씀드리겠습니다.  제가 박사 연구원들의 성향을, 성향이라는 게 아니라 분석을 좀 해보니까 아까 위원님들께서도 그런 말씀 많이 해주셨습니다만 지금 연구 박사님들이 총 42명 정도 되시지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 지금 현재는 박사 42명 포함해서 총 연구인력이 50명인가요? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 정규직이 51명입니다.
</p>
<p><b>○ 함진규 위원 </b> 그 중에서 박사학위 소지자가 42명이고 인원이 앞으로 더 늘어날 예정이지요? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 내년에도 저희가 11명의 박사를 더 증원할 것을 신청해 놓고 있습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그래서 제가 차제에 말씀을 드리는데요.  우리 박사님들의 학위별로 이게 연구과제에 어떻게 보면 중요한 역할을 하기 때문에 제가 자료를 좀 받아봤거든요.  42명 중 행정학 쪽에 다섯 분이 계시고 경제학 다섯 분, 정치학 6명, 공학 9명, 도시지역계획 9명, 그 다음에 교통계획이 다섯 분이시지요?  그리고 첨단학제공학박사가 한 분, 이학박사가 한 명, 지리학박사가 한 명 해서 총 42명입니다.  저는 그렇게 생각합니다.  연구원을 채용하는 데, 직원도 마찬가지이고요.  지역이라든가 출신학교에 차별을 둬서는 안 된다고 보거든요.  중요한 것은 저는 연구실적이라고 보거든요.  제 말이 맞습니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 맞습니다. 
</p>
<p><b>○ 함진규 위원 </b> 연구실적인데 그 연구실적이 과연 어느 정도의 객관성과 공정성이 있느냐가 중요한 관건이라고 보는데 지금 현재 연구원 채용하는 것은 어떤 기준으로 초빙하고 있나요? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 저희가 3단계로 하고 있습니다.  첫 번째는 응시를 하게 되면 서류심사를 합니다.  이 서류심사에서 가장 중요한 부분이 바로 함 위원님께서 말씀하신 연구실적입니다.  연구실적을 토대로 해서, 연구실적이라 함은 어떤 것을 말하냐면 논문형태를 학회에 발표해서 학회지에 실었거나 아니면 외부 컨퍼런스(conference)에서 발표한 것들을 중심으로 해서 연구실적을 잡아서 그것을 중요한 기준으로 해서 서류전형을 하고요.  서류전형에서 합격된 사람은 평균적으로 뽑을 인원의 3배수를 뽑아서 저희들이 세미나를 하게 됩니다, 그분들을 초빙해서.  초빙하게 되면 그분들이 각자 자기가 가장 강점을 가지고 있는 분야를 가지고 세미나를 하고 그것을 저희들은 저희와 외부 교수들을 심의위원으로 해서 약 여섯 명이 심의를 해서 잡 세미나의 결과를 평가합니다.  그래서 그 중에서 가장 적합하다고 생각되는 분 한 분을 선정하고 그분과 마지막 면접을 통해서 선발하게 됩니다. 
</p>
<p><b>○ 함진규 위원 </b> 말씀 들어보면 굉장히 공평하고 타당성이 있다고 사료됩니다.  사실 지금 실업난이 있다보니까 저학력자 또는 일반 대학생들만 실업난이 있는 게 아니고 연구원, 고급인력도 상당히 실업난이 있습니다.  대학에서도 그런 부분이 많이 대두되고 있지만 저는 무슨 서울대를 나왔느냐 연세대학을 나왔느냐 고려대학을 나왔느냐 무슨 경북대학을 나왔느냐 이게 중요한 것이 아니라고 보거든요.  우리 부원장님 말씀하신 대로 국내외 저명한 학술지에 학술발표를 했다든가 그러면 객관성이 있지 않습니까?  그런 부분은 문제될 게 아무 것도 없지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다.  저희도 그것을 중점적으로 보고 있습니다.
</p>
<p><b>○ 함진규 위원 </b> 꼭 서울대만 뽑는 게 아니고, 그렇다고 해서 서울대이기 때문에 떨어져서는 안 된다고 보거든요.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다.
</p>
<p><b>○ 함진규 위원 </b> 제 말에 공감하시지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다.
</p>
<p><b>○ 함진규 위원 </b> 그래서 앞으로 그런 부분에 대해서 객관적인 타당성 또 아까 우리 이효선 위원님도 말씀을 해주셨지만 어떤 특정신문에만 내서 인재들을 좁게 할 수 있는 부분에 대해서는 생각을 많이 해주셨으면 좋겠습니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇게 하겠습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그리고 아울러서 박사 42명에 대한 전공분야별로 말씀을 드렸지만 앞으로 행정학이나 이런 부분을 뽑지 말라는 것이 아니라 아울러서 말씀드리는 것은 다양화시켜야 되거든요.  너무 이것이 어떤 특정분야에만 치우쳐 있으면, 박사님들께 죄송한 말씀인지 모르지만 자기분야 외의 남의 분야를 연구한다는 게 사실, 그렇게 안 하시겠지만 힘든 겁니다.  그래서 차제에 아까 제가 문화재 관련도 말씀을 드렸습니다만 예를 들면 문화관련 박사님이라든가 아니면 기타 여러 분야의 박사학위 소지자들이 있지 않습니까?  그래서 그런 것을 다양화시킬 필요가 있지 않느냐.  거기에 대해서는 어떻게 생각하시는지.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 당연히 저희들도 그렇게 생각하고 있습니다.  사실은 경기도가 종합행정이기 때문에 저희 입장에서는 경기도에서 추진하고 있는 일을 저희들이 보좌, 백업하기 위해서는 앞으로 상당히 많은, 그것도 다양한 분야의 인력이 필요하다고 생각합니다.  따라서 저희가 여력이 되는 한 많은 인력을 다양하게 선발해서 각각의 과제에 대응하도록 하겠습니다. 
</p>
<p><b>○ 함진규 위원 </b> 부언해서 말씀드리고 싶은 것은 민선3기 손학규 경기도지사께서 중점적으로 추진한 사항 중에 하나가 영어마을입니다.  그렇지요? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 영어마을을 막대한 돈을 투자해서 해가지고 상당히 도민들한테도 좋은 반응을 얻고 있고 특히 저소득층한테도 상당히 어떤 효과를 주고 있는데 지금 보니까 아까 말씀을 드렸지만 무슨무슨 영문학박사라든가 언어학박사라든가 이런 부분 쪽은 없어요.  그러면 과연 그런 부분에 대해서, 물론 해당 기관에 가면 현지 원어민 네이티브 스피커가 있겠지만, 박사도 있고 다 있겠지만 우리 연구원에서는 사실 어떤 중점과제가 딱 던져졌을 때 이것을 외부에 용역합니까?  엄청난 예산이 들어가서 시행되고 있는데.  그래서 이런 부분도 심층적으로 고려하셔서 다음에 박사인력 10명 늘어날 때는 적어도 그런 다양한, 도민이 다양한 것을 요구하기 때문에 다양성을 갖춰야 되지 않겠냐.  제가 이런 말씀에서 한마디 드렸고요.  그 다음에 마지막으로 말씀드리고 싶은 게 지금 여기 박사님들, 연구를 위해서 외국에 나간 자료를 제가 받아봤습니다.  받아보니까 총 50명 되신다고 했지요?  연구인원이요.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네.
</p>
<p><b>○ 함진규 위원 </b> 50명 중에서 2004년도에 출장 건수는 25건입니다.  제가 본 자료에 의하면.  그 다음에 2005년도에 역시 25건.  그러면 이게 무슨 제한이 있나요?  1년에 예산상 얼마큼 나갈 수 있다는 제한이 있기 때문에 똑같이 25건씩 돼 있는 건가요, 아니면 공교롭게도 그렇게 된 건가요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 공교롭게 그렇게 됐는데요.  특별한 제한은 없고 두 가지 형태로 해외출장을 가게 됩니다.  세 가지라고 이야기할 수도 있겠고요.  첫 번째는 기본과제나 정책과제 중에서 특별히 해외에 나가서 자료를 받아올 필요가 있을 경우에 해외출장을 가고요.  두 번째는 수탁과제로 했을 경우에 그 과제의 필요상 나가는 해외출장이 있고요.  세 번째는 이것도 저것도 아닌데 국제회의나 아니면 세미나가 있어서 나가는 경우도 있습니다.  이 중에서 앞의 두 개는 과제비로 나가게 되는 것이고요.  세 번째 같은 경우는 저희 연구원에서 부분적으로 지원하고 있습니다.
</p>
<p><b>○ 함진규 위원 </b> 그래서 이것을 제가 분석해 보니까 나라가 여러 나라가 있습니다.  구미 선진국도 있고 유럽의 선진국도 있고 많이 있습니다만 2004년도에 총 25건 출장 중에서 중국출장이 9건이에요.  그 다음에 2005년도 역시 총 25건 중에 중국출장이, 두 달이 남아있기는 합니다만 7건이고요.  그래서 꼭 필요한 것은 나가야 되겠지요.  그러나 전체 25건 중에서 국가가 지금 세계에 한 이백 몇 개의 국가가 되지요?  한 이백 서너 개 되고 있는 것으로 알고 있는데, 다 나갈 수는 없지만, 말이 국가지 다 나갈 수는 없지만 중국 쪽에만, 제가 출장의 내용은 안 봤습니다.  그것은 어차피 정확하지 않은 면도 있을 수 있기 때문에, 죄송합니다만.  그래서 이게 형식논리에 치우쳐서 그저 한 번 복지차원에서 그냥 중국이나 갔다 와라 이것은 아니었는지.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 결코 그런 것은 아니었습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그런 게 아니었다면 좀 다양화시키고 현실화시킬 방향으로 나갈 용의는 없는지.  이게 왜 그러냐면 같은 돈 들여서 나가는데 몇 십만 원 더 들어가는지 제가 모르겠습니다.  횟수를 꼭 제한할 필요는 없고 불필요한 것은 자제를 해야 되겠지만 연구차, 그것이 하나의 연구가 도 집행과 관련돼서 심대한 영향을 미친다면 출장비 몇 푼이 문제겠습니까?  정확한 자료나 정확한 조사를 위해서 충분히 다양화시켜 나가야 된다고 저는 봅니다.  그렇기 때문에 지금 제가 중국을 비하하거나 중국출장이 잘못됐다는 뜻은 아니고 총 건수에 비해서 거의 40%대에 가까운, 40 내지 45%에 달하는 그런 문제기 때문에 앞으로는 실질적인 차원에서 출장을, 횟수는 제가 얘기하고 싶지 않습니다만 그런 것으로 다양화시킬 용의는 없는지 그것을 한번 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 해외출장에 대해서 저희가 어떤 제한을 두지는 않습니다.  과제 시작 때 저희 연구위원회에서 이 해외출장이 이 과제를 위해서 꼭 필요하다고 하는 경우에는 대부분 허용하고 있고요.  하필 작년, 금년에 들어서 중국출장이 많아진 것에 대해서 두 가지로 말씀드리겠습니다.  첫 번째는 작년, 금년 들어서면서 한ㆍ중 관련된 과제가 좀 많았다는 점, 두 번째 저희가 중국 산동성 내지는 강서성과의 상호교류프로그램이 있습니다.  이 교류프로그램을 진행하다보니까 자료에서 보셔서 아시겠습니다만 특정인사가 자주 중국을 왔다갔다 하면서 교류프로그램에 대해서 성안을 하느라고 자주 왔다갔다 하게 됐습니다.  따라서 그게 갈 때마다 한 번씩 횟수가 잡히다보니까 중국출장이 많은 것으로 보였을 거라고 생각합니다. 
</p>
<p><b>○ 함진규 위원 </b> 아울러서 마지막으로 말씀드리고 싶은 것은 중국이 그렇게 중요한 것만큼 인도도 상당히 중요한 분야 중의 하나입니다.  그러나 인도에 대한, 여기 있는지 없는지 모르겠지만 인도는 없는 것 같아요, 찾아봐도.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 저희가 금년에 과제 하나를 외부에 발주했는데요.  “브릭스의 발전과 우리의 대응방안”이라는 과제가 지금 진행되고 있습니다.  지금부터 저희들도 러시아, 인디아 그 다음에 브라질까지 포함해서 그런 지역에 대한 연구를 본격적으로 할까 생각 중입니다.
</p>
<p><b>○ 함진규 위원 </b> 그래서 인도도 우리 부원장님 잘 아시다시피 IT쪽으로는 상당히 선점해 나가고 있는 국가 중의 하나 아닙니까?  그래서 이 부분에 대해서 중국 못지않게 부언해서 다변화시켜 주셨으면 좋겠고 연구도 그 부분에 관심을 가져주셨으면 좋겠고요.
</p>
<p style="padding-left:1.2em">  그 다음에, 질의는 끝났습니다.  서두에도 제가 말씀을 드렸지만 우리 원장님이 어떻게 된 건가요?  지금 현재도 처리가 된 겁니까?  어떻게 된 겁니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 원장 사직이요?
</p>
<p><b>○ 함진규 위원 </b> 네.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 11월 10일자로 사직처리가 됐습니다. 
</p>
<p><b>○ 함진규 위원 </b> 11월 10일로 사직이 돼 있습니까?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그렇습니다.
</p>
<p><b>○ 함진규 위원 </b> 앞으로 후임 내부승진이 됐든 외부에서 취임을 하시든 공백기간이 상당기간 동안 있으리라고 봅니다만 제가 서두에도 말씀드린 것과 같이 본 위원만 그런 시각으로 보는 것이 아니라 뭔가 흔들리는 것 같은 위상도 보였습니다만 부원장님이 원장 취임하실 때까지 심기일전하셔서 위상을 종전대로 유지하시고 더 강화할 수 있는 방안을 마련해 주셨으면 좋겠고요.  특히 아까 이효선 위원도 말씀을 해 주셨지만 관련이 없다고 하니까 앞으로 불명예스러운 연구원에 대해 신문에 내용이 나왔을 때는 적극적으로 대응할 수 있는 그런 방법도 강구해 주셨으면 좋겠습니다.  이상입니다.  답변 감사합니다. 
</p>
<p><b>○ 위원장 정인영 </b> 네, 장시간 수고하셨습니다.  다음 질의하실 위원 질의해 주시기 바랍니다.  이흥규 위원 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이흥규 위원 </b> 이흥규 위원입니다. 아까 오전에 질의했던 부분에 대해서 보충질의를 드리겠습니다.  아까 답변에서는 1차, 2차 보고를 해서, 한류우드보고서요.  보고를 해서 경기도의 요구사항을 해서 반영한 것이 3차보고서라고 말씀하셨는데 그러면 1차, 2차, 3차 보고서의 차이점은 무엇인지 구체적으로 설명해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 양해해 주신다면 그 과제를 진행했던 실무자한테 설명하도록 하겠습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 네.
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 경제사회연구부의 김흥식입니다.  이 위원님께서 질의해 주신 내용 중에서 1차, 2차, 3차의 차이점이 뭔가에 대해서 간략하게 설명을 드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 공식적으로 경기관광공사, 위탁기관에 저희가 제출한 중간보고서는 숫자상으로 보면 3차가 공식적으로 공문을 통해서 건너간 유일한 공식보고서가 되겠습니다.  1차, 2차는 중간중간에, 우리가 9월에 세 번의 중간보고가 있었는데 1차, 2차는 공식보고는 아니고 비공식적으로 연구진과 위탁기관의 실무자간 보고형태로 진행됐다는 것을 사전에 말씀드리고요.  우선 1차에 대한 보고서 내용은 주로, 원래 이게 고양관광문화숙박단지 개념으로 기 승인받았던 내용이 되겠습니다.  그런데 이것이 올해 2월에 한류우드라고 개발 컨셉이 바뀌면서 거기에 따른 개발 컨셉과 부지공급계획 그리고 마케팅계획을 새로 수립해야 되기 때문에 그와 같은 내용에 대한 한류우드 활성화방안에 대한 개발 컨셉과 마케팅 계획에 대한 초기의 개발구상형태로 진행됐고요.  그런 형태로 보고서가 1차로 나갔고, 2차에 있어서는 중요한 부분이 마케팅 개발 컨셉을 구체화시키면서 한류우드의 부지공급계획, 말하자면 사업공모방식에 대한 부분이었는데 오전에도 일차적으로 말씀이 있었습니다만 그 부분이 SPC방식의 단일안을 형태로 해서 2차 보고가 됐던 내용이 되겠습니다.  그와 같은 보고내용에 관련돼서 경기관광공사하고 경기도에서 그런 부분을 다양화시켜서 사업공모방식을 다양한 대안을 통해서 비교검토를 해달라고 얘기를 했기 때문에 그와 같은 부분이 한류우드 부지공급과 사업공모방식에 대해 세 가지 대안을 제시했습니다.  그래서 1안이 2차에서 얘기했던 슈퍼블럭경영에 대한 일괄공급형태가 되겠고요.  두 번째가 필지별 개별공급형태가 되고 세 번째가 중간에 어떤 믹스형, 중블럭형 분할공급형태로 해서 대안을 제시했습니다.  그래서 2차와 3차 차이의 중요한 부분은 대안별 비교검토가 이루어졌다는 게 중요한 차이점이 되겠습니다.  
</p>
<p style="padding-left:1.2em">  참고로 말씀드리면 이와 같은 부분이 사실은 사업공모방식이 결론이 안 난, 실무자 간에 결론이 안 나서 10월말 경에 연구진과 실무자회의를 통해서 다시 도지사께서 제2안인 필지를 개별공급방식으로 해서 한류우드를 사업자공모하는 것으로 결론을 그렇게 진행 중에 있습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그런데 설명을 그대로 믿기에 좀 어려운 부분이 뭐냐면 설명은 잘 들었는데 경기도가 9월 30일자로 해서 관광공사에 10월 4일에 접수된 공문에 보면 그때의 팀장님 말씀은 1차, 2차에 보고를 하고 경기도가 요구한 사항을 3차에 넣은 것이라고 얘기하시는 거지요?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 네, 대안을 추가로 해서 보완이 돼 있습니다.  
</p>
<p><b>○ 이흥규 위원 </b> 그런데 경기도가 관광공사에 보낸 공문에 의하면 1차와 2차 중간보고에서 보고한 사항에 대한 반영이 되지 않았다는 얘기이고 또 1차 중간보고서와 3차 중간보고서에는 동일한 용역이라고 보기 어려울 정도의 현저한 내용차이가 있습니다 하고 얘기했거든요.  그러면 경기도가 만약에 지시해서 그것이 들어간 것이라고 한다면 경기도가 이러한 공문을 보낼 이유가 없지요.  
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 그 부분에 있어서는 저희가 2차의 회의를 통해서 중간보고됐을 때 그 차이가 상당히 많은 부분이 지적됐었습니다, 실무자 검토를 거쳐서요.  그 부분을 우리가 접수하고 거기에 따라서 국토도시계획학회하고 한양대학교, 저희가 모여서 그 부분에 대한 각각의 업무분장별로 해서 검토를 해서 3차 보고서에 난 것은 그런 부분 때문에 상당히 보완이 된 부분이 되겠습니다.  검토내용에 대해서 보완이 됐던 내용이기 때문에 그와 같은 부분에 있어서는 내용이 상당부분 조금 다른 부분이 2차와 다른…….
</p>
<p><b>○ 이흥규 위원 </b> 그 내용이 보완된 것까지는 이해가 가는데 경기도가 요청한 사항을 보완해 준 것을 가지고 경기도가 내용이 이렇게 차이가 있다고 공문을 보낼 이유는 없지 않겠느냐.  
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 그것은 보고서 결과를 가지고 말씀을 하신 것 같은데요.  2차와 3차 결과보고서의 차이가 2차보다는 3차에 상당히 다른 부분이 포함됐기 때문에 그런 걸 지적해서…….
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 알아들었습니다.  알아들었고요.  그러면 경기개발연구원에서 SPC방식이 가장 좋다라고 연구용역에서 나왔다라고 보는 건데요.  SPC방식을 주장한 거지요.  그러면 오늘 경기도가 한류우드사업 용지공급에 대한 방식에 대해서 발표한 것 아시지요?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 네.
</p>
<p><b>○ 이흥규 위원 </b> 그렇게 되면 경기개발연구원의 연구용역이 안 받아들여진 거네요.  그렇게 봐야 됩니까? 
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 아닙니다.  지금도 아직까지 한류우드에 관련된 용역이 완료된 것이 아니고 내년 2월까지…….
</p>
<p><b>○ 이흥규 위원 </b> 부지공급에 대한 의견은 경기개발연구원에서 가장 좋다라고 한 SPC사업은 반영이 안 된 거지요? 
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 그 부분에 대해서는 저희가 혼자서 연구자 입장에서 진행시키는 것은 아닙니다.  그렇기 때문에 실무자 관계관 회의를 하는 것은 그와 같은 부분에 있어서 보완이 될 수 있게끔 하는 부분입니다.  그 부분이 9월 이후에 상당히 보완돼서 더 구체화돼서 나온 게 지금 제2안에 대한 필지를 개별분할공급방식으로 해서 첫 번째 저희가 최종안이라고 제시했던 부분보다는 필지별로 가는 그런 형태로 해서…….
</p>
<p><b>○ 이흥규 위원 </b> 처음부터 SPC 방식을 경기개발연구원에서는 최적의 방법이라고 얘기했고 경기도가 그 방법 말고 2안, 3안을 검토해 달라고 제시해서 그것까지 돼서 결국은 2안으로 된 것 아니냐 이거죠.  
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 그것은 실무자들하고 연구진 간의 어떤 관점의 차이도 있을 수 있을 것 같거든요.  
</p>
<p><b>○ 이흥규 위원 </b> 결과론적으로는 그렇게 된 거죠?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 결과론적인 거라 하더라도 저희가 연구를 통해 가지고 제시됐던 내용이 채택됐기 때문에…….
</p>
<p><b>○ 이흥규 위원 </b> 본 위원은 이 부분이 처음부터 잘못된 것이 아니냐.  경기개발연구원은 처음부터 1안, 2안, 3안을 연구해서 주셔야 되는 것이고 그 가운데서 경기도가 선정을 해야 되는데 경기개발연구원은 오로지 1안을 가지고 최적의 안이라고 해서 경기도가 2안, 3안을 연구해 달라 그런 요청에 의해서 결국은 2안, 3안을 해가지고 경기개발연구원의 최적의 방식이라고 하는 1안은 채택이 되지 않았고 2안으로 채택된 것을 아시냐 이거죠.  
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 아까도 말씀드렸지만 아까 기준에 따라서…….
</p>
<p><b>○ 이흥규 위원 </b> 아니, 어떤 안이 가장 좋은 안이라고 판단하는 것이 아니라 결과론적으로 봤을 적에 경기개발연구원에서 최적의 안이라고 한 1안은 경기도가 채택하지 않고 2안을 채택했다는 얘기 아닙니까?  결과가 어떤 것이 좋을지는 더 지나가 봐야 될거고요.  
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 그렇습니다.  저희가 생각할 때는 처음에 용역에 대한 스콥(Scope) 자체를 받았을 때는 대안별 검토는 없었고요.  그래서 저희가 일단 사업에 대한 부분에서 특혜논란 시비라든가 그 다음에 어떻게 하면 사업을 가장 스피디하게 진행시킬 수 있는가 그런 부분에 대해서 초점을 맞췄었는데요.  저희가 수퍼블럭형 일괄공급의 형태라는 것하고 제2안으로 나와 있는 개별 필지별 개별공급방식이라는 것도 특혜논란 시비에는 항상 어떤 규모의 차이가 있지만 특혜논란 시비에는 똑같은 형태로 진행이 될 것이기 때문에 저희가 생각하기에는 한 번에 사업안이 가장 최적안이라고 했을 때 수퍼블럭형으로 특혜논란 시비를 거치면 될 걸 갖다가 여러 번 특혜논란 시비를 거쳐서 진행되는 거는 사업진행에 있어서 더 불필요한 게 아닌가 하는 생각에서 저희가 단일안을 제시…….
</p>
<p><b>○ 이흥규 위원 </b> 그 부분에 대해서는 공감 안 하는 게 SPC 방식은 수의계약방식이죠?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 네, 맞습니다. 
</p>
<p><b>○ 이흥규 위원 </b> SPC 방식은 수의계약방식이고 지금 2안은 입찰공모 아닙니까? 
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 결국은 SPC 자체도 경쟁입찰로 해서 가는 부분이고요.  그 다음에 개별부지공급방식도 경쟁입찰이지만 나중에 결국은 그것도 일종의 수의계약 형태로 최종적으로 가는 것은 동일하다고 말씀드릴 수 없습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 그 부분은 제가 전문가가 아니라서 어떤 것이 더 좋다고 할 수 없는 것이고 그것은 우리 박사님들이 판단하실 부분이고요.  지금 박사님이 얘기하신 대로 특혜논란이 나올 수 있는 부분이 분명히 있거든요.  지금 경기개발연구원이 연구한 SPC 방식을 경기도가 채택 안 함으로써 경기개발연구원이 연구한 부지공급방식에 대한 부분은 논란이 경기도가 채택한 부분하고 틀리다는 부분을 지적하고 싶고요.  거기에 연구원으로 돼 있는 박기완 연구원께서 처음에 연구원으로 위촉할 때는 판교 IT업무 연구로 위촉을 하셨네요.  그런데 이분이 어떻게 별안간 한류우드로 연구원으로 가게 된 거죠?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 오전에 잠깐 말씀드렸습니다만 한류우드에 대한 개발 컨셉 자체는 작년 12월에 시작한 것으로 알고 있습니다.  그때 한류우드 개발 컨셉에 주도적으로 참여했던 연구진이 박기완 위원이 그 중에 한 사람이었고요.  그렇기 때문에 그 이후에 개발 컨셉이 바뀌다 보니까 고양관광숙박단지에서 새로운 용역에 대한 필요성이 제기됐기 때문에…….
</p>
<p><b>○ 이흥규 위원 </b> 이분이 판교 IT에도 하고 한류우드에도 하고 두 군데 하는 겁니까?  아니면 판교 IT에서 손을 떼고 이쪽만 하는 것입니까? 
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 그 부분은 지금 IT도 같이 연구를 동시에 하고 있는 것으로 알고 있습니다.
</p>
<p><b>○ 이흥규 위원 </b> 당초에 그분이 위촉된 판교 IT업무지구 사업화 공동연구에도 참여하시고 한류우드 연구에도 참여하신다는 얘기죠?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 네, 그런 것으로 지금 알고 있습니다.  아까도 말씀드렸듯이 박기완 위원이 올 2월에 한류우드에 대한 도지사께서 보도자료를 발표했을 때 개발 컨셉의 기초적인 개발구상안을 만들 때 주도적인 역할을 했기 때문에 한류우드…….
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 알았습니다.  박기완 연구원께서는 판교 IT로 채용되셔서 한류우드까지도 관계를 하신다는 얘기죠?
</p>
<p><b>○ 경제사회연구부 김흥식 </b> 네.
</p>
<p><b>○ 이흥규 위원 </b> 그런데 이 부분은 박사님이 답변하실 게 아닌 것 같네요.  부원장님이 답변해 주셔야 될 것 같아요.  박기완 연구위원님께서 채용됐을 때도 이사회에서 규정을 또 바꾸셨네요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 이사회에서요?
</p>
<p><b>○ 이흥규 위원 </b> 인사규정은 누가 바꿉니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 인사규정은 이사회가 아니라 저희 내부의 심의위원회에서 결정하는 겁니다. 
</p>
<p><b>○ 이흥규 위원 </b> 심의위원회에서 비상임정책연구위원을 둘 수 있는 것을 개정한 것이 2004년 12월 17일이니까 박기완 연구위원을 채용하기 위한 인사규정을 바꾼 거네요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 비상임정책연구위원은 12월에 개정했지만 박기완 위원이 처음 임용된 날짜는 2004년 10월입니다.  그래서 박기완 위원을 채용하기 위해서 그것을 바꾼 것은 아니라고 봅니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그러면 박기완 위원님 전에 비상임정책연구위원이 있었습니까?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 제가 알기로는 2명 정도의…….
</p>
<p><b>○ 이흥규 위원 </b> 규정에 없는데 있어요?  비상임정책연구위원을 둘 수 있다라고 해서 여기 자료 469페이지에 보면 2004년 12월 17일에 개정됐는데 그러니까 10월에 채용하면서 인사규정을 바꾼 것이 아니냐 이거죠?  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 비상임정책연구위원은 469페이지 보면 “연구원 또는 본원에 50억원 이상의 기금을 출연한 기관에 대하여 전문가로서의 정책자문을 위하여 비상임정책연구위원을 위촉할 수 있다”, 개정이 2004년 12월 17일로 돼 있는데요.
</p>
<p><b>○ 이흥규 위원 </b> 그러니까 2004년 12윌 17일이니까 그 근거규정을 만들기 위해서 개정한 것이 아니냐.  사실 여부만 얘기해 주면 돼요.  
</p>
<p><b>○ 행정지원과장 김영수 </b> 제가 말씀드리겠습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 누구신지 말씀해 주세요.
</p>
<p><b>○ 행정지원과장 김영수 </b> 행정지원과장 김영수입니다.  비상임정책연구위원 제도는 본래 있었습니다.  저희 연구원에 50억원 이상의 기금을 출연한 기관에 대해 정책자문을 하기 위해서 위촉할 수 있다라고 돼 있었고요.  지금 말씀하신 바와 같이 그것 외에 우리 연구원에서도 별도로 비상임정책연구원을 쓸 수 있다는 규정을 새로 개정한 것은 맞습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그러니까 이분이 거기에 해당이 안 되고 연구원으로 해당이 되니까 비상임정책연구원을 하려고 하다보니까 이 부분이 들어간 것 아니냐 이거죠.  
</p>
<p><b>○ 행정지원과장 김영수 </b> 제가 말씀드리면 그 당시의 시기가 어떻게 딱 맞아들었는데요.  사실 원장님께서 “비상임정책연구위원 제도를 좀 활용해야 되겠다” 그렇게 지시가 있어서 했던 겁니다.  사실 박기완 위원을 목표로 해서 개정한 것은 아닙니다.  
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 그때에 이것이 개정이 됐고…….
</p>
<p><b>○ 행정지원과장 김영수 </b> 네, 그때 공교롭게 맞았습니다.
</p>
<p><b>○ 이흥규 위원 </b> 박기완 연구위원님은 개인적인 부분입니다만 원장님하고 고교동창인 거 아시죠?
</p>
<p><b>○ 행정지원과장 김영수 </b> 네, 나중에 신문에도 나오고 해서 저도 알고 있습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 원장님이 고교동창을 표현적으로는 그렇게 하지 않았지만 그 부분에서는 오해가 가죠?  아무튼 그 부분은 그렇고요.  그것이 중요한 것은 아닙니다.  그런데 이분이 이력서를 제출한 내용을 보면 주식회사 코스모디아 인터내셔널 사장으로 2002년 12월부터 현재까지라고 기록돼 있거든요.  맞죠?
</p>
<p><b>○ 행정지원과장 김영수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그런데 본 위원이 코스모디아 등기부등본을 떼어봤습니다.  거기에는 2002년 12월 9일에 사임한 것으로 돼 있습니다. 
</p>
<p><b>○ 행정지원과장 김영수 </b> 2002년 12월 9일이요?
</p>
<p><b>○ 이흥규 위원 </b> 네.  그러면 2002년 12월부터 현재까지 인터내셔널 사장으로 돼 있는데 2002년 12월 9일에 등기부등본에는 사임을 했다 이거죠.  그러면 이분이 2004년도 12월에 경기개발연구원에 들어오신 거라면서요?
</p>
<p><b>○ 행정지원과장 김영수 </b> 10월 정도에 들어왔습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 10월에 들어오셨다면서요.  그런데 2002년부터 2004년까지 계속 현재 사장이라고 하셨는데 2002년도에 이미 사임이 된 부분이다 이거죠.  그러면 이분이 제일 위에 적은 코스모디아 인터내셔널 사장이라고 하는 부분이 허위기재 아니냐 이거죠.
</p>
<p><b>○ 행정지원과장 김영수 </b> 저도 그것을 나중에 초빙연구원으로 쓸 때 다시 봤는데 사실, 지금 카피본 가지고 계시죠? 
</p>
<p><b>○ 이흥규 위원 </b> 네.
</p>
<p><b>○ 행정지원과장 김영수 </b> 거기에 보면 지금 말씀하시는 코스모디아 인터내셔널 사장은 2002년도까지만 한 것으로 저희는 그때 자료로 위촉을 했습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그렇죠.  등기부등본에는 2002년 12월 9일에 사임을 했단 말이죠.  사임을 했는데 이 이력서가 본인이 작성한 이력서라면서요?
</p>
<p><b>○ 행정지원과장 김영수 </b> 그렇습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 본인이 작성한 이력서인데, 2002년 12월 9일 사임을 했는데 2002년 12월부터 내가 사장을 했다라고 하는 것이 첫 번째 나온다 이거죠.  그 내용은 어떻게 되는 것이냐.  그리고 그 부분은 제가 자료를 보다 보니까 이해가 안 가서 얘기하는 부분이고 그 회사가 주택신축판매업, 건물신축판매업, 주거용건물 임대업, 비주거용건물 임대업, 토지 및 기타 부동산 임대업, 사업 및 경영상담업, 기타 이와 관련된 업무일체, 사실 이분은 코스모디아 인터내셔널에서도 연구하고는 아무 상관이 없고 사업시행자라고 봐야죠.  
</p>
<p><b>○ 행정지원과장 김영수 </b> 제가 당시에 이러한 사람들을 위촉할 때 사실 비상임정책연구원이나 초빙연구원이나 단순하게 생각해서 위촉했을 때는 박사가 제일 좋습니다.  그런데 이렇게 박사학위가 없는 사람을 위촉할 때는 사실 실무자로서 애로사항이 많고요.  이 절차를 말씀드리면 일단 연구부서에서 저희한테 이러한 사람이 필요하다고 오면 저희는 임용절차만 갖춰주는 건데 마지막 결재는 물론 제가 맡습니다.  그때 제가 말씀드렸던 겁니다.  “이런 사람이 학위가 없기 때문에 위촉하기가 곤란합니다” 했을 때 우리 원장님이 당시의 말씀은 “토지이용이나 이런 쪽에는 상당한 식견이 많다 건설컨설트 같은 데에” 지금 말씀하시고 이상하게 보시는 코스모디아 인터내셔널 사장은 그 당시에는 검토 자체도 안 했습니다.  이 사람이 개인사업을 하는 사람인지 그런 것도 파악을 하지도 않았고요.  다만 저희 최고 결심권자가 잘 아시는 분인 것 같고 그래서 크게 의심없이 위촉했던 겁니다.  
</p>
<p><b>○ 이흥규 위원 </b> 과장님 말씀은 그렇게 밖에 답변을 못하시리라 믿고요.  그런데 문제는 뭐냐하면 그 밑에 커리어란에 보면 주식회사 아람손 인터내셔널 사장을 1996년부터 2002년까지 했었다라고 기재가 돼 있거든요.  그 부분도 등기부등본을 열람해 보니까 ’98년 9월 18일에 취임해서 2001년 9월 18일에 퇴임하고 2004년 6월 1일 다시 취임했습니다.  그러면 이분이 2004년도 10월에 입사했다는데 어떻게 등기부등본하고 틀리게 기재를 했겠느냐. 
</p>
<p><b>○ 행정지원과장 김영수 </b> 저희가 이 사람이 제출한 이력서를 굳이 하나하나 검토하지 않은 잘못이 있는 것 같습니다.  죄송합니다.  그것은 확실히 파악하지 않았습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 좋습니다.  그 부분은 어떤 착각에서 이렇게 잘못 쓰셨는지 모르지만 문제는 아람손 인터내셔널 회사가 지금은 인송개발로 2004년 11월에 명칭을 변경했네요.  그 인송개발의 사업목적은 부동산 컨설팅업, 건물관리용역업, 투자중개업, 이런 사업자인데 이런 사업자를 판교 IT 계획하고 한류우드 계획에다가 연구위원으로 위촉해 놓으면 이것이 어떻게 비밀이 보장되고 어떻게 특혜가 안 가겠느냐 이거예요.  그것에 대한 방지책은 무엇입니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그 부분에 대해서 간단히 답변을 드리겠습니다.  우선 박기완 위원이 제출한 이력서가 사실과 부합하는지 안 하는지를 제대로 확인하지 못한 것은 전적으로 저희들의 책임이라고 생각하고요.  사실은 현재도 박기완 위원이 저희 연구원의 초빙연구원으로 있기 때문에 이 문제는 이번에 행정사무감사하고 무관하게 저희가 다시 사실관계를 확인해서 이흥규 위원님께 다시 한 번 보고를 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  두 번째, 그럼에도 불구하고 비상임연구위원을 쓰는 것은 실제로 박기완 위원이 저희들한테 제출한 경력증명서를 가지고 그것에 적합한 경력이 있는지 없는지를 가지고 비상임정책연구위원을 랭크로 정했다는 점을 말씀드리겠고, 세 번째…….
</p>
<p><b>○ 이흥규 위원 </b> 부원장님, 그 경력증명서 어떤 부분을 참고해서 하셨는지요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 지금 박기완 위원이 저희들한테 제출한 경력증명서가 2개가 있습니다.  첫 번째가 아모르에서 낸 경력증명서가 있고요.  아, 3개가 있군요.  두 번째가 서울종합건축사 사무실에서 제출한 게 있고요.  그 다음에 대우건설에서 근무한 경력증명서를 저희들이 가지고 있습니다.  이 경력증명서에 근거해서 저희들이 거기에 맞는 직위를 부여했다고 말씀드리겠습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그런데 이분이 왜 건축사 경력하고 이 아모르 경력서는 제가 번역을 제대로 못해서 어떤 경력인지 모르겠습니다만 건축사 경력은 집어넣으면서 본인이 사장으로 있는 부분에 대해서는 경력증명서를 왜 못 떼왔는지…….
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 제가 굳이 여기 이 자리에서 말씀드려야 될 이야기인지 아닌지 모르겠습니다만 아마 이런 회사에 취직해 있다가 경우에 따라서 개인사업도 했었던 것으로 저희들은 들어서 알고 있습니다.  따라서 개인사업을 하다보니까 경우에 따라서 소위 대표이사 자리를 유동적으로 활용했었던 것은 아닌가 싶은 생각이 들고요.  그 부분에 대해서는 어쨌든 저희들이 확인해서 나중에 보고드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 세 번째는 왜 하필 이런 사람을 저희 연구원에서 썼느냐는 부분에 대해 답변해 드리겠습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 아니, 그런 사람을 썼느냐가 아니라 제가 걱정하는 부분은 사실 판교 IT든 한류우드든 그 계획이 사실 엄청나게 중요한 자료거든요.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 굉장히 중요한 자료입니다.
</p>
<p><b>○ 이흥규 위원 </b> 사업자들로 봤을 때는 아주 그야말로 엄청나게 중요한 자료인데 사업시행자를 여기 연구원으로 넣었을 때 그분이 양심적으로 이용을 안 하면 좋겠지만 그것을 안 한다고 믿는 사람이 많지 않거든요.  그것에 대한 보완대책은 무엇이 있느냐.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 일단 두 가지로 말씀드리겠습니다.  첫 번째, 박기완 위원을 전 한현규 원장님께서 활용했었던 이유는 두 가지 이유라고 제가 전 한현규 원장이 계실 때 들은 적이 있었습니다.  사실 좀더 정확하게 말씀드리면 박기완 위원의 자격요건에 대해서 실제로 저희들이 이 과제를 하는 중간에도 문제제기가 한 번 있었습니다.  공식적인 문제제기는 아니고 제가 비공식적으로 들었던 문제제기가 있었고 따라서 제 입장에서는 그걸 원장님께 보고하고 그것을 확인할 필요가 있었습니다.  그래서 확인을 했더니 두 가지 점을 말씀하셨습니다. 
</p>
<p style="padding-left:1.2em">  지금 이 위원님께서도 정확하게 말씀하고 계셨듯이 SPC 사업방식 자체가 우리한테는 굉장히 생소한 사업방식이다.  그 생소한 사업방식에 대해서 뭔가 해박한 지식을 가지고 있는 사람이 우리 연구를 도와준다면 좋겠다라는 게 첫 번째였고요.  두 번째 그런 사업을 진행하기 위해서는 연구부 자체도 연구부 자체지만 구체적으로 사업을 실행하기 위한 아주 세부적인 것을 알아야 된다.  그 세부적인 것을 알아야 되는데 그 세부적인 것을 우리가 전혀 알지 못하는 엉뚱한 사람한테 물어보게 되면 오히려 그것이 비밀유지에 훨씬 더 문제가 된다.  따라서 어느 정도 경력을 갖추고 있고 지식도 있고 또 전 한현규 원장께서 신뢰할 수 있는 사람을 고용해서 하는 게 좋겠다라고 생각해서 박기완 위원이 오기 싫어하는데도 오히려 붙들어서 왔다라고 전 원장님께서는 대답을 하셨습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그러면 부원장님께서는 그 부분에 대해서 일반 도민들이 믿겠느냐 이겁니다.  사업시행자를 연구위원으로 위촉해서 그 핵심부서에서, 더군다나 SPC 사업을 박기완 연구위원님께서 주장하신 부분이라고 하시는데 그러면 어느 일반 사업자에게 수의계약으로 한다는 그 핵심부분을 이 양반이 알고서, 본 위원이 얘기하는 부분은 그렇습니다.  그분이 그야말로 이것을 활용 안 한다고 뭘로 장담하느냐 이거죠.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 다시 한 번 말씀드리겠습니다.  SPC라는 게 절대 수의계약이 아닙니다.  SPC라는 것은 SPC를 만든 업체들 간의 경쟁입찰을 통해서 최종 사업자를 정하는 것이기 때문에…….
</p>
<p><b>○ 이흥규 위원 </b> 최종 수의계약이죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 경쟁입찰입니다.
</p>
<p><b>○ 이흥규 위원 </b> 경쟁해도 최종 수의계약이죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 경쟁인데 어떻게 수의계약이 되겠습니까?  경쟁입찰방식입니다.
</p>
<p><b>○ 이흥규 위원 </b> 자료에 그렇게 안 나와 있는데요.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 여러 SPC들 간의 경쟁입찰입니다.
</p>
<p><b>○ 이흥규 위원 </b> 경쟁을 해서 계약방식이…….
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 아니, 경쟁을 해서 입찰됐으면…….
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 좋아요.  그 부분에 대해서 논쟁하고 싶은 것은 아니고, 논점을 다른 데로 흐리지 마시고요.  제가 얘기하는 것은 이렇게 중요한 연구를 하는데 사업시행자가 여기 들어와서 연구하시는 부분, 지금 부원장님이 얘기하는 부분대로 참고하실 수 있겠습니다.  그러나 그 핵심 연구내용을 이분이 활용하지 않을 방도가 있느냐 이거죠.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 저희들이 사람이니까 그것에 대해서 100% 어떻게 할 수는 없습니다.  그런데…….
</p>
<p><b>○ 이흥규 위원 </b> 그렇다면 그분이 만약에 활용해서 한다고 그러면 특혜시비에 충분히 들어갈 수 있죠?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 특혜라는 것이 이 건과 관련된 특혜는 두 가지 형태가 있습니다.  아까 실무자가 이야기했습니다만 정확하게 다시 한 번 설명을 드리겠습니다.  개별 입지별로 잘라서 하는 경우에는 그 개별 입지를 잘라서 분양받고 나서 그것을 되팔든 내지는 거기에다 상가를 세우든 이것을 우리가 통제할 방법이 없습니다.  더더군다나 그것이 만일 한류우드와 관련된 사업이라면 그 한류우드의 합목적에 맞게 써야 되는데 그 목적에 맞게 쓸 수 있도록 통제할 방법이 없습니다.  지금 가장 유사한 예가 상암에 있는 단지입니다.  그것 같은 경우에는 개별 입지별로 나눠서 팔았습니다.  이것이 경우에 따라서 자칫 잘못하면 방조된 특혜가 될 가능성이 없지 않아 있습니다.  이것이 개별 입지로 판매하는 방식의 문제점이고요.
</p>
<p style="padding-left:1.2em">  SPC라는 것은 어떤 것이냐 하면 전체적으로 큰 땅을 한 사람한테 경쟁입찰을 통해서 넘겨줍니다.  그러면 그 부지에 대해서 전반적으로 합목적으로 써야 되기 때문에 우리가 생각하는 한류우드란 목적에는 가장 맞습니다.  문제는 이 SPC에서 어떤 문제가 있느냐 하면 이 SPC를 만드는 업자들이 여러 업자들이 모여서 SPC를 만들 겁니다.  그러다 보면 그 안에 전혀 자격요건이 주어지지도 않는 업자들이 이를테면 프리라이드(Freeride), 말타기를 할 가능성이 있다는 겁니다.  그것 때문에 문제가 생긴다는 것이죠.  그래서 이 두 가지를 놓고 어차피 일장일단이 있는 것이기 때문에 이걸 놓고 검토해서 어느 것이 나을 것인가를 결정하는 과정이고 그것에 대해서 아까 이미 김흥식 박사가 이야기했습니다만 지난 10월말에 경기도에서는 두 가지의 장단점을 면밀히 비교검토한 다음에 이미 확정한 상태이고요.  그것과 무관하게 박기완 위원이 그것을 이용할 수 있다라는 부분, 그 부분에 대해서는 제가 아까도 이미 설명을 드렸습니다만 이 사업을 진행해 나가려면 연구 자체가 아니라 구체적으로 사업적인 프로세스가 전제합니다.  이 사업적인 프로세스는 연구자인, 소위 책상머리에 앉아있는 저희들이 알 길이 없습니다.  그렇기 때문에 어떤 방식으로든 소위 사업자들의 조언을 통해서 그 프로세스를 우리가 이해를 해야 됩니다.  그것을 이해를 해야 되는데 다시 한 번 말씀드리지만 전임 원장께서 이야기하신 것처럼 아무 사업자나 불러다가 그것을 이해하게 되면 오히려 그 사업자가 그것을 가지고 장난칠 수가 있다.
</p>
<p><b>○ 이흥규 위원 </b> 거기까지는 이해하겠는데, 좋습니다.  부원장님이 얘기하신 대로 실제 현장에 있는 자문을 구하기 위해서 쓰는 것까지 이해하겠다 이거예요.  그러면 그 부분을 활용 못할 방안이 뭐가 있느냐 이겁니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 지금도 박기완 위원께서 저희 과제에 아직도 인볼브(Involve) 되어 있습니다.  따라서 지금 당장 이를테면 그것이 문제가 된다고 한다면 저희들은 당연히 박기완 위원을 지금 당장이라도 위촉을 해지해야 됩니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그것은 본인이 활용하겠다고 안 하겠죠.  그것을 얘기하는 것이 아니라 지금 부원장님이 얘기하신 대로 필요성이 있어서 한다면 문제가 생길 것에 대한 문제방지대책도 세워야 될 것 아니냐 이거죠. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 문제방지대책이 사실은 바로 경쟁입찰방식이라는 겁니다. 
</p>
<p><b>○ 이흥규 위원 </b> 부원장님!  그 부분을 호도하지 마시고요.  자료에 보면 SPC 방식이 뭐냐면 사업자선정방식, 제한심사에 의한 수의계약.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 제한심사라는 게 뭐냐면 SPC를 만들어온 사업자들 간에 심사입니다.  그것이 사실은 경쟁적인 입찰관계구조입니다.
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 제한심사에 의한 수의계약을 경쟁입찰로 봐야 됩니까?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 제가 지금 다시 말씀드리지만 그것은 경쟁입찰방식입니다.
</p>
<p><b>○ 이흥규 위원 </b> 그러면 한글학자 데리고 올까요?  제한심사에 의한 수의계약, 이걸 뭐라고 봐야 됩니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> SPC를 만든, 소위 이게 Special Purpose Company니까 그 컴퍼니들끼리…….
</p>
<p><b>○ 이흥규 위원 </b> 그 다음에 여기 보면 제2안 공개경쟁입찰…….
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그것은 와장창 다 빼놓고 한꺼번에 다…….
</p>
<p><b>○ 이흥규 위원 </b> 그러면 이 자료는 뭘로 보라는 겁니까?  말 같은 소리를 해야지.  자료를 보고 얘기하는 건데.  제한심사에 의한 수의계약을 공개입찰계약으로 갈음한다는 얘기입니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 실제로 업체를 선정하기 위해서 필요한 점수들을 놓고 그 점수에…….
</p>
<p><b>○ 이흥규 위원 </b> 그것은 제한심사라고 보는 거죠.  공개경쟁입찰이라고 보지 않죠.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 공개는 아닐지 모르겠습니만 단독으로 누가 들어와서 그 업체에 대해서 단독으로 평가하는 게 아니라는 것입니다. 
</p>
<p><b>○ 이흥규 위원 </b> 물론 그렇죠.  문제는 뭐냐하면 제한심사에 의한 수의계약을 부원장님은 마치 공개경쟁입찰로 얘기하시는 부분은 잘못됐다 이겁니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 경쟁입찰이라고 제가 말씀을 드렸습니다.
</p>
<p><b>○ 이흥규 위원 </b> 그러면 여기 검토에도 경쟁입찰로 나와야지 부원장님께서, 그러면 위원은 한글도 모르는 바보로 안다는 말입니까?  분명히 여기 “제한심사에 의한 수의계약” 이렇게 써있는데 이 부분을 가지고 경쟁입찰이라고 한다고 그러면 어떻게 믿으란 얘기입니까?  그것을 그런 방향으로 호도하지 마시고, 본 위원이 걱정하는 것은 그것 아닙니까?  이런 중요한 부분이 있는데 그 연구위원께서 다행히 이것을 활용 안 하셨다면 좋겠죠.  그렇지만 경기개발연구원에서는 그런 실무적인 경험이 필요해서 쓴다고 했을 때 그분이 이것을 사업에 활용했을 때는 커다란 문제점이 생기는 것 아닙니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그 활용이라는 것에 대해서 제가 계속 말씀드리는 건데요.  그 활용을 해서 특정한 SPC한테 이익을 줄 수가 없다는 겁니다.  왜냐하면 여러 개의 SPC가 같이 들어와서 같이 심사를 받기 때문이라는 겁니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그러면 연구위원이 핵심 연구원에 있으면서 아무런 연구과제가 쓸모가 없다는 얘기입니까?  그렇게 말씀하실 수 있어요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그게 무슨 말씀이신지…….
</p>
<p><b>○ 이흥규 위원 </b> 사업자한테 아무런 쓸모가 없는 자료다?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 사업자한테 아무 쓸모가 없는 자료라는 게 무슨 말씀인지…….
</p>
<p><b>○ 이흥규 위원 </b> 이 연구용역의 핵심내용이 일반 사업시행자들한테 도움이 안 되는 내용이냐 이거죠.  
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 중요한 것은 객관적인 기준이 설정된다면 그 프로세스를 미리 알았다.  이를테면 한류우드의 예를 들면 그림을 먼저 알았다고 그래서 그것이 크게, 일찍 준비하는 효과는 있을지 모르겠습니다만 크게 효과는 없을 거라고 생각합니다.  그리고 사실은 그 분야에 대해서 많은 업체들이 관심을 보이고 각각 스스로 SPC를 만들기 위해서 노력을 해왔습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 부원장님께서 본 위원이 걱정하는 부분을 모르고 모르는 척 하시는 겁니까, 진짜 알면서 모르는 척 하시는 겁니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 제가 솔직히 말씀드리면 이 위원님께서 어떤 부분을 정확하게…….
</p>
<p><b>○ 이흥규 위원 </b> 판교 IT 사업이나 한류우드 사업의 연구위원이 사업시행자라고 했을 때 문제점이 없다고 생각하시는 거예요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 만일 그 연구위원이 밖에 나가서 사적인 목적으로 그것을 활용하려고 한다면 그것은 저희 연구원의 연구자로서 참여하는 사람에 대해서 저희들이 통제를 해야 된다고 생각합니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그래서 어떻게 통제하실 거냐 이겁니다.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 통제에 대해서는 저희들이 지금까지 계속 그 과제에 참여한 사람들한테 계속적으로 해왔고요.  실제로 그런 부분에 대해서 조금이라도 어떤 외부적인 문제나 잡음이 생긴다면 그 순간부터 그 과제 참여에서 배제를 시켜야 된다고 생각합니다. 
</p>
<p><b>○ 이효선 위원 </b> 위원장!  의사진행발언 있습니다.  너무 한 가지로 길게 가는데 서류로 받죠.  시간이 너무 지나가는 것 같습니다.
</p>
<p><b>○ 이흥규 위원 </b> 이효선 위원님 죄송합니다.  이 부분은 중요한 문제입니다.  경기개발연구원의 핵심연구위원이 현직 사업시행자라고 했을 때 이 정보가 중요하지 않다고 하는 부분은, 부원장님이 그렇게 얘기하시면 안 되고 이것은 분명히 중요한 정보가 될 수 있습니다.  이 부분에 문제가 생기면 그때 연구요원 제제하겠다는 부분은 바람직하지 않지요.
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 현직 사업시행자라는 게 제가 지금 계속 이해가 안 되는데 현직 사업시행자라고 말씀하시지만 지금 박기완 위원은 저희 연구원에 풀타임으로 와서 근무하고 있습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그러면 이 등기부등본은 믿지 말아야 되나요?
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 그 부분에 대해서는 아까도 말씀드렸습니다만 저희도 다시 한 번 확인해 보고 표현이 좀 이상합니다만 두 개의 잡(job)을 가지고 낮에는 저희 연구원에서 일하고 밤에는 그렇게 하고 있다면 저희 연구원의 임용규정에도 어긋납니다.  그에 따라서 정확하게 처리를 하도록 하겠습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 이 부분 갖고 길게 논의할 것은 아니고 경기개발연구원의 핵심연구원이 사업시행자라고 하는 부분은 우리 국가에서 발행하는 등기부등본에 나와 있거든요.  이런 문제점이 있다는 것을 지적하겠습니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 네, 그것은 저희가 반드시 확인해서 이 위원님께 보고를 드리도록 하겠습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 수고하셨고요.  사실 요즘 경기개발연구원의 사기가 저하된 부분 이해하고 그럼에도 불구하고 열심히 근무하시는 박사님들에게 감사드리면서 경기개발연구원이 경기도정의 중ㆍ장기 비전 제시와 정책개발 지원ㆍ발전에 적극 도움이 되기를 바라겠습니다.  이상입니다.
</p>
<p style="padding-left:2.4em">    (정인영 위원장, 김대원 간사와 사회교대)
</p>
<p><b>○ 위원장대리 김대원 </b> 이흥규 위원님 보충질의 수고하셨습니다.  더 질의하실 위원님 계십니까?  의사진행발언입니까, 보충질의입니까?
</p>
<p><b>○ 이건희 위원 </b> 아니에요, 제가 신청했던…….
</p>
<p><b>○ 위원장대리 김대원 </b> 이건희 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이건희 위원 </b> 이건희 위원입니다.  아까 오전에도 질의했고 오후에 다시 연구과제 추진실적 및 연구실적에 관해서 제가 많은 자료를 요청했었고요.  그 자료를 지금 다 넘겨받고 그러한 많은 연구과제를 심혈을 기울여서 연구원에서 했는데 과연 도정에 반영되는 비율이 얼마인가를 제가 저번 감사 때도 질의를 드렸었고 우리가 100억 가까이 되는 많은 예산도 지원하고 있고, 도정에 반영되는 비율을 제가 쭉 다 넘겨봤습니다.  기본과제만 해도 23개 과제이고 수탁과제 39, 정책과제도 2004년도나 2005년도에 비슷하기 때문에 40여개, 그리고 지역과제, 기타 과제 해서 보통 150개 이상 되는 일련의 그런 과제물을 수행하시는데 제가 쭉 넘겨보니까 어떻게 반영이 돼 있는가 했더니 예를 들어서 경기도 대중교통기구 설립방안에 관한 연구에 보면 “주민 교통불편을 완화했다” 뭐 이렇게 해서 “어떤 방안을 제시했고 지침을 마련했다”, 그리고 “어떤 것의 개선에 기여했고” 심지어는 “새로운 지평을 개척했다” 이렇게 저렇게 해서 개선대안 제시, 기초자료로 활용 등등 수많은 사연으로 해서 전부다, 제가 보니까 80% 이상이 “도정이라든지 시정에 기초자료라든지 반영이 됐다” 이렇게 적시하고 있는데 부원장님이 생각하시는 바로는 우리 경기개발연구원에서 발행된 많은 연구자료들이 어느 정도 도정에 반영되고 있다고 생각합니까? 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 아마 경중은 있겠습니다만 저희 연구원에서 하고 있는 것 중에 과제를 두 가지, 수탁은 일단 빼고 말씀드리면 기본과제하고 정책과제가 있는데요.  정책과제는 문자 그대로 도에서 정책적 수요가 있다고 판단됐을 때 하는 것이기 때문에 그 과제의 결과는 크고 중요한 것일 수도 있고 사소한 것일 수도 있습니다만 도정에 100% 반영된다고 보고요.  두 번째, 기본연구과제 같은 경우는 저희들이 연심회에 도의 공무원, 과장들을 참여시킵니다.  그래서 도에서 필요로 하는 것들이 그 과제에 어떻게 반영되는지를 사전에 파악해서 그것들을 저희들이 집어넣도록 하고 있습니다.  그러다보니까 아마 반영률이 높은데 솔직히 말씀드리면 정책반영실적의 내용으로 보면 아주 중요하게 반영된 것도 있고 이를 테면 의미가 좀 떨어진 것도 있을 수 있다고 생각합니다. 
</p>
<p><b>○ 이건희 위원 </b> 제가 경기개발연구원에서 보내주는 책자를 사실 100% 못 봅니다.  하지만 앞머리 머리말 부분이라든지 서론부분이지요.  서론부분하고 결론부분은 보는데 이 수많은 책자 중에서 사실 제가 봤을 때 허술한 면도 있고 또 한 가지 지적하고자 하는 것은 아까도 경기방문의 해에서, 아직 제대로 경기방문의 해에 대해서 어떻게 외국인을 유치할 것인지에 대한 대책도 없이 이렇게 해서 별 효과를 못 봤다 이런 말씀을 드렸고요.  여기 보면 광교테크노밸리를 조성하는 데 있어서 거기에 대해 우리가 사업과 입안하는 연구를 동시에 하고 있는 이런 실정입니다.  조급한 느낌이 들고요.  물론 우리 도지사님이라든지 임기가 보통 4년 주기로, 경기개발연구원은 영원하지만.  그러다보니까 이것을 동시에 하다보니까 광교테크노밸리에 대한 어떤 조성사업이라든지 어떻게 해나가겠다는 것도 연구를 하면서 그것을 그대로 시행해 나가는 이러한 문제점을 발견할 수가 있었습니다.  그것 외에도 물론 현안사항에 따라서 갑작스럽게 과제가 수행될 수도 있는데 제가 한 가지만 예를 들어서 보면, 저는 우리 경기개발연구원에 대해서 칭찬의 말씀을 드리는 겁니다.  “경기북부지역 발전촉진을 위한 규제완화특별법안 제정 논리개발 및 대응방안”이라는, 참 제목도 깁니다.  이것을 지금 현재 보니까 한 권의 책이 나오기 위해서 여섯 명의 박사님들이 1년 가까이 걸려서 이러한 제시를 해왔는데 제가 봐도 연구의 필요성부터 정부규제 그리고 북부지역의 어떤 규제내용들이 너무나 상세하게 잘 돼 있어서 이런 정책반영이라든지 어떤 법률안을 만드는데 기초자료로 쓰는데 충분하다라는 이런 생각이 들었고요.  하여튼 이 수많은 과제를 수행하시는 여러분들에게 정말 감사의 말씀을 드리고 이번 경기개발연구원의 약간 흔들리는 모습이 있을 수 있는데 앞으로도 좀더 최선을 다해서 사명감을 갖고 연구과제를 수행해 주시기를 부탁의 말씀드리면서 저는 이상 마치겠습니다. 
</p>
<p><b>○ 경기개발연구원부원장 김태승 </b> 감사합니다.  앞으로도 연구질을, 품질을 높이기 위해서 최선을 다하겠습니다. 
</p>
<p><b>○ 위원장대리 김대원 </b> 더 이상 질의하실 위원 안 계시지요? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원이 안 계시면…….
</p>
<p><b>○ 이흥규 위원 </b> 위원장님, 잠깐 한 가지만.
</p>
<p><b>○ 위원장대리 김대원 </b> 그렇게 계속 하시면 다른 위원님들도 다 하셔야 되잖아요.
</p>
<p><b>○ 이흥규 위원 </b> 끝나는 것 아닙니까? 
</p>
<p><b>○ 위원장대리 김대원 </b> 그러니까 끝나니까…….
</p>
<p><b>○ 이흥규 위원 </b> 끝나니까 제가 한 가지만 질의…….
</p>
<p><b>○ 위원장대리 김대원 </b> 지금 다른 두 분 위원의 질의요청이 들어왔는데 안 하는 것으로 말씀을 드렸는데 또 다시 하자고 하시면 계속 진행해야 됩니다.
</p>
<p><b>○ 이흥규 위원 </b> 알았습니다. 
</p>
<p><b>○ 위원장대리 김대원 </b> 협조를 좀 해주세요.
</p>
<p><b>○ 이흥규 위원 </b> 알았어요.
</p>
<p><b>○ 위원장대리 김대원 </b> 장시간 열의를 갖고 감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료준비와 위원님들의 질의에 성실히 답변해 주신 김태승 부원장을 비롯한 임직원 여러분께 감사드립니다.  끝으로 오늘 감사위원장으로서 연구원 가족 여러분들에게 정인영 위원장님의 당부말씀을 간략하게 읽어드리겠습니다. 
</p>
<p style="padding-left:1.2em">  “오늘 감사 중에 여러 위원님들께서 말씀이 있으셨습니다만 한현규 전 원장님의 불미스러운 일과 관련해 행여 여러분께서 동요하거나 의기소침하지 않았으면 하는 바람을 위원회를 대표해 여러분께 전하고자 합니다.  여러분께서도 자부하고 계시지만 경기개발연구원은 경기도의 싱크탱크입니다.  싱크탱크가 흔들리면 경기도정에 좋지 않은 영향을 끼칠 수 있습니다.  민선3기 경기도정이 원활히 마무리되고 경기도가 흔들림 없이 앞으로 나갈 수 있도록 여러분의 분발을 당부드립니다.” 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 연구원 임직원 여러분!  수고하셨습니다.  그러면 이상으로 경기개발연구원에 대한 2005년도 행정사무감사를 모두 마치겠습니다.  감사합니다. 
</p>
<p class=''ar''>(17시31분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원
</b></p>
<p class=''aMan''>정인영김대원김영복박영신이건희이효선장정은정금란진종설함진규</p>
<p class=''aMan''>이흥규</p>
<p><b>○ 행정사무감사보조공무원
</b></p>
<p><p class=''em15''>전문위원 오태철지방행정주사 박준호지방행정주사보 임장호</p>
<p><p class=''em15''>지방기능7급 전순옥지방기능8급 정지연</p>
<p><b>○ 출석증인
</b></p>
<p><p class=''em05''>ㆍ경기개발연구원</p>
<p><p class=''em15''>부원장 김태승사무처장 이강수기획조정실장 성현찬</p>
<p><p class=''em15''>자치행정연구부장 이용환교통정책연구부장 조응래</p>
<p><p class=''em15''>도시지역계획연구부장 김제국환경정책연구부장 이정임</p>
<p><p class=''em15''>경제사회연구부장 김군수동북아지역연구부장 김동성</p>
