            <div','경기도의회',false,'{"legacy_id": "audit-3297", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=3297"}'::jsonb,'2005-11-17'::date,'2005-11-17'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-3297');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2004.11.26. 금요일] 경기개발연구원 — 기획위원회 2004년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제6대 경기도의회 기획위원회</b> · 2004년도 행정사무감사(2004. 11. 22. ~ 2004. 12. 01.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=3351" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2004년도 행정사무감사
</p>
<h4>기획위원회 회의록 
</h4>제5호
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일  시 : 2004년 11월 26일(금)
</p>
<p>장  소 : 경기개발연구원회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시50분 감사개시)
</p>
<p><b>○ 위원장 정인영 </b> 좌석을 정돈하여 주시기 바랍니다.  지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례 제2조의 규정에 의하여 경기개발연구원에 대한 2004년도 행정사무감사를 시작하겠습니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기개발연구원장을 비롯한 임직원 여러분!  안녕하십니까?  기획위원회 감사위원장 정인영입니다.   오늘은 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다.  여러분께서도 잘 아시는 바와 같이 지방의회의 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2005년도 예산안 심사자료 및 정보 획득을 통해 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 할 수 있습니다.  따라서 감사위원 여러분께서는 연일 계속되는 감사일정으로 노고가 많으십니다만 도민을 대표하여 도비 출연기관인 경기개발연구원의 운영실태를 감사하는 것이니만큼 심도 있는 감사활동으로 소기의 성과를 거둘 수 있게 되기를 기대하면서 아울러 감사에 임하는 연구원 원장님과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기를 당부드립니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다.  감사를 받는 경기개발연구원장 및 실ㆍ부장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 합니다.  증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2004년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 
</p>
<p style="padding-left:1.2em">  만약, 증인이 허위증언을 한 때에는 지방자치법 제36조제5항 및 경기도의회행정사무감사및조사에관한조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만원이하의 과태료가 부과될 수 있음을 알려드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인출석 여부를 확인하겠습니다.  피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다.  경기개발연구원장 나왔습니까? 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 네.
</p>
<p><b>○ 위원장 정인영 </b> 기획조정실장 나왔습니까? 
</p>
<p><b>○ 기획조정실장 신원득 </b> 네.  
</p>
<p><b>○ 위원장 정인영 </b> 자치행정연구부장 나왔습니까? 
</p>
<p><b>○ 자치행정연구부장 이용환 </b> 네 
</p>
<p><b>○ 위원장 정인영 </b> 교통정책연구부장 나왔습니까? 
</p>
<p><b>○ 정책개발센터장겸교통정책연구부장 조응래 </b> 네.
</p>
<p><b>○ 위원장 정인영 </b> 도시지역계획연구부장 나왔습니까? 
</p>
<p><b>○ 도시지역계획연구부장 이성룡 </b> 네.
</p>
<p><b>○ 위원장 정인영 </b> 경제사회연구부장 나왔습니까? 
</p>
<p><b>○ 경제사회연구부장 이상훈 </b> 네.
</p>
<p><b>○ 위원장 정인영 </b> 다음은 선서의 요령을 설명드리겠습니다.  선서는 증인을 대표해서 경기개발연구원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에서 오른손만 들어주시면 되겠습니다.  그러면 선서를 해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 선서!  본인은 경기도의회가 지방자치법 제36조, 동법시행령 제16조제1항, 경기도의회행정사무감사및조사에관한조례 제2조의 규정에 의하여 소관 업무에 대한 2004년도 행정사무감사를 실시함에 있어 성실하게 감사를 받을 것이며, 또한 증인으로서 증언을 함에 있어서는 지방자치법시행령 제17조의4 제5항과 지방의회행정사무감사및조사에관한조례 제18조의 규정에 의하여 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다.
</p>
<p class=''ar''> 2004년 11월 26일
</p>
<p class=''ar''>증인 경기개발연구원장 한현규.
</p>
<p><b>○ 위원장 정인영 </b> 자리에 앉아주시기 바랍니다.  그러면 경기개발연구원장 나오셔서 간부소개와 업무보고를 해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 경기개발연구원장 한현규입니다.  존경하는 정인영 위원장님과 위원님 여러분!  바쁘신 의정일정 중 우리 연구원을 찾아주시어 행정사무감사를 해 주시는 것에 대하여 전 연구원을 대표하여 우선 감사의 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  우리 연구원은 지난 6월 30일 이곳 새로운 청사에 입주하여 예전보다 훨씬 좋아진 분위기 속에서 연구활동에 임하고 있습니다.  이에 필요한 막대한 예산을 뒷받침 해주신 위원님들께 감사의 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  저는 7월 말에 부임하여 약 4개월 되는 기간입니다만 나름대로 우리 연구원의 경기도 싱크탱크로서의 역할과 기능을 강화하기 위한 노력을 경주하고는 있습니다만 능력이 미진하여 아직까지 별다른 성과를 보이지 못하고 있는 것도 사실입니다.  이러한 때에 마침 도의회 기획위원님들께서 행정사무감사를 통해 평소 의정활동 과정에서 느끼신 우리 연구원의 운영상의 문제점과 발전방안에 대하여 저희를 질책하시고 지도해 주시는 계기가 마련되었음을 개인적으로 무척 다행이라고 생각하고 있습니다. 
</p>
<p style="padding-left:1.2em">  무릇 연구원이라고 하는 것이 연구실에 틀어 박혀 연구를 위한 연구를 하는 것이 아니라 도정을 뒷받침하고 도민들의 일상생활에 파고 들어갈 수 있을 때 그 본연의 기능을 다하는 것인 만큼 의정활동에서, 그리고 지역구 활동에서 도민과 함께 하면서 생생하고 피부에 와닿는 현장의 목소리와 생각을 전달하고 이입시켜 주시는 위원님들의 고견이 절실히 필요한 때라고 봅니다.  아무쪼록 오늘 행정감사를 통해서 원장을 비롯한 우리 연구원 전원이 다시 한 번 정신 바짝차리고 연구원과 도정발전을 위해 새로운 각오를 다짐할 수 있도록 애정어린 질책과 함께 발전적인 조언을 하여 주실 것을 간곡히 기원하면서 업무보고에 앞서 연구원의 간부를 소개해 드리겠습니다.  먼저 신원득 기획조정실장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  조응래 정책개발센터장 겸 교통정책연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사) 
</p>
<p style="padding-left:1.2em">  다음은 이용환 자치행정연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이성룡 도지지역계획연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상훈 경제사회연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  성현찬 환경정책연구부장은 당초 감사일정에 따라 29일 출석 예정이었으나 26일 귀국예정으로 현재 해외출장 중에 있음을 송구스럽게 생각합니다. 
</p>
<p style="padding-left:1.2em">  그러면 지금부터 배부해 드린 유인물을 중심으로 우리 연구원의 주요업무를 보고 드리겠습니다.  보고드릴 순서는 일반현황과 재정운용, 2004년도 연구사업 추진현황, 2005년도 연구사업 계획에 대해 중요사항을 중점으로 간략히 보고드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 유인물 1페이지입니다.  저희 연구원은 ''95년도 개원후 9주년이 되었으며 2004년 6월 23일 현 청사로 이전하였습니다.  연구원의 주요기능은 도정의 비전 제시와 정책개발을 위하여 기획조정실, 정책개발센터, 자치행정연구부 등 5개 연구부가 경기도 수요에 맞게 다양하고 심도 있는 연구를 수행하고 있으며 보다 자세한 사항은 유인물을 참고하여 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  2페이지 본원의 기구 및 인력사항입니다.  본원은 1실ㆍ1센터ㆍ1처ㆍ5부로 구성되어 있고 현재 인력은 박사급 연구직 45명을 포함해서 모두 64명이 재직하고 있습니다.  연구원 총정원은 63명으로 18명이 부족한 연구직 중 2004년 11월 공개모집을 통해 최종 3명을 선발하였으며 나머지도 수시모집을 병행하여 우수한 인력이 충원될 수 있도록 최선을 다하도록 하겠습니다.  특히 표에 나타난 정책개발센터는 연구원의 연구성과를 보다 효과적으로 도정에 반영하고 적극적인 홍보대책 등을 통해서 연구원의 기동타격대와 같은 기능을 갖추기 위해 지난 8월에 신설하였습니다.  총 10명의 정원입니다만 지금까지 3명의 정원을 확보하였고 연말까지 나머지 정원을 채워나가도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  또 한 가지 직제에서 보고드릴 사항은 상임위원회 자문위원에 관한 건입니다.  위원님께서도 잘 아시겠습니다만 지난 2월부터 7월까지 근 5개월 동안 연구원장이 공석으로 있었습니다.  그 기간 중에 대표이사를 맡으셨던 이수영 위원께서 연구원뿐만 아니고 도정 전반에 관한 폭넓은 경험과 지식을 저희가 활용하기 위해서 상임자문위원이라고 하는 직제를 신설하여 그 자리에 임명하였습니다.  임명과정에서 정인영 위원장님께서 여러 가지 문제 제기를 해주셨습니다만 저희가 꼭 필요한 사람이라고 하는 점을 널리 양해해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 3페이지 시설 및 물자현황을 보고드리겠습니다.  먼저 청사는 금년도 6월 23일부터 경기도공무원교육원 6층에서 12층까지 대지 9,190평에 건평 1,656평을 사용 중입니다.  연구에 필요한 장서는 2만 9,000권 정도를 보유하고 있으며, 주요 최신의 국내외 전문서적 및 경기도관련 자료로서 연구원뿐만 아니고 일반 시민들, 학생들에게까지 모두 공개하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 4페이지 재정운용사항입니다.  먼저 올해 총예산 규모는 437억 7,900만원으로 일반회계 131억원, 기금관리특별회계 268억원, 수탁용역사업특별회계 37억원으로 구성되어 있습니다.  일반회계 주요 세입재원으로는 전입금 11억 9,300만원, 수탁용역사업 수입 9억 8,700만원, 도비출연 75억원, 환급금 2억 1,500만원, 이월금 30억 2,800만원 등이며 주요세출로는 연구사업비가 전체 73%인 95억원, 기관운영비가 11%인 14억원, 청사유지비가 7%인 9억 6,000만원으로 구성되어 있습니다. 
</p>
<p style="padding-left:1.2em">  5페이지 기금관리특별회계와 수탁용역사업특별회계의 수입ㆍ지출내역은 유인물로 갈음토록 하겠습니다.  예산집행에 있어 충실한 연구가 수행될 수 있는 여건지원에 중점을 두어 내실 있는 운영을 하도록 최선을 다하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 6페이지 기금조성 운영사항은 총 기금조성액 257억원 중에서 57.2%인 147억원을 도에서 출연하였고 15.4%인 39억원은 시ㆍ군 출연금입니다.  나머지 2개 은행의 출연금과 자체적립금으로 구성되어 있습니다.  기금예치상황을 보면 이자율 및 예금의 종류를 고려하여 분산예치를 원칙으로 운영하고 있으며 표에서 보는 바와 같이 기금 257억원은 현재 6개 금융기관에 11종의 금융상품으로 적립되고 있습니다.  자세한 유치내역은 유인물을 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음 7페이지 금년도 연구사업 추진상황 중 주요실적을 보고드리겠습니다.  기업과 수도이전을 위한 중앙정부 정책에 대응하는 국가균형발전 전략, 수도권의 성장관리, 지방분권 등에 대하여 적극적인 도정 지원을 하고 있으며 개정된 국토계획법에 각 시ㆍ군이 합리적으로 대응할 수 있도록 도시계획수립지침 등 각종 개발과 보전에 대한 방법을 보급하고 있습니다.  또한 수도권 대기질 개선을 위한 연구를 서울, 인천과 공동으로 추진하고 경기도가 직접 해결하기 어려운 각종 현안에 대해 세미나 등 공개토론회를 개최하여 국민적 공감대를 형성해 나가고 있으며, 경기도의 주요 정책과 이슈에 대한 방향을 설정하고 심도 깊게 논의할 수 있는 정책포럼을 운영하고 있으며 핫이슈에 대한 CEO 리포트를 작성하였습니다.  그리고 중국 산동성 사회과학원과 교류협력을 위한 자매결연을 금년도에 체결하였고, 연구원 통합정보시스템을 구축하여 현재 운영 중에 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 8페이지부터 11페이지에 이르기까지 2004년도 연구사업의 세부추진실적을 보고드리겠습니다.  우선 도정의 제도개선과 정책개발의 시의성을 높이기 위해서 국제무역환경의 변화와 경기도의 대응, 민선3기 2년 성과의 평가와 향후 도정방향, 시화ㆍ반월공단의 악취관리대책, 소각업체 관리방안 등을 연구하고 있으며 도정 이슈에 대한 구체적인 방법과 대안마련을 위해 생물서식공간 조사 및 조성지침, 지방정부 성과관리모델 설계 등을 추진하였습니다.  그리고 국가균형발전과 지방분권을 위한 정책개발을 위해서 정책개발센터 내에 국가균형발전TF팀을 둬서 국가균형발전을 위한 전략연구를 수행하고 있으며 수도권성장관리를 위한 기본구상 및 계획, 경기도지역혁신발전 5개년계획사업과 지역혁신협의회 조직을 운영 중이고 수도권공장의 신설과 증설규제의 개선방안 및 수도권공장입지규제 개선정책에 대한 효과분석을 하고 있으며 제4차 국토계획 수정계획 경기도편을 저희가 수립하였습니다. 
</p>
<p style="padding-left:1.2em">  또한 동북아 경제중심, 동북아협력체계 구축을 위해서 차세대 융합기술연구원의 건립 기본계획과 바이오 장기생산연구시설 건립 기본계획 등을 추진하였고 미군기지 이전에 따른 지원대책안을 수립하기 위해서 군사시설주변지역의지원에관한법률 제정 연구와 용산 미군기지 이전에 따른 경기도 대응방안을 수행하고 평택시 장기발전계획과 용산기지평택이전에따른지원특별법, 동두천지역지원특별법 제정방안을 마련 중에 있습니다.  이 외에도 대중교통 개선을 위한 체계적이고 구체적인 노력을 하고 있으며 선도적 도정방향의 유도와 인재육성과 고용의 촉진을 위해 노력하였습니다. 
</p>
<p style="padding-left:1.2em">  다음 12페이지 금년도 연구사업 총괄편을 간략히 보고드리겠습니다.  연구과제 사업은 계획대비 118%인 158과제, 정기간행물 간행사업은 계획대비 76%인 22회, 연구조성사업은 계획대비 130%인 35건을 달성할 것으로 예상되며 총계획대비 114%인 215건을 달성할 것으로 예상하고 있습니다.  각 연구사업의 세부추진사항은 13페이지부터 23페이지까지 간략히 보고드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 13페이지 기본연구과제 27과제를 수행하고 있습니다만 수도권 대기질 지역간 영향분석 등 5개 과제를 완료하였고 경기도 대중교통관리기구설립방안에 관한 연구 등 22개 과제는 현재 연구 중에 있습니다. 
</p>
<p style="padding-left:1.2em">  14페이지부터 16페이지까지의 수탁연구과제는 작년도에 이월된 38개 과제와 금년도에 신규로 위탁받은 30건을 포함한 68건 중 성과중심예산제도 도입을 위한 지표체계 구축 등 34건을 완료하였고 과천 지식정보타운개발계획 수립 및 타당성조사 연구 등 34건은 아직도 추진 중에 있습니다.
</p>
<p style="padding-left:1.2em">  17페이지부터 19페이지까지 정책연구과제입니다.  전년도에 이월된 8개의 과제와 금년도에 신규로 요청받은 39건을 포함한 47건 중 용산 미군기지 평택이전에 따른 평택지역지원특별법 제정방안 연구 등 30건은 완료하였고 개발제한구역의 합리적 관리를 위한 제도개선 방안 등 17건은 현재 추진 중에 있습니다.
</p>
<p style="padding-left:1.2em">  19페이지 위탁연구과제 7건 중에서 경기개발연구원 CI개발 위탁용역 1건은 완료하였고 나머지 6건은 추진 중에 있습니다.  20페이지 협약연구과제 5건은 푸른경기비전 심포지엄 1건을 완료하고 동두천시 지역연구과제 등은 현재 진행하고 있습니다. 
</p>
<p style="padding-left:1.2em">  21페이지 정기간행물 발간사업은 연구원이 발행하고 있는 경기논단 등 4건을 정기적으로 발행하고 있으며 2004년도 워크숍 자료집과 해외출장보고서도 발간할 예정입니다.  번역사업 중 1건은 완료하였고 1건은 현재 추진 중에 있습니다.  다음은 22페이지 정책세미나 및 워크숍은 모두 23회를 완료하였고 1건은 현재 추진 중이며 자세한 내역은 유인물을 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 23페이지 정책포럼은 남북포럼, 교육포럼, 동북아포럼을 총 9회에 걸쳐 개최하였고 시ㆍ군 담당연구원제를 구축해서 운영 중에 있고 올해는 시ㆍ군 관계자들과의 1차 면담을 추진하고 향후 관ㆍ연 협력체계가 활성화 될 수 있도록 노력하겠습니다.  24페이지 연구사업의 연도별 수행현황은 유인물을 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  이어서 25페이지부터 50페이지까지 2005년도에 연구사업계획을 보고드리겠습니다.  내년도 연구사업의 기본방침은 민선3기 후반기에 도정 주요현안과제와 신정부의 국정 추진과제 등에 대하여 탄력적으로 대응하고 실효성 있는 연구성과물을 도출하며 신속하고 시의성 있는 도정 정책개발기능을 강화하고 연구실적의 평가와 수행체계 개선을 통해서 경영내실화 및 연구결과의 질을 제고코자 하고 있습니다.  지속가능한 경기도를 위해 총체적이고 다양한 연구결과를 지향하기 위해서 우수인력을 적극적으로 채용ㆍ활용하고 연구원 개원 10주년 기념사업을 계기로 연구원의 홍보와 이미지도 한층 개선해 나갈 계획을 갖고 있습니다. 
</p>
<p style="padding-left:1.2em">  이어서 연구사업의 주요계획은 경기도학술연구용역계획을 연구원에서 최대한 기본연구과제로 수행하기 위하여 경기도와 사전검토 및 연석회의를 거쳐서 기본연구과제를 심도있게 논의해서 선정하였고 실적과 진도관리를 통해서 중간평가개념을 도입하고자 합니다.  또한 수탁연구과제는 무엇보다 경기도정을 시의적절하게 지원하는데 큰 차질이 없는 범위내에서 연구위원회에서 수행여부를 심도있게 논의하여 결정하고 정책과제를 상대적으로 강화해 나갈 계획입니다. 
</p>
<p style="padding-left:1.2em">  교육포럼, 남북포럼, 동북아학술포럼, 사회포럼 등 4개의 포럼을 더욱 내실 있게 추진하여 우리 도정의 일관성을 유지할 계획입니다.  한편 통합정보시스템의 효율적인 운영을 통해 각 연구자의 연구실적을 효율적으로 관리하고 지리정보시스템 운영으로 적극적인 연구를 지원하고 연구원 홍보와 위상강화를 위한 개원 10주년 기념사업 등을 추진할 계획입니다.  이 밖에도 우수연구인력을 적극적으로 확충하고 도정 전반에 대한 대응체계를 확립하고 국정 현안과제 등 효율적인 수행을 위해 탄력적인 TF팀을 계속 운영해 나가도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  26페이지부터 27페이지까지 세부추진계획입니다.  우선 도정과 밀착된 연구수행을 위해서 지방재정조정제도 변화에 따른 합리적인 재원조정방안을 수립하고 경기도내 주차장법 관련 조례개정안 등을 마련하며 도정 주요시책을 즉시 지원하는 시스템 구축을 위해서 정책개발센터 내에 국가균형발전, 미군기지 이전, 동북아 협력, 대중교통개선 TF팀을 운영하면서 상시 도정아이디어를 제공하기 위해서 교육과 남북ㆍ동북아포럼을 운영토록 하겠습니다.
</p>
<p style="padding-left:1.2em">  지속가능한 경기도를 위한 총체적인 접근을 위해서 수도권의 효율적인 정책집행을 위한 정보인프라를 구축하고 효과적인 하천유지관리방안 등을 제시하고자 하면서 도민의 삶의 질 개선을 위한 도정현안 지원을 위해 오존경보제 개선방안을 수립하고 기성시가지 정비계획, 공동주택관리체계 개선안 등을 마련토록 하겠습니다.  그리고 앞서가는 도정을 위한 정책개발과 정책전환 유도를 위해서 경기도 첨단행정신도시 택지개발사업의 이미지 설정 및 조성관리방안을 수립하고 경기도 교육지원사업의 평가와 발전방향 등을 연구해 나가도록 하겠습니다.  경제살리기와 지역경쟁력의 강화를 위해서 경기북부 산업클러스터 육성방안을 수립하고 주5일 근무제에 대비한 사회적 교육인프라 등을 구축해 나가도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  다음 28페이지 연구과제별 연구사업계획 총괄표는 유인물을 참조해 주시기 바랍니다.  다음은 29페이지 기본연구과제 추진계획입니다.  기본연구과제는 추천 및 제안된 연구과제를 경기도와 사전검토를 통해서 선정된 26개 과제를 수행할 계획입니다.  협의 및 반영과제 현황과 부서별 세부추진계획은 30페이지부터 43페이지까지 유인물로 갈음해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 44페이지 수탁연구과제 추진계획입니다.  수탁연구과제는 전년도에서 이월된 과제를 포함해서 내년도 신규 수탁연구과제를 부서당 10건 내외인 모두 50건의 과제를 수행할 예정입니다. 
</p>
<p style="padding-left:1.2em">  다음 45페이지 정책연구과제입니다.  정책연구과제는 경기도로부터 긴급 요청되는 시의성있는 과제와 또 연구원에서 자체적으로 판단해서 중요하다고 생각되는 자체 추진과제 등 총 59건의 과제를 수행할 계획입니다. 
</p>
<p style="padding-left:1.2em">  다음 46페이지 위탁 및 지역연구과제 추진계획입니다.  위탁연구과제는 학ㆍ연 네트워크협정대학 등과의 공동연구 8건의 아웃소싱을 통해서 연구원 외부의 노하우를 활용할 계획이고 지역연구과제는 특정현안이 발생하고 있는 경기도내 시와 군을 대상으로 6개월에 1건씩 모두 2건을 추진할 예정입니다. 
</p>
<p style="padding-left:1.2em">  다음 47페이지 정기간행물 발간사업입니다.  정기간행물은 올해와 같이 경기논단을 4회, GRI 뉴스레터를 매월 1회씩 12회, 경기도 경제동향과 전망 12회를 발간할 계획입니다. 
</p>
<p style="padding-left:1.2em">  다음 48페이지부터 50페이지까지는 연구조성사업 계획입니다.  번역사업은 경기도정에 도움이 될 수 있는 최신 외국도서 2종을 번역하여 배포할 계획이고 당면문제 및 학술적 성격의 대내외적인 여론선도를 위해서 모두 15회의 정책세미나와 워크숍 등을 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  49페이지 정책포럼은 기이 보고드린 바와 같이 남북, 교육, 사회, 동북아포럼입니다.  관ㆍ연 협력체계인 시ㆍ군 담당 연구원들을 보다 실질적으로 활성화하여 운영토록 하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 50페이지 연구결과를 토대로 도정의 핫이슈(Hot issue)에 대해 경기도 공보관실과의 협의를 통해 선정한 홍보계획을 추진하고 개원 10주년 기념사업으로 백서를 발간하고 영상물을 제작하고 기념세미나 등을 유치할 계획입니다.  특히 개원10주년 기념사업을 추진하는데 있어서는 기획위원님들의 적극적인 지도와 편달을 바라는 바입니다.
</p>
<p style="padding-left:1.2em">  마지막으로 51페이지부터 52페이지까지 2003년도 행정사무감사 처리요구사항에 대한 조치결과입니다.  2003년도 11월 26일 행정사무감사시 처리요구사항은 모두 3건이었고 현재 2건은 완료되었으며 시ㆍ군 담당연구원제 활성화 1건은 계속 진행되고 있는데 내년에는 관ㆍ연 협력체계가 보다 실효성있고 활성화될 수 있도록 노력하겠습니다.  구체적인 조치결과는 배부해 드린 유인물로 갈음토록 하겠습니다.  이상으로 2004년도 주요업무보고를 모두 마치겠습니다.  감사합니다.
</p>
<p><br /></p>
<p>(업무보고서는 끝에 실음)
</p>
<p><br /></p>
<p><b>○ 위원장 정인영 </b> 한현규 경기개발연구원장 수고하셨습니다.  다음은 질의ㆍ답변순서가 되겠습니다.  감사의 원활한 진행을 위해 질의ㆍ답변은 일문일답식으로 진행을 하도록 하겠습니다.  질의에 앞서 위원장으로서 한 가지 부탁의 말씀을 드리겠습니다.  위원님들의 질의사항 중 원장의 답변이 어려울 경우 담당 실장 및 부장인 실무자가 답변을 해도 좋습니다.  다만 사전에 위원장에게 동의를 얻은 후 발언대로 나와서 소속과 직, 성명을 분명히 밝히고 답변을 해주시기 바랍니다.  그러면 질의하실 위원께서는 거수로 신청하여 주시기 바랍니다.  김대원 위원 질의하여 주시기 바랍니다.
</p>
<p><b>○ 김대원 위원 </b> 감사준비에 만전을 기해 주신 경기개발연구원 원장이하 모든 직원 여러분들께 감사를 드리고요.  더군다나 연일 되는 감사에서 상당히 노고가 있습니다마는 오늘 감사준비를 위해서 더더욱 힘드신 위원님들에게도 같이 고맙다는 말씀을 드립니다.  이런 실질적인 감사라기보다 제가 우선 하는 발언은 질의의 성격이 되겠습니다.  경기개발연구원의 임원이 이사 18명, 감사 2명으로 구성돼 있죠?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그렇습니다.
</p>
<p><b>○ 김대원 위원 </b> 그런데 당연직이 7명이고 선임직이 나머지 13명이죠?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그렇습니다. 
</p>
<p><b>○ 김대원 위원 </b> 선임직 임용일자를 보면 2002년 2월 6일입니다.  그런데 당연직은 이사장이 손학규 지사, 연구원장, 기획위원장, 기획관리실장 등 선출직입니다.  그래서 선출직이 이사장으로 있었을 때 보면 이분들의 임기는 2002년 7월 1일부로 시작된 걸로 알고 있습니다.  2002년 7월 1일이 맞죠?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그렇습니다.
</p>
<p><b>○ 김대원 위원 </b> 그런데 선임직을 보면 2002년 2월 6일입니다.  그래서 어떤 부작용이 생겼냐면 그때 선임직 중에 아마 경기개발연구원에 출자를 한 지방 기초자치단체도 포함되는 걸로 알고 있습니다.  그래서 단체장 중에 일부를 이사로 선임했는데 이분들도 마찬가지로 결과적으로는 기초자치단체에서 선출직입니다.  그래서 2월 6일 선임을 받고 나서 7월 1일부로 선출직에서는 상실된 분들입니다.  그런데 이분들로 이사를 선임했으니까 결과적으로 이사 중에서는 전 파주시장, 전 의왕시장 등 이런 분들은 7월 1일부로 실질적으로 자격상실자거든요.  그런데 현재까지 임용기간이 3년간이니까 실질적으로 비합리적인 부분으로써 이분들이 자기가 이미 선거를 통해서 자격을 상실한 입장에서 여기 이사로서 무슨 발언을 하겠습니까?  그래서 이런 제도적인 장치를 좀 보완해 주시기를 요구하고요.  이것은 아마 내부규약으로서 충분히 가능할 부분인데, 더군다나 연구를 목적으로 하는 경기개발연구원에서 이런 불합리한 제도에 대해서는 내부규약을 개선해서라도 현실성 있는 이사를 구성해서 경기개발연구원 발전에 도움이 될 수 있도록 선임해 주시기를 당부드립니다.  가능하시겠습니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 정말 죄송합니다.  오늘 지적해 주셨길래 망정이지 엊그제 이사회를 개최했습니다마는 저도 이사회를 개최하면서 이 부분을 미처 파악을 못했습니다.  최대한 빠른 시일내에 조치를 하겠습니다.
</p>
<p><b>○ 김대원 위원 </b> 그래서 이사회 얘기가 기왕에 나왔으니까 하는 얘기인데 이사회가 꼭 나쁘게 말하면 어용입니다.  이런 분들이 뭔 얘기를 하시겠습니까?  더군다나 이번에 한 부분이 기구개편인데 작년까지의 기구를 대비해 보면 처나 부는 얘기를 안 하겠습니다마는 분명히 지금까지 부원장제도가 있었습니다.  8년간 부원장제도가 있었는데 항상 결원을 시켜 놓은 상태에서 자문위원을 거의 편제해 만들어서 기구를 개편했습니다.  그러니까 이런 이사들로 구성된 이사회에서 결정된 사항을 어떻게 국민들이 인정을 하겠습니까?
</p>
<p style="padding-left:1.2em">  그리고 임용에 관한 자료요청한 걸 보면 자료 107페이지입니다.  임용방법은 공개채용 및 특별채용으로써 연구원에 한한 건지 모르겠습니다마는 모집공고를 하고 서류전형 1, 2단계를 하고 논문발표 및 심사를 해서 거기서 1차 합격자를 선발하고 이사장 승인을 받아서 최종 합격자로 발표하게 돼 있습니다.  그런데 내용은 충분히 압니다마는 자문위원으로 선임되신 분의 능력과 자질은 경기개발연구원에 충분한 도움이 되리라는 부분을 인정하는 전제하에서 가능합니다마는 이런 이사진에서 추천된 부분에 대해서는 분명히 문제가 있다고 지적할 수밖에 없습니다.  그리고 존경하는 박영신 위원님께서 요청한 자료 104페이지를 보면 급여관련 부분이 있습니다.  책임연구원, 최고 연봉이 연 5,000만원을 넘지 못합니다.  우리 연구기관에 관장하시는 최고 연구원이 연봉 5,000만원을 넘지 못하는 부분인데 이게 현실입니다.  그런데 관리직 자문위원을 둠으로써 이런 책임연구원 몇 명을 더 두는 부분에 대한 예산의 소요가 예상됩니다.  그래서 모든 게 경영평가적인 차원으로 봤을 때 한 분이 열 분 이상의 몫을 충분히 하리라는 전제를 두고 말씀드립니다마는 객관적인 입장으로 봤을 때 실제 성과물을 만들어내는 연구원보다 관리직은 최소화해야 되고 설립목적에 맞는 연구부분을 집중적으로 육성해야 된다는 데 뜻이 있습니다.  원장님 생각은 어떠십니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 김대원 위원님 말씀 구구절절 옳으십니다.  다만 제가 아까 업무보고 때 말씀드렸습니다마는 지난번에 저희가 상임자문위원을 채용한 것은 우리 연구원과 도정에 상당한 특수상황이 있었습니다.  그 부분에 대해서 오늘 위원장님께서 지난번 이사회 때도 참석해 주셔서 위인설관 아니냐 그런 말씀까지 하실 정도로 강력한 이의를 제기하셨습니다마는 저도 솔직히 그랬습니다.  위인설관 맞습니다.  그럼에도 불구하고 저희가 이수영 상임자문위원을 영입한 것은 그분이 저희 연구원이 5개월동안 공석일 때 그래도 연구원을 끌고 나가신 성과와 함께 또 이수영 상임자문위원이 갖고 있는 개인적으로 풍부한 경험 이런 것들을 연구원에 적극 반영하는 것이 구체적인 연구성과를 거두는 것보다 더 중요한 일이 아닐까 해서 조금 어떻게 생각하면 저희가 예외적인 경우를 인정했습니다.  널리 양해해 주시면 고맙겠습니다.
</p>
<p><b>○ 김대원 위원 </b> 그 내용을 저희들도 충분히 이해를 합니다.  그런데 과연 기구까지 개편해서 부원장제도를 없애버리고 자문위원이라는 빈칸을 만들어서 집어넣을 만한 그런 중대 사안이냐는 얘기죠.  더군다나 문제가 있는 이사들을 동원해서 그런 이사회에서 이런 기구까지 개편해서 한다는 것은 문제가 있고 분명히 부원장제도가 있었는데 필요하시다면 굳이 자리가 명칭이 문제가 아니라고 생각합니다.  본 위원 입장에서는.  과연 경기개발연구원을 위해서 봉사해 주시겠다면 자리가 무슨 문제겠습니까.  그냥 외곽에서도 충분히 도와주실 수도 있고 더군다나 기왕 부원장제도가 있었는데 그 부원장제도를 활용해서라도 충분히 소화하고 연구원을 도와주실 수 있었던 부분이라고 생각을 합니다.  그런데 자문위원이라는 제도를 다시 만들어서 넣는다는 것은 문제가 있고요.  그리고 또 더더욱 전임 원장님이시라든가 경기개발연구원에 엄청난 도움을 줄 수 있는 그런 인사들은 많다고 생각합니다.  그런 분들을 다 자문위원으로 추대하실 것 같으면 이 제도의 발로로 앞으로 훨씬 더 많이 늘어나야 될 겁니다.  기왕이면 이사회를 운영하셔서 기구를 개편할 게 아니라 그 기구내에 포함시켜서 운영하시는 게 바람하지 않느냐는 부분입니다.  그 부분은 일단락 하겠습니다.
</p>
<p style="padding-left:1.2em">  그리고 제가 기왕에 먼저 질의를 시작했으니까 제 사안도 말씀을 드리겠습니다.  보고서 22쪽에 보면 정책세미나 부분이 있습니다.  그래서 지금 경기도의 캐치프레이즈가 세계 속의 경기도이고 기업하기 좋은 경기도 만들기가 우리 경기도의 도정방침이라고 할 수 있습니다.  그래서 그에 걸맞게 우리 경기개발연구원에서 4월 2일 기업하기 좋은 경기도 만들기 토론회를 했었고 4월 26일 기업하기 좋은 환경조성을 위한 대토론회를 했습니다.  그런데 본 위원이 알고 있기로는 2004년 4월 2일 기업하기 좋은 경기도 만들기 토론회는 경기개발연구원에서 경기발전위원회 위원들을 모시고 한 걸로 알고 있습니다.  맞습니까?  잘 모르시면 다른 연구원이 답변하셔도 좋습니다.
</p>
<p><b>○ 대외협력팀장 이용원 </b> 대외협력팀장 이용원입니다.  4월 2일은 경기발전위원회가 주최한 세미나 맞습니다.
</p>
<p><b>○ 김대원 위원 </b> 그리고 4월 26일은 경기문화의전당에서 대토론회를 가졌었죠?
</p>
<p><b>○ 대외협력팀장 이용원 </b> 네, 맞습니다.
</p>
<p><b>○ 김대원 위원 </b> 이것은 주체가 누구였었죠?
</p>
<p><b>○ 대외협력팀장 이용원 </b> 이것은 경기도 정책기획관실에서 경기도 시ㆍ군의 공무원을 대상으로 했던 겁니다.
</p>
<p><b>○ 김대원 위원 </b> 그런데 여기 경기개발연구원에서 같은 부분으로 정책세미나를 하신 걸로 보고서에 만들어져 있지 않습니까?
</p>
<p><b>○ 대외협력팀장 이용원 </b> 경기도에서 이렇게 하는 행사들도 저희가 도정지원 차원에서 하고 있습니다.
</p>
<p><b>○ 김대원 위원 </b> 왜 제가 이런 말씀을 드리냐면요.  첫 번째 발의자가 상당히 중요합니다.  기업하기 좋은 환경 만들기를 위한 토론회를 가졌으면 그 토론회 처음 시작한 주체가 경기발전위원회라고 봤을 때 경기발전위원회 명단 가지고 계시죠?
</p>
<p><b>○ 대외협력팀장 이용원 </b> 네, 가지고 있습니다.
</p>
<p><b>○ 김대원 위원 </b> 경기발전위원회가 남덕우 전 부총리를 비롯한 대형 거물급 인사들로 거의 구성이 돼 있죠? 
</p>
<p><b>○ 대외협력팀장 이용원 </b> 네, 그렇습니다.
</p>
<p><b>○ 김대원 위원 </b> 그리고 선임직 이사분도 여기 포함돼 있죠?
</p>
<p><b>○ 대외협력팀장 이용원 </b> 네, 그렇습니다.
</p>
<p><b>○ 김대원 위원 </b> 제가 그날 4월 26일 대토론회에 토론자로 참석을 했었습니다.  그런데 그때 참석자들 중에 경기발전위원회 위원들께서 한 분도 참석을 안 했습니다.  용두사미에요.  이렇게 토론회를 만들고 여기서 이슈를 만들었으면 나중에 결과를 보셔야지.  4월 2일 여기서 기업하기 좋은 토론회를 갖고 나서 그 다음에 그게 발전돼서 대토론회로 됐으면 주체가 나오셔서 당연히 그 토론회를 주관하시고 그 중간에 주제발표라든가 토론을 해야 되는데 이분들이 참석을 안 했습니다.  그 내용은 아시죠?
</p>
<p><b>○ 대외협력팀장 이용원 </b> 네, 알고 있습니다.
</p>
<p><b>○ 김대원 위원 </b> 심지어는 거기 토론자로 참석하시기로 한 분이 대리토론자를 내보냈습니다.  내용 알고 계시죠?
</p>
<p><b>○ 대외협력팀장 이용원 </b> 그것은 지금 제가 자세하게 파악을 못하고 있습니다.
</p>
<p><b>○ 김대원 위원 </b> 아니, 여기 선임이사직 중에 계시는 분이에요.  경기발전위원회에도 소속돼 있고 더군다나 그분이 경제단체연합회장님이에요.  기업하기 좋은 여건조성을 하기 위해서는 기업체가 더 적극적으로 나서야 되는 것 아닙니까?  평양감사도 자기 싫으면 마는 것인데 주고 싶은 사람이 아무리 주고 싶어도 받을 사람이 받을 준비가 돼 있어야 주는 것이죠.  그래서 기업과 관이 합심해서 이루어냈을 때 기업하기 좋은 환경도 만들어지고 세계 속의 경기도도 만들어 지는 것이고 국가경쟁력도 제고되는 것이지 본인들이 참석을 안 하는 이런 부분은 하지 마시라는 얘기예요.  기왕에 경기개발연구원이 주최해서 기업하기 좋은 환경조성을 위한 발언을 시작했으면 끝까지 결과도 주관하셔야 된다고 생각합니다.  어떻게 생각하세요?
</p>
<p><b>○ 대외협력팀장 이용원 </b> 앞으로는 좀더 정책대안이 효과적으로 도출될 수 있는 세미나라든지 행사가 진행될 수 있도록 노력하겠습니다.
</p>
<p><b>○ 김대원 위원 </b> 그래서 본 위원이 보니까 12월 7일부터 12월 8일까지 다시 또 토론회를 한다고 그랬는데 이때 한번 지켜보겠습니다.  도대체 어떤 부분으로, 지금 두 번 토론회를 하고 더군다나 정책세미나를 여기 업무보고에 세 번까지 집어 넣어놨는데 같은 사안을, 이때 한번 지켜보겠습니다.  어떤 방법으로 하는 건지.  그리고 이런 토론회를 했으면 토론결과물을 만들어서 제출해 주시고요.  그리고 제가 알기로는 토론회에 나온 말들이 전부 규제입니다.  규제 때문에 못해 먹겠다는 얘기예요.  그래서 규제를 풀자 라는 게 그 토론회의 총 목적입니다.  그런데 규제가 아시다시피 법으로 정해진 규제가 있고 또 운영하는 사람에 의해서 이루어지는 규제가 있습니다.  그래서 경기도 감사관실에서도 왜 안 해주는가 라는 책자까지 만들어 냈습니다.  옛날에는 해주면 문제 삼겠다는 것이 많았었는데 이제는 안 해주면 문제 삼겠다는 그런 부분이 인력으로서 할 수 있는 것들은 개선해 나가자는 게 목적입니다.  그리고 법으로 규제된 부분은 경기개발연구원에서 충분히 연구과제를 통해서 발췌하셔서 법을 개정해야 될 사항은 정책대안을 내주셔야 된다는 얘기입니다.  경기개발연구원의 목적이 거기에 더 맞는다고 생각을 합니다.  어떻게 생각하세요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 제가 답변드릴 사항인 것 같습니다.  김대원 위원님 말씀 경청해서 잘 들었습니다.  우선 위원회와 관련된 것은 제가 오기 전이라고 책임을 면하고 싶은 생각은 없습니다마는 경기발전위원회가 좀더 실질적인 참여를 안한 것에 대해서 송구스럽게 생각을 합니다.  그러지 않도록 하겠습니다.  그리고 내일모레 하는 기업하기 좋은 경기도 만들기 토론회는 감사관실과 함께 하는 토론회인데 김 위원님 기대에 어긋나지 않도록 내실있고 실효성 있는 그런 토론회가 되도록 최선을 다하겠습니다.  규제와 관련된 부분은 위원님 말씀하신 바처럼 우리 경기개발연구원의 가장 중요한 업무, 거의 고유업무라고 해도 과언이 아닐 것입니다.  특히 수도권정비계획으로 대표되는 수도권 관련규제를 철폐하고 대체입법을 하는데 저희가 여러 가지 연구를 하고 있고 또 여러 가지 경로를 통해서 대외적으로 홍보하고 중앙부처에 항의도 하고 아이디어도 내고 하는 역할을 수행하고 있습니다.  지금까지는 커다란 성과를 거두지는 못했습니다마는 이것은 오늘 내일의 성과에 관계없이 경기도가 존재하는 한 수도권정비계획이 사라지지 않는 한 저희가 혼신의 힘을 다해서 노력할 대상이라고 봅니다.  앞으로 더욱 노력을 하겠습니다.
</p>
<p><b>○ 김대원 위원 </b> 경기개발연구원의 역량을 충분히 믿고요.  저희들도 동 시대에 같은 세대를 사는, 저희들도 선출직입니다.  같이 책임지는 자세로 임할 테니까, 저희들이 이렇게 감사를 합니다마는 감사가 꼭 지적하기 위한 감사가 아니라 더 나은 방향으로 발전하기 위한 이런 대안의 자료도 될 수 있다고 생각합니다.  그래서 진솔하게 답변해 주셔서 고맙고요.  또 정말로 오늘 이런 감사가 구호에만 그치고 입으로만 왔다 가지 않는 그런 감사가 되기를 빌겠습니다.  꼭 그런 고유목적대로 운영돼서 경기도 발전에 도움이 되는 경기개발연구원이 되시길 빌겠습니다.  이상입니다.
</p>
<p><b>○ 위원장 정인영 </b> 김대원 위원 수고하셨습니다.  다음 질의하실 위원께서는 거수로 신청해 주시기 바랍니다.  이효선 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이효선 위원 </b> 광명출신 이효선입니다.   104쪽에 보면 관리직 임금체계가 나옵니다.  일반 직원들이 연구지원수당이라는 항목으로 지급이 되거든요.  여기에 대한 답변 부탁합니다.  원장님이 아니라도 좋습니다.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 이 부분은 조금 기술적인 분야 같아서 우리 행정과장이 답변토록 하겠습니다.
</p>
<p><b>○ 행정과장 김영수 </b> 행정과장 김영수입니다.  연구지원수당은 관리직에 대한 지급수당이 맞습니다.  그리고 이것은 저희 수당규정에 정해진 기준에 의해서 지급하고 있습니다.
</p>
<p><b>○ 이효선 위원 </b> 김영수 과장님 연구하세요?
</p>
<p><b>○ 행정과장 김영수 </b> 연구직은 연구수당이 따로 있고요.  이것은 연구지원수당이라고 해서 만들어 놓은 겁니다.
</p>
<p><b>○ 이효선 위원 </b> 제가 지적하는 사항은요.  김영수 과장님부터 관리직들은 연구를 하지 않습니다.  항목변경을 해달라는 겁니다.  차라리 직책수당으로 바꿔주시고, 연구지원을 어떻게 하는지 몰라도 항목변경을 요청합니다.  내년에 감사할 때는 이 항목이 없어지길 바랍니다. 
</p>
<p><b>○ 행정과장 김영수 </b> 네, 알겠습니다.
</p>
<p><b>○ 이효선 위원 </b> 107쪽에 보면 올해 9명의 인원이 보충된 걸로 알고 있습니다.  이번에 9명 임용된 분들의 출신도별 분포가 설명되겠습니까?
</p>
<p><b>○ 행정과장 김영수 </b> 지금 저희가 출신도별로는 가지고 있지 않습니다.  기다리시면 자료를 해드리겠습니다.
</p>
<p><b>○ 이효선 위원 </b> 자료가 필요한 것이 아니라 원장님께 부탁은 우리가 분권, 통합 이런 얘기를 많이 합니다.  단 1명을 뽑든 9명을 뽑든 몇 명을 뽑든간에 각 도출신의 유능한 사람들을 뽑아서 경기도가 통합의 정책, 연구소 자체가 통합하는 모습을 대외적으로 알릴 수 있는 기회라고 봅니다.  학연, 지연에 의해서 뽑는 것보다 각 출신 도별로 유능한 연구원을 뽑아서 경기도가 인사정책까지도 연구원의 손님기준도 그러한 평등과, 평등이라는 것은 기회의 평등을 얘기하는 겁니다.  요즘 평등 얘기를 많이 하는데 민주주의라고 평등을 주자는 것이 아니라 기회의 평등을 줘야 된다.  민주주의와 자본주의는 차별의 시대입니다.  차별이 민주주의라고 저는 봅니다.  능력있는 자가 대우받는 사회 그것이 진정한 자본주의 체계라고 봅니다.  하지만 기회의 평등을 줘야 됩니다.  부모를 잘못 만났다고 해서 공부를 못한다거나 내가 경상도, 전라도 출신이라고 해서 경기개발연구원에 와서 연구하고 싶은데 못한다는 것은 잘못된 것이니까 그런 것을 염두에 두시고 인사정책에 쓰시기 바랍니다.
</p>
<p style="padding-left:1.2em">  331쪽에 보면 임직원 해외연수실적에 대해서 자료가 있습니다.  본인이 작년 감사 때 원장 외 몇 명이 가면 공무원 출장기준에 의해서 과다한 지급이 됐다는 지적을 했습니다.  그것을 고쳤습니까, 김영수 과장님?
</p>
<p><b>○ 행정과장 김영수 </b> 행정과장 김영수입니다.  네, 고쳤습니다.
</p>
<p><b>○ 이효선 위원 </b> 고쳤습니까?
</p>
<p><b>○ 행정과장 김영수 </b> 네.
</p>
<p><b>○ 이효선 위원 </b> 그 자료를 나중에 주시고요.  기준표를 나중에 저한테 개인적으로 주시기 바랍니다.
</p>
<p><b>○ 행정과장 김영수 </b> 네, 알겠습니다.
</p>
<p><b>○ 이효선 위원 </b> 주요업무보고서 8쪽에 보면 연구사업 실적이 나옵니다.  제도개선, 국가균형발전, 동북아 경제중심, 도정이슈에 대해서 여러 가지가 나옵니다.  요즘 몇 달간에 핫이슈로 떠오르는 경기분도 문제에 대해서는 준비하신 것이나 연구실적이 있습니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 네, 있습니다.
</p>
<p><b>○ 이효선 위원 </b> 대안이 뭡니까?  결론이.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 분도가 바람직하지 않다고 하는 연구결과가 나왔습니다.  그런데 사실은 좀더 솔직히 말씀드리면 저희가 그 연구를 작년에 시작해 가지고 금년 1월에 3개월간 연구과제를 통해서 분도가 바람직하지 않다.  국내외 사례, 여러 가지 득보다는 실이 많다는 그런 논리적인 결과를 냈습니다마는 그 당시의 상황이 오히려 그것을 출간하면 오히려 분도 논의에 불이 붙고 또 이것이 정치적으로 이용되지 않을까 하는 우려에서 그 당시에 출간하지 않고 저희가 가지고 있었습니다.  그런데 최근에 정치권에서 분도 논의가 일고 있고 저희가 공식적으로 이것을 대응해야 되겠다는 그런 차원에서 이미 연구결과가 거의 1년 전에 나온 것이기 때문에 그걸 지금 수정하고 있습니다.  새로운 상황에 따라서 다시 한 번 분도 논의를 객관적으로 짚어보고 조만간 빠른 시일내에 저희가 그것을 공포하겠습니다.  그래서 그것을 지금 현재는 대외비로 가지고 있습니다마는 앞으로는 그걸 풀어서 일반에게 공개하고 저희들의 논리를 적극적으로 펼쳐나갈 그런 계획으로 있습니다.
</p>
<p><b>○ 이효선 위원 </b> 도정이슈 중에 핫이슈가 지금 분도문제입니다.  제가 늘 인용하는 공자 말씀 중에 ''시즉동이다'' 움직이는 데는 시기를 놓치면 아무 필요가 없습니다.  이것이 감춰지고 몇 사람의 헤드들만 알고 있는 자료는 그런 연구는 할 필요가 없습니다.  그것이 사적에서나 공적에서나 공유됐을 때 가치가 있는 것입니다.  분도를 하면 이러이런 불이익이 있고 이런 문제점이 있다는 것보다 그런 어떠한 논리라도 한 쪽 일부의 불만과 이해를 못하는 부분이 있다면 그것은 극소화시켜야 될 문제가 있습니다.  사회포럼이 있는데 올해 사회포럼한 적 있습니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 사회포럼을 저희가 지금 형성을 인선정도만 해놓고 있고 아직 열어본 적이 없습니다.  곧 본격적으로 가동하려고 합니다.
</p>
<p><b>○ 이효선 위원 </b> 원장님이 올해 취임하셔서 모르는 것 같은데요.  작년에는 서울대학의 송 교수를 좌장교수로 해서 사회포럼이 한 번 있은 적이 있습니다.  올해는 안 했습니다.  이 사회포럼의 사회는 도대체 어떤 것을 얘기하는지 모르지만 지금 정권의 최대이슈인 수도권 이전, 경기도의 핫이슈인 분도문제에 대해서 사회학자와 여러 사람이 모여서 하는 그런 포럼이 시기를 놓치고 있다는 겁니다.  80억원의 예산을 들여서 운영되고 있는 2004년도 경기개발연구원의 문제점은 거기 있습니다.  항상 시기를 놓쳐요.  그래서 그런 것들을 말씀드리고요.  조만간에 빨리 12월 중에라도 사회포럼이 열려서 이런 문제들의 대응방법에 대해서 논의해야 될 것 같습니다.
</p>
<p style="padding-left:1.2em">  제가 22일 월요일에 정책기획관실 감사하면서 분도에 대한 대안으로 경기도특별도법 입법추진을 요구한 적이 있습니다.  어느 지역이 아닌 상대적 빈곤감에 대한 탈출, 긍지와 자부, 정체성에 대한 확립을 위해서는 경기도특별도가 필요하다는 본인의 몇 달에 걸친 생각과 행정학 교수들과의 토론에서 나온 결론이었습니다.  거기에 대해서 입법추진에 대한 방법과 분도에 대한 논리개발을 여기 행정을 전공하신 분이 계시면 일주일 정도의 시간을 드릴 테니까 거기에 대한 자료를 저한테 제출해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  저는 이렇게 생각합니다.  우리가 국회의원을 보면 비례대표가 있고 지역대표가 있습니다.  비례대표는 전문성을 갖고 국가정책을 논한다면 지역구 국회의원은 그 지역의 아픔과 그 땅을 사랑하는 마음으로서 척박한 땅을 기름진 가나안땅으로 만들려는 애착과 애정이 출발점이라고 생각합니다.  경기개발연구원에 계신 연구원들은 경기도를 사랑하며 경기도 발전을 위해서는 온 몸을 올인 할 수 있는 자세가 되어야만 진정한 연구결과가 나온다고 생각합니다.  수도이전과 분도에 대한 대응전략에서 경기개발연구원의 전략은 빵점이었습니다.  지금 R&D가 기업의 장래를 책임지고 있습니다.  대기업들은 총매출액의 5∼10%의 R&D 비용을 씁니다.  경기도는 교육예산을 빼고도 9조원, 10조원이라는 예산을 씁니다.  그런데 내년예산에 경기개발연구원이 100억원을 올렸습니다.  상당히 빈곤하고 어쩔 수 없는 투자같이 본 위원 눈에는 보입니다.  연구원장의 의지와 뜻을 담아서 아무리 경기도의 예산이 몇 천억원 줄더라도 기업의 R&D로 비교될 수 있는 경기개발연구원의 예산을 몇 십억원 증액해서 많은 인원을, 유능한 분들을 모시고 경기도 발전을 위해서 일할 수 있는 기회가 됐으면 좋겠습니다.  원장님, 그런 의지 있으십니까? 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 전적으로 동감합니다.  아직 발표는 안 된 것으로 알고 있습니다만 저희가 얼마 전에 마친 연구결과 중에 하나가 경기도의 기업과 관련된 수도권규제를 풀면 연간 15조원의 생산액이 더 늘어날 수 있다는 연구결과를 저희가 가지고 있습니다.  아직 언론에 공포를 안 하고 그것을 가지고 디베이트(debate)를 안 했습니다만 15조원, 연간 15조원이 아마 우리나라 1년 성장률의 2.7% 정도를 더 기여할 수 있는 건데, 이런 것을 위해서 저희 경기개발연구원은 어떠한 노력을 해도 충분하지 못하다고 생각합니다.  저희가 혼신의 노력을 다해서, 아까 기업의 R&D 말씀하셨습니다만 저는 수도권과 경기도에 관련된 여러 가지 규제나 정책이나 사람들의 비뚤어진 인식이라든가 이런 것을 바꾸는데 경기개발연구원은 몸과 마음을 다 바쳐도 모자라다는 생각을 하고 있습니다.  그런 의미에서 혼신의 노력을 하겠습니다. 
</p>
<p><b>○ 이효선 위원 </b> 내년 1차 추경에라도 추가비용을 요청해서 유능하고 경기도가 필요한 연구원들을 모셔서, 많은 인원을 채용해서 진짜 태스크포스팀이라는 팀을 만들어서 장기적 계획을 가지고 1년이나 2년, 손학규 지사의 임기가 끝나는 그날까지 중ㆍ장기 계획을 세워서라도 큰 프로젝트를 하는 그런 연구원이 됐으면 좋겠습니다.
</p>
<p style="padding-left:1.2em">  그리고 남북포럼이 올해 5월과 9월에 열린 것으로 알고 있습니다.  특히 5월은 4월 평양방문 이후에 있었던 포럼입니다.  저 개인은 당시 남북교류협력위원장으로서 남북포럼에 패널로 가끔 참석을 했습니다.  이게 독선입니까, 아니면 도의원 무시입니까?  경기개발연구원에서 주관이 돼서 남북교류와 경제협력이 이루어졌습니다.  4월에 일주일간 같이 북한도 다녀왔습니다.  이번에 새로 채용한 최용환 박사와 김동성 박사가 동행했던 도의원 2명, 경기개발연구원 2명, 공무원 2명, 우리민족서로돕기 1명에 7명의 방북단이 갔다왔습니다.  그후에 있은 5월, 9월 남북포럼에 도의회나 해당 경기도의회 기획위원회에 통보도 하지 않고 한 이유는 뭡니까?  여기에 대한 답변 부탁합니다.  담당하시는 박사님이 얘기해 주시기 바랍니다.  이런 것들이 잘못된 겁니다.  우리가 경기개발연구원 돈으로 북한 갖다 줬습니까?  만나서 얘기하고 떠들고 자료 몇 개 만들어내는 게 포럼의 목적입니까?  손학규 지사 출범이후 2년 동안 남북포럼과 그러한 결과물로 4월에 북한을 다녀왔습니다.  14억원 정도 되는 돈을 우리가 도장을 찍고 사인하면서 남북교류가 어느 정도 이루어졌습니다.  그 이후 포럼에 왜 여러분들만 합니까?  여러분들이 돈 냈어요?  경기개발연구원이 모든 것을 독점하고 독선해도 되는 겁니까?  경기도남북교류위원회도 있고, 경기도에 남북교류협력위원회가 있고 여기 앉아 있는 본인은 남북포럼에 가끔 패널로 참석도 했습니다.  이러한 자그마한 것들이 여러분의 자세라고 저는 생각합니다.  여러분의 정보를 공유하고 200억원에 달하는 남북교류기금을 쓰는데 있어서 같이 노력해야 됨에도 불구하고 자기들의 돈도 아니면서 자기들은 말로, 지식으로만 참여하는 사람으로서 북한에 갔다왔는데도 불구하고 그것이 적절하게 인적교류나 물자지원이 되지도 않는 상태에서 여러분들만 5월, 9월에 포럼하면 뭐 생기는 것 있어요?  왜 통보 안 합니까?  이런 식의 자세가 이번에 제주도 세미나에서 어느 분이 "우리 예산 많으니까 좀 깎아라"라는 농담 섞인, 언중유골 같은 얘기를 들으면서 가슴이 아팠습니다.  애사심도 없고 책임감도 없고, 그러지 마시기 바랍니다.  여러분 돈으로, 여러분 월급으로 남북교류하는 거 아닙니다.  남북통일을 동서독의 통일과 비유하는 그런 학자 데려다가 돈 주고 포럼하는 것, 생각이 다 틀리겠지만 그런 것은 지양해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  지난 4, 5개월 동안 경기개발연구원장님의 공백기간이 있었습니다.  그리고 지금 평소 존경하는 한현규 원장께서 부임하신 것을 도민의 한 사람으로서 축하드립니다.  여기에 또 7월 1일부터인가 사무처장이 공석으로 있습니다.  여기에 대한 대안이나 대책이 아까 원장의 보고에 끼지 않았습니다.  없어도 되는 자리입니까?  답변 부탁합니다. 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 사무처장을 저희가 지금 계속 물색 중에 있습니다.  조만간 채용을 하도록 하겠습니다.
</p>
<p><b>○ 이효선 위원 </b> 그런 것들이 업무보고에 들어와야 됩니다.  부원장이 직제에 빠지고 원장 다음에 차석이, 사무처장이 빈 것에 대한 언급이 없는 것은 경영의 잘못이라고 생각합니다.  없으면 없애세요.  필요 없으면 이 자리를 없애 버리십시오, 월급만 없애지 말고.  벌써 5개월 동안 자리가 비었는데도 운영에 문제가 없다면 사무처장 자리 없애기 바랍니다.  아니면 다음 달내로 빨리 사람을 채용하셔서 원활하게 업무가 돌아가게끔 하시기 바랍니다.
</p>
<p style="padding-left:1.2em">  본 위원은 경기개발연구원에 대해서 상당히 기대와 희망과 꿈을 가지고 있다고 생각합니다.  경기도민이 경기개발연구원의 연구결과물을 가지고 아픔을 같이 하고 슬픔을 같이 하고 즐거움을 같이 하는 시의적절한 연구결과들이 일천만 도민의 꿈과 희망이라고 생각합니다.  여러분들의 지난 1년, 특히 2년 반 동안 도의원하면서 경기개발연구원을 쳐다보는 본 위원의 시각은 그렇게 맑지 않습니다.  평소 존경하는 정인영 위원장과 김대원 간사께서 지적하신 옥상옥이냐.  왜 자리가 필요하냐.  그렇다면 부원장 자리를 놓고 모시면 될 것 아니냐라는 비유적절한 지적들을 여러분은 가슴으로 받아들이고 이것이 어느 특정인이 아닌 진정한 시스템으로 움직일 수 있는 경기도가 되기 위해서는 원장님의 결단이 필요하다고 전 생각합니다.  노출할 것은 노출하고 요구할 것은 요구하고 그러면서 역할을 다할 때 우리 경기도는 발전한다고 저는 생각합니다.
</p>
<p style="padding-left:1.2em">  질의를 마치면서 마지막 부탁은 유능한 연구원들을 많이 모시면서, 아까 제가 얘기한 전국 16개 광역시ㆍ도 출신으로서 지금 많이 분포되지 않은 지역, 각 시ㆍ도에 한 명 정도 연구원을 발탁해서라도 분단과 도, 도 안에서의 남북, 계층간의 갈등, 지역의 갈등 이런 것들이 몸으로 그 지역에서 공부하신 연구원을 통해서 각 도의 정체성을 연구하고 통합할 수 있는 7,000만 국민이 통합할 수 있는 연구과제를 가지고 당장은 그게 필요하지 않지만 그 팀이 만들어낸, 1년반 후에 손학규 지사가 그만두고 한현규 원장이 그만둘 때 마지막으로 발표한 것은 대량적으로는 나타나지 않지만 국가 미래와 민족통일을 위해서, 정체성 통일을 통해서 꼭 필요하다고 저는 생각합니다.  그러한 태스크포스팀을 꾸려서 16개 광역 시ㆍ도출신 연구원 한 명씩 해서 16명으로 구성된 국가 미래와 통합과 지역의 갈등을 해소할 수 있는 장기 미래를 가지고 연구하시기 바라면서, 또한 내년에 그런 데 돈이 필요하다면 1차 추경을 올리시면, 특히 본 위원이 예결위원회에 있습니다.  적극적으로 반영되도록 하겠습니다.  이상으로 질의 마치겠습니다. 
</p>
<p><b>○ 위원장 정인영 </b> 이효선 위원 수고하셨습니다.  다음 질의하실 위원께서는 거수로 신청하여 주시기 바랍니다.  정금란 위원 질의해 주시기 바랍니다.
</p>
<p><b>○ 정금란 위원 </b> 정금란 위원입니다.  자료집 65쪽에 보면 2003년도, 2004년도 예산 집행잔액이 과다한 것 같은데 발생사유와 처리방법은 무엇입니까? 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 예산집행잔액이 과다한 것은 실제 연구 진행되는 과정하고 예산집행이 진행되는 과정이 미스매치가 일어나고 있습니다.  매년 일어나는 현상인데 이것은 특별한 사유가 있는 것은 아니고 연구하는 실적하고 예산을 집행하는 실적하고 좀더 제도적으로 바꾸어서, 즉시 연구가 진행됨에 따라서 예산이 집행되도록 제도를 개선해 보도록 노력하겠습니다.  매년 일어나는 사항이고 제도개선이 필요한 부분이 아닌가 생각합니다. 
</p>
<p><b>○ 정금란 위원 </b> 앞으로는 이런 액이 발생하지 않도록 처리해 주시고요.  그리고 광교테크노밸리 조성사업은 경기도에서 심혈을 기울이고 있는 사업이고 지방자치단체가 주도하는 대규모사업이라는 점에서 많은 관심을 끌고 있는데 본 사업과 관련하여 경기도의 정책방향이 어떠해야 하는지와 연구원에서 생각하는 바람직한 개발방향은 어떤 것이 있습니까? 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 광교신도시 문제는 여러 가지 의미를 가지고 있습니다만 저는 우리 도가 하는 대규모 첫 사업이라는 데 의미가 있습니다.  경기도가 항상 중앙정부의 주도에 의해서 도시개발이 되고 택지개발이 되고 그러다 보니까 국민들로부터, 도민들로부터 난개발이라고 하는 소리를 들었지만, 또 집도 지어야 되고 직장도 만들어야 되고 그런 불가피한 상황에서 개발은 해야 되겠고 뭔가 개발의 모범답을 한번 찾아보자.  그것도 중앙정부에 의존할 것이 아니고 경기도가 직접 참여해서, 경기도가 직접 만들어서 앞으로 경기도의 개발은 이렇게 하는 거다 하는 것을 보여주기 위해서 중앙정부로 하여금 중앙정부가 따라오게 하기 위해서 하는 그런 사업에 가장 큰 의미가 있을 것 같습니다.  그런데 현실적으로 상당히 어려운 문제가 많이 있습니다.  여러 가지 좋은 아이디어가 나와야 되고 또 여러 가지 재정적으로 필요한 부분도 있고 그래서 저희 경기개발연구원에서 연구원뿐만 아니고 연구원 밖의 여러 전문가들을 동원해서 정말 바람직한 미래의 신도시, 바람직한 미래의 테크노밸리가 어떻다 하는 것을 저희가 보여주는데 최선을 다하도록 하겠습니다. 
</p>
<p><b>○ 정금란 위원 </b> 말씀 감사하고요.  도정 발전에 뒷받침이 될 수 있도록 노력해 주시기 바랍니다.  그리고 판교신도시개발사업에 포함된 20만평 도시지원시설용지는 경기도가 주관하여 개발하고 기본계획은 연구원에서 수행하고 있는 것으로 알고 있습니다.  판교 IT업무지구, 도시지원시설용지 20만평에 대한 기본계획 추진상황에 대해서 말씀해 주세요.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 기본계획이 작년 연말부터 시작해서 지금 거의 다 완성단계에 있습니다.  기본계획에서 거기를 IT를 포함한 최첨단산업의 집적지구로 만들자는 개념을 정리하고 그 사업을 어떻게 수행하느냐 하는 여러 가지 대안을 제시했습니다.  도에서 직접 하는 방안이라든가 아니면 지방공사에서 한다든가 아니면 제3의 기관을 설립해서 추진한다든가, 그리고 거기에 들어올 업체들을 어떤 방법으로 어떻게 모집해야 되는지 그런 데 대한 광범위한 조사를 통해서 기본계획을 수립하였습니다.  다만, 구체적인 방법에 대해서는 연구원에서 결정할 것은 아니고 연구원에서는 여러 가지 합리적 대안을 마련해서 기본계획을 통해서 도에다 그것을 제출하면 도차원에서 최종적인 결정을 내릴 수 있도록 저희가 뒷받침하는 일에 최선을 다하고 있습니다.  조만간 연구결과 보고서가 도로 제출될 계획으로 있습니다. 
</p>
<p><b>○ 정금란 위원 </b> 좋은 개발방향을 연구원에서 의견을 내서 도의 발전이 되도록 노력해 주시기 바랍니다.  이상입니다.
</p>
<p><b>○ 위원장 정인영 </b> 정금란 위원 수고하셨습니다.  다음 질의하실 위원 질의해 주시기 바랍니다.  함진규 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 함진규 위원 </b> 고양시출신 함진규 위원입니다.  금번 감사를 준비하느라고 한현규 원장님을 비롯한 직원여러분께 우선 감사의 말씀을 드립니다.  저는 질의에 들어가기에 앞서서 여러 위원들이 많은 지적을 해주셨습니다만 본 위원도 기획위원회에 3년 동안 있으면서 경기개발연구원을 지금까지 감사하면서 느낀 점을 말씀드리겠습니다.
</p>
<p style="padding-left:1.2em">  우선 한현규 원장님 취임을 축하드리고요.  제가 지금까지 경기개발연구원을 보니까 중요한 역할들을 많이 수행했습니다.  그리고 청사도 비좁던 공간에서 이쪽으로 이전해서 명실공히 좋은 여건속에서, 제가 연구원 개인분들을 만나뵙지는 않았지만 우리 기획위원회에서 지금까지 문제점들을 많이, 보수문제라든지 연구공간문제라든가 이런 부분에 대해서 많이 말씀을 드렸지만 그래도 지난 2002년이나 2003년보다는 나아지지 않았나 생각해 봅니다. 
</p>
<p style="padding-left:1.2em">  중요한 것은 한현규 원장께서 사실 본 위원이 알고 있기로는 중앙정부에 재직경력이 있으시고 또 정무부지사로 근무하셨기 때문에 오히려 지금이 경기개발연구원을 한층 더 도약시킬 수 있는 좋은 기회가 되지 않느냐.  왜냐 하면 경기개발연구원이라는 게 어떻게 보면 성격상 이론적인 성격이 강하거든요.  박사 여러분들이 포진하고 계시고, 실무면에서는 집행부와 아무래도 많은 차이가 나는 감이 있었는데 원장께서는 이런 두 부분, 실무나 이론을 접합시키고 조화시킬 수 있는 좋은 기회라고 생각됩니다.  그래서 지금까지 문제점, 해결방안 등 이런 것을 누구보다도 잘 아시리라고 봅니다.  그래서 지금 취임하신 이후에 업무숙지가 다 되셨다면 현재 본인이 느끼시는 바로 가장 큰 문제점이 무엇인지 간단하게 답변해 주실 수 있습니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 한 서너 가지가 있습니다.  제가 제일 걱정스러운 건 앞으로 행정수도이전에 관한 문제가 아직 끝나지 않은 싸움입니다.  그 부분에 대해서 저희가 대책을 마련하고 있고요.  그 다음에 분권과 분도의 문제입니다.  저희는 항상 주장하는 것이 지방분권입니다.  지방분권에 대해서 저희가 16개 광역시ㆍ도를 대표할 만한 정도의 대안을 마련토록 하겠습니다.
</p>
<p style="padding-left:1.2em">  그 다음에 항상 나오는 얘기지만 수도권규제와 관련된 문제입니다.  지금 중앙정부에서 선 지방육성, 후 수도권규제 완화라는 시책을 가지고 있는데 저희가 정면으로 거기에 도전하겠습니다.  그래서 지방육성도 중요하지만 수도권 규제완화가 더 중요하다는 사실을 적극적으로 연구하고 홍보하겠습니다.
</p>
<p><b>○ 함진규 위원 </b> 좋은 말씀 해주셨는데요.  헌법재판소 판례에 따라서 수도이전문제가 법적으로 일단락 된 상태입니다.  그런데 본 위원도 지방분권에 대해서 반대하는 사람은 아닙니다.  철저하게 찬성하는 입장에 있는 그런 사람 중 하나인데요.  우리가 지난 행정수도이전문제, 현재 불거지고 있는 분도론과 관련돼서 상당히 아쉬운 점이 많이 있습니다.  왜 그러냐면 경기도가 향후 성장잠재력이 굉장히 크고, 또 세계 전략적으로도 그렇고 한국내에서도 굉장히 중요한 위치에 있는데도 불구하고 상당히 그것을 도외시해 나가는, 현실을 인정하지 않고 도외시해 나가는 경향이 강한 것 같습니다.  그리고 수도이전논리에 대한 것을 경기도 입장에서도 기존에 보면, 저번에 제가 기획관리실 감사 때도 말씀드렸습니다만 어떤 대응논리에 있어서 상당히 취약한 것이 아닌가.  그리고 아까 이효선 위원님께서도 지적해 주셨지만 좋은 내용들을 갖고 있는데 그것이 정치적인 문제가 아닌 순수한 경기도민을 위한 방향에서 충분히 발표는 가능하다고 보거든요.  그런 경기도 입장에서의 문제점을 진단하고 연구용역결과가 있으면 저는 널리 홍보해야 된다고 보거든요.  그것이 자칫 정치논리에 따라가다 보면 문제가 있다고 봅니다.  그렇지만 정치논리가 아닌 순수한 경제논리라든가 도민 입장에서 충분히 권익을 보호하는 그런 것은 얼마든지 가능하다고 보는데 그러한 중요한 연구물들을 사장시킨다든가 아니면 묻혀 있는 것은 문제가 있다고 봅니다.  그래서 원장께서는 그런 부분에 대해서 앞으로, 본 위원이 중앙 TV든 신문에 원장이 언제 한번 나오신 것은 봤습니다만 연구원에 인재들이 저는 많은 것으로 알고 있습니다.  능력 있는 연구원들도 많이 계신 것으로 아는데 자주 그런 부분에 TV 출연을 한다든가, 기회가 있다면.  그래서 경기도의 논리를 대변해 주셔야 되는데 그게 전혀 없고 원장이나 취임한 이후에 한번 나오시는 정도고 전임 원장들도 별로 그렇게 많이 나오시는 것을 못 봤어요.  그래서 일천만 도민이 살고 있는데 그런 부분에 대해서는 너무 부족하지 않나 생각하는데 향후 그런 방향으로 홍보논리를 대응해서 하실 용의는 없는지 답변 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 함 위원님, 전적으로 동감입니다.  제가 연구원장으로 와서 한 얘기도 바로 그렇습니다.  연구원 안에서 아무리 잘하면 뭐 하냐, 연구원 밖으로 튀어나가야 된다.  연구원 밖에 사람들한테 알려야 된다.  그리고 경기도만 알리는 것도 부족하다, 대한민국 전체 사람들한테 알려야 된다.  홍보의 중요성을 강조했고 또 여러 가지 그 동안 하고 있는 것을 보면, 예를 들어서 이것이 정말 경기도민 전체가 알아야 되고 위원님들은 물론이고 대한민국 전체가 알아야 된다면 똑같은 연구결과라 하더라도 정치성이 있고 시의성이 있는 부분은 그 배포범위를 광범위하게 넓히고 그렇지 않고 기술적인 부분은 좁히고 이런 식으로 탄력적으로 운영했어야 되는데 지금까지 그렇지 못했던 것 같습니다.  앞으로 적극적으로 이것을 바꿔서 정말 TV출연, 신문기고 이런 것을 통해서 적극적인 홍보도 하고, 또 연구성과물을 배포함에 있어서도 홍보에 중점을 둬서 경기개발연구원, 경기도가 뭘 하는 것이구나, 어떤 생각을 가지고 있구나 하는 것을 국민과 함께 하는 노력을 기울이도록 하겠습니다. 
</p>
<p><b>○ 함진규 위원 </b> 앞으로 그렇게 해 주시기를 바라고요.  왜 제가 그런 말씀을 드렸느냐면 경기도는 도 자체가 이미 아시다시피 정치집단이 아니고 하나의 광역자치단체이기 때문에 중앙정부, 국회의원들이 주장하는 그런 내용들의 문제를 말할 필요는 없고, 또 도민들을 설득할 필요는 없다고 봅니다.  다만 경기도의 처한 문제점들을 왜 그런지 있는 그대로 설명만 해주면 됩니다, 어떤 기회를 통해서든.  그렇다면 그 분들이 판단할 문제이기 때문에 지금 분도문제를 말씀해도 국민들은 왜 분도가 필요한지, 또는 하지 말아야 되는지에 대한 판단이 막연한 정치적인 입장으로 따라갈 가능성이 많기 때문에 그런 말씀을 드렸고요.
</p>
<p style="padding-left:1.2em">  그 다음에는 연구원이 제가 지금 이쪽으로 이전해서 보니까 자료실이 있습니다.  자료실을 지금 개방하고 있습니까?  일반 도민들한테.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 네, 자료실 개방하고 있습니다. 
</p>
<p><b>○ 함진규 위원 </b> 개방이 되어 있다면 제가 더 드릴 말씀은 없는데 본 위원도 경기개발연구원에서 보내주는 귀중한 자료들을 잘 보고 있습니다.  그래서 일반시민들이 다른 서점이라든가 이런 데서 볼 수 없는 귀중한 연구자료들을 접해야 되지 않겠나 해서 이 말씀을 드렸습니다. 
</p>
<p style="padding-left:1.2em">  그리고 현재 세미나를 개최한 실적을 보니까 굉장히 많이 했습니다.  2003년에 22건, 2004년 21건 해서 총 43건, 그리고 주신 감사요구자료 327페이지에 있습니다.  총 43건을 했는데 여기에 보면 본 위원이 쭉 보니까 대략 월 2건 정도, 2건이 안 되는 정도로 하고 있는데 주로 주제 및 주요내용들이 한쪽에 치우쳐 있는 게 아닌가 하는 생각이 듭니다.  그래서 본 위원이 보니까 그중에서 소위 취약계층이라고 할 수 있는 장애인과 노약자와 관련된 세미나 및 워크숍 같은 것은 본 위원이 43건을 훑어 봤습니다만 있는지는 모르겠습니다.  그러나 얼핏 보기에 눈에 안 들어오는데 한 건도 없는 것으로 보이고 있습니다.  있다 하더라도 상당히 미미한 내용들인데 이렇게 그 분야에 대해서 한 번도 하지 않은 이유는 어떤 이유인지 원장님 말고 누가 담당하시는 분이 계신가요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 제가 내용을 알고 있습니다.  지금 함 위원님께서 잘 지적해 주셨는데 이번에 국정감사에서도 그게 지적됐습니다.  경기도가 장애인 분야는 말할 것도 없이 복지분야나 사회 전반적인 분야에 노력이 덜 하지 않느냐 하는 지적을 받았었는데 물론 우리 도의회에서도 계속 그런 지적을 받았습니다만.  제가 와보니까 연구원에 경제사회부라고 있는데 사회쪽이 거의 연구원이 없었습니다.  특히 복지라든가 장애 이런 분야에 대해서 전혀 전문가도 없고 그래서 당장 그 부분에 연구원을 저희가 2명 채용할 계획으로 있었습니다만 2명 중에서 일단 1명만 이번에 채용했습니다.  내년부터는 사회복지 분야에 대해서 세미나는 물론이고 연구를 좀더 심도있게 하고 그것을 도정에 반영하는데 노력하도록 하겠습니다.
</p>
<p><b>○ 함진규 위원 </b> 그렇게 관심을 가져준다고 해서 고맙습니다.  다만 장애인이나 노약자 중에서는 본 위원이 알고 있기로는 각 자치단체에서도 그렇게 관심을 갖고 있습니다마는 그냥 일방적으로 예산을 장애인단체나 노인회 측에서 지원을 요청하면 주는 식으로만 하지 근본적인 사회 일반인들이 알 수 있는 세미나나 워크숍 같은 것은 많지 않은 걸로 알고 있습니다.  해봐야 그분들인데 자체적으로 몇몇 지역의원들을 모셔놓고 하는 정도이고 그렇기 때문에 그 정도 갖고는 주위를 환기시키기가 상당히 어렵기 때문에 이렇게 많은 연구과제 중에서 경기도에서도 그런 부분에 관심을 가져야 되지 않겠느냐 해서 했고요.  앞으로도 이런 데 대해서 많은 관심을 가져주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그리고 연구사업 연도별 수행현황을 보면 2002년도에 경기개발연구원에서 수행한 연구과제 사업들이 연도를 달리하면서 상당히 많이 늘어나고 있습니다.  그래서 이런 부분들이 연구원이 2003년보다 더 많이 증원됐나요?  수탁 아니면 기본연구에서 연구량이 상당히 늘어나는데 연구과제에 비해서 인원도 충족이 된 겁니까 아니면 어떻게 된 겁니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 인원은 정원은 조금 늘어났는데 저희가 여러 가지 이유로 충원을 제대로 못 시키고 있습니다.  지난 8월부터 충원을 시작했는데요.  아직도 한 10명 정도의 T/O가 더 남아 있습니다.  그걸 하루빨리 시일내에 충원하면 나름대로 늘어나는 과제를 충분히 소화해 낼 수 있지 않을까 생각합니다.
</p>
<p><b>○ 함진규 위원 </b> 그것과 덧붙여서 업무량은 상당히 늘어나는데, 방금 이효선 위원님께서 지적을 해주셨는데요.  급여 관련도 제가 대학교수, 종합대학 큰 대학교수들하고 비교할 수는 없지만 2002, 2003년 계속 지적사항이 있었습니다.  원장님 오시기 전부터도 그런 내용들이 있었는데 연구라는 것이 사실 상당히 처우문제 때문에 모처럼 확보한 우수한 연구원들이 여기 연구원을 징검다리로 생각해서 향후 더 좋은 대학기관이나 연구기관으로 자꾸 이동하는 그런 비율이 좀 많이 있었습니다.  최근에는 제가 어떻게 됐는지 그건 모르겠지만 이런 부분이 아까 이효선 위원도 지적해 주신 대로 급여 부분들도 많이 관련이 될 수 있고요.  그와 아울러서 481페이지에 보면 연구원 휴직제 운영이 있습니다.  휴직자 처우가 보수는 기본연봉 지급이고 연구과제수행비 얼마 그 다음에 해외연수일 경우에 얼마 이렇게 지급을 하고 있는데요.  이게 483페이지에 보면 대상자에 대한 소요예산이 있습니다.  휴직기간 동안에 대상자에 대한 처우가 있는데요.  원장님은 어떻게 보십니까?  이게 적정하다고 보십니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 해외에 나가서 하는 것이기 때문에 상당히 비용이 듭니다.  비용이 들고 이것이 효과가 있느냐 없느냐는 논란을 벌일 수가 있습니다마는 또 이런 전문직들은 나름대로 정기적으로 해외에 나가거나 아니면 연구원 밖의 대학을 나가거나 이런 데 가서 리프레시(refresh)할 기회가 필요하다고 봅니다.  휴직년제에 대해서 들어가는 비용만큼 저희가 보다 커다란 성과를 가져올 수 있도록 노력을 하겠습니다.
</p>
<p><b>○ 함진규 위원 </b> 여기 대상자 일곱 분이 전부 연구원입니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그렇습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그리고 연구 휴직할 때 대상 연수처라고 할까요?  연수처하고 그 과제명을 누가 선정한 겁니까?  여기 보면 휴직기관 그러니까 휴직을 하게 될 경우에 대상처가 있지 않습니까?  그 과제명이 있는데 이런 부분들은 연구원에서 지정을 해주는 겁니까 아니면 본인들이 자유롭게 선택하는 겁니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 본인이 선택해서 원장이 최종적으로 승인하고 있습니다.
</p>
<p><b>○ 함진규 위원 </b> 그렇다면 다행이라고 생각을 합니다.  본 위원 생각으로는 휴직기간이 대학교수들도 마찬가지지만 글자 그대로 휴직기간이라는 말 자체가 상당히 용어상에 문제가 있다고 봅니다.  휴직기간이 노는 기간이 아니고 사실 장기근속자 여기 대상기간이 6년으로 돼 있습니다마는 일반 대학의 경우에도 대학마다 좀 틀리긴 하지만 몇 년동안 기간을 정해 놓거든요.  그래서 절대 노는 기간이 아니고 그 동안 자기가 부족했던 부분들 아마 이것을 채우고 향후 보다 더 적극적인 연구활동을 위해서 보충하는 중요한 기회라고 보거든요.  그런데 제가 보수지급기준이나 경기개발연구원의 운영규칙 같은 그런 것은 보지 못해서 모르겠는데 휴직자 처우를 평상시에 하는 것보다 줄여서 주는 특별한 규정이나 제도가 있습니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 휴직자 처우를 평상시보다 적게 해주진 않습니다.  더 많이 해주고 있습니다.
</p>
<p><b>○ 함진규 위원 </b> 그러면 제가 잘못 판단했는지 모르겠는데요.  대상자들을 보니까 본봉이라든가 기존에 받던 것 말고 그럼 이 소요예산이 별도로 주는 겁니까?  483페이지에 있는 내용들이요.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 이것은 연구과제비고요.  481페이지를 보시면 휴직자 처우 이게 사실 저도 용어가 좀 잘못된 것 같습니다.  이 사바티카(sabbatica)를 휴직자라고 했는데 사실 파견근무, 파견연구라고 표현하는 게 더 좋을 듯 싶습니다.
</p>
<p><b>○ 함진규 위원 </b> 이 내용을 얼핏 보기에는 평상시 주던 것보다 줄여서…….
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 기본연봉을 지급하고 제일 밑에 체재비 월 1,000불을 별도로 줍니다.
</p>
<p><b>○ 함진규 위원 </b> 어쨌든 본 위원이 질의하고자 하는 취지는 아까 말씀드린 대로 휴직기간이 노는 기간이 아니고 보다 양질의 연구 성과물을 내기 위해서 더 충분한 공부를 하는 기간이라고 보기 때문에 여기에 대한 세심한 관심을 가졌으면 하고요.
</p>
<p style="padding-left:1.2em">  그 다음에 말씀드리고 싶은 것은 시ㆍ군 담당자 선정현황입니다.  555페이지에 보면 2002년 10월에 한 번 개최됐습니다.  15차 경기도시장ㆍ군수협의회 이게 그 이후에는 쭉 안 됐었나요?  시장ㆍ군수협의회가요.  경기개발연구원 시ㆍ군간 관ㆍ학 협력체계 구축 건의요청이 있었는데요.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그때 결정한 것이 지금도 계속 유지되고 있습니다.
</p>
<p><b>○ 함진규 위원 </b> 여기 보면 각 기초자치단체 쪽에서는 지역현안에 대해서 경기개발연구원에 거는 기대가 상당히 있는 걸로 보입니다.  31개 시ㆍ군에 대해서 전부 다 담당을 설정해서 이분들이 담당하고 계시는데 실제적으로 시ㆍ군에서 올라오는 정책건의라든가 이런 내용들이 많이 있고 또 해결한 사례들도 많이 있습니까?  여기 자료에 보니까 그런 내용들이 별로 없어서요.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 이것이 상당히 연구원이 가지고 있는 딜레마입니다.  저희 인원이 한정돼 있는데 거의 한 연구원이 31개 시ㆍ군이면 31개에 다 배석되다 보니까 사실 풀타임 잡으로 한 시ㆍ도를 자문하고 도와줘도 시간이 모자랄 겁니다.  그런데 우리 연구원에서 연구과제도 그대로 하고 또 정책과제, 수탁과제를 다 하면서 사실은 엑스트라로 시ㆍ군을 지원하다 보니까 시ㆍ군에서도 불만이 많습니다.  그래서 어떤 시ㆍ군은 우리도 자체적으로 연구원을 만들겠다.  이렇게 나오는 시ㆍ군도 있고 그런데 이 문제는 연구원의 규모가 대폭 확대되지 않으면 상당히 어려운 일이라고 봅니다.  그렇다고 저희가 한정된 인원과 예산으로 31개 시ㆍ군을 돌봐주다 보면 우리 본연의 업무인 도정개발이라든가 도정에 전념하지 못하는 그런 결과가 나옵니다.  그래서 중장기적으로 연구원의 규모를 확대해서 도정 뒷받침에 지장이 없는 범위 내에서 시ㆍ군도 적극적으로 도와줘야 되겠지만 지금 당장에는 운영의 묘를 통해서 연구원들이 좀더 분발해서 도정은 도정대로 차질없이 진행하면서 보다 더 많은 시간을 시ㆍ군에 쏟는 그런 방법밖에 없지 않을까 생각을 합니다.
</p>
<p><b>○ 함진규 위원 </b> 그리고 제가 경기개발연구원의 기금조성을 보니까 단연 경기도에서 57.2%를 조성하고요.  그 다음에 일선 시ㆍ군에서 15.4%의 기금조성을 하고 있고 자체적립이 19.6%, 나머지 기타 등등이 있습니다마는 중요한 것은 시ㆍ군에서 15.4%의 기금조성에 기여하고 있기 때문에 일선 자치단체장들도 많은 기대를 하고 있는 것 같습니다.  그래서 제가 말씀드리고 싶은 게 경기개발연구원이 연구용역과제도 굉장히 많지만 지금도 많이 하고 있는 걸로 알고 있습니다.  그러나 도의회 또 도 집행부, 나아가서는 일선 시ㆍ군하고 워크숍이라든가 세미나 같은 것을 좀더 활발하게 개최해야 된다고 보고 특히 일선 시ㆍ군 같은 경우는 현장세미나를 하는 것이 그 지역에 특별한 이슈들이 있을 것입니다.  그런 문화재 관련이든 아니면 다른 지역현안 문제점들 이런 게 충분히 있을 텐데 그것을 시간상 어려움은 있으시겠지만 현장에 돌아가면서 현장세미나를 하는 방법이 어떤가.  그것을 또 도에 직접적인 정책의 가교역할을 해줄 수 있고 실질적인 연구활동을 할 수 있는 그런 내용이 아닌가 해서 그런 현장세미나를 앞으로 많이 개최해 주셨으면 하는 바람이고요.
</p>
<p style="padding-left:1.2em">  끝으로 제가 서두에도 말씀드렸지만 원장께서는 집행부의 실무담당을 많이 하신 분이기 때문에 지금 청사도 이전된 상태에서 그런 경기개발연구원의 문제점들을 심층 파악하셔서 경기개발연구원의 위상이 더욱더 높아질 수 있는 방향으로 최선의 노력을 해주시길 부탁드립니다.  이상입니다.
</p>
<p><b>○ 위원장 정인영 </b> 함진규 위원님 수고하셨습니다.  위원님들께 양해말씀을 드리겠습니다.  행정사무감사 중 중식시간이 많이 경과되었습니다.  따라서 중식 후에 계속 감사를 진행코자 하는데 이의 없습니까?
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 중식과 휴식을 위하여 14시 30분까지 감사를 중지하겠습니다.
</p>
<p class=''ar''>(12시33분 감사중지)
</p>
<p class=''ar''>(14시23분 감사계속)
</p>
<p><b>○ 위원장 정인영 </b> 좌석을 정돈해 주시기 바랍니다.  계속해서 감사 질의ㆍ답변을 진행토록 하겠습니다.  그러면 질의하실 위원 계시면 거수로 신청하여 주시기 바랍니다.  이건희 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이건희 위원 </b> 광주출신 이건희 위원입니다.  행정사무감사 준비자료를 해주신 한현규 원장님과 직원 모든 분께 감사를 드립니다.  본 위원은 연구용역과제 선정에 관련해서 질의를 하도록 하겠습니다.  연구용역과제 선정의 여러 가지 문제점에 대해서 질의할 건데요.  연구과제를 어떤 것을 어떻게 선택해서 그것이 도정에 반영되고 정책에 반영돼서 도민들의 삶의 질이라든지 더 나아가서는 경기도 국가발전에 많이 반영돼야 되는데 그렇지 못한 경우가 많습니다.  그래서 본 위원이 질의하고자 하는 것은 과제선정의 원칙이 어떤 것인가에 대해서 먼저 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 아까 오전에 말씀드린 것처럼 저는 연구원의 연구결과가 도정에 즉각적으로 반영되는 것, 또 도가 고민하고 있는 부분을 저희가 긁어줘야 될 의무를 가지고 있다고 봅니다.  그런 의미에서 저희가 과제선정을 할 때는 현재 기본과제를 중심으로 하겠습니다마는 미리 도하고 상의하고 또 도의회의 의견도 받고 그래서 도의회와 도 집행부 그리고 저희 연구원 3자간의 논의와 토론을 통해서 기본과제로 선정합니다.
</p>
<p><b>○ 이건희 위원 </b> 그리고요.  지금 연구원의 능력이라고 평가하면 좀 뭐하지만 저는 자체 가지고 있는 인력과 인원수에 비해서 과제물이 과다하다 이런 생각을 갖습니다.  현재 이 자체에서 하는 것과 그리고 다른 데서 위탁받아서 하는 것도 있고 수탁 주는 것도 있는데 그 비율이 어느 정도 됩니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 전체 연구비가, 전체 예산이 100억원 정도라면 연구비 비중이 한 70억원 정도 되겠습니다.  그런데 그 70억원 정도의 연구비 중에서 100% 외부위탁으로 나가는 것은 1년에 3억원 정도가 됩니다.  100% 외부위탁으로 나가는 비율은 적고 다만 내부적으로 하는 거라 할지라도 프로젝트의 일부를 외부에 주는 것이 있습니다.  그 부분에 대해서 비율은 제가 정확히 알지 못하겠습니다마는 20%를 넘지 않을 거라고 생각하고 있습니다.  제가 정확한 데이터는 가지고 있지 않습니다마는 곧 분석해서 보고드리겠습니다.
</p>
<p><b>○ 이건희 위원 </b> 그것은 나중에 자료를 주시면 좋겠습니다.  그리고 현재 위탁뿐만 아니라 이런 모든 과제에 대해서 원장님 생각에는 과제가 좀 많지 않나 하는, 어떤 의견을 갖고 있습니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 저는 개인적으로 과제수가 너무 많지 않냐.  지금 우리 연구원 한 사람이 담당해야 될 과제의 수가 너무 많아서 거기에 대해서 좀 검토해 보자 그랬는데 저는 개인적으로 연구의 과제 숫자가 중요한 것이 아니고 연구를 하나 하더라도 좀더 심도있고 도정에 즉시 반영될 수 있는 연구를 해야 되지 않을까.  그래서 과제숫자는 줄이되 그 내용은 좀더 충실하게 하는 것이 우리 연구원이 취할 방향이라고 생각합니다.
</p>
<p><b>○ 이건희 위원 </b> 그래서 지금 본 위원이 질의하는 요지를 원장님께서 답변해 주셨는데요.  지금 여러 가지 연구용역과제를 하는데 실질적으로 도 정책에 반영이 안 되는 게 많습니다.  물론 이것이 자료가 부실한 것도 있고 여러 가지 형식적인 어설픈 자료가 있어서 현실적이지 못하기 때문에 도정에 반영이 안 됩니다.  그리고 어떤 경우에는 이게 너무 잘 돼 있는데 너무 앞서가는 내용이거나 아니면 향후에 적용될지는 모르지만 현재 적합하지 않은 그런 내용이 많습니다.  그래서 말씀드리고자 하는 것은 연구인력도 전문화하고 정예화된 인력을 좀더 보강할 수 있으면 보강하시고요.  외부에 주는 일이 많지 않아야 된다는 생각이고 과제선정에 있어서도 정말 필요한 것들만 엄선해야 될 것 같다는 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  한 가지 더 말씀을 드리면 그런 주어진 과제들이 경기개발연구원에서 수탁을 주거나 이런 여러 가지 과제들, 여기 것뿐만이 아니라요.  그런 것의 사전 사후감독은 어떻게 하고 계십니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 저희가 위탁을 주는 부분에 대해서는 통상 사후감독이라든지 납품을 받아서 제가 그 내용을 검토는 합니다.  검토는 하는데 사실 여기서 제가 일부러 드릴 말씀은 아닙니다마는 지난번 행정수도이전 문제하고 관련돼서 경기도 인구변화 이런 걸로 국정감사에서 논란이 되고 그랬습니다마는 일부 연구는 우리가 위탁을 준 것이기 때문에, 우리가 외부에 맡긴 것이기 때문에 그 외부연구자의 권위라든가 전문성을 인정해서 저희가 일부는 좀 스크린을 제대로 하지 않은 것이 있던 것이 사실입니다.  그래서 지난번 사건을 계기로 해서 아무리 우리가 외부에 주는 위탁기관이 전문성이 있고 또 그 사람들의 권위를 인정해야 될 필요성도 있지만 그 범위 안에서 연구원에서 연구결과를 제대로 새로 해석을 해야 된다.  그래서 연구원에서 생각하는 것과 다르면 그분들하고 다시 협의해서 연구결과를 우리 원하는 대로 혹은 좀더 객관적인 기준으로 수정해 나가야 될 그런 필요성을 느낍니다.  앞으로 그런 위탁연구에 대해서는 제도적인 보완장치를 마련하겠습니다.
</p>
<p><b>○ 이건희 위원 </b> 그런 위탁연구든 아니면 자체에서 하든 간에요.  그 모든 것의 책임적인 것은 원장님이 지셔야 되는 겁니다.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그럴 것 같습니다.
</p>
<p><b>○ 이건희 위원 </b> 외부전문기관이라고 해서 잘못된 연구용역을 주는 경우가 경기개발연구원 뿐만 아니라, 예를 들어서 제가 실학에 관련해서 자꾸 말씀드리게 되는 것은 실학박물관이라든지 이런 것을 연구용역 주는데 이게 분명히 인문사적이고 역사적인 것이고요.  과연 그것을 인문사적으로 보나 아니면 실학사조 적으로 보나 이런 것은 분명히 인문계열에 해당되는 학자들이 따로 있고 실학학회가 있는데도 불구하고 경기도에서는 이런 실학에 관련돼서 용역 줄 때 어디에 줬냐면 산업대학교 경영대학에연구용역을 줬어요.  이것은 원장님 생각에 맞다고 생각하시는 겁니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 어떤 특별한 사정이 있었는지는 모르겠습니다마는 조금 이상하게 들리는 면이 없지 않습니다.
</p>
<p><b>○ 이건희 위원 </b> 그래서 이런 말씀을 드리는 것은 그 분야에 맞는 전문연구기관이나 대학, 거기에 관련돼 있는 데에 용역을 줬을 때 타당한 내용이 나올 겁니다.  지난번 실학용역 줬을 때도 보면 실학자 의견서는 단 한 자 한 줄도 없었어요.  그리고 실질적으로 그 지역에 가서, 의원이 의원을 욕하는 것 같아서 뭐하지만 의원님들이나 아니면 공무원이나 거기에 관련돼 있는 사람들이 현지답사를 하지 않은 겁니다.  그저 그냥 제목 있으면 용역을 시ㆍ군이나 도나, 여기도 마찬가지겠지만 좀 덜 하리라고 봅니다마는 실질적인 데 주지 않는 것에 대해서 저는 문제점을 일단 짚고 싶고요.  여기는 대부분 연구용역입니다, 연구이거나.  그래서 특별히 어떤 원칙을 가지고 과제도 선정해야 할뿐더러 원칙을 가지고 일해야 된다는 말씀을 드리고요.
</p>
<p style="padding-left:1.2em">  제가 한 가지 짚어서 말씀드리고자 하는 것은 지난번에 저도 여기 회의에 참석했었는데 팔당댐이라든지 그런 침전물 수거정비를 하겠다고 한현규 원장님께서 의욕을 갖고 출발했었는데 최근에 와서는 그것이 불필요하다고 지난번 결정을 했는데 이와 같은 것도 사실은 현지에 있는 환경단체라든지 NGO 이런 분들과 직접적인 대화를 덜 했기 때문입니다.  저는 그런 생각이 들거든요.  그러니까 과제선정 때부터 결과물 나올 때까지 연구원에 계시는 분들도 어쩌면 옛날 연구소 하면 연구소에서 연구하는 그런 생각을 많이 갖고 있지 않는가 그런 생각이 드는데요.  팔당댐 수질개선을 위해서 침전물 수거라든지 정비하는 것에 대해서도 간단하게 답변을 해주시고 아울러 말씀드리고자 하는 것은 이제는 연구부서도 개발연구원이 발로 뛰는 연구원이 돼야 된다.  그래야지 현지실정이라든지 현 시대에 적합한 연구자료를 낼 수 있다는 말씀을 드립니다.  거기에 대해서 1년간은 연구용역을 했는데 어떤 사유에서 별다른 효과가 없는지에 대해서 간단하게 설명을 해주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 팔당호 수질관련대책은 저도 그때 도에 있었습니다마는 팔당호와 관련돼서 물의 공급자도 경기도이고 물의 수요자도 경기도이고 또 그 물의 거의 80%를 경기도 사람들이 먹습니다.  거의 100%가 경기도에서 공급이 되는 거고.  그럼에도 불구하고 팔당호의 관리가 중앙정부인 환경부 차원에서만 이루어지기 때문에 경기도가 보다 주인의식으로 팔당호 이북사람들과 팔당호 물을 이용하는 사람들의 이해관계를 조정하면서 어떻게 하면 수질도 개선하고 또 지역발전도 함께 이룰 수 있느냐 하는 종합적인 대책을 경기도가 주도적으로 한번 해보자 해서 연구용역을 시작했던 겁니다.
</p>
<p style="padding-left:1.2em">  그래서 얼마 전에 중부일보인가 어디서 팔당호 준설을 거의 포기했다 이런 식으로 신문에 나오고 그랬었는데 그러한 노력의 일환으로써 팔당호를 준설하느냐 마느냐 하는 것은 커다란 노력의 일부분이었습니다.  그걸 할 필요가 있느냐 없느냐 논란이 많은데 그 부분에 대해서도 우리 경기도에서 명확한 입장을 가지자는 그런 차원에서 연구용역의 일부분으로 그것이 진행된 것이고 저희 전체 연구용역은 팔당호를 준설하느냐 마느냐 하는 것은 여러 가지 중의 하나지만 주로 되는 것이 하수처리장을 어떻게 건설할 것이며 그 주변관리를 어떻게 할 것이며 이런 주변지역에 대한 발전방안을 수질이 나빠지지 않는 범위 내에서 어떤 방식으로 추진해야 될 것이며 하는 종합적인 연구를 하는 것입니다.  그런데 종합적인 연구결과는 거의 마무리 단계에 있습니다마는 곧 저희가 정리해서 도청으로 주면 도청에서 그걸 정책으로 집행할 것이고 다만 중간에 전체 연구 중에 일부분인 준설부분에 대해서는 저도 여러 번 검토하고 또 우리 연구원을 통해서 확인해 봤습니다마는 준설할 필요성이 별로 없다는 것이 지금까지 나온 연구결과입니다. 
</p>
<p><b>○ 이건희 위원 </b> 그래서 제가 말씀드리는 것은요.  작년에도 저희가 행정사무감사 때 국가균형발전법부터 시작해서 몇 가지 요구사항이 있었습니다.  그때도 연구원 시ㆍ군담당제를 강화하라고 얘기한 것은, 팔당호 준설은 사실 금년 2004년 경기개발연구원의 30개 과제 중에서 제가 하나만 그냥 짚어서 예를 들어 말씀드리는 겁니다.  그런 지역현안문제를 처리해 나가는 것, 어떤 정책방향이라든지 국가균형특별법이라든지 수도권정비법 이런 문제는 원장님이하 여기 있는 주요 핵심멤버들이 결정해도 좋습니다마는 그 지역 1시ㆍ군 1담당제를 활성화해 달라고 우리가 요구했던 것은 그 지역을 예비군이 제일 잘 알듯이 그 지역에 대한 현안문제들을 여기에서 연구하는 것은 데이터 취합정도이고요.  그 데이터 취합하는 것도 시ㆍ군에 가서 시ㆍ군 담당하는 분들하고 꼭 누가 매치를 안 하더라도 그 지역에 있는 사람들이나 인사들과 만나서 현안을 해결해야 된다는 겁니다.  그러면 지금 팔당호에 대한 침전물이라든지 퇴적층 이런 것을 수거할 필요가 없다, 준설할 필요가 없다고 생각이 된다면 본 위원 생각에는 지난번에 제가 담당 위원님한테 말씀을 드렸는데 그 지역에 용인부터 시작해서 상ㆍ하수도 관련 GIS를 명확하게 하고요.  그것을 종말처리장에 명확하게 전부 다 연결해서 처리하는 문제하고 팔당댐 깊은 데 퇴적층이 얼마 있다 이런 것은 중요하지 않고 그 지천이라든지 경안천 이런 데에 움푹 파이고 고저가 굉장히 심한데 그런 부분을 정비할 필요는 있습니다.
</p>
<p style="padding-left:1.2em">  그래서 제가 말씀드리는 것은 이런 정책을 세웠다가 별로 필요성이 없다고 접어두게 된다면 그 후속대책은 뭔가.  그러면 준설작업을 못한다고 결론 나면 그 지역 1급수 만드는 것에 대해서 어떤 다른 방안을 강구하고 있으신 게 있으면 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 아까 말씀드린 것처럼 준설이라고 하는 것이 수질을 높이는데 별로 기여를 하지 못한다 하는 것을 이번에 다시 한 번 확인했습니다.  그렇지만 준설 이외에 팔당호의 수질을 지금보다 좋게 할 수 있는 방법은 사실 여러 가지가 있습니다.  지금 위원님 말씀하신 것처럼 하수종말처리장을 좀더 통합적으로 잘 건설하고 운영하는 문제라든가 경안천 같은 지천을 제대로 정비해서 덜 오염된 물이 나오게 한다든가 여러 가지 수변구역에 대한 관리를 강화하고, 또 기존에 있는 환경처리시설에 대한 관리 감독을 더 강화한다든가 여러 가지 분야에서 지금보다 더 노력해야 될 부분이 많다고 생각합니다.  그런 부분들을 통해서 우리가 노력하고 예산을 투입해서 팔당호수질을 지금보다 더 좋은 방향으로 가지고 가는 그런 종합적인 연구가 지금 거의 마무리 단계에 있고 그것이 마무리되는 대로 저희가 도하고 상의해서 도에서 집행가능한 예산을 집어넣고 또 필요한 예산은 국가로부터 신청하고 해서 종합적인 대책을 추진해 나가는 계기를 만들도록 하겠습니다.
</p>
<p><b>○ 이건희 위원 </b> 고맙습니다.  본 위원이 3년째 기획위원회를 지켜왔고 수많은 사업들에 대해서 많은 것들을, 개략적인 것을 아는데 일일이 지적하기에는 시간상 그렇고요.  마지막으로 한 가지만 질의하고 끝내겠는데요.  지금 동부권 쪽에는 환경법에 의해서 오염총량관리제를 임의제로 하는 건데 광주는 이미 금년 7월부터 총량제와 관련해서 받아들이기로 해서 2만 9,000t에 대해서 총량제를 확정했습니다.  그런데 현재 주변지역 8개 시ㆍ군과 관련해서 2004년도 주요시책이라고 51페이지를 보면 총량관리제를 연구하는 것이 가평, 여주라고 되어 있는데 총량관리제를 5년 단위마다 하는 것 맞습니까? 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 제가 그 분야에 대해서 그렇게 깊이 알지 못하기 때문에 그 분야를 전공하고 있는 송미영 박사한테 대신 답변드리도록 하면 어떻겠습니까? 
</p>
<p><b>○ 이건희 위원 </b> 좋습니다.  물론 팔당상수원이 이천만을 커버하고 있지 않습니까?
</p>
<p><b>○ 환경정책연구부연구위원 송미영 </b> 인사 먼저 드려도 돼요?
</p>
<p><b>○ 이건희 위원 </b> 네.
</p>
<p><b>○ 환경정책연구부연구위원 송미영 </b> 환경정책연구부에 연구위원이고요.  이름은 송미영입니다. 
</p>
<p><b>○ 이건희 위원 </b> 송미영 박사님하고는 지난 번에 팔당에 같이 배를 타고 지역적인 문제를 돌아보고 어떻게 대책을 세울까 해서 함께 다닌 기억도 있고, 그쪽에 많은 노력을 해주셔서 감사드리고요.  제가 지금 질의드린 요점은 뭐냐면 오염총량관리제에 대해서 물론 환경법에서는 임의제지만 우리가 개발하더라도 무한정 할 수도 없는 거고 오염총량을 계산해서 거기에 맞춰서 제한적인 개발을 하는 것이 오염총량제라고 알고 있는데요.  광주시에서는 여기 경기개발연구원에서 연구하기 이전에 그것을 받아들여서 이미 시행하고 있는데 몇 가지 문제점이 많습니다.  그래서 현재 가평이나 여주같은 데는 총량관리제 연구가 몇 년 단위로 연구가 돼 있습니까? 
</p>
<p><b>○ 환경정책연구부연구위원 송미영 </b> 원래 총량단위는 환경부에서 정한 지침에 따라서 5년 기본계획을 수립하도록 되어 있고요.  광주는 이미 5년짜리로 2007년까지인가, 제가 기억하기로는.  
</p>
<p><b>○ 이건희 위원 </b> 네, 2007년까지 맞습니다.
</p>
<p><b>○ 환경정책연구부연구위원 송미영 </b> 하는 것으로 돼 있고 가평, 여주는 지금부터 5년짜리 계획을 수립하고 있는 중이고요.  그 다음에 국가 전체로 보면 2010년까지 총량 1단계가 계획 중인데 그 1단계의 세부기본계획으로 광주에서는 첫 번째로 한 거죠.  우리나라의 지자체 중에서는 처음으로 하셨죠.
</p>
<p><b>○ 이건희 위원 </b> 저희가 우리나라에서는 처음으로 시행했는데 사실 불안한 감도 있고 저희뿐만 아니라 8개 시ㆍ군이 다 오염총량관리제를 시행해야 된다고 생각합니다.  그렇게 해야만 더럽히지 않는 1급수를 만들어 나가는 길이라는 생각을 갖고 있는데요.  이거 얘기하면 한참 걸리니까 한 가지 말씀드리면 우리가 1일 처리용량 2만 9,000t이라는 것을 받아들였는데 5년 후에 만일 서로가 약정했던, 예를 들어서 소화하기 위해서 4.3ppm이 지켜지지 않았을 경우에, 그럼 그 다음에는 처리시설을 받지 못하는 겁니까? 
</p>
<p><b>○ 환경정책연구부연구위원 송미영 </b> 그렇게 생각하시기 보다는 2007년까지 계획을 받으셨잖아요.  그런데 사실 이행계획이라 그래서 시행계획 말고 평가계획이 있습니다.  평가계획은 시행계획 그 다음해 1년부터 계속 1년 단위로 평가를 받으세요.  그러면 예를 들어 내년 해당사항에 대한 평가를 받으시는데 내년에 받으실 때 내년까지 약속한 부분을 이행 못하셨으면 거기에서 아마 제동조치가 있을 겁니다.  그런데 제가 생각할 때는 만약에 모든 제도가 원래 계획대로 갔다면 제가 말씀드린 게 맞는데 광주가 맨 처음으로 갔고 지금 이행계획을 실제로 작동하기 위한 체제가 환경부 자체에서 아직 준비가 안 됐어요.  그래서 이행계획을 하는 과정 자체도 아마 기본계획 수립하시는 것만큼 지연될 거예요.
</p>
<p style="padding-left:1.2em">  제가 기억하기로는 ''99년에 하시려고 했는데 2004년에 하셨잖아요.  그러니까 거의 3년이지요.  이행계획도 2년이상 아마 지연될 거고 그때 가서 아마 지금 걱정하시는 일이 일어날 텐데 저는 광주는 그런 면에서는 운이 좋다고 생각해요.  매를 먼저 맞으셔서 아직 매를 때릴 준비가 안 돼 있는데 매 맞으실 준비하고 계시기 때문에 다른 시ㆍ군보다 상당히 여유 있으실 거고 매 안 맞으실 수도 있어요.
