<p><b>○ 환경정책연구부연구위원 송미영 </b> 1년 동안 하신 것을 가지고 조사해서 이행계획단계에서 원래 평가를 하게 되어 있는데 제가 말씀드린 것처럼 지침 안에는 세부적인 내용이 다 있지만 그것을 사실 시ㆍ군에서 하실 수가 없어요.  거기에는 일단 시ㆍ군에서 한다고 되어 있지만 시ㆍ군에서 이행평가계획서를 다 작성하셔서 환경부에 내면 환경부에서 다시 평가를 해주는 건데 그것을 하실 수 없기 때문에 그것도 용역하셔야 돼요.  그런데 용역하게 되면 말씀드린 것처럼 기본계획시간 하신 만큼 이행평가 자체도 시간이 오래 걸린다는 거지요.  그렇기 때문에 아직 시간적인 여유가 있으실 거라는 거고요.  그 다음에 세부적인 기준들은 생각하시는 것보다 훨씬 더 기술적인 단계에서 세부적으로 정해져 있습니다.  그래서 그 기준대로 만약 간다면 광주가 어떤 식으로든 벌을 받겠지요.  그런데 제가 지금 말씀드린 것처럼 벌을 줄 수 있는 여건이 아직 안 돼 있으니까 그것을 너무 걱정하시기 보다는 약속하신 내용 있잖아요.
