<p><b>○ 이건희 위원 </b> 광주시가 어떤 제재를 받고 개발이 안 된다는 것을 걱정하는 면도 일부 있지만 8개 시ㆍ군의 전체적인 문제를 말씀드리는 거고요.  이것은 여기까지만 말씀드리고 나중에 또 개인적으로 총량제에 대해서 해 주시기 바랍니다.  그리고 저는 이 지역을 송미영 박사께서 하시는데, 팔당지역 주민지원사업비 여러 가지 복잡한 게 많지 않습니까.  그런 문제점을 잘 분석하셔서 그 지역주민들에게 도움이 될 수 있도록 연구를 계속해 주시기 바라면서 일단 들어가셔도 되겠습니다.
