<p style="padding-left:1.2em">  본 위원이 질의하는 것은 이런 연구용역과제 선정의 과다성이라든지 그리고 정예화된 주요업무들을 좀더 집중적으로 하더라도 너무 많은 것을 펼치지 않기를 바라는 마음에서 질의를 드리는 거고요.  그에 따른 예산소요라든지 낭비요소를 한현규 원장께서 철저하게 감시 감독을 잘 하셔서 정말 꼭 필요한 과제가 선정돼서 그 과제가 될 수 있는 대로 우리 도정에 반영될 수 있도록 노력해 주시기 바라면서 질의를 마치겠습니다. 
