<p><b>○ 이흥규 위원 </b> 알겠습니다.  저는 사실 이 조직표를 보면서 경기도의 현안사항에 대해서 경기개발연구원이 잘 적응하고 있다라고 생각했는데 원장님 답변을 들어보니까 너무 즉흥적이지 않나라는 생각이 들고요.  특히 대중교통문제에 관한 부분은 사실 위원님들이나 대한민국 국민이 잘 알고 있지만 서울시의 이명박 시장은 서민들의 대중교통 불편을 해소하기 위해서 서울시내 교통체계 개편을 일제히 단행했습니다.  그래서 많은 문제점도 생겼고 질타도 많이 받았지만 몇 개월이 지난 현재의 입장에서 보면 서울시 전체의 교통상황이 많이 좋아졌다는 긍정적인 평가를 받고 있거든요.  그런데 저는 경기개발연구원이 손학규 도지사님의 싱크탱크 역할을 해주시면서 경기도에는 사실 여러 가지 교통문제가 있습니다만 용인과 성남이 대립하고 있는 그런 도로가 사실 한 곳밖에 없는데, 현재로서는.  그것도 해결을 제대로 못하고 있는 시점을 바라보면서 과연 우리 경기개발연구원의 대중교통개선TF팀이 지사님을 더 적극적으로 보좌했으면 좋겠다는 생각이 듭니다.  그런 아쉬움이 들고요.  경기개발연구원이 용역결과를 발표하지 않은 과제는 얼마나 되는지요?
