<p><b>○ 이흥규 위원 </b> 그러면 경기개발연구원의 용역결과가 원장님이나 지사님의 저의에 따라서 발표가 되고 안 된다고 한다면 경기개발연구원의 본래 목적대로 운영하고 있지 않다라고 봐야 되겠네요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 연구원의 연구결과가 불필요한 논란을 일으키거나 불필요한 정치적인 활동으로 이어질 가능성이 있다면 원장이나 도지사는 당연히 자기의 직권을 이용해서 당연히 그 연구결과를 발표하지 않을 수도 있다고 생각합니다. 
</p>
<p><b>○ 이흥규 위원 </b> 정무부지사님 출신이신 원장님 입장에서는 그렇지만 진정한 연구과제는 지사님의 논리에 맞든 안 맞든 발표가 되어야 된다고 저는 생각합니다.  그리고 지사님이나 원장님의 의지와 틀린 연구과제라도 발표하고 정치적인 선택을 하는 것은 원장님이나 지사님의 권한에 있다고 할 수도 있지만 연구과제 자체를 발표 안 하고 있다는 것은 문제가 있습니다.  더군다나 아까 원장님 답변내용에도 보면 일부 수정하고 있다라고 한다면 그 연구논문 자체는 과연 신뢰도가 떨어지지 않겠느냐.  이런 논쟁이 있기 전에 그런 것이 있다고 발표했더라면 그 논문에 대한, 과제에 대한 신뢰도는 높지만 이러한 논쟁이 있은 다음에 원장님이나 지사님의 의지를 거기에 포함시킨다면 그 연구과제는 생명을 잃지 않았느냐라고 생각합니다.  어떻게 생각하시지요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 저희가 연구결과를 어차피 발표해야 되겠다고 결심한 이후에 생각은 저나 지사의 의지를 거기다 심는 것이 아니고 그것이 1년 전에 수행한 연구이기 때문에 그 동안에 여러 가지 예산적인 수치라든가 신행정수도하고 관련된 사항이라든가 여러 가지 여건변동이 생겼습니다.  그 부분을 객관적으로 반영해서 좀더 시의 적절한 연구결과를 제출하고자 저희가 간단하게 수정하고 있는 것입니다. 
</p>
<p><b>○ 이흥규 위원 </b> 그 부분은 원장님의 생각이 맞지 않다고 생각합니다.  연구과제는 연구한 그대로 발표하는 것이 연구의 신뢰도에 적정성을 기할 수 있다고 봅니다.  더군다나 경기개발연구원의 목적은 지사님이나 원장님의 정치적인 저거를 여기다 넣으라고 하는 목적은 없습니다.  경기도의 발전과 도민의 삶의 질을 위한 전문적 연구수행기관으로서 중앙과 지방의 정책조화와 균형발전을 위해서 있다라고 했거든요.  그런데 거기다 대고 지사님이나 원장님의 생각을 집어넣으면 이것은 경기개발연구원의 당초 목적대로 활용하고 있지 않다라고 보지요.
</p>
<p style="padding-left:1.2em">  그 실례로 보고서 51페이지에 보면 2003년도 행정사무감사 처리 요구사항 조치결과에서도 그런 것이 여실히 나와 있습니다.  "국가균형발전 개정, 신행정수도 건설, 지방분권, 지방특화발전특별법 제정 등 정부시책에 대한 연구원 대비책을 강구하기 바람" 했는데 그 중간에 보면 신행정수도 건설에 대해서는 행정수도이전이 경기도에 미치는 영향의 행정수도이전의 정치적 타당성에 관한 연구를 수행하였고, 수행만 하면 뭐 합니까?  그 부분을 지사나 연구원장이 활용을 못하고 감추고 있었는데.  그러면 과연 공적인 연구기관으로서 제대로 역할을 수행했다고 봅니까?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그 부분에 대해서는 저희가 전혀 감춘 적이 없습니다.
</p>
<p><b>○ 이흥규 위원 </b> 그러면 그 연구결과를 지사님이 봤기 때문에 지사님이 신행정수도에 대해서 이명박 시장보다는 적극적이지 못하고 소극적이라는 평가를 받았습니까?  오히려 그렇다고 한다면 지사님이 명분이 있다고 할 수 있겠지요.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 이 연구결과하고 지사님의 태도하고는 아무런 관련이 없는 것으로 알고 있습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 본 위원이 봤을 때는 이 연구과제 결과가 나온 것을 가지고 저도 의회에서 행정수도반대특별위원회가 구성될 때 순수한 마음에서, 우리 경기도가 행정수도가 옮겨질 때에 이점은 뭐고 불이익은 뭔지 그것이 알고 싶었거든요.  그런데 그런 부분을 얘기했어도 집행부도 제대로 자료를 준 적이 없었고, 물론 제가 찾아보지 못한 것도 있지만 이렇게 연구과제가 사장되어 있었다는 부분을 심히 유감으로 생각합니다.  물론 연구원에서는 은폐하지 않았다라고 얘기하지만 그 자료는 국감에서 국회의원이 제기하기 전까지는 경기도 어디에서도 행정수도가 이전하면 남부지역이 이익을 보고 전체적으로 봐서 이익을 본다라는 주장은 없었거든요.  중앙정부에서는 있었지만 경기도 자체에서는 그런 부분은 하나도 없었다 이거지요.  연구과제로 해놓고 그것을 사장시킨다면 무슨 의미가 있겠습니까? 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 지난 번 국감에서 문제가 됐던 것은 그 연구과제를 저희가 전혀 사장하거나 숨긴 것이 아닙니다.  연구과제가 끝나자마자 다른 연구과제와 함께 배포를 했고 그것을 교보문고를 비롯해서 전국 다섯 군데 서점에서 판매가 되었고, 또 그 자체가 저희 연구원 홈페이지에 전문이 게재되어 나갔습니다.  다만, 많은 사람들이 그런 연구가 있었는지, 그런 연구결과서를 본 적이 없고 또 그것이 널리 홍보되지 못한 측면은 있습니다.  그것을 국감장에서 어느 의원께서 들고 나왔을 때 저희가 그것을 숨기거나 감출 의도가 있었다는 것처럼 왜곡했기 때문에 그것이 그렇게 나온 것이지 저희 연구원에서 연구결과를 전혀 은폐하거나 감출 의도가 없었습니다.  다만, 나중에 보니까 연구의 결과가 일반인들이 쉽게 이해할 수 있는 정도로 연구의 결과가 나오지 못한 부분이 있었습니다.  그래서 오해의 소지가 있었던 것은 사실입니다.  그래서 아까 제가 오전에 말씀드린 것처럼…….
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 그 부분에 대해서는 사실 어떻게 보면 그렇게 오해를 받고, 교보문고에서 판매했었기 때문에 공개했다라고 하는 부분은 어떻게 보면 궁색한 답변이지요.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 왜냐 하면 저희가 은폐나 감출 의도가 있었느냐 하는 질의에 대해서 다른 연구결과물과 똑같이 취급했다는 것을 말씀드리기 위해서 하는 겁니다.  전혀 그런 의도가 없었습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 의도가 없었다고 하니까 믿겠습니다만 그래도 그 부분을, 경기도로 봤을 때는 중요한 과제라고 생각합니다.  경기개발연구원이 서울대학교에 용역을 줬을 때는 중앙정부는 경기도에 이익이 된다고 하고 경기도의 입장에서는 이익이 안 된다라고 생각했을 때에 그래도 객관적인 평가를 보기 위해서 제3자인 서울대학교에다 용역을 준 것입니다.  어떻게 보면 객관적인 자료가 나왔다라고 할 수 있는 부분인데 그 부분을 은폐는 아니더라도 공개를 안 하려고 노력한 건 사실지요.  그런 점을 봤을 때 어떻게 보면 경기개발연구원이 공개적이지 않고 너무 정치적으로 흐르는 것 아니냐 그런 생각이 듭니다.  십분 이해하실 수 있겠지요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 정치적으로라고 하는 것에 대해서 정치라는 것이 좋은 것이다라고 하는 뜻에서 인정하겠습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 앞으로도 경기개발연구원의 과제가 분도관련 과제처럼 금방 연구과제가 나와서 보류하고 있다든가 이렇게 객관적인 연구과제가 나왔을 때 적극적으로 활용하지 않은 점에 대해서는 너무 본 위원은 정치적이었다라고 생각하고 향후에는 연구과제는 있는 그대로, 우리 입맛에 쓰든 달든 있는 그대로 발표될 수 있는 진정한 연구기관으로 거듭나기를 바라겠습니다. 
</p>
<p style="padding-left:1.2em">  한 가지만 더 질의 드리겠습니다.  자료집에 2003년도와 2004년도 경상예산 집행내역을 살펴보면 2003년도에는 79.6%가 집행됐고 2004년도 10월 현재는 57.7%가 집행됐습니다.  자료상으로는 특히 예비비의 경우 사용실적이 하나도 없는 것으로 나타나고 있습니다.  원장님은 이 부분에 대해서 집행실적이 저조한 부분하고 예비비 사용한 내용이 있는지 답변해 주시기 바랍니다.  자료 65페이지입니다. 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 저희가 정확하게 분석은 못했습니다만 이 부분에 대해서는 아마 4∼5개월 동안 원장이 공석이었었고 연구진행은 예년처럼 진행되는데 예산집행이 금년에 특별히 덜 된 것으로 파악이 되고 있습니다.  제가 앞으로 남은 기간에 예산집행을 좀더 신속하게 해 나가서 이월되는 분야가 없도록 최선을 다하겠습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 아무튼 올해에 원장님이 공석이었던 부분도 있습니다만 2003년도의 집행내역도 79.6%라고 한다면 경기도의 집행률보다는 훨씬 떨어지거든요.  올해도 10월 현재로 57.7%라고 하면 위원 입장에서 보면 경기개발연구원의 예산이 너무 많은 것 아닌가 이런 오해를 갖게 됩니다.  특히 중요한 것은 다른 것도 중요하지만 연구과제사업이 2003년도에는 73.9%, 2004년도에는 51.8%밖에 안 되는 예산이 집행됐거든요.  이 부분 연구하셔서 집행이 가능한 것은 빨리 집행하고 그렇지 않은 것은 다른 데로 돌려서라도 더 중요한 과제에 쓸 수 있도록 하시는 것이 낫겠다고 생각합니다.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 금년 연말까지 예년수준 이상으로 예산이 집행되도록 노력해 나가겠습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 예비비 사용한 실적은 없지요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 없습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 작년에도 없고 올해도 없고요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 네.
</p>
<p><b>○ 이흥규 위원 </b> 사실 예비비가 작년보다 올해 더 많아진 이유는 규정 때문에 그렇습니까? 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 예산규모가 늘어나서 지금 예비비는 전체예산의 1%를 계상하고 있습니다.  예산규모가 늘어나니까 늘어나는 걸로.
</p>
<p><b>○ 이흥규 위원 </b> 그런 내용이죠?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그렇습니다. 
</p>
<p><b>○ 이흥규 위원 </b> 규정 때문에 그렇다고 보이는데 경기개발연구원에서 예비비를 쓸 수 있는 사업이라면 뭐가 있을까요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 저희가 만약에 분도관련 연구를 안 했다.  그런데 지금 급히 분도관련 연구를 해야 된다면 아마 다른 데 예산이 없으면 그 정도의 사안에 대해서는 예비비를 쓸 사항이 아닌가 생각합니다.  그렇지만 지금까지 그렇게 급박한 예비비 사용 사례가 나온 적이 없기 때문에 그냥 미집행으로 넘어가고 있는 겁니다.
</p>
<p><b>○ 이흥규 위원 </b> 예비비는 그런 성격이 아닌 것 같은데요?  연구과제 예산이 따로 있는 관계에서 그쪽 예산에서 써야 될 부분이지 예비비, 아무튼 예비비 집행이 안 되고, 하나 더 본 위원이 생각하기에는 경기개발연구원에 예비비가 이렇게 많이 필요하지 않겠다고 생각이 들거든요.  그 부분은 공감하시죠?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 네.  예비비라고 하는 것은 어떤 상황이 닥칠지 모르기 때문에 설정해 놓은 항목이 예비비인데 만일에 예비비 설정을 안 해놓으면 어떤 급박한 시점에 연구를 못하거나 아니면 다른 편법에 의해서 예산을 집행하거나 하는 그런 사유가 발생하기 때문에 예비비 1%라고 하는 것이 많은지 적은지는 잘 파악을 못하겠습니다마는 어느 정도의 예비비는 정말 특단의 대책을 강구해야 될 때를 대비해서 있는 것이 좋다고 생각합니다.
</p>
<p><b>○ 이흥규 위원 </b> 물론 예비비가 없어야 된다는 논리는 아니고요.  물론 있어야 되겠죠.  그런데 현재 작년이나 올해 집행된 내용을 제로라고 봤을 때 지금보다는 적어도 되지 않겠느냐는 얘기입니다.  아무튼 경상경비부분은 이렇게 간단하게 지적하고요.  원장님이 적극적으로 하시겠다고 하니까 넘어가겠습니다.  저는 경기개발연구원이 당초의 목적대로 경기도의 싱크탱크로 활용되기를 기원합니다.  지금까지 일부 언론에서 비쳐지는 것처럼 지사의 사유물로 비쳐지지 않도록 적극 노력해 주시기를 바라면서 간단하게 마치겠습니다.  이상입니다.
</p>
<p><b>○ 위원장 정인영 </b> 이흥규 위원님 수고하셨습니다.  다음 질의하실 위원 거수로 신청해 주시기 바랍니다.  진종설 위원 질의해 주시기 바랍니다.
</p>
<p><b>○ 진종설 위원 </b> 세계 속의 경기도, 동북아 경제중심의 경기도를 만들기 위해, 또 도민의 삶의 질 향상을 위해 연구개발에 진력하시는 한현규 원장님 이하 임직원 그리고 연구원 여러분께 감사를 드리면서 몇 가지 질의를 드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  고양시 출신 진종설 위원입니다.  질의에 앞서 자료요청을 몇 가지 하도록 하겠습니다.  요즘 거론되는 분도와 관련된 대응자료를 제시해 주시고 남북포럼의 발제자료와 토론자료를 제시해 주시기 바랍니다.  그리고 세 번째로 경기서북부 관광벨트화 추진에 관한 연구자료를 제출해 주시기 바랍니다.  본 위원이 요구한 자료 중에서 몇 가지만 질의를 드리도록 하겠습니다.  의뢰받은 용역사업 중에서 재위탁현황이 총 36건에 23억 8,500여 만원인데 총 연구사업비 연구건수에 비해서 좀 과다하다고 생각되지 않으시나요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 이것은 제가 파악하기로는 외부에서 우리가 수탁받아서, 시ㆍ군이라든가 다른 기관에서 수탁을 받은 과제 45억원 중에서 절반 정도를 우리, 또 다른 외부로 주는 겁니다.  그러니까 다시 말씀을 드려서 외부에서 저희한테 연구용역을 의뢰하는 사업 중에서 상당부분은 우리가 그 분야에 전문성이 없거나 그런 인력이 없거나 아니면 이쪽에서 시간이 없거나 해서 외부에 준 사항이기 때문에 그거 가지고 전체적으로 연구기본과제라든가 정책과제라든가 이런 걸 토털 하면 수탁비율이 20% 정도가 안 되는 걸로 파악하고 있습니다.  다만 수탁과제는 그 성질상 예를 들어서 외부에 엔지니어링 용역을 준다든가 여러 가지 그런 면에서 불가피한 측면이 없지 않나 생각이 됩니다.
</p>
<p><b>○진종설 위원 </b> 외부의 수탁이라는 것이 거의 대부분 경기도 내의 시ㆍ군인데 그 시ㆍ군에서 수탁하는 것도 외부라고 하는 건가요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그렇습니다.  시ㆍ군에서 저희한테 하라고 준 용역 중에서 상당히 기술적인 부분은 저희가 못합니다.  그래서 여기 보시면 위탁사유 그래 가지고 하천수질 측정문제라든가 여러 가지 기술적인 문제들, 엔지니어링 측면에 있는 그런 것들을 우리가 외부에 줍니다.  그런 단가가 세고 그렇기 때문에 수탁과제 중에서 위탁되는 부분이 많은 것이 사실입니다.  그런데 전체적으로 보면 그렇게 큰 분량은 아니라는 말씀을 드립니다.
</p>
<p><b>○ 진종설 위원 </b> 그런데 본 위원이 보니까 인력의 문제가 되는 것 같기도 하고요.  또 사안에 따라서는 조사인력을 파트타임이나 학생들을 채용해서 일시적으로 써도 될만한 이런 것들이 있다고 보거든요.  그래서 앞으로는 그런 인력을 많이 필요로 하는 것은 일반적인 깊이 있는 연구용역이 아닌 이런 것들은 파트타임을 써서 하시면서 외부위탁은 좀 줄이도록 노력해 주시길 부탁드립니다.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그렇게 하겠습니다.
</p>
<p><b>○ 진종설 위원 </b> 좀전에 존경하는 함진규 위원님께서 질의한 것 중에 중복되는 걸로 판단되지만 좀 시각을 달리해서 본 위원이 질의드리도록 하겠습니다.  아까 시ㆍ군담당연구원제가 활성화되는 것이 경기도의 정책이 각 시ㆍ군에 고루 이해가 되고 정확하게 파급될 수 있는 그런 제도라고 보는데 아까 업무보고에서도 전문연구원직을 1명씩 시ㆍ군에 파견하는 걸로 추진하겠다고 말씀하셨는데 답변하는 중에는 인력이 달려서 애로가 있다고 말씀하셨어요.  그렇다면 인력을 좀 늘려야 될 필요성도 느껴지거든요.  물론 재정적인 뒷받침도 수반돼야 되겠지만 거기에 대한 견해를 좀 밝혀주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 이건 아까도 말씀드렸습니다마는 참 어려운 과제입니다.  최소한도 31개 시ㆍ군에서, 제일 좋은 방법은 31개 시ㆍ군이 다 저희 경기개발연구원 같은 연구원을 갖는 것이겠습니다마는 그게 불가능하니까 시ㆍ군 입장에서는 경기개발연구원이 이걸 좀 해줬으면 하는데 우리 입장에서 보면 1시ㆍ군을 담당하는데 최소한 한 사람 정도는 있어야 됩니다.  한 사람 정도 있다 보면 그것만도 31명입니다.  그런데 지금 우리 조직에 있는 박사 숫자가 35명인가 36명인가 그렇습니다.  조직이 지금보다 두배 세배 되기 전에는 시ㆍ군의 요구를 다 충족시키지 못할 그런 상황입니다.  그래서 한 쪽으로는 우리의 규모와 조직을 늘려나가야 되겠습니다마는 현재로써는 지금 있는 조직과 예산규모를 가지고 가급적 우리 연구원들이 시간을 쪼개서 시ㆍ군의 요구에 어떻게 부응하는 방안을 찾아내느냐 하는 것이 지금 당장 시급한 과제이고 그렇다 보면, 위원님들 생각해 보십시오.  엊그제 여기 이사왔는데 벌써 우리 조직규모가 두배 세배 는다면 이런 빌딩을 또 새로 지어야 되고 그런 면에서 보면 참 달성하기 쉬운 과제는 아니라고 봅니다.  그렇지만 기본적으로 나가야 될 길은 그 길이고 그 범위 안에서 우리가 현재 있는 가용재원과 가용인력을 활용해서 시ㆍ군을 도와주는데 최선을 다하겠습니다.
</p>
<p><b>○ 진종설 위원 </b> 적극적으로 활성화될 수 있도록 연구원제가 정착됐으면 하는 마음에서 질의드렸습니다.  같은 맥락의 질의인데 연구원 대외활동 또한 지극히 미미하거든요.  이것 또한 연구인력이 부족하다고 보는데 지금 재위탁을 하고 시ㆍ군 담당연구원제 또 연구 대외활동이 아주 미미한 것 이런 등등을 종합해 볼 때 결국 재정인력이 부족하다고 볼 수밖에 없거든요.  그러면 재정인력이 부족한데 또 인력을 보강할 수도 없는 처지에 있다고 말씀하신 걸로 이렇게 받아들여지는데 이런 상태에서 극대화할 수 있는 방안을 적극적으로 세워주시기를 당부드리면서 간단하나마 질의를 마치겠습니다.  이상입니다.
</p>
<p><b>○ 위원장 정인영 </b> 진종설 위원님 수고하셨습니다.  감사를 진행하는 동안 시간이 많이 흘렀습니다.  휴식을 위해서 감사중지를 하고자 하는데 이의 없습니까?
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
