<p><b>○ 위원장대리 이흥규 </b> 좌석을 정돈해 주시기 바랍니다.  계속해서 감사 질의ㆍ답변을 진행토록 하겠습니다.  다음 질의하실 위원 계시면 거수로 신청해 주시기 바랍니다.  박영신 위원 질의해 주시기 바랍니다.
</p>
<p><b>○ 박영신 위원 </b> 박영신입니다.  행정사무감사 일정이 변경됐는데도 철저하게 행정사무감사 준비를 해주신 한현규 원장님을 비롯한 경기개발연구원 임직원들한테 다시 한 번 감사의 말씀을 드립니다.  아마 경기개발연구원이 생긴 이후 금년이 대변화가 있던 한 해가 아닌가 생각합니다.  새로운 청사 이전으로 여러 가지 사무실 분위기도 많이 바뀌었고 또 제가 와서 보니까 아주 훌륭한 청사를 마련한 점, 모든 분들께 늘 쾌적한 업무능력을 발휘할 수 있게 돼서 대단히 감사하고 축하를 드립니다.  더욱이 평소 존경하고 늘 많은 행정적인 경험을 갖춘 한현규 원장님이 취임한 점 다시 한 번 축하드리면서 경기도민들의 큰 기대에 부응해 주시기를 부탁드립니다.
</p>
<p style="padding-left:1.2em">  손학규 지사가 취임한 이후 경기도 도정발전의 여러 가지 계획 중에서 경기도를 동북아의 중심으로 만들어야 된다.  그래서 여러 가지 많은 연구를 하고 특히 중국에는 경기도하고 자매결연을 맺은 지역이 두 군데나 있어서 빈번하게 교류를 하고 있습니다.  또 지금 한국의 많은 기업체들이 중국에 진출해 있고 중국을 모르면 앞으로 여러 가지 경제적인 면에서 뒤떨어질 수밖에 없다.  또 현재 중국의 경제적인 발전속도는 세계가 놀랄 만큼 많은 변화를 가져오고 있습니다.  그런 때에 우리 경기개발연구원에는 중국에 대한 전문가들을 얼마나 가지고 있으며 활용을 어느 정도 하고 있는지 그 점에 대해서 답변해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 박 위원님 말씀하신 것처럼 어느 덧 중국이 한국경제가 벤치마킹할 정도로 좋은 성적을 보이고 있습니다.  저희도 한 2년 전에 대만에서 석사를 하고 중국 북경대학에서 경제학을 한 이수행 박사를 채용해서 중국에 관한 연구를 본격적으로 하고 또 중국과의 상호 연구를 추진하고 있습니다마는 이수행 박사 혼자 힘 가지고는 안 될 것 같습니다.  앞으로 좀더 많은 중국전문가를 영입해서 보다 긴밀한 중국과의 협력관계를 모색해 나가도록 하겠습니다.
</p>
<p><b>○ 박영신 위원 </b> 그러면 현재 중국전문가는 이수행 박사 한 분이신가요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그렇습니다.
</p>
<p><b>○ 박영신 위원 </b> 하여튼 연구원 나름대로 여러 가지 사정이 있겠지만 중국에 대해서 우리 경기도에서 많은 연구가 필요한 시점이라고 생각합니다.  어제 우리 기획위원회가 제2청 감사를 실시했습니다.  2청에서 외부기관에 연구용역 준 게 상당히 많더라고요.  그런데 연구용역 준 기관을 보니까 경기개발연구원은 하나도 없고 오히려 제3의 연구기관들에 다 연구용역을 줬어요.  제가 볼 때 감사를 하면서도 경기개발연구원이 경기도의 싱크탱크로서 역할을 다하고 있다고 생각하고 있는데 2청에서는 그런 생각을 하고 있지 않은 것 같다.  그쪽에는 그렇게 얘기했지만 제가 속으로는 경기개발연구원이 우리 것도 챙기지 못하는 게 아닌가.  그러면 어떻게 연구실적이라든지 외부 연구용역을 수주할 수 있는가.  그래서 좀 안타까운 생각이 듭니다.  그 점에 대해서 잘 아시는 분이 누구예요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 제가 답변을 올리면 아마 도 본청하고 하는 기본과제 이런 것들이 분명히 2청에서 요구해 가지고 저희가 2청과 함께 하는 것이 있을 걸로 압니다.  다만 2청에서 연구용역을 외부에 준 것은 저희 경기개발연구원이 아까 말씀드린 것처럼 어떤 엔지니어링 분야에 대한 그런 연구능력을 가지고 있지 못하기 때문에 주로 엔지니어링 분야의 연구용역이 아닐까 생각되고 학술용역 같은 것은 2청에서 다른 외부용역기관에 주는 것이 있다면 그것은 저희 능력범위 안에서 되도록이면 저희를 활용하도록 2청하고 협력해 나가겠습니다.  잘 부탁드립니다.
</p>
<p><b>○ 박영신 위원 </b> 네.  아까 원장님이 앞으로 경기개발연구원이 2005년도 이후 해야 될 과제 중에서 행정수도이전문제, 지방분권문제 또 수도권 규제완화문제에 대한 말씀을 해주셔서 공감대를 가지고 있고요.  그런데 저는 그중에서 행정수도이전문제에 대해 얼마 전 서울대학교 용역 준 문제, 존경하는 우리 이흥규 위원님께서 아까도 질의하셨는데 신행정수도와 고속철도사업이 수도권에 미치는 영향 이 연구과제가 결론은 하여튼 수도이전이 도내 총생산 8조원의 순소득 증산을 가져오고 또 충청권에는 132조원이라는 10년 동안 어마어마한 그런 생산의 증거가 있다는 연구결과가 나왔습니다.  하여튼 어떻게 연구가 되는지 모르지만 저는 그 과정에서 이 연구과정을 선정할 적에 어떤 절차로 선정하는지, 담당을 하는 분이 누구십니까?  조응래 부장님이 담당이셨나요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 지우석 박사가 그것을 담당했습니다.  지우석 박사한테 직접 답변 올리도록 하겠습니다.
</p>
<p><b>○ 교통정책연구부연구위원 지우석 </b> 교통정책부 지우석입니다.
</p>
<p><b>○ 박영신 위원 </b> 지우석 박사님이 이 연구의 주연구원입니까?
</p>
<p><b>○ 교통정책연구부연구위원 지우석 </b> 주가 아닙니다.
</p>
<p><b>○ 박영신 위원 </b> 그러면요?
</p>
<p><b>○ 교통정책연구부연구위원 지우석 </b> 외부 전문가들에게 저희가 필요한 연구과제에 대해서 위탁을 부탁드리는 과제고요.  저는 그 과정에서 연구의 행정적인 절차나 연구가 잘 마무리될 수 있도록 옆에서 관리하는 그런 책임이 있습니다.
</p>
<p><b>○ 박영신 위원 </b> 그러면 신행정수도와 고속철도사업이 수도권에 미치는 영향을 정책과제로 선택하고 용역을 주게 된 과정을 한번 설명해 주세요.  경기개발연구원의 어떤 절차를 밟았는지.
</p>
<p><b>○ 교통정책연구부연구위원 지우석 </b> 위탁과제를 발굴하는 절차가 제가 알기로는 두 가지가 있는데요.  하나는 외부 연구기관에서 제안하는 경우가 있고요.  또 한 가지는 저희가 과제를 발굴해서 외부기관에 위탁을 하는 경우가 있습니다.  이 경우는 저희가 연구과제를 발굴해서 외부전문가에게 위탁을 의뢰한 그런 케이스가 되겠습니다.
</p>
<p><b>○ 박영신 위원 </b> 그러면 연구과제를 개발해서 과제 선택이 됐지 않습니까?  연구기관이나 연구용역을 누구한테 줄 건지는 누가 결정합니까?
</p>
<p><b>○ 교통정책연구부연구위원 지우석 </b> 그것은 저희가 공람을 하고요.  프로포절(proposal)을 받아서 가장 적임자라고 생각되는 분을 선정해서 위탁하게 됩니다.
</p>
<p><b>○ 박영신 위원 </b> 이번에 적임자한테 잘 줬습니까? 
</p>
<p><b>○ 교통정책연구부연구위원 지우석 </b> 제가 판단하기에는 지금 이 연구를 책임하시는 분이 인구이동 관련된 부분에 있어서 많은 논문을 냈고 또 그 부분의 모형부분에서 권위가 인정되는 분이라고 판단돼서 그렇게 결정했습니다.
</p>
<p><b>○ 박영신 위원 </b> 박사님이 잘 아시겠지만 어떤 데이터를 입력하느냐에 따라서 또 누가 어떻게 목표를 설정하고 그 연구를 하느냐에 따라서 180도 다릅니다.  그렇죠?
</p>
<p><b>○ 교통정책연구부연구위원 지우석 </b> 네, 맞습니다.
</p>
<p><b>○ 박영신 위원 </b> 그러면 경기도는 현재 또 우리 원장님이나 지사님이나 도의회를 보면 100%는 아니겠지만 거의 다 수도이전을 반대하고 있습니다.  그렇죠?  이것은 충청도에서 연구용역을 준 결과라야지 어떻게 경기도에서 준 용역이 이렇게 결과가 나옵니까?
</p>
<p><b>○ 교통정책연구부연구위원 지우석 </b> 그 부분에 대해서는 저도 드릴 말씀이 없을 정도로 반성과 또 관리를 잘못한 데 대한 책임을 통감하고 있는데요.
</p>
<p><b>○ 박영신 위원 </b> 이런 연구원에 우리가 자본금을 100% 출자하고 예산을 지원할 일이 뭐 있습니까?
</p>
<p><b>○ 교통정책연구부연구위원 지우석 </b> 그 당시 연구를 처음에 의뢰할 때는 사실 대한민국 내 시ㆍ도간 비교에는 연구의 목적이 없었고요.  만약에 행정수도가 남부로 내려가게 된다면 경기도 내 시ㆍ군간 인구의 이동 부분에 초점을 맞춰서 했습니다.
</p>
<p><b>○ 박영신 위원 </b> 아니, 어떻든 간에 수도이전이 안 되면 인구이동이 있다는 건 다 맞는단 말씀이에요.  그건 다 알고 있어요.  그러면 결과적으로 그게 인구이동이 되고 그러는데도 경기도의 총생산이 8조원 늘어난다는 게 어떻게 가능하냔 말씀이에요.  또 어떻게 충청권에는 132조원이라는 막대한 생산의 증가가 이루어지냐 이 말이지.  물론 데이터는 있겠지만 가끔 보통 사람들하고 박사님들하고의 견해차이가 모든 게 다 보통 사람들의 생각이, 보통 사람들이 이해할 수 있는 그런 범주가 있어야 되거든요.  안 그렇습니까?  그게 만일 보통 사람들의 생각하고 동떨어진다면, 물론 그럴 수도 있겠죠.  하지만 이 연구에서는 도저히 이해할 수 없는 것이고 또 경기개발연구원에서 이런 연구용역 결과물을, 아까 보니까 원장님이 말씀하신 것 중에서 존경하는 이흥규 위원님께서 질의하신 경기분도에 대한 연구결과 발표를 안 할 수 있다.  이런 답변을 하고 현재 안 하고 있습니다.  그러면 이게 경기도민들이 다 반대하고 경기도에서도 수도이전반대특위를 만들고 원장님도 TV에 나와서 반대하고 지사님도 그냥 단호하게 수도이전 반대한다는 그런 마당에 이런 연구용역을 공식적으로 배포하고 인쇄하는 게 경기개발연구원이 해야 될 일이냐 이 말이에요.
</p>
<p><b>○ 교통정책연구부연구위원 지우석 </b> 그 연구결과를 조금 자세하게 말씀드리면 사실은 절대치의 비교는 무리가 있다고 연구보고서 내용에 지적이 있습니다.  그래서 지금 문제가 돼 있는 그런 부분들을 보완해서 시ㆍ도간의 비교를 절대치 화폐가치로 비교할 수 있도록 지금 모형을 다시 만들어서 산정결과를 곧 내도록 조치하고 있습니다.
</p>
<p><b>○ 박영신 위원 </b> 물론 한현규 원장님 오시기 전에 연구성과물이, 과제물이 결정되고 했지만 연구원에 부탁하는 것은 연구과제를 선택하는 것도 중요하지만 누구한테 용역을 줄 거냐 하는 것을 엄청 신중하게 해야 됩니다.  지금 이런 연구용역결과를 충청권에서 얼마나 홍보하겠냐 이 말이야.  경기도에서 100% 출자한 경기개발연구원에서 한 결과가 경기도에도 8조원 플러스가 되고 충청권에는 132조원이 된다.  우리가 그 사람들을 위해서 연구원을 설립했습니까?  문제는 이게 정부기관 같았으면 벌써 난리가 났을 겁니다.  이 문제에 대해서는 누군가가 책임을 지고 현 체제 갖고 안 된다면 우리 경기개발연구원의 내부 조직개편이라든지 지휘체계가 다시 개선돼야 돼요.  연구원들로만 이루어진 체제가 아니라 정말 경기도의 뜻이 반영될 수 있는 그런 체제로 변형돼야 되지 않느냐는 생각을 하고 있습니다.  그 점에 대해서는 한현규 원장님이 답변해 주시죠.  박사님 들어가세요.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 이 연구에 대해서는 사실 저도 원장에 취임한 이후에 안 사실이었습니다마는 입이 열 개라도 저희가 변명하기 힘든 연구원의 명백한 잘못이 있습니다.  다만 제가 연구원들하고 쭉 얘기를 해본 결과 이것이 작년 1년 전에 시작한 연구입니다.  1년 전의 상황에서 연구원들이 그 당시 행정수도후보지도 결정이 안 됐고 행정수도 이전한다고 하는데 설마 이전하겠느냐.  그래서 이것을 행정수도이전에 대해서 논리적으로 잘 분석해서 대응을 하겠다는 그런 절박성이 없었던 듯합니다.  그래서 연구의 목적 자체가 행정수도이전에 대해서 경기도에 어떤 영향을 미치고 경기도에 플러스 영향이냐 마이너스 영향이냐, 그것에 대해서 찬성해야 되느냐 반대해야 되느냐 이런 포지션을 정하기 위한 연구가 아니고 연구 자체가 만약에 행정수도가 이전한다면 하는 가정 하에서 경기도 내에서 어떤 인구구조의 변화가 생기겠느냐.  즉 이천은 인구가 빠질 거냐 늘어나느냐, 수원은 인구가 빠지냐 늘어나느냐, 동두천은 어떻게 되느냐.  이런 경기도 내에 시ㆍ군간의 인구이동분석모형을 만든 겁니다.  그런데 그것으로만 끝이 났어야 되는데, 사실은.  고속철도도 마찬가지입니다.  고속철도도 이미 고속도로가 다니고 있으니까 그것으로 인해서 경기도 안의 인구분포가 어떻게 되느냐.  그것으로만 연구를 했으면 또 나름대로 의미가 있었겠는데 그것에 그치지 않고 타 시ㆍ도는, 예를 들어서 충청도나 전라도나 이런 데는 또 시ㆍ군별로, 이것을 나눠서 분석하지 않고 그것을 뭉뚱그려서 하나의 도를 또 분석했습니다.  경기도는 잘라서 분석하고 다른 시ㆍ도는 뭉뚱그려서 분석하고 기획기법이 서로 틀리다 보니까 결과가 사실은 부정확하게 나온 겁니다.  그 부정확하게 나온 결과를 연구원에서 잘 한번 심사해 가지고 연구방법이 틀렸느냐 맞았느냐 다시 한 번 검증을 해봐라 하는 그런 과정이 있었어야 되는데 이 연구의 목적이 당초에 그렇게 절박감에서 시작된 연구가 아니고 그냥 행정수도 이전한다고 하니까 될지 안 될지 모르겠습니다만 된다고 하는 가정 하에서 경기도 문제를 해결해 보자는 그런 느슨한 목적에서 시작된 연구이다 보니까 그것을 못했던 겁니다.  나중에 행정수도 후보지가 결정되고 정부 여당에서 그것을 실제로 추진하다 보니까 우리가 그랬으면 훨씬 더 객관적인 방법으로 객관적인 모델을 만들었어야 하는 것 아니냐 하는 자성론이 일어나고 그랬었는데, 그래서 저희가 곧바로 그 일이 있고나서 연구방법을 처음부터 모델을 다시 만들어봐라.  경기도도 도 전체로 놓고 시ㆍ군으로 쪼개지 말고 연구방법론에 있어서 객관성을 분석해서 결과가 지금 보완이 됐습니다.  보완된 결과 일반사람들이 예상하는 대로 경기도 쪽에서 인구도 빠지고 행정수도이전 안 했을 때보다 생산성도 낮아지고 하는 연구결과가 나왔는데 앞으로 이것을 어떻게 일반국민들한테 홍보하고 그래서 행정수도이전이 경기도에 불리한 영향을 미친다는 것을 객관적으로 증명하는 데 주력을 다하고 그것보다 더 중요한 문제는 아까 박영신 위원님 말씀하신 것처럼 이런 일이 일어나서는 안 됩니다.  이런 일이 일어나서는 안 되는 데 대해서 다시 한 번 사죄의 말씀을 드리면서 앞으로 외부위탁연구에 대해서 저희가 내부적으로 그것을 검토하고 객관성을 검증하는 일에 최선을 다하겠습니다.  죄송합니다.
</p>
<p><b>○ 박영신 위원 </b> 앞으로는 경기개발연구원에서 이런 경기도의 정서에 맞지 않는, 경기도의 여러 가지 정책방향하고 맞지 않는 연구결과가 나오지 않겠지만, 나올 수도 없겠지만 그런 일이 없도록 우선 경기개발연구원의 내부적인 시스템의 보완이 필요하다는 점을 다시 한 번 말씀드리면서 다시 한 번 한현규 원장님이 취임한 이후 경기개발연구원의 정말 변한 모습을 기대하고 우리 모두의 기대에 어긋나지 않도록 열심히 일해 주십사 하는 부탁의 말씀을 드립니다.  이상입니다. 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 알겠습니다. 
</p>
<p><b>○ 위원장대리 이흥규 </b> 박영신 위원 수고하셨습니다.  다음 질의하실 위원 계시면, 김영복 위원 질의해 주시기 바랍니다.
</p>
<p><b>○ 김영복 위원 </b> 가평출신 김영복 위원입니다.  다른 위원님들이 인사말을 많이 하셨기 때문에 인사말은 생략하고 바로 몇 가지 궁금한 사항이 있어서 질의드리겠습니다. 
</p>
<p style="padding-left:1.2em">  행정감사자료 692쪽에 2004년도 연구원 용역에 대해서 나오는데요.  본 위원이 이렇게 2004년도 연구과제 용역한 것을 보니까 한 30과제가 되는데 그 중에서 수도권성장관리기본계획 수립 연구용역이 총 연구용역비 받은 것 약 44억원 되는 가운데서 수도권성장관리기본계획 수립 연구용역이 한 20억원 됩니다.  또한 그만큼 금액이 많다는 것은 경기도 발전에 중요한 사항이다라고 봅니다.  그리고 아까 조금 전에도 한현규 연구원장님께서 연구수를 줄이고 앞으로 내용을 충실하게 한다고 말씀하셔서 거기에 대해서 질의드리겠습니다. 
</p>
<p style="padding-left:1.2em">  수도권성장관리기본계획 수립 연구용역을 해 가지고 용역수행기간은 2004년 1월 19일에서 2004년 11월 13일까지 하고 금액은 20억 5,926만 8,000원인데 여기 연구용역 중에서 용역을 하다가 처음 경기도하고의 계약 당시하고 나중에 내용이 틀려진 게 있지 않습니까?  계획과정하고.  그게 어떤 사항입니까? 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그 부분은 조응래 박사가 기술적인 부분을 답변하고 수도권성장관리 용역에 대해서는 제가 답변 하겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 답변 가능하신 분이 답변 부탁드립니다.  여기에는 연구자가 이상대 박사님으로 되어 있는데 안 계신가요?  누가 가능하신 분이 답변 바랍니다. 
</p>
<p><b>○ 교통정책연구부장 조응래 </b> 교통정책연구부장 조응래입니다.  성장관리계획에 당초에 비해서 과업이 줄어들었던 부분은 당초계획 3단계 용역에서는 관련되는 단지들에 대한 구체적인 계획까지 검토 추진하는 것으로 했다가 2단계 최종 결과보고하고 그러면서 3단계에서 단지에 대한 구체적인 계획까지는 수립할 필요가 없겠다 그래서 그 부분에 대해서는 용역내용을 다 뺐습니다.  그러면서 과업의 총액이 줄어든 내용이 되겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 그리고 본 위원이 행정감사자료를 보다 보니까 처음에 도하고 연구용역 협약한 것, 아까 말씀하신 것 말고도 해외출장에서 벤치마킹하고 와서 연구과제를 내는 사항이 있었는데 업무가 바쁘다는 이유로 해외출장을 안 가고 다른 자료를 대체해서 그것을 이용해 가지고 연구과제로 쓴 것으로 본 위원은 알고 있습니다.  그래서 이것은 어떻게 보면 임의적 판단이 아닌가 보는데 한현규 연구원장님께서 좀전에 연구수를 줄이고 내용을 충실하게 하겠다고 했는데 만약에 실제 이런 해외견학계획이 처음에 있었으면 갔다오셔서 나름대로 연구원의 좋은 내용으로 연구를 충실하게 할 수 있는 사항을 만들었어야 되지 않나 본 위원은 보는데 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 조금 옆으로 지나가는 얘기인지 모르겠습니다만 수도권성장관리기본계획은 연구원 설립이래 가장 큰 용역이 아닌가 싶습니다.  이것은 두 가지 목적에 의해서 시작하게 된 겁니다.  첫째는 우리 경기도가 중앙정부의 주택정책이나 도시정책이 맨날 난개발을 초래한다 난개발을 초래한다 하지만 난개발을 하지만 말라 그랬지 거기에 대한 대안을 내본 적이 없습니다.  그러면 난개발이 아닌 정개발이라고 하는 대안을 내놔야 하는데 그런 계획을 세워 본 적이 없었고, 또 한 가지는 매일 수도권 규제를 풀라고 합니다.  그런데 우리가 수도권 규제를 풀라고 할 때 중앙정부에서 하는 얘기가 수도권 규제를 풀면 수도권이 난개발 된다고 하는 논리를 펴고 있습니다.  그래서 수도권 규제를 풀면 수도권의 모습은 이렇게 될 것이다.  이렇게 수도권의 모습을 경기도가 그려가겠다 하는 모습을 제시하고자, 그런 청사진을 만들고자 수도권성장관리기본계획을 마련했습니다. 
</p>
<p style="padding-left:1.2em">  이 과정에서 이 연구용역이 상당히 크다보니까 우리 연구원에서는 사실 몇몇 사람만 연구책임자로 참석하고 상당히 많은 외부의 전문가들을 동원했습니다.  국토계획학회라든가 도시학회라든가 환경학회라든가 해서 수도권성장관리계획에 대한 전반적인, 앞으로 우군이 되어 줄 사람들을 이 연구를 통해서 많이 확보했습니다.  그 과정에서 연구기간도 길고 또 연구용역도 광범위해서 여러 차례 설계변경이 일어났습니다.  지금 김 위원님께서 말씀해 주신 해외출장 문제도 그렇고 아까 조 박사가 답변한 도시개발계획의 세부구상 같은 것도 연구단계에서 삭제가 됐고 많은 변동이 있었습니다만 당초 저희가 예상한 대로 지금 거의 연구용역이 법적으로는 한 일주일 전에 끝이 났고 지금 유인단계에 있습니다.  그래서 연말쯤 돼서 모든 성과품이 나오게 되겠습니다만 그 성과품을 가지고 여러 가지 변화된 모습의 지표에 따라서 저희가 집행하고 중요한 것은 중앙정부에 저희 계획을 제출해서 앞으로 중앙정부가 수립하는 수도권정비계획이라든가 아니면 수도권 광역도시계획이라든가 이런 데 적극적으로 반영해서 경기도만의 계획이 아니고 중앙정부의 계획으로 채택되게 함으로 해서 경기도가 좀더 살기 좋고 기업하기 좋고 교통이 편리한 대한민국 중심지로 발돋움할 수 있는 그런 계기를 마련하고자 노력하겠습니다.  앞으로 기회가 있는 대로 기획위원님들께 성장계획의 아웃풋을 가지고 브리핑하는 기회도 갖도록 하겠습니다.
</p>
<p><b>○ 김영복 위원 </b> 말씀은 공감합니다.  그런데 처음 계획부터 여러 번 계획이 있었고 그 중에서도 특히 경기도가 대처할 수 있는 방안, 다른 도하고.  그러니까 본 위원은 해외출장을 안 가고도 우리나라에서 어떤 사례라든가, 다른 나라 사례인지 몰라도 다른 자료를 이용해서 임의적으로, 추상적으로 경기도에서 갈 방향을 했다라고 본 위원은 보거든요.  그런데 본 위원은 그중에서도 나름대로 저희가 벤치마킹을 해서 그 방향을 제시했으면 더 낫지 않았나 하는 생각이 듭니다.  왜 그러냐면 우리나라의 사례를 어떻게 봤을 때는 경기도 같은 특이한 지역이 따로 없지 않습니까?  수도권에.  그래서 그런 방향을 외국 사례를 들어서 제시해 가면서 남을 설득하고 아까 같이 다른 외부전문가를 이용해서 뜻을 같이 할 수 있는 이런 것을 갖췄으면 더 좋지 않나.  그런데 여기 보니까 그 용역비가 6,157만원 정도 되는데 돈의 문제가 아니라 우리 경기도의 입장을 표시하는데 전문연구기관에서 문제제기를 했을 때에 문제점이 되지 않을까 그래서 질의드렸고요. 
</p>
<p style="padding-left:1.2em">  그리고 지금 여기 조사에서 보면 해외출장을 안간 게 연구과제도 많고 바빠서 어떤 다른 일이 있어서 못간 것으로 자료가 나왔습니다.  그런데 지금 연구원분들이 연구과제가 많은 건지, 아니면 다른 일이 그때 있어서 그랬는지 연구기간은 길은데 그 중에서 시간을 낼 수 없었는지 말씀해 주시기 바랍니다.  아니면 다른 뜻이 있었는지?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 해외출장비 관계는 이 연구를 맡은 이상대 박사가 양해해 주시면 답변토록 하겠습니다만 지금 김 위원님이 말씀하신 것이 중요한 지적이십니다.  다른 나라의 대도시권 하고 비교해서 경기도의 특색이라든가 혹은 경기도가 나갈 방향의 정당성을 구하는데 다른 나라 대도시권을 벤치마킹해야 하는 것은 사실입니다.  그런데 이번 연구에서 제가 나중에 보니까 그런 부분이 빠졌습니다.  그런 부분은 단순히 짧은 기간에 해외출장을 나간다고 될 것이 아니고, 그래서 제가 최근에 이 연구결과를 보고 바로 김 위원님이 주장하시는 것처럼 대도시권, 외국의 대도시권에 대한 연구가 결여되어 있다.  그래서 그것은 내년도에 별도로 수도권성장관리계획과는 달리 외국의 대도시권, 예를 들면 동경권은 어떻게 나가고 있느냐, 북경권은 어떻게 나가고 있느냐, 상해권은 어떻게 나가고 있느냐 하는 데 대한 심도 있는 연구를 통해서 그것을 가지고 외국도 이렇게 나가니까 우리나라도 빨리 수도권정비계획 폐지하고 성장관리계획으로 대체입법을 하고, 그런 논거를 만들기 위해서 별도의 용역을 실시할 계획입니다.  해외출장비 6,700만원에 대해서는 이상대 박사로 하여금 대신 답변드리도록 하겠습니다.
</p>
<p><b>○ 김영복 위원 </b> 그렇게 답변하시면 다른 것은 안 들어도 되겠습니다.  그래서 그 중요성에 대한 것을 하면 좋지 않겠나.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그렇게 하겠습니다.
</p>
<p><b>○ 김영복 위원 </b> 앞으로는 우리가 경기도의 발전을 위해서 대체할 수 있는 것을 폭넓게, 남들이 이해가 가기 쉽게 해주시기 바라겠습니다.  그리고 좀전에도 제가 인력관리에 대해서 여쭤봤는데 저희가 행정감사 전에 보니까, 2003년도 행정감사 할 때도 보니까 연구과제의 기한을 넘겨서 연구물이 나온 게 있습니다.  기본연구과제 같은 게.  그런데 거기에서 두 가지를 본 위원은 생각할 수가 있는데 연구하시는 박사님들이 바빠서 그럴 수도 있고, 나름대로 다른 사항이 있을 수도 있고 그런데 기본연구과제 수탁 같은 게 늦어지는 이유는 크게 뭐라고 생각하시는지 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 저도 사실 내용을 잘 몰랐는데 여기 와서 보니까 연구원들이 과제중심으로 일을 합니다.  기본과제, 수탁과제, 정책과제 해서 연구원 한 사람당 서너 건의 과제, 많으면 7∼8건의 과제 그렇게 하고 있는데.  사실 연구원에서 연구원 생활을 하다 보니까 그런 과제 이외에 우리가 해줘야 될 사항이 한두 가지가 아닙니다.  도청에서 그냥 보고서 하나 만드는데 통계자료 좀 달라, 또 어떤 경우에는 도의회에서도 빨리 뭐 하나 좀 만들어 달라.  제가 또 개인적으로 연구원장으로 있으면서 이거 빨리 해 와라.  이런 과제로 잡히지 않은 부분들이 굉장히 많은 것이 사실입니다.  그리고 그런 부분들이 또 상당히 중요합니다.  유인이 돼서 책자로 나오고 정식 연구결과로 발표되는 것은 아니지만 그때그때 도정이 돌아가고 의정이 돌아가고 하는 부분에 대해서 그때그때 지원해 줘야 될 일들이 굉장히 많이 있습니다.  그래서 그런 부분들에 대해서 연구원들은 개인적으로 굉장히 싫어합니다.  왜냐 하면 그거 잘 해준다고 해서 무슨 평가를 잘 받는 것도 아니고 그거 잘 해준다고 해서 승진이 되는 것도 아니고 그래서 그것을 귀찮아하는 면이 있습니다.  그럼에도 불구하고 우리 연구원 본래의 기능이 우리 도정이나 의정을 뒷받침 해주는 그런 일이기 때문에 싫지만 하게 되는 경향이 있습니다.  그런 것을 하다 보면 자기가 연구과제로 정식으로 해야 될 것들이 항상 시간적으로 뒤쳐지고 해서 연말에 몰리는 그런 결과가 생기고, 또 연구원의 연구성과를 평가하는 방법에도 문제가 있고 그래서 저희가 지금 전면적으로 연구원의 연구성과를 평가하는 평가방법을 바꾸려고 합니다. 그래서 정식연구과제뿐만이 아니고 우리가 얼마나 도정에 즉각적으로 이바지 했느냐, 또 의정에 이바지 했느냐.  또 아까 말씀드린 것처럼 얼마나 대외적으로 홍보를 많이 했느냐, TV에 나갔느냐, 신문에 기고가 됐느냐 하는 정식연구과제 이외에 지금까지 귀찮은 일로 취급되었던 그러한 일들을 제도권으로 끌어들여서 그것을 종합적으로 평가하는 시스템으로 가려고 합니다.  그렇게 되다 보면 지금까지 연구원 입장에서는 중요하지만 개인적으로는 허드렛일로 생각했던 것들이 좀더 신경을 쓸 수 있고 그런 과정에서 전체적인 정식 연구와 어떤 비공식 연구간에 균형을 연구원 스스로가 잡아나갈 수 있지 않을까 생각합니다.  그래서 앞으로 연구원 평가시스템을 고쳐서 연구원들이 양쪽 일을 다 효율적으로 할 수 있게끔 제도개선을 해 나가겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 한현규 원장님이 부임하고 나서 기본연구과제 같은 게 수행기간 끝나기 전에 마무리 못한 것을 연기가 된다라고 얘기들은 적이 있습니까?  또 승락해 준 게 있고?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 지금까지는 없습니다만 지금 거의 마무리단계에 들어가고 있습니다.  몇몇 연구원은 "도저히 못하겠습니다, 연기해 주십시오" 하고 저한테 부탁이 올 것으로 예상됩니다.  제가 알아서 판단하겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 왜 그런 말씀을 드리느냐면 2002년도에는 연구과제 30건 중에 29건이 연기가 됐고요.  2003년도에는 28건 중에서 27건이나 연기된 것으로 행정감사자료에 나옵니다.  맞지요?
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그렇습니다. 
</p>
<p><b>○ 김영복 위원 </b> 그런데 이상하게도 연구과제 결과가 그렇게 늦어지면서 연기가 됐는데 그것을 사실 연구원장님께 보고하고 승인 받게끔 되어 있는데 그때 당시는 이철규 원장님이 계셨습니다만 한 번도 맡은 게 없어요.  승인을 맡지 않고 그냥 나름대로 아까처럼 바쁘면 바쁜대로 해서 나중에 마무리짓고 이런 결과를 나았습니다.  맞지요?  그렇게 한 게.
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 당시에 아마 구두결재만 하고, 그러니까 이것이 이월되느냐 안 되느냐 하는 것은 제가 보기에 이렇습니다.  연구원들한테 무조건 연내에 끝내라고 목표를 정합니다.  목표를 정하기 때문에 연구원들 나름대로 끝까지 하려고는 합니다.  하려고는 하는데 거의 마지막 단계에 가서 며칠만 더, 한 주만 더, 두 주만 더 이런 것을 아마 지금까지 구두로 원장이 승인하고 그랬던 것 같습니다.  앞으로는 이런 것들을 문서화하고 이월하는 것에 대해서 좀더 엄격한 통제와 관리를 해 나가겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 그래서 본 위원은 보니까 심지어 8개월에서 1년 2개월까지 연기가 돼서 연구과제가 마무리된 게 있습니다.  그렇다면 지금 인원이 사실 아까 여러 가지 수탁과제들도 있고 도에서, 다른 행정기관에서 부탁하는 일이 있어서 그런지 몰라도 사실 우리 연구원들이 너무 일이 많은 게 아닌가.  그렇지 않으면 연구과제를 줄이든 연구원장님께서 말씀하신 연구수를 줄여서 내용을 하나라도 제대로 충실하게 뺄 수 있는 그런 데 연구원의 중요성이 있지 않나 보는데 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 그래서 이번 연구과제는, 특히 기본연구과제 같은 경우에는 예년하고 달리 도하고 여러 가지 연석회의를 통해서 정말 도에서 필요한 것만 엄선해서 선정한 경향이 있습니다.  그래서 이 연구과제를 수행함에 있어서, 아마 내년에도 이런 연구과제뿐만 아니고 제가 아까 말씀드린 것처럼 여러 가지 부수적인 일들이 많이 일어나게 될 것입니다.  제가 도청하고 도의회하고 의사소통 과정을 좀더 원활히 하는데 매개체가 돼서 연구는 연구대로 원활히 수행하고 도정의 다른 방안으로 우리가 공헌하는 것은 그것대로 효율성을 높여서 양쪽 다 원활히 해 나가는데 최선을 다하는 수밖에 없다고 생각합니다.  금년을 포함해서 내년에도 기본적인 연구과제들이 볼썽사납게 이월되는 일은 제가 있는 한 철저히 방지해 보도록 노력하겠습니다.
</p>
<p><b>○ 김영복 위원 </b> 본 위원은 그렇게 생각됩니다.  경기개발연구원이 사실 KRI비전 2006에서 동북아의 최고지역의 연구기관으로 남으려면 연구과제에 대한 것이 남들이 봤을 때 어떤 신뢰성이 있어야 된다고 봅니다.  숫자보다 질적으로.  그래서 앞으로는 그렇게 될 때만이 여기 KRI비전 2006에서 제시한 동북아 최고지역의 연구원이지 그렇지 않으면 사실 신뢰받기가 쉬운 게 아닐 겁니다.  그래서 앞으로는 거기서도 제시한 세계화의 흐름속에 동북아의 미래를 준비하는 최고의 연구기관으로 남는다고 말씀을 하셨는데 그렇게 될 수 있도록 해주시길 바라겠습니다.  이상입니다. 
</p>
<p><b>○ 경기개발연구원장 한현규 </b> 노력하겠습니다.
</p>
<p><b>○ 위원장대리 이흥규 </b> 김영복 위원님 수고하셨습니다.  더 이상 질의하실 위원 계십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원이 안 계시면 이상으로 경기개발연구원에 대한 질의와 답변을 모두 마치겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기개발연구원장을 비롯한 임직원 여러분!  장시간 열의를 갖고 감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료준비와 위원님들의 질의에 성실히 답변해 주신 한현규 연구원장을 비롯한 임직원 여러분께 감사드립니다.
</p>
<p style="padding-left:1.2em">  오늘 여러 위원님들께서 감사시에 지적해 주신 사항은 도민의 뜻이니 이를 겸허히 받아들여서 연구원 업무에 적극 반영될 수 있도록 최선의 노력을 다해주시기를 바랍니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 연구원 임직원 여러분!  수고하셨습니다.  그러면 이상으로 경기개발연구원에 대한 2004년도 행정사무감사를 마치겠습니다. 
</p>
<p class=''ar''>(16시42분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원
</b></p>
<p class=''aMan''>정인영김대원김영복박영신이효선이건희정금란진종설함진규이흥규</p>
<p><b>○ 행정사무감사보조공무원
</b></p>
<p><p class=''em15''>전문위원 오태철지방행정주사 박준호지방행정주사보 김민기</p>
<p><p class=''em15''>지방기능7급 김경애지방기능8급 정명숙</p>
<p><b>○ 출석증인
</b></p>
<p><p class=''em15''>경기개발연구원장 한현규기획조정실장 신원득정책개발센터장겸교통정책연구부장 조응래</p>
<p><p class=''em15''>자치행정연구부장 이용환도시지역계획연구부장 이성룡경제사회연구부장 이상훈</p>
                <!--// 회의록내용 --> 

            <p class="skip">맨위로 이동</p>

            <div','경기도의회',false,'{"legacy_id": "audit-3351", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=3351"}'::jsonb,'2004-11-26'::date,'2004-11-26'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-3351');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2003.11.26. 수요일] 경기개발연구원 — 기획위원회 2003년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제6대 경기도의회 기획위원회</b> · 2003년도 행정사무감사(2003. 11. 21. ~ 2003. 11. 28.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=3401" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2003년도 행정사무감사
</p>
<h4>기획위원회 회의록 
</h4>제3호
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일  시 : 2003년 11월 26일(수)
</p>
<p>장  소 : 경기개발연구원회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시33분 감사개시)
</p>
<p><b>○ 위원장대리 이원재 </b> 좌석을 정돈해 주시기 바랍니다.  지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례 제2조의 규정에 의하여 경기개발연구원에 대한 2003년도 행정사무감사 실시를 선언합니다.  위원 여러분, 그리고 연구원장을 비롯한 임직원 여러분!  안녕하십니까?  
</p>
<p style="padding-left:1.2em">  오늘은 우리 기획위원회 감사일정에 따라서 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다.  여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2004년도 예산안 심사자료 및 정보획득을 통해 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다 할 수 있습니다.  따라서 감사위원 여러분께서는 연일 계속되는 감사일정에 노고가 많으십니다마는 도민을 대표하여 도비 출연기관인 경기개발연구원의 운영실태를 감사하는 것인 만큼 심도있는 감사활동으로 소기의 성과를 거둘 수 있게 되기를 기대하며 아울러 감사에 임하는 연구원 원장님과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다.  감사를 받는 경기개발연구원장 및 실·부장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 됩니다.  선서를 하는 이유는 이번에 경기도의회가 2003년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다.  만약 증인이 허위증언을 할 때는 지방자치법 제36조제5항, 경기도의회행정사무감사및조사에관한조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부할 때는 동법 규정에 의하여 500만원 이하의 과태료가 부과될 수 있음을 알려드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 피감사 기관의 증인은 모두 자리에서 일어서 주시기 바랍니다.  먼저 증인출석여부를 확인하겠습니다.  경기개발연구원장님 나오셨습니까?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 사무처장님 나왔습니까?
</p>
<p><b>○ 사무처장 김봉규 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 기획조정실장 나왔습니까?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 자치행정연구부장 나오셨습니까?
</p>
<p><b>○ 자치행정연구부장 김동성 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 도시교통연구부장 나오셨습니까?
</p>
<p><b>○ 도시교통연구부장 지우석 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 경제사회연구부장 나오셨습니까?
</p>
<p><b>○ 경제사회연구부장 김흥식 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 환경정책연구부장 나오셨습니까?
</p>
<p><b>○ 환경정책연구부장 송미영 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 다음은 선서의 요령을 설명해 드리겠습니다.  선서는 증인을 대표해서 경기개발연구원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서도 자리에서 오른손만 들어주시면 되겠습니다.  그러면 선서를 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 선서!  본인은 경기도의회가 지방자치법 제36조, 동법시행령 제16조제1항, 경기도의회행정사무감사및조사에관한조례 제2조의 규정에 의하여 소관 업무에 대한 2003년도 행정사무감사를 실시함에 있어 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법시행령 제17조의4 제5항과 경기도의회행정사무감사및조사에관한조례 제18조의 규정에 의하여 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다.
</p>
<p class=''ar''>2003년 11월 26일
</p>
<p class=''ar''>증인 경기개발연구원장 이철규. 
</p>
<p><b>○ 위원장대리 이원재 </b> 자리에 앉아 주시기 바랍니다.  그러면 경기개발연구원장님 나오셔서 업무보고해 주시기 바랍니다.  간부소개도 함께 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 존경하는 위원장님!  그리고 경기도의회 기획위원회 위원님 여러분!  연일 공사다망하신 중에도 저희 연구원을 찾아주신 위원님 여러분께 심심한 감사를 드립니다.  여러분 모두의 건승과 그리고 도약을 바라마지 않습니다.   또다시 1년이 훌쩍 지나가고 있습니다.  정신 없이 한해를 보내게는 되었지만 과연 얼마만큼 보람 있는 한해를 보냈나를 생각해 보면 부족한 점이 너무나 많습니다.  저희들 연구원만 보더라도 그 동안 새 건물을 짓고 있다는 핑계로 연구진들에게 충분한 연구공간을 제공해 주지 못한 것은 무엇보다도 아쉬운 일이었습니다.  어떻게 보면 토끼장 같은 연구실에서 묵묵히 연구해 주고 견뎌준 연구진 여러분께 원장으로서 죄송하고 감사할 따름입니다.  경제 및 복지부문 연구진을 아직 보강하지 못한 것도 못내 아쉬운 일입니다.  도정의 가장 중요한 부문에 우리 연구원이 더 넓고 더 깊게 기여하지 못하고 있는 것입니다.  내년도에 우선적으로 풀어야할 저희들의 과제라고 생각하고 있습니다.  그러나 저희 연구원으로써는 몇 가지 보람도 있습니다.  지방행정, 교육, 도시계획, 교통, 환경, 관광 등 여러 분야에서 우수한 연구진을 금년도에 보강할 수 있었던 것은 무엇보다도 가슴 뿌듯한 일이었습니다.  앞으로 새로 들어올 신진기예들의 내년도 활약이 기대됩니다.  그리고 남북교류 사회포럼 등 몇 가지 포럼도 차질없이 잘 운영되고 있습니다.  각계에 비중있는 전문가들을 곁에 모시고 그분들과 국정이나 도정을 함께 논의할 수 있게 되었다는 것은 참으로 고마운 일이라 생각됩니다.  도정의 방향을 정립하는데는 물론 경기도의 위상을 대내·외에 제고하는 데도 이 포럼들이 큰 도움이 되고 있다고 생각합니다.  CEO리포트를 발행하게 된 것도 매우 기쁜 일입니다.  CEO들이 관심을 가졌으면 하는 중요 사안들을 찾아서 그때그때 그들에게 직접 서비스를 제공하겠습니다.  앞으로 이것이 좀더 안정적으로 발전할 수 있다는 가능성만 보이면 우리 위원님들께도 적시에 제공해서 의정활동에 도움을 드리도록 운영해 나가겠습니다.  
</p>
<p style="padding-left:1.2em">  지금 노무현 정부는 지방분권의 확대를 주요정책 과제로 추진하고 있습니다.  매우 고마운 일이라고 생각됩니다.  많은 장애가 있으라고 예상은 되지만 정부의 관련조치들이 국민 모두의 호응 속에서 차질없이 추진되기를 바랍니다.  그리하여 지방의회도 주민의 대표기관다운 격을 갖추고 보다 폭넓은 권한들이 또 보다 전문성 있고 책임성 있는 자세로 추진할 수 있는 그런 시스템이 마련되기를 바랍니다.  다시 한 번 위원님 여러분의 열정과 노고에 감사를 드리고 양해해 주신다면 보다 구체적인 업무는 기획조정실장으로 하여금 보고드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  우선 보고에 앞서 저희 간부진을 위원님 여러분께 소개해 올리겠습니다. 
</p>
<p style="padding-left:1.2em">  이상훈 기획조정실장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김봉규 사무처장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동성 자치행정연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  지우석 도시교통연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  송미영 환경정책연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김흥식 경제사회연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  감사합니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 수고하셨습니다.  그러면 기획조정실장 나오셔서 업무보고해 주시기 바랍니다.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기획조정실장 이상훈입니다.  2003년도 경기개발연구원 주요업무에 대해서 보고드리겠습니다.  보고는 기 배부해 드린 자료를 중심으로 해서 보고를 드리고 보고순서는 일반현황하고 재정운영현황 그리고 2003년도 연구사업추진상황 그리고 2004년도 연구사업계획, 2002년도 행정사무감사 처리요구사항 조치결과 순으로 보고드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  우선 보고자료 1쪽의 일반현황입니다.  일반현황의 연혁 및 기능에 대해서는 자료로 갈음해 주시면 감사하겠습니다. 
</p>
<p style="padding-left:1.2em">  2쪽의 기구 및 인력입니다.  인력은 총정원이 59명이고 현원이 56명으로서 과부족이 3명으로 되어 있습니다.  연구직은 참고로 1명이 과부족으로 되어 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 시설 및 물자현황으로써 3쪽입니다.  청사는 현재 894평 대지에 851.5평의 건물로 되어 있습니다.  2004년 5월 중에는 신청사로 입주할 예정입니다.  그 외 주요물품 현황은 자료로 갈음하도록 하겠습니다.  장서는 약 2만 2,700권을 보유하고 있고 가장 최신의 업데이트된 자료중심으로 구성되어 있다는 것을 보고드립니다.
</p>
<p style="padding-left:1.2em">  다음은 4쪽의 재정운영현황이 되겠습니다.  총 예산은 347억 5,000만원이 되겠습니다.  이 중에서 일반회계가 100억 8,200만원, 그리고 기금관리 특별회계가 약 247억원이 되겠습니다.  일반회계 100억 8,200만원 중에서는 가장 큰 비중이 도비보조금이 56억원으로 약 55.5%를 차지하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 전입금이 약 9.6%를 차지하고 있고요.  수탁용역 사업수입은 5억 4,200만원이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  참고로 5억 4,200만원의 수탁용역사업 수입을 내기 위해서는 저희들이 2003년도 수탁사업 수주금액이 43억원이라는 말씀을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 지출입니다.  지출에서는 연구부 운영과 연구과제 사업 그리고 연구조성사업 등 연구관련된 예산이 약 64%라는 보고를 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  기금관리 현황은 현재 기금이 237억원이 조성되어 있습니다.  ''99년 이후로 경기도출연이 중단됐지만 그 이후에 자체 적립은 지속적으로 확대해 가고 있다는 것을 보고드립니다.  기금의 예치는 한미은행을 포함한 8개 기관의 안전을 위해서 분산 예치되어 있음을 보고드리겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 6쪽 이후부터는 2003년도 연구사업 추진상황이 되겠습니다.  연구사업 총괄표를 보시면 총 189건의 사업량을 계획했지만 이것이 예정보다 증가돼서 209회가 현재 100회가 완료됐고 109회가 추진 중에 있습니다.  이 중 기본연구과제와 수탁연구과제, 그리고 정책연구 기본연구과제 이외에 수탁연구 30과제가 사업량으로 예정되어 있습니다마는 57과제로 확대해서 추진하고 있다는 것을 보고드립니다.  정기간행물 사업은 경기연구를 포함해서 다섯 가지 정기간행물 사업을 추진을 했습니다.  연구조성 사업으로는 번역사업 3조원을 포함해서 정책세미나 24회가 예정되어 있는데 이 중 20회를 저희들이 추진하고 있고 나머지 GIS팀 운영이 연구조성사업에 포함되어 있습니다. 
</p>
<p style="padding-left:1.2em">  7쪽 이후는 연구사업 세부추진 상황이 되겠습니다.  총 사업량은 32개 과제를 수행할 계획이고 현재 28개 과제가 진행 중이라는 것을 보고드리겠습니다. 
</p>
<p style="padding-left:1.2em">  8쪽은 수탁연구과제가 되겠습니다.  수탁연구과제는 외부기관이 경기개발연구원의 연구를 의뢰하는 연구비를 부담하는 과제가 되겠습니다.  이 중 57개 과제가 추진상황이고 이미 23개 과제는 완료가 됐고 3개 과제는 발주한 측의 중지요청에 의해서 중지됐고 31개 과제가 진행중이라는 것을 보고드리겠습니다.
</p>
<p style="padding-left:1.2em">  10쪽부터는 정책연구과제가 되겠습니다.  정책연구 과제는 경기도가 긴급 요청하는 현안 연구과제입니다.  현안이 발생했을 때 경기도가 요청하기도 하고 아니면 연구원이 자체적으로 필요하다고 판단해서 추진하는 과제가 되겠습니다.  약 53개 과제가 수행 중에 있고 추진은 56개 과제, 이 중에서 29개 과제는 이미 완료가 됐고 27개 과제는 진행 중에 있습니다.  정책연구과제로는 12쪽의 CEO리포트 건이 있습니다.  이미 원장님의 인사말씀에서도 소개해 드렸습니다는 핫이슈들이 수시로 발생을 하고 있습니다.  그래서 저희들이 판단하는 것은 실무자선에서 판단하는 그러한 의사결정과 그 다음에 최고경영자인 CEO 수준에서 판단한 의사결정이 차이가 있다라고 판단하고 그 다음에 시의성 있는 이슈들에 대해서 신속하게 대응해야 된다는 판단에서 CEO리포트를 현재 7건을 추진하고 있습니다마는 6건이 완료가 됐고 한 건은 추진 중에 있습니다.  
</p>
<p style="padding-left:1.2em">  다음은 위탁연구 과제입니다.  13쪽부터 위탁연구 과제가 되겠습니다.  저희 내부에 물론 연구진을 갖추고 있지만 저희 연구진이 하는 것보다는 외부연구진이 하는 것이 보다더 효율적이라고 판단될 때 그리고 설사 경기개발연구원에서 수행가능 하려면 어떤 객관성이라든지 이런 데서 외부와의 협력적 연구가 필요할 때 추진하는 사업이 되겠습니다.  총 12개 과제 중에서 이미 3개 과제가 완료됐고 9개 과제가 현재 진행 중에 있습니다.  
</p>
<p style="padding-left:1.2em">  다음은 협약연구과제입니다.  협약연구과제는 총 4개 과제인데 이 중 1개 과제가 완료가 됐고 3개 과제는 현재 진행 중에 있습니다. 
</p>
<p style="padding-left:1.2em">  14쪽에는 지역연구과제가 되겠습니다.  총 3건의 추진상황이 있고 1개 과제는 완료가 됐고 2개 과제는 진행중입니다마는 완료시점에 있다는 것을 보고드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그 외 정기간행물이 되겠습니다.  총 5건의 정기간행물이 있는데 연간발행하는 경기연구와 경기논단 그리고 KRI 뉴스레터, 경기도 경제동향과 전망, 그리고 알기쉬운 경기도경제지표가 되겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 번역사업이 되겠습니다.  번역사업은 총 3종이 저희들이 추진상황에 있고 1종은 완료를 했습니다.  그리고 나머지 2개종에 대해서는 현재 막바지 작업을 진행 중에 있다라는 말씀을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 정책세미나입니다.  정책세미나는 위원님들께서 익히 아시는 바와 같이 당면 문제 및 학술적인 성격의 어떤 대내적인 여론도 주도하기도 하고 그 다음에 토론을 통해서 중요한 현안에 대한 대안을 찾고자 하는 것입니다.  그래서 총 20회를 계획을 하고 있고 이 중에서 16회는 이미 개최가 됐고 4회는 개최될 예정에 있습니다. 
</p>
<p style="padding-left:1.2em">  16쪽에는 그 동안 연구사업 연도별 수행현황이 되겠습니다.  ''95년 이후에 2002년도까지 연구과제 사업별로 그리고 정기간행물 발간, 그리고 연구조성사업에 추진상황이 요약되어 있습니다. 
</p>
<p style="padding-left:1.2em">  17쪽부터 2004년도 연구사업계획안이 되겠습니다.  우선 기본방침은 참여정부 이후에 중앙정부의 국정과 관련해서 현황과제가 많이 발생을 했습니다.  경기도 나름대로 대응논리도 개발을 해서 시의성 있는 연구성과물을 도출해야 되겠다라는 것이 2004년도 연구용역사업의 기본방침이 되겠습니다.  또한 신속하고 실효성있는 도정정책개발 기능을 강화해야 되겠다라고 하는 것이 방침이고 그 다음에 일원화된 연구실적평가체계 시행을 통해서 경영 내실화를 해야 되겠다 그리고 연구실적 등 효율적인 자료관리를 위한 통합정보시스템구축 및 지리정보시스템운영을 기본방침으로 설정했습니다.  또한 우수연구원을 확보해서 연구의 질을 제고하고 열린 조직문화를 실현하는 것이 기본방침입니다. 
</p>
<p style="padding-left:1.2em">  주요 방침으로는 기본과제 같은 경우 저희 연구원에서 발행하는 과제 중 가장 아카데믹한 과제가 되겠는데 과제선정 단계부터 연구위원회에서 심도있게 논의하여 선정을 하고 있습니다.  그리고 수탁연구과제는 수행절차를 일부 과제에서는 간소화해서 신속히 추진할 수 있는 체계를 갖추고 정책연구과제 같은 경우는 특히 시의성 있는 도 의뢰과제가 핫이슈에 대한 CEO리포트 등을 수행을 하고 있습니다.  
</p>
<p style="padding-left:1.2em">  연구조성 사업은 포럼과 통합정보관리시스템구축 운영 등을 추진할 예정으로 있습니다.  그리고 또한 적극적인 해외 우수인력 헌팅 등을 통한 연구 우수인력을 확충하고 다면평가 및 노사협의회 활성화 등으로 열린 조직문화 실현을 추진방향으로 설정하고 있습니다.  그리고 또한 아울러서 연구원 홍보 및 이미지 제고를 위한 CI계획을 추진 중에 있습니다. 
</p>
<p style="padding-left:1.2em">  18쪽에는 2004년도 연구사업 계획에 대한 총괄이 되겠습니다.  총 190건의 사업량을 계획하고 있습니다.  이 중에서 연구과제 사업으로써 우선 기본연구과제는 28개 과제를 계획하고 있고 그 다음에 수탁연구과제는 40과제 이것은 부서당 8개 과제를 수행하는 것을 목표로 설정했습니다.  정책연구과제는 55개 과제입니다.  그리고 위탁연구과제와 지역연구과제를 우선적으로 했습니다.  
</p>
<p style="padding-left:1.2em">  다음은 정기간행물 사업입니다.  그 동안 경기연구원은 연간으로 발행을 하면서 추진했습니다마는 실효성 문제를 저희들이 검토를 해서 이것을 연 4회 발행하는 경기논단과 통합을 해서 특집주제 중심으로 발행할 예정에 있습니다.  또한 KRI 뉴스레터를 발행할 예정이고 경기도 경제동향과 전망, 이것은 월간이 되겠습니다.  경기도 경제동향과 전망은 맨 밑에 보시면 알기 쉬운 경기도경제지표를 통합해서 조금더 효율적인 간행물을 관리를 할 예정에 있습니다.  또한 연구원 안내책자 브로셔를 발행할 예정입니다.  연구조성사업은 총 27건 그리고 기타 통합정보시스템, GIS 실험실 1시·군 1담당제 정책포럼 등을 운영할 예정입니다. 
</p>
<p style="padding-left:1.2em">  19쪽부터는 기본연구사업에 대한 구체적인 사항이 되겠습니다.  우선 기본연구과제는 보시는 바와 같이 20쪽에 10개 과제가 소개가 되어 있습니다마는 현재 자료 제출한 시점하고 현재의 시점이 차이가 있어서 총 14개 과제가 연구위원회를 통과한 상태다 이렇게 말씀드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  다음에 세부연구사업 계획은 21쪽부터 25쪽 기본과제에 대한 구체적인 과제명, 그 다음에 연구목적과 내용, 그리고 기대효과 등으로 정리가 되어 있습니다.  이것은 자료로 갈음하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 26쪽의 수탁연구과제가 되겠습니다.  수탁연구과제는 외부기관에서 경기개발연구원에 용역을 의뢰한 과제가 되겠습니다.  그래서 이것은 앞으로 추진방향은 재정자립도의 제고뿐만 아니라 여러 가지 목적을 위해서 적극적으로 수행을 해야 되겠다 라고 하는 것이고 일정금액 이하의 용역 수행절차를 간소화해서 일부 시·군에서 상당히 중요한 과제임에도 불구하고 금액이 적다라든지 절차가 복잡해서 수행하는데 소극적인 이런 것을 해소하고자 합니다.  사업계획은 1개 부서당 총 8건으로 해서 40개 과제를 수행할 예정입니다. 
</p>
<p style="padding-left:1.2em">  다음은 27쪽 정책연구과제가 되겠습니다.  앞에서 소개해 드린 바와 같이 경기도로부터 긴급 요청된 시의성 있는 현안문제하고 연구원 자체적으로 이 문제가 다뤄져야 되겠다라고 판단하는 과제가 되겠습니다.  또한 여기에는 CEO리포트도 포함이 돼서 앞으로 도정 현안에 대해서 조금더 적극적으로 대응하겠다라고 하는 계획이 포함되어 있습니다.  총 사업은 55개 과제에서 6억 6,000만원의 사업비가 책정되어 있습니다. 
</p>
<p style="padding-left:1.2em">  28쪽이 되겠습니다.  위탁연구과제인데 위탁연구과제는 앞에서 간략히 설명을 드렸습니다마는 기초적, 예비 또는 보완적인 추가 연구가 필요한 건이 있습니다.  그리고 특히 외부기관과의 협력적인 연구가 필요한 사업이 상당히 많아졌습니다.  경기개발연구원에서 연구를 하더라도 경기도 및 시·군 출연기관이기 때문에 문제 자체가 저희들이 체계적인 연구를 했음에도 불구하고 이의 제기되는 바가 있기 때문에 외부의 전문가들과 협력적인 연구가 필요하게 됐습니다.  그래서 그런 내용을 위탁연구과제로 추진한다 그래서 총 9개 건에 약 3억원이 연구비로 책정이 되어 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 지역연구과제입니다.  지역연구과제는 지역에 대한 특정현안이 발생하고 있는 시·군을 대상으로 하는 연구로 해마다 2개 지역에 대해서 추진할 계획으로 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 정기간행물사업입니다.  앞에서 보고드린 바와 같이 경기연구를 폐간하고 경기논단과 통합을 했고요.  그 다음에 알기 쉬운 경기도 경제지표를 경기동향과 전망에 포함을 시켜서 이것을 부록 형태로 발간하는 것으로 2004년도에 추진할 계획입니다. 
</p>
<p style="padding-left:1.2em">  다음은 30쪽이 되겠습니다.  연구조성사업입니다.  우선 번역사업에 2종 번역을 저희들이 계획을 하고 있고 그 다음에 정책세미나 사업량을 25회로 설정을 했습니다.  그리고 정책포럼을 조금더 확대해서 4개 포럼을 운영하는 계획을 수립했습니다. 
</p>
<p style="padding-left:1.2em">  다음에 32쪽, 1시·군, 1담당제입니다.  그 동안 경기도 및 시·군에 많은 연구진들이 직·간접적으로 여러 가지 프로젝트에 관여를 했습니다마는 일부 시·군에서는 경기개발연구원에 특별한 창구가 없기 때문에 알음알음 연락하는 문제가 있었습니다.  저희 연구진이 조금 적극적으로 한 시·군에 연구직 한 사람을 배출을 해서 연구원내에 물론 배치를 합니다마는 하나의 창구로 정해서 해당 시·군에 여러 정책결정 사항이라든지, 누구를 소개받는다든지, 연구진을 소개받는다든지 하는 역할을 수행하도록 하는 것을 2004년도에, 역시 과거에 시행을 했었습니다마는 보다 효율적으로 시행하고자 합니다. 
</p>
<p style="padding-left:1.2em">  다음 33쪽 이후부터는 2002년도 행정사무감사 처리요구사항 조치결과가 되겠습니다.  위원님께서 지적해 주신 내용이 집행부와 상관없이 첫 번째 보시면 독자적으로 경기도에 올바른 정책방향을 제시하는 연구원이 될 수 있도록 노력을 강구해 달라는 요청사항이 있으셨습니다.  사실 이 문제에 대해서는 경기도의 특수한 이익과 국가적인 보편이익의 충돌시 사실 연구자가 여러 가지 어려움에 빠진 것은 사실입니다.  그렇지만 현재는 경기도의 올바른 정책방향을 제시하는데 연구원들이 노력하고 있다는 것을 보고드립니다. 
</p>
<p style="padding-left:1.2em">  두 번째는 많은 과제를 수행하는 것보다 적정한 연구과제를 심도있게 연구해서 브랜드 가치와 더불어 전출금을 높이는 발전적인 방안을 모색하기 바란다는 제안이 있으셨습니다.  그래서 저희 연구원내에서는 연구위원회의 사전심의 기능을 강화해서 적정한 연구과제를 연구해서 경기개발연구원의 브랜드가치를 높이려고 노력하고 있습니다.  그리고 전출금을 높이는 방법은 참고로 일부 대학에서 전출금은 연구소 같은 경우는 5%을 부과하고 있습니다.  저희는 30%를 부과하고 있는데 여기에 대해서는 향후 경기개발연구원의 브랜드 가치가 사회적으로 인정받는 시기가 도래할 경우에 조금더 높일 수 있을 것으로 판단이 됩니다. 
</p>
<p style="padding-left:1.2em">  다음 세 번째는 유사한 연구지를 통·폐합하여 유익한 간행물이 될 수 있도록 조치바람, 이런 지적사항이 있으셨습니다.  이미 기업경기조사 BSI를 경제동향과 전망에 통합을 했고 그 다음에 2003년도에는 경기 이코노믹을 영문으로 발행하는 경기도 지역현안 문제를 폐간을 했습니다.
</p>
<p style="padding-left:1.2em">  알기쉬운 경기도경제지표를 경제동향과 전망에 포함을 시켰습니다.  그리고 전문학술지인 경기연구를 계관지인 주제중심 논문집인 경기논단으로 발행할 계획임을 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 34쪽에 기획조정실 기구 중 도시환경자문팀의 기능이 타부서 기능과 중복된다고 보는데 이 팀의 역할이 꼭 필요하다면 아예 정식으로 기구에 편입시키고 업무의 중복성이 있다면 폐쇄해야 된다 이런 지적사항이 있으셨습니다. 
</p>
<p style="padding-left:1.2em">  경기도내에 도시계획 상임기획단을 둬야 하는 것으로 되어 있습니다마는 현행법상 경기도 정원상의 문제로 경기개발연구원이 임시조직으로 아직 운영하고 있습니다.  그래서 경기개발연구원과 중복되는 부분은 없다고 저희들은 판단하고 경기도의 조직개편시 도시환경자문팀의 기능을 경기도에서 인력으로 운영토록 추진하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  다섯 번째 위탁연구기관을 선정할 때 사안별로 전문가의 자문을 통해 위탁기관을 선정하기 바람, 이런 지적사항이 있으셨습니다.  그래서 위탁연구기관을 해당 전문가그룹으로 구성된 부문에서 검토의견을 제시하고 검토의견에 대해서 저희들 전문가로 구성된 연구위원회 심의의결을 거쳐 선정하고 있다라는 것을 보고드립니다.
</p>
<p style="padding-left:1.2em">  여섯 번째는 연구원과 기획위원회가 발전방안에 대해서 토의할 수 있는 간담회를 개최하기 바람, 이런 말씀을 하셨습니다.  이 문제는 앞으로도 향후 기획위원회와 간담회를 확대하도록 노력하겠다는 보고를 드리겠습니다.  
</p>
<p style="padding-left:1.2em">  일곱 번째 수탁용역사업 수입이 적은데 이를 보다 증가시킬 수 있도록 노력을 기 바람, 이런 지적이 있으셨습니다.  이것은 경기개발연구원이 브랜드가치를 높여서 앞으로 수탁용역사업의 수익을 증가시키기 위한 노력을 하겠다라는 보고를 드립니다.  
</p>
<p style="padding-left:1.2em">  이상으로 2003년도 경기개발연구원 주요 업무보고를 마치도록 하겠습니다.  감사합니다.
</p>
<p><br /></p>
<p>업무보고서는 끝에 실음
</p>
<p><br /></p>
<p><b>○ 위원장대리 이원재 </b> 이상훈 기획조정실장 수고하셨습니다.  다음은 질의·답변 순서가 되겠습니다.  감사의 원활한 진행을 위해서 질의·답변은 일문일답 식으로 진행하도록 하겠습니다.  질의에 앞서 위원장으로써 한 가지 부탁말씀을 드리겠습니다.  위원님들의 질의사항 중 연구원장이 답변이 어려울 경우 담당 실·부장 등 실무자가 답변해도 좋지만 다만 사전에 위원장의 동의를 얻은 후 발언대에 나와서 소속과 직·성명을 분명히 밝히고 답변해 주시기 바랍니다.  그러면 질의하실 위원님께서는 거수로 신청해 주시기 바랍니다.  김대원 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김대원 위원 </b> 김대원 위원입니다.  장족의 발전을 하는 경기개발연구원에 대해서 경기도민의 한 사람으로 경기도민의 삶의 질 향상과 경기도민의 권익을 위해서 노력하시는 부분에 대해서 감사를 표하고요.  작년도 감사 이후에 1년만에 다시 이 자리에 앉게 돼서 감개무량하게 생각하면서 될 수 있으면 감사에 충실하고자 앞부분부터 질의하겠습니다.  작년도 행정사무감사시 정원부분에 대해서 부원장의 결원상태가 현재까지 진행되고 있습니다.  이철규 원장님께서는 자타가 인정하는 능력있는 분이라고 믿습니다만 원장과 부원장은 서로 업무성격이 비슷할 수도 있지만 보완관계가 유지돼야만 원장의 역할이 충실히 수행될 수 있다고 보는데 부원장을 선임하지 않은 이유가 무엇인지, 두 번째 직제표를 보면 작년도 지적사항인데 도시환경자문팀이 경기도 정원으로 운영하도록 지금도 조치사항에 보면 노력하고 있다는데 도시환경자문팀이 현재 어떻게 운영되고 있는지, 그리고 성과연봉평가가 부적정하게 돼서 과다 지급된 부분을 회수하여 재배정하라는 감사원조치결과가 있었는데 어떤 방식으로 재조정했는지, 그리고 작년도 감사시 연구원과 기획위원회가 경기도 발전방안에 대해서 긴밀히 협의해서 하겠다고 했는데 어떻게 기획위원회와 경기개발연구원이 경기도 발전을 위해서 긴밀하게 협의했는지 사례가 있으면 말씀해 주시기 바랍니다.  이상 요약해서 작년도와 올해 정원에 대해서 기초적인 부분을 네 가지로 질의드렸습니다.  원장께서 답변해 주시기 바랍니다.
</p>
<p><b>○ 위원장대리 이원재 </b> 답변해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 원장이 답변드리겠습니다.  김대원 위원님께서 네 가지 질의해 주셨는데 그 중에 세 가지는 제가 답변드릴 수 있고요.  한 가지 성과연봉평가시에 지적사항을 어떻게 조치했는지에 대해서는 제가 오기 전 일이기 때문에 이것은 담당실무자로 하여금 답변드리도록 하겠습니다.  양해해 주시기 바랍니다.
</p>
<p><b>○ 김대원 위원 </b> 그것은 2002년 8월 8일 조치사항이니까 그때 근무하신 것 아니에요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 제가 8월 15일에, 제가 답변할 수도 있는데요.  상세한 답변을 드리기 위해서 그렇습니다. 
</p>
<p><b>○ 김대원 위원 </b> 알겠습니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 먼저 부원장이 결원돼 있고 보완관계상 필요하다고 생각되는데 왜 임명을 하지 않느냐 질의하셨습니다.  솔직히 그렇습니다.  현재 우리 연구원의 조직규모로 봐서는 저 개인적으로 판단할 때 부원장이 필요하지 않다고 생각합니다.  다만 연구원은 계속 성장하고 있기 때문에 조만간 부원장 제도가 도입이 돼야한다는 필요성에 대해서는 공감하고 있습니다.  그래서 조직편제를 현재 상태로만 판단한다면 부원장 제도가 없어져도 된다라는 생각을 그 동안은 해왔지만 그러나 조직 성장속도가 굉장히 빠르기 때문에 바로 부원장제를 없애는 것보다는 나중에 활용에 대비해서 계속 유지하는 것이 좋겠다 이렇게 판단을 해왔습니다.  따라서 필요한 시점까지는 앞으로도 계속 부원장 결원상태를 유지해 나갈 생각으로 있습니다. 
</p>
<p style="padding-left:1.2em">  두 번째 도시환경자문팀의 운영실태에 대해서 질의하셨습니다.  전에 지적해 주신 것이 그 이후로 크게 개선되지 않고 있습니다.  그 원인은 아까 보고에서도 말씀드렸던 것처럼 도에 정원이 확보되지 않고 있기 때문입니다.  도의 정원확보가 이렇게 어렵습니다.  앞으로도 계속 행정자치부와 협의해서 정원을 확보하도록 노력해 나가야 되겠습니다만 그것이 실현되기 전까지는 바람직하지 않지만 현재 상태로 유지될 수밖에 없다고 생각합니다.  다만 도시환경자문팀이 하는 역할이 경기도 도시계획의 정밀한 심의를 위해서 꼭 필요한 것이라고 생각하기 때문에 도시환경자문팀이 설사 조직은 엉거주춤한 상태지만 업무는 확실하게 수행될 수 있도록 감독을 철저히 해나갈 것을 위원님들께 약속드립니다.
</p>
<p style="padding-left:1.2em">  그리고 끝으로 기획위원회 위원님들과 경기개발연구원과의 긴밀한 협의를 위한 사례가 있으면 제시해 보라는 말씀을 하셨는데 자랑스럽지는 않지만 열심히 해왔다고 생각합니다.  앞의 보고에도 나와 있습니다만 보고에서 몇 가지 사례가 제시되고 있습니다만 사례를 일일이 거론하기보다 그 동안 부족하다고 느낀 점이 있다면 김대원 위원님께서 질의하시는 의미는 부족하지 않느냐는 의미가 내포돼 있다고 느끼기 때문에 이제까지 한 것을 자랑하지 아니하고 앞으로 더욱더 위원님들과의 관계를 돈독히 하고 긴밀히 하는데 최선을 다할 것을 악속드립니다.
</p>
<p><b>○ 김대원 위원 </b> 답변 감사합니다.  우선 성과연봉 부분에 대해서는 나중에 하기로 하고 지금 답변사항에 대한 보충질의를 하겠습니다.  작년도도 역시 원장님 답변 대로 부원장 제도가 없어도 충분히 조직이 운영될 수 있다라는 답변을 올해도 그대로 하셨는데 그러면 계획대로 청사를 옮겨야 되는데 계획서에 보면 현재 사용하는 경기개발연구원과 지금 신축 중인 신청사 부분에 대해서 사용을 같이 하는 계획을 가지고 계신가본데 부원장 방이 만들어져 있는지 모르지만 앞으로 요구사항에 보면 원장님 방이 20평이 필요하고 부원장님 방이 20평이 필요하고 처장 및 기조실장 방이 12평씩 공간이 필요다고 요구했습니다.  요구사항 중에서도 20평짜리 방이 요구평수보다 4평씩이 모자란다는 계획서가 있어요.  그러면 이전을 하면 바로 부원장이 필요해서 방 만들기 위해서 20평을 요구했는지 더군다나 무엇을 기준으로 해서 20평이 요구돼 있는데 4평이 부족하다고 요구했는지, 없다면 현재같이 부원장방 자체도 없애야지 왜 그것을 요구했는지, 만약에 부원장이 필요하다면 그 시점을 언제로 보시는지, 그리고 도시환경자문팀이 작년에도 나왔을 때 끝까지 공개석상에서 요구하지 않았습니다만 도시환경자문팀의 출생배경에 상당히 문제점이 있는 관계로 그 인력을 어떻게 관리할 것인지, 내용요지는 그것이었습니다.  그런데 작년도 도시환경자문팀에 있던 인력이 현재 인력으로 그대로 운영하시는지, 그리고 세 번째 부분에 대해서 연구원과 기획위원회가 긴밀히 협의했다는 부분인데 현재 보고서 대로라면 포럼이라든가 간담회는 전체적인 상황이지 기획위원회하고는 별 관계가 없다는 것으로 알고 있습니다.
</p>
<p style="padding-left:1.2em">  그리고 저희들이 지방의회 발전을 위해서 경기개발연구원과 미국에 다녀왔습니다만 그때 책임연구원이 같이 갔습니다.  그런데 원래 연구원 배정을 보니까 책임연구원으로서 상근책임연구원이 아닌 것으로 돼 있는 것 같아요.  그냥 70만원짜리 비상근연구원으로 돼 있는데 그러다 보면 연구원에 비중없는, 쉽게 말해서 기획위원회와 연구원과 긴밀히 협의될 수 있는 인물이 아닌 그런 사람과 저희들이 의회발전을 위해서 미국을 다녀왔다는 결론이 되니까 결론적으로 기획위원회와 경기개발연구원은 긴밀하게 협의한 사항이 한 번도 없다고 봅니다.  그런데 자료에 앞으로도 간담회를 운영해 볼 계획이다.  지금이 11월 말인데 작년도 감사에서 기획위원회와 경기개발연구원이 긴밀히 협의해서 경기도 발전을 위해서 노력하겠다고 했는데 기획위원회와 한 번도 간담회를 안 가지지 않았습니까?  저희들 회의 열렸을 때 존경하는 김영수 과장이나 의회사무처에 얼굴 한 번 보였고 원장님만 한 번 오셨지 기획위원회와 뭘 긴밀히 했다는 겁니까?  저는 여기에 책임연구원, 박사님들 많이 계십니다만 우리 기획위원회 위원들 얼굴이나 아시는지, 이름이나 아는지 그리고도 긴밀하게 협의했다고 하면 이것은 말이 안 되지 않습니까?  경기개발연구원이 기획위원회 감사를 왜 받아야 되는지 이유도 모르시면서 앉아 계시는 것 같아요.  그래서 그 부분에 대해서 다시 한 번 세밀하게 답변해 보시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 답변드리겠습니다.  신청사에 부원장실 확보는 필요하다고 생각합니다.  여러 위원님들께 지난번에 이미 보고를 드렸습니다만 제가 2006년까지 장기발전계획을 수립해서 추진하고 있는데 앞으로 2006년까지 60명 이상의 연구진을 확보하고 연구원의 규모가 크게 팽창이 된다고 하면 현재 체제로써는 관리하기 힘든 상황이 올 수 있다고 봅니다.  그때에 가면 부원장 제도의 도입 필요성이 검토될 수 있기 때문에 그에 대비한 사무실 확보는 필요하다고 판단하고 있습니다.  다만 평수가 4평이 부족하다 그렇기 때문에 저희들이 이견을 제시한다거나 그런 것은 아니고 원래는 24평을 요구했는데 20평이 확보됐다라는 것을 보고드리기 위한 자료이지 4평이 부족해서 늘려 주십시오 그런 의미의 보고는 아닙니다.  양해해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  도시환경자문팀 운영은 솔직히 말해서 그전보다 인력이 증원됐다든지 또는 능력이 개선됐다든지 하는 것은 없습니다.  지금 오히려 한 명의 결원이 생겨서 한 명 줄어든 상태입니다.  다만 확보가 될 때까지는 부족한 인력이지만 이 사람들이 그 이상의 배전의 노력을 기울임으로써 맡은 바 업무를 충실히 수행할 수 있지 않을까 이렇게 기대를 하고 있습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 김대원 위원님께서 기획위원회와 연구원과의 긴밀한 협력에 대해서 매우 섭섭한 느낌을 가지고 계신 것으로 취지의 질의를 해주신 데 대해서 원장으로서 매우 송구스럽게 생각합니다.  가장 친해야 할 기획위원 여러분과의 관계가 혹여 저희들의 성의 미흡으로 인해서 상처를 받게 된다면 그것은 전적으로 저희들 책임이라고 생각합니다.  앞으로 위원 여러분들에 대해서 우리 연구원의 모든 식구들이 가족처럼 그리고 가장 연구원을 도와줄 수 있는 자문팀으로 대접해 나가는 자세를 우리 연구진들한테 다시 한 번 강조하겠습니다.  위원님 여러분들게 정말 송구스럽다는 말씀을 드리고 그 동안 섭섭하거나 부족했다고 느끼는 사항들이 있으시면 널리 용서해 주시기 바랍니다.  감사합니다. 
</p>
<p><b>○ 김대원 위원 </b> 성실히 답변해 주셔서 감사하고 인간적인 답변도 감사하게 생각합니다.  저는 의왕출신입니다만 여기서 거리가 제일 가까울 겁니다.  예를 들어서 설명을 하겠습니다.  경기개발연구원 소속 연구원이 아마 타 시·군에도 어떤 위원이라든가 자문팀 또 연구를 위한 과제수행 때문에 방문하시는 과정들이 많을 겁니다.  그런데 저희들은 경기개발연구원이 기획위원회 산하단체로서 정말 애정이 가고 식구로서 가깝게 느껴집니다.  그런데 가까운 사람들이 가깝지 않다고 알고 있었을 때의 서운함은 상당히 컸을 겁니다.  그런데 저만 느끼는 게 아니라 기획위원회 위원 여러분들이 경기개발연구원에 대한 현재까지의 감정은 다 그렇다라는 얘기입니다.  개중에 아닐 수도 있지만, 그래서 더 서운함이 크고요.  저는 오늘 원고도 자료도 없습니다만 안 보는 것 같아도 저희들 산하기관이고 단체다 보니까 앞으로 진행상황이라든가 전에 일어났던 상황들을 눈여겨 보게 되는 게 사실입니다.  그게 애정이 아닐까요?  기획위원회는 경기개발연구원의 발전을 위해서 애정을 가지고 지켜보고 잘 되기를 비는 심정으로 보고 있는데 경기개발연구원은 기획위원회와 무관한 그런 부분을 저희들 의회가 출범한 이후로 보여준 게 없습니다.  그리고 조치사항에 보면 "향후 기획위원회와 간담회를 개최할 계획임"  이걸 답변서라고 만들었어요.  참 인간적인 비애를 느낍니다.  과연 경기개발연구원이 기획위원회와 무슨 상관이 있는 단체인지, 그리고 도시환경자문팀에 대해서 아직까지 답변이 두루뭉수리 스타일이지 완벽하지 않다고 생각합니다. 
</p>
<p style="padding-left:1.2em">  제가 분명히 질의 부분에 인력구성에 대해서 안양에서 넘어온 도시환경자문팀 인력이 그대로 재배치돼서 운영되는 건지 아니면 다른 사람들로 충원됐는지가 제 질의의 요지입니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 안양에서 넘어온 게 뭡니까? 
</p>
<p><b>○ 김대원 위원 </b> 도시환경자문팀이 원래 안양에서 신설돼서 사무실을 이쪽으로 옮겨온 게 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 안양에 설치됐다는 게 무슨 팀을 가지고 말씀하시는지 혼선이 생기는데요.  도시계획을 위한 도시환경자문팀을 말씀하시는 겁니까, 아니면 안양에서 이상하게 만들었던 조직을 말씀하시는 겁니까? 
</p>
<p><b>○ 김대원 위원 </b> 그 조직을 말하는 겁니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 아닙니다.  그 조직은 제가 오자마자 폐지했습니다. 
</p>
<p><b>○ 김대원 위원 </b> 저는 그 조직이 이름이 바뀌어서 사무실을 이쪽으로 옮겨서 지금까지 유지돼서 도시환경자문팀으로 계속 운영되는지 알고 있었어요.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그 조직은 바람직하지 않은 조직이라고 생각했기 때문에 바로 폐지했습니다. 
</p>
<p><b>○ 김대원 위원 </b> 작년부터 제가 묻는 요지가 그것이었습니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 아닙니다.  죄송합니다.
</p>
<p><b>○ 김대원 위원 </b> 알겠습니다.  이상입니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그리고 앞에서 위원님께서 누차 지적하신 것은 저희들이 뼈저리게 느끼고 앞으로 위원님을 비롯해서 기획위원회 모든 분과의 관계가 더욱더 돈독한 관계가 될 수 있도록 배전의 노력을 다하겠습니다.  믿어주십시오. 
</p>
<p><b>○ 김대원 위원 </b> 감사합니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 수고하셨습니다.  다음 함진규 위원 질의해 주시기 바랍니다. 
</p>
<p><b>○ 함진규 위원 </b> 수고 많으십니다. 고양시 출신 함진규 위원입니다.  김대원 위원님이 좋은 말씀해 주셨는데 세 가지만 대략적으로 묻겠습니다.  제가 보니까 연구원들이 상당히 이직현상이 심한 것으로 알고 있습니다.  기본적인 연구과제 수행이라고 하는 것이 단기간에 끝나는 것도 있지만 장기간의 연구를 요하는 것도 있고 또 단순한 연구로 끝나는 것이 아니라 기본적인 정서랄까, 해당지역에 대한 바탕이랄까 이런 것을 알아야 심도있는 연구가 가능하다고 보거든요.  그런데 연구원 특히 책임연구원 박사급 중에서 상당부분이 본 위원이 알고 있기로는 마치 하나의 지나가는 과정, 쉽게 얘기하면 다른 종합대학이든 단과대학이든 대학에 전임교수직으로 가기 위해서 잠시 거쳐가는 자리로 생각하는 경향이 많은 것으로 알고 있습니다.  그렇게 이직현상이 심한 이유는 무엇인지 하고, 두 번째 이직현상이 심하다면 그것이 급여문제 때문인지 아니면 원장님 말씀하신 대로 연구공간이라든가 급여를 제외한 다른 부분에 있어서의 위상이 튼튼하지 못한 이유 때문에 그만두는지 향후 대처방안이 있으면 말씀해 주시고요.
</p>
<p style="padding-left:1.2em">  그 다음에 연구원의 성격상 총정원이 59명이라고 하시는데 제가 분류는 안 해봤지만 주로 연구원의 성격상 박사급이 주류를 이룰 수밖에 없다고 생각되거든요.  그렇지만 연구라는 것이 박사만 가지고 모든 것이 해결될 수 있는 것이 아니고 석사 다시 말해서 석사나 학사쪽이라 하더라도 해당 분야에 대해서 실전·실무 경험이 많은 분들이 많습니다.  이런 분들을 앞으로도 채용해서 실무적인 경기도 내 뿐만 아니라 경기도와 관련된 산하 기초자치단체 같은 경우에도 용역사항들이 학문적인 것을 떠나서 실용적인 부분에서도 많은 연구대상들이 있다고 생각합니다.  그래서 석사나 학사급으로도 실무진을 더 채용할 용의가 없는지 그것을 첫 번째로 말씀드리고 싶고요.
</p>
<p style="padding-left:1.2em">  제가 엊그제도 정책기획관실 감사할 때 말씀드렸지만 경기도가 상당히 난처한 입장에 처해 있습니다.  마치 국가의 균형발전 개발에 대해서 우리가 반대하는 식으로 비쳐지는 게 있습니다.  차제에 경기개발연구원이 경기도와 관련된 기관임에는 틀림없기 때문에 경기도청에서 요청이 없다고 하더라도 경기도가 왜 발전돼야 하는지 타 지역에 국가중앙정부에서 주장하는 국토균형개발이라는 것을 경기도가 반대하는 것이 아니라 다만 경기도는 경기도 나름대로의 특색을 갖춘 개발논리를 가지고 설득할 수 있어야 합니다.  이것을 설득하지 않고 개발논리도 없이 무조건 중앙정부하고 부딪치는 인상을 주면 앞으로 경기도는 어려운 입장에 처해지고 여러분도 잘 아시다시피 국회에서도 수도권 위원들하고 지방위원들 하고 당내 뿐만 아니라 정당간, 당내간 전부 충돌하고 있습니다.  이런 상황에서 경기개발연구원이 어떠한 대응논리, 왜 경기도가 특화돼서 발전할 필요성이 있는지 대응논리를 개발해야 한다고 본 위원은 생각하거든요.  도청에서 요청사항이 없더라도 그런 논리를 개발해서 경기도청에 자료제공을 하든가 아니면 가능하다면 언론에 홍보할 가능성은 없는지 그 부분에 대해서 말씀을 해주시고요.
</p>
<p style="padding-left:1.2em">  세 번째는 지엽적인 부분이지만 번역사업이 있더라고요.  번역사업 부분이 세 건이 있습니다.  예산이 2,400만원 정도 되는데 조그만 거지만 이것이 단순번역사업이라면 경기개발연구원의 성격상 단순 영어 번역이든, 일본어 번역이든, 프랑스어 번역이든 단순번역 같은 것은 여기서 볼 때 효율적인 것이 아니라고 생각합니다.  이런 것은 단순한 외부용역기관에 번역을 의뢰를 하는 것이 낫고 오히려 심층적으로 다른 부분을 연구해야 할 책임연구원들이 아니면 이하 석사급 연구원들이 그런 부분에 매달리는 것이 바람직하지 않다고 생각하고 본 위원의 기우인지는 몰라도 그런 부분이 오히려 구색을 맞추기 위한 이러이러한 번역물도 간행한다라는 인상을 줄 수 있기 때문에 효율성이 없다면 과감히 외부기관에 용역을 줄 용의가 없는지 묻고 싶고요.
</p>
<p style="padding-left:1.2em">  그와 관련해서 33페이지입니다.  주요 업무보고 하신 내용 중 33페이지에 보면 작년에 수감기관이, 저희 위원들이 감사한 건가요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그렇습니다. 
</p>
<p><b>○ 함진규 위원 </b> 그때 어떤 분이 주장하셨는데, 기억은 안 나는데요.  제가 이 자리에 있었던 것 같은데요.  경기개발연구원에서 영문판이든 일본판이든 경기도의 위상과 관련된 또는 경제와 관련된 영문이든 일본어든 잡지를 만들어 내는 게 있습니까?  없다면 본 위원 생각은 좀 있어야지 이런 부분을 전혀 도외시하고 폐관한다는 것은 문제가 있다고 보고요.  왜 그러냐 이런 것을 통해서 경기도를 해외에 알릴 수 있는 그런 부분의 외국투자를 주도할 수 있는 부분이 있기 때문에 만들어서 외국대사관이라든가 상공회의소, 기타 외국회사 또는 지점을 두고 있는 이런 데도 그런 것을 배부할 필요가 있다고 생각이 됩니다.  그에 대한 견해를 말씀해 주십시오.  이상입니다.  
</p>
<p><b>○ 위원장대리 이원재 </b> 답변해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 답변드리겠습니다.  먼저 연구원의 이직 현상의 심각성에 대해서 지적을 해주셨습니다.  ''97년 이후에 우리 연구원에서 이직한 사람은 총 17명입니다.  이 중 이직사유를 보면 대학교수로간 분이 12명이 있고 기타연구소 등으로 가신 분들이 5명이 있습니다.  따라서 우리 연구원에서 이직하시는 사유가 어떤 급여의 불만족이라든지 또는 연구공간의 미흡 이런 것보다는 본인의 발전을 위한 그런 이직현상이라고 저희들은 생각하고 있습니다.  이러한 이직현상은 우리 연구원에만 국한된 것이 아니고 모든 연구기관들이 대개 있을 수 있는 일이고 특히 발전하는 연구기관일수록 그러한 현상은 더 있을 수 있다고 생각합니다.  오히려 지방의 많은 연구기관들 중에는 이러한 신진대사 교류가 없기 때문에 연구원이 정체화되어 가는 그러한 현상도 있습니다.  그러한 현상과 비교해 볼 때 이러한 정도의 이직현상은 오히려 연구원의 분위기를 위해서 바람직한 측면도 있다고 생각합니다.  다만 우리 연구원이 제대로 뒷바라지를 못해서 연구원에 불만을 가지고 가시는 분들 이런 분들이 없도록 관리하는 것은 앞으로도 계속 저희들이 유의해야 될 사항이라고 생각하고 또 현재 계신 분들이 항상 만족감을 가지고 일할 수 있는 분위기 그런 신바람 나는 연구분위기를 만들어 나가는 것도 우리들의 계속적인 과제가 되리라고 생각합니다.
</p>
<p style="padding-left:1.2em">  그리고 두 번째 석사급 연구원들도 채용이 되어야 되는 것이 아니냐, 석사급이나 학사급 연구원들도 있어야 되는 것 아니냐 라는 지적이신데요.  동의합니다.  지금도 사실 이름이 위촉이라는 말이 붙어서 그렇지 우리 연구원에는 박사급 연구원 외에 석사급, 학사급 연구원들이 많이 있습니다.  현재 56명의 위촉연구원이 있는데 석사급, 박사급 연구원들입니다.  그 사람들이 박사급 연구원들을 보좌하면서 연구를 하고 있는데 그러한 분들의 도움이 없이는 박사급 연구원들도 제대로 된 연구를 하기가 힘들 것이라고 생각을 합니다.  다만 우리 경기개발연구원은 가급적이면 우수한 박사급 연구원을 확보하는 것을 일단은 주 목표로 삼고 있습니다.  그런 우수한 박사급 연구원들이 들어옴으로써 경기 도정시책에 대해서 보다 정취한 연구, 심층적인 연구를 할 수 있으리라고 생각하기 때문입니다.  그러나 박사급 연구원보다 더 많은 석사급 내지 학사급 연구원들은 계속 우리들이 확보해야 된다고 생각하고 지금 그렇게 운영해 나가고 있습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 세 번째로 현재 수도권과 비수도권 간에 가장 크게 논란이 되고 있는 균형발전 시책에 대해서 우리 경기개발연구원이 나름대로의 역할을 해야 될 것이 아니냐 하는 지적의 말씀이 계셨습니다.  물론 동의합니다.  그리고 지금까지 그렇게 해오고 있습니다.  그것은 도의 요구에 의해서도 하고 있지만 또 우리 스스로가 어떤 존립근거에 의해서도 그러한 대처를 스스로 자발적으로 하고 있다는 말씀을 드리고 싶습니다.  이 자리에서 꼭 한번 말씀을 드리고 싶은 것은 정부가 국가균형발전특별법이라고 하는 법을 지금 제출해 놓고 있는데 그 법의 논리라든지 의도가 저희들로써는 적절하지 않다고 생각을 하고 있습니다.  지금 함 위원께서 지적하신 것처럼 경기도에 어떤 개발욕구라든지 현상 같은 것을 너무 몰이해하고 있는 부분들이 있다 이렇게 생각을 합니다.  앞으로 저희들은 정부제출법안의 불합리성을 지속적으로 지적해 나갈 것이고 따라서 이러한 우리들의 지적이 관철될 수 있도록 노력해 나갈 것입니다.  지금 우리 원내에는 여기에 대처하기 위한 태스크 포스팀이 만들어져서 운영되고 있습니다.
</p>
<p style="padding-left:1.2em">  그리고 그 다음 네 번째로 번역사업 같은 것을 외부에 의뢰해서 하는 것이 더 효율적이지 않느냐 라는 지적을 해주셨습니다.  물론 저희들 외부에 의뢰해서 하고 있습니다.  지금 여기서 우리 박사들이 관여하고 있는 것은 직접 번역을 하는 데 관여하는 것이 아니라 외부에 의뢰해서 하는 번역을 감수하는 역할을 저희들이 하고 있습니다.  이 중 2,400만원의 번역사업비가 들어가는 것은 번역을 위한 번역료가 외부에 지출되는 그러한 것들을 예산적으로 표현한 것입니다.  
</p>
<p style="padding-left:1.2em">  끝으로 영문잡지 폐간의 불합리성을 지적하시고 그러한 잡지가 존치해야 되는 것 아니냐 하는 지적을 하셨습니다.  어떻게 보면 함 위원님 말씀에 저희들이 부끄럽게 생각을 합니다.  영문잡지를 지속적으로 발간할 수 있는 그런 체제를 확보할 수 있다고 그러면 그것도 매우 바람직한 것이라고 생각합니다.  그런데 이제까지 경기이코노믹이라고 하는 영문잡지를 발간해 오다가 이번에 폐간을 하게 된 것은 발간의 실효성에 대해서 일단 재평가를 하게 되었기 때문입니다. 
</p>
<p style="padding-left:1.2em">  그 동안 우리가 발간한 영문잡지가 얼마만큼 기여를 해왔는가 라는 것을 되새겨 볼 때 미흡한 점들이 많았다 그래서 이번에 잠시 쉬면서 우리가 다시 한 번 새로운 방법을 모색해 봐야 되는 것이 아니냐, 그리고 우리 내부역량을 충전하는 것도 필요하지 않느냐, 집필진들이라든지 참여했던 분들이 그 동안 지쳐 있었던 것 같습니다.  그래서 이런 것들을 잠시 되돌아보면서 내부역량을 보충한 다음에 재검토 하도록 하겠습니다.  이상입니다. 
</p>
<p><b>○ 함진규 위원 </b> 추가적으로 말씀드리고 싶은 것은 아까 연구원에 박사말고 석사나 학사급을 채용할 의사가 없느냐고 물었던 것은 물론 박사들이 학문적으로는 우수하다 하더라도 어쨌든 실무적인 측면이 많은 거기 때문에 그런 부분들을 말씀드렸던 거고 가장 중요한 것은 석사나 박사, 또는 학사 이런 분들의 연령 제한이 있나요?  채용하는데 예를 들면 석사는 몇 살까지, 학사는 몇 살까지, 박사는 몇 살까지 어떤 채용 연량 상한선이라고 그럴까요, 그런 기준이 있습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 없습니다. 
</p>
<p><b>○ 함진규 위원 </b> 없으면 다행이고, 앞으로 공무원을 우수하게, 예를 들면 중간에 한 40대든 30대든 이런 분들이 퇴직하신 분들이 아니면 외적인 기관에서도 우수한 분이 있으면 이러한 분들을 좀 활용하십사 하는 뜻이고 그 다음에 마지막으로 당부드리고 싶은 것은 뭐니뭐니 해도 급여라고 생각합니다.  이직현상에 대해서 순기능적인 측면만을 말씀해 주셨는데요.  제가 볼 때에는 급여가 자기 활동하는 것에 비해서 상응하지 못하다고 그러면 어느 누구도 열심히 일을 하려는 의욕이 없기 때문에 그에 상응하는 급여도 형평성이 특히 박사, 석사, 학사 이 부분들에 있어서 어느 정도 형평성이 있어야지 너무 차이가 난다든가 지나칠 정도가 되면 상당히 의욕이 떨어진다고 봅니다.  그런 부분을 말씀드렸고요.  마지막으로 번역사업에 대해서 말씀드렸던 것은 저도 경기개발연구원에서 자료가 많이 집에 배달이 됩니다.  눈에 띄는 것은 좀 보고 때로는 저장해 놓고 이런 상태에 있는데 한글발행부수 또는 종류에 비해서 활용도가 굉장히 낮다고 생각하는데 외국인들 같은 경우에는 전혀 경기도에 대한 자료를 볼 수가 없는 상황입니다.  경기도에 관한 영문자료를 어디서 구해볼 수 있겠습니까?  어디가 있겠습니까?  이것은 부수나 효율성 이런 것을 떠나서 단 한 명이 보더라도 엄청난 양의 투자를 할 경우에 그 효과라는 것은 실로 막대하거든요.  이런 부분을 집중적으로 생각을 하셔야지 그것을 생각을 안 하면 경기도를 홍보할 수 있는 방안이 없다고 생각을 합니다.  답변은 필요 없습니다.  이상입니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 수고하셨습니다.  다음은 김준회 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김준회 위원 </b> 저는 부천출신 김준회 위원입니다.  우선 재정에 대해서 몇 가지 질의하고자 합니다.  2002년도보다 현재 재정자립도의 달라진 차이점이라든지 2002년도, 재정자립도가 금년에는 37.4%로 나왔는데 작년에는 몇 %였죠?  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 말씀드리겠습니다.  2000년도에 자립도가 33%, 금년도에는 현재까지 44%로 분석되고 있습니다. 
</p>
<p><b>○ 김준회 위원 </b> 현재 44%입니까?  유인물에는 37.8%로 나왔거든요.  왜 이런 질의를 드리느냐 하면 경기개발연구원 개원이 1995년 3월 20일로 되어 있습니다.  약 10년 가까운 세월이 되면서 그 동안 제 개인적으로 판단할 때 상당히 지명도가 있는 연구원이라고 생각을 하는데 10년의 세월이 가까워 오면서 재정자립도가 40%도 안 된다고 하는 것은 개인적으로 아쉬운 부분이 있는데 재정자립도 100% 다 올릴 수 있다면 몇 년도까지 예측해 보셨습니까?  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 100%는 생각해 본 적이 없습니다.  지난번에 2006 KRI장기비전을 위원님들께 보고드리면서 저희들이 2006년 목표연도에 재정자립도를 50%로 올리도록 준비하겠습니다라고 보고 드린 적이 있습니다.  다만 50%의 재정자립도를 확보하기 위해서 기금의 규모를 현재보다 조금 늘려야 되겠다 그런 내용을 보고드렸습니다.  물론 기금의 증액뿐만 아니라 저희들 자체적인 수주노력도 아울러서 겸비가 되어야 된다고 생각합니다.  
</p>
<p><b>○ 김준회 위원 </b> 그럼 원장님의 답변은 기금을 늘려야 된다고 말씀하시는데 결국은 기금 늘려서 수익금으로 충당하겠다는 그런 논리밖에 안 되지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그런 논리도 있습니다.  기금의 규모가 은행과 협상을 해나가는데 있어서 협상력을 확보하기 위해서는 규모가 지금보다 늘었으면 하는 것을 지난번에도 보고를 드렸습니다마는 지금도 그런 생각을 가지고 있습니다. 
</p>
<p><b>○ 김준회 위원 </b> 기금을 늘리겠다는 것은 그것도 역시 경기도에 의존하겠다는, 개인적으로 자립도라고 볼 수가 없는데 아쉬운 부분이 여기 유인물을 잠시 검토한 결과 연구간행물이 상당히 많은 부수가 발행이 됐는데 이게 2003년도에 전부 연구간행물 판매부수가 1,114권밖에 안 됐어요.  그리고 금액은 이 연구원에서 볼 때 1,190만원이라는 판매금액밖에 실적이 없습니다.  물론 함 위원님이 일부분 지적했습니다만 이런 부분이 너무나 아쉽다 본 위원은 이런 생각을 하고 있는데 그러다 보니까 재정자립도에 대해서 너무나 방심하는 것 같습니다.  언제까지 경기도에 의존하고 계속 혈세를 낭비할 것인지 사실 그런 부분이 아쉽습니다.  그리고 2002년도에는 숱한 간행물을 발행했습니다마는 1,663건밖에 외부에 판매되지 않았습니다.  금액이 또 1,440만원밖에 안 돼요.  그래서 이런 것이 우선 아주 확 달라져야만 이것도 재정자립도의 한 방법이 아닌가 이런 생각을 갖습니다.  이런 부분에 대해서 어떻게 생각하십니까?  그리고 이 간행물에 대해서 현재 서점이나 이런 데는 일절 내보내지 않습니까?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 내보내고 있습니다.  판매수입이라는 것이 바로 서점에서 판매한 수입입니다.  
</p>
<p><b>○ 김준회 위원 </b> 그런데 간행물 양으로 봐서 1,000여권밖에 안 된다는 것은 연구간행물이 특성상 그렇게 밖에 될 수가 없는지 본 위원으로서는 궁금한데 그런 부분에 대해서 답변해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 김 위원님 지적말씀 정말 많은 부분 공감하고 있습니다.  연구간행물의 특성상 독자가 많지 않기 때문에 판매실적이 저조하다는 것은 일반적인 현상이라고 생각합니다.  따라서 판매실적을 획기적으로 증가시킨다고 하는 것은 현재로써는 매우 어려운 과제라고 생각이 됩니다.  다만 저희들 연구원이 보다 발전되고 어느 정도 위상을 갖추게 되고 연구진들 개개인의 능력이 대외적으로 확실하게 인증을 받게 된다고 하면 판매실적은 그 이상으로 증가될 수 있으리라고 봐집니다.  부끄러운 말씀이지만 연구원이 만들어진지 일천하기 때문에 이런 정도의 실적밖에 낼 수 없었다는 것을 이해해 주시고 앞으로 판매실적 배가에 더욱더 노력을 해 나가겠습니다.
</p>
<p><b>○ 김준회 위원 </b> 감사자료 111면 보면 1부도 판매되지 않는 부수도 있고 한자리 숫자에서 맴돌고 있는데 이런 부분이 너무나 아쉽다는 말씀을 드리고 그리고 원장님 보고 말씀 중 연구원에 대해서 현 건물을 토끼장 같은 환경이라고 말씀하셨는데 내년도에는 새 건물로 이사갈 줄로 알고 있는데 제 개인적으로는 그런 표현이 적절한가 이런 아쉬움도 있었는데 현재 인원이 56명이라고 했습니다.  건평 851평이고 개인별 수치로 보면 약 15평이 되는데 물론 이중에는 연구시설 이런 부분도 차지할 것으로 압니다.  적정한 시설규모라면 어느 정도로 생각을 하고 계십니까?  예를 들어 건평이라면 몇 평이고.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 신 청사로 옮길 경우에 연구진 1인당 연구공간을 5.3평 확보하는 것으로 계획되어 있습니다.  당초에 사실은 1인당 연구공간을 6평으로 욕심을 낸 적이 있었는데 반영이 안 됐고 51평이 배정되었습니다. 
</p>
<p><b>○ 김준회 위원 </b> 그럼 옮기시는데 전체 평수가 몇 평이에요. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 1,630평됩니다. 
</p>
<p><b>○ 김준회 위원 </b> 현재 총재정의 임금 여기 월수당이라고 표시를 했는데 몇 % 차지합니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 전체 예산 중 인건비 말씀하시는 겁니까? 
</p>
<p><b>○ 김준회 위원 </b> 네. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 인건비 비중이 35%가 되죠.  
</p>
<p><b>○ 김준회 위원 </b> 그런데 새로 이전하는 데가 1인당 5.3평이면 현재 이 건물이 821평인데 현재보다도 개인당 면적이 적다는 그런 계산이 나오네요.  현재는 851평에 56명으로 본다면 개인당 면적이 15평 정도 되는 데요.  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 지금 전체를 총괄해 가지고 연면적을 전체인력으로 나누는 1인당 공간면적 계산방법을 저희들은 쓰고 있지 않습니다.  건축 연면적 중에서 연구에 공여될 수 있는 면적, 연구진에게 공여될 수 있는 면적을 계산해서 그것을 개인의 숫자로 나눈 것입니다.  그랬을 때에 연구공간이 현재는 3평 정도밖에 안 됩니다.  그런데 앞으로 이것을 5.3평 정도로 늘리게 되면 연구분위기가 좋아질 수 있을 것이다 그렇게 전망을 하고 있습니다. 
</p>
<p><b>○ 김준회 위원 </b> 마지막으로 본 위원의 부탁은 너무 경기도에만 의존하지 마시고 더 대외적으로 열심히 수탁을 받아서 재정자립도가 빨리 이루어질 수 있도록 그런 부탁을 드립니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 위원님!  들으시기에 언짢으실는지 모르겠는데요.  재정자립도를 늘리는 것이 연구원의 궁극적인 목표가 될 수는 없다고 생각합니다.  그런 식으로 하게 되면 저희들 올릴 수 있는 방법이 없는 것도 아닙니다.  
</p>
<p><b>○ 김준회 위원 </b> 그런 부분도 일부 인정은 합니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 저희들이 어디까지나 공공성을 중시하다 보니까 민간으로부터는 일체 수주를 안 받고 있습니다.  그런 것 받기 시작하면 자립도를 올리는 것은 할 수 있을지도 모릅니다.  그것을 양해해 주시기 바랍니다.  
</p>
<p><b>○ 김준회 위원 </b> 우선 언급했습니다만서도 연구간행물이 많은 부수를 발행했는데 종류도 여러 가지고 그런데 이렇게 미미하다 보니까 그런 생각이 들어서 말씀드린 겁니다.  이해합니다.  제 질의 마치겠습니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 다음 질의하실 분, 김영복 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 김영복 위원 </b> 가평출신 김영복 위원입니다.  먼저 연구환경이 좋지 않은 시설과 여건에도 불구하고 고생하시는 이철규 원장님을 비롯한 연구원과 관계자 여러분의 노고에 진심으로 감사를 드립니다.  본 위원은 먼저 연구과제에 대한 양과 질에 대해서 질의를 드리겠습니다.  양은 어떻게 보면 수탁관계고 질은 위탁관계에서 어떤 객관적인 이런 면에서 말씀을 드려보겠는데요.  지금 연구인력을 보니까 늘어나지 않는 가운데서도 2001년도, 2002년도, 2003년도 대비가 우리 연구과제가 건수로 111건에서 133건, 143건, 1인당 수행건수가 2001년도 4.1건에서 2002년도 4.3건 2003년도에는 4.6건까지 올라와 있습니다.  앞으로 2004년도 계획을 보니까 더 많아지는 것 같아요.  그래서 본 위원이 거기에 대해서 질의를 드리겠습니다.  수탁관계에서 우리 용역비 수입현황을 보니까 업무보고 자료하고 행정감사자료가 틀린 면이 있습니다.  확인 좀 하나 시켜주세요.  2002년도 27건의 용역비가 행정감사자료에 보면 24억 9,851만 2,000원으로 나오는데요 업무보고에 보면 아까 보니까 약 25억 2,600만원 정도가 나옵니다.  틀리거든요.  건수는 맞는데, 나중에 확인 좀 시켜주시고 2003년도에 보니까 수탁연구가 무려 27건에 수입 올리는 것은 좋겠지만 수입금액이 37억원까지 올라갔어요.  대신 깊게 생각해야될 부분이 위탁연구추진인데 사실 어떻게 보면 질적 향상을 위한…….
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 위원님, 지금 보시고 있는 자료가 어떤 자료죠? 
</p>
<p><b>○ 김영복 위원 </b> 그러니까 행정감사자료하고 업무보고 하고 같이 맞물려 있습니다. 그럼 페이지 수를 말씀드리면 위탁관계연구에 대해서는 23쪽을 봐주시고요.  용역비 수입현황과 맞물려서 수탁관계에 대해서는 행정감사자료 659쪽을 봐 주시기 바랍니다.  못 보셨으니까 제가 다시 말씀을 드릴게요.  연구용역비 수입현황을 보면 659쪽입니다.  거기에 보면 2002년도 27건에 용역수입이 24억 9,851만 2,000만원 정도 나와 있거든요.  그런데 아까 업무보고에 보니까 25억 2,600만원, 업무보고 16쪽입니다.  수탁금액, 이게 건수는 맞는데 좀 차이가 나요.  확인 좀 해주시고 원장님은 수탁관계 수입이 날로 늘어나는 것도 좋지만 사실 위탁관계에서 저희가 경기개발연구원에서 연구한 게 경기도에서 토론회라든가 다른 연구자료에서도 보면 사실 아까도 말씀하셨지만 객관적인 면에서 남들이 설득이 가고 그래야 되거든요.  토론회에서도 누가 제시하는 그런 연구하시는 분들이 남들이 보기에도 거기에 올바른 방향으로 가야 된다고 보는데 여기에 보면 앞으로 계획이 위탁연구는 보니까 2001년도에 11건, 2002년도에 11건, 2003년도에 11건 해 가지고 건수가 꽤 됩니다.  그런데 2004년도 계획보니까 9건으로 줄어요.  그렇게 됐을 때 앞으로 경기개발연구원 KRI비전 2006년도 계획을 보면 지역정책연구에 있어서 한국 최고로 가야될 방향 그 다음에 세계화 속에서는 동북아의 초인류 연구기관으로 남겠다고 하는데 과연 그런 식으로 가능한지 궁금합니다.  거기에 대해서 답변을 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 연구의 종류가 기본연구도 있고, 정책연구도 있고, 위탁연구도 있고, 수탁연구도 있고 그런데 위탁연구는 저희들의 경우 하느냐 하면 자체적으로 연구진을 확보하고 있지 못한 경우에 하고 또 다른 경우는 학연간에 연구네트워크를 조성하기 위해서 일부러 우리하고 협력이 필요한 기관에 위탁을 줘서 같이 상부상조 하는 목적으로 운영하고 있습니다.  그런데 평균적으로 보니까 1년에 10건 정도 하더라 그런 개념입니다.  이번에 용역비를 2003년도와 마찬가지로 3억원을 요구해 왔습니다.  늘리지 않고 요구한 겁니다.  저희들이 예산을 너무 경직되게 운영하지 않기 때문에 만약에 운영하다가 위탁연구의 필요성이 더 증대된다면 늘릴 수 있습니다.  다만 위탁연구의 증가만이 우리 연구원의 목표는 아니고, 김 위원님 지적하신 대로 연구의 양과 질이 같이 가는 연구여야 하기 때문에 우리들이 하는 연구들을 어떻게 하면 업그레이드 시킬 수 있을까 그런 쪽에 초점을 맞추다 보니까 건수 부분들은 크게 증가되거나 그렇지 않도록 예산이 짜여져 있습니다. 
</p>
<p><b>○ 김영복 위원 </b> 본 위원이 보니까 3년에 걸쳐서 위탁연구를 했더니 1년에 약 5억원정도씩 들어갔네요.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 위탁이요?
</p>
<p><b>○ 김영복 위원 </b> 위탁연구가 31건에 3년 동안…….
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 위탁은 다른 데 우리 돈을 줘서 주는 겁니다.  수탁은 우리가 돈을 받는 겁니다. 
</p>
<p><b>○ 김영복 위원 </b> 알고 있어요.  왜냐하면 위탁연구에 5억원 정도가 들어갔는데 저는 2004년도 계획에 보니까 9번에, 제가 왜 지적을 하냐 하면 인원이 부족하다고 얘기하지 않았습니까?  자료에도 나와 있고.  2002년도에 비해서 2003년도에 보니까 비상근 연구인력이 37명에서 58명까지 늘은 것은 다행이라고 생각하는데 그것을 나름대로 연구하는데 보탬이 되지 않을까 이런 것은 맞습니다.  그런데 저는 느끼는 게 정말 계획대로 인원에 대해 안 하고 예산이라든가 2004년도 계획을 봤을 때 아까도 말씀드렸지만 진정한 최고의 결과를 자랑하는 용역이 나올 수 있나 궁금증이 있어서 말씀을 드리는 거거든요.  원장님이 자신있다고 하면 자신있겠지만 저는 원장님 생각하고 나름대로 연구를 하시는 분들하고는 생각이 틀리다라고 생각합니다.  왜냐하면 연구하시는 분들도 제가 봤을 적에 과제가 너무 많고 하면 사람이 일에 시달려서 좋게 안나오는 거거든요.  저희 위원들도 자료가 워낙 많습니다.  보는 한계가 있어요.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 위원님!  제 얘기를 듣지 마시고 연구하시는 분들께 직접 한 번 들어보시죠.
</p>
<p><b>○ 김영복 위원 </b> 기회를 드리겠습니다.  누가 한 번 말씀해 주시기 바랍니다.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기획조정실장 이상훈입니다.  김 위원님 말씀에 동의를 합니다.  저희들은 두 가지 고민이 있습니다.  특정한 현안이 발생했을 때 연구원에서 누가 할 것인가라는 고민을 하고요.  외부에는 누가 경쟁력이 있다고 해서 나갔는데, 또 한 가지 고민은 첫 번째는 문제가 없습니다.  저희보다 경쟁력이 있어서 외부에 나가는데 또 한 가지 고민은 과연 이분들이 연구를 해줘서 우리 연구원에서 한 것보다 더 나을까 바로 그 문제입니다.  그 동안 확대해서 여러 가지 시행을 해봤는데 연구결과에 대한 평가를 사실 저희들이 냉정하게 판단하고 있습니다.  이 건에 대해서는 건수, 외부에 위탁나간 과제수가 문제가 아니라 조금 더 경쟁력있게, 정작 경기개발연구원이 경쟁력이 없는 부분에 대해서만 할애해야 되겠다 나름대로 검토한 결과라는 것을 보고드리겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 본 위원도 생각은 그렇습니다.  왜 그런 말씀을 드리냐 하면 위탁연구 부분에서도 경기개발연구원에서 연구원들을 다 가지고 있다면 좋겠지요.  그렇지 않은데 다른 데 위탁연구줘서 참고해서 하다 보면 나중에 다른 사람한테 비춰질 때는 자료를 자세히 안 보면 경기개발연구원에서 그런 자료를 낸 줄 압니다.  그리고 위탁된 내용은 참고를 안 합니다.  가장 좋은 방법은 연구진을 확보해서 계획대로 자체적으로 가면 좋겠죠.  저는 장기적으로 그런 쪽에서 대비를 해달라는 말씀을 드리겠습니다.  그래서 자립도 이런 것을 연구원에서 하는 것은 잘못이죠.  그래서 연구과제에 대한 평가, 연구과제에 대해 연구를 했으면 시간이 흘러서 나중에 결과를 봤을 때 그 결과가 역시 맞았다 라는 게 나와야 되거든요.  왜 그런 말씀을 드리느냐 하면 쉽게 말씀을 드리겠습니다.  
</p>
<p style="padding-left:1.2em">  경기도의 세입에 대해서 추계를 했습니다.  제가 거기에 있어 봤습니다.  경기개발연구원에서 연구한 추계하고 관계공무원들이 생각하는 추계하고 전혀 안 맞는다라는 괴리를 느낍니다.  인정을 안 해요.  그게 현실이거든요.  그렇게 봤을 적에 앞으로 연구원에서 했던 결과가 3년, 4년 뒤에 딱 맞아 들어갔을 때 역시 그때가 맞았구나 라는 걸 느낍니다.  당장 내년이라도 1년이 흘러가면 올해 2003년도 경제성장하고 맞물려서 떨어지거든요.  이런 게 신뢰거든요.  그래서 그런 쪽으로 질보다 양적으로 발전이 있기를 바래서 질의를 드렸고요.  마지막으로 앞으로 경기개발연구원 2006비전처럼 한국최고의 지역정책연구 전문기관, 세계화의 흐름 속에서 동북아의 초일류 연구기관이 되시기를 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 수고하셨습니다.  이건희 위원 질의해 주시기 바랍니다. 
</p>
<p><b>○ 정인영 위원 </b> 연결된 질의이기 때문에 보충질의하겠습니다.  
</p>
<p><b>○ 위원장대리 이원재 </b> 의사진행에 협조를 해주시기 바랍니다.  정인영 위원 질의해 주시기 바랍니다. 
</p>
<p><b>○ 정인영 위원 </b> 경기개발연구원에서 열악한 환경과 인원을 가지고 많은 노력을 해주신데 대해서 이철규 원장님을 비롯한 연구원 여러분들께 감사의 말씀을 드리면서 김영복 위원님이 성과물에 관한 질의를 했기 때문에 본 위원이 보충해서 질의를 드리겠습니다.  실질적으로 내용이 빈약한 성과물은 의미가 없다고 봅니다.  내용이 빈약한 성과물을 양산하게 되는 여러 가지 요인들이 있겠지만 첫째는 연구원들이 준비되지 않은 상태에서 연구 또 업무가 과중된 상태 내지는 과제가 너무 많이 부여됨으로 인해서 한 문제를 가지고 깊이 파악하지 못하는 문제들에 기인한다고 봅니다.  실질적으로 자료에도 보면 연구과제가 2001년도에 111건에서 2002년도 113건, 2003년 10월 현재 113건 등으로 연구과제가 점점 늘어나고 있습니다.  그러면 과연 경기개발연구원에서 연구한 과제평가를 어떻게 하고 계십니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 평가에 신경쓰고 있습니다.  연구를 할 때 하나의 연구과제에 대해서는 세 번의 평가를 받습니다.  처음에 시작할 때 착수심의하면서 평가받고요.  중간에 중간평가 받고, 연구가 끝나면 나중에 최종평가 받습니다. 
</p>
<p><b>○ 정인영 위원 </b> 평가하는 특별한 팀이 있습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네, 평가위원이 사전에 선정됩니다.  본인의 의사와 관계없이 선정됩니다. 
</p>
<p><b>○ 정인영 위원 </b> 평가위원이 본인의 의사와 관계없이 연구원 자체내 인력으로 구성됩니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 아닙니다.  내부, 외부, 도청 이렇게 다양하게 평가팀이 구성됩니다. 
</p>
<p><b>○ 정인영 위원 </b> 그렇게 해서 평가를 제대로 함으로써 성과급도 평가에 의해서 지급이 되겠지만 그러한 시스템이 되어 있어야 과제물을 양산하는 연구가 되지 않는 것으로 알고 있고요.  또 한 가지는 정기간행물을 5점을 발행하고 있습니다만 실질적으로 전문가들이 경기개발연구원에서 연구한 연구물을 인용하는 경우가 있겠습니다만 애독할 수 있는 연구물 내지는 잡지가 나와야 한다고 보는데 그 점에 대해서는 어떻게 생각하세요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 정기간행물 말씀하십니까? 
</p>
<p><b>○ 정인영 위원 </b> 네.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 정기간행물이 여러 논란이 있었지만 이번에 2건을 폐지하는 것도 바로 그런 취지입니다.  간행물을 많이 발간하는 것이 능사가 아니고 하나를 하더라도 제대로 해야 되겠다.  읽히는 간행물이 돼야 하겠다는 의미에서 이번에 일부 통·폐합을 하게된 건데요.  아직까지도 자신있다고 말할 수는 없습니다.  그러나 편집진을 계속 보강하고 원고집필진들 선정에도 신경을 써서 보다 읽히는 그리고 평가받을 수 있는 잡지가 되도록 노력하겠습니다. 
</p>
<p><b>○ 정인영 위원 </b> 잡지문제는 그렇고요.  경기개발연구원에서 2003년도에 초빙연구원을 9명을 위촉했고요.  위촉기간을 보면 상당히 위촉기간이 짧습니다.  2003년 10월 16일부터 12월 15일까지 초빙연구원을 위촉하게 되면 2개월에 불과한 위촉기간이고 월수당 지급액도 231만원에 불과한 수당을 지급하면 과연 이러한 상태하에서 연구기관과 월수당 지급액이 적은 상태에서 위촉사유를 보면 굉장히 중요한 문제들을 위촉하고 있습니다.  이게 과연 가능하겠느냐는 질의고요.
</p>
<p style="padding-left:1.2em">  두 번째 비상임연구위원회는 58명을 위촉했는데 이것은 더 심합니다.  위촉사유를 일일이 나열할 수 없지만 굉장히 중요한 연구들을 했습니다.  예를 들어서 경기도의 현안분석, 미 나토·소파연구 굉장히 중요한 연구과제물을 주는데 이게 심지어는 어떠한 경우가 있느냐 하면 불과 보름에 불과한 2003년 1월 10일에 위촉해서 2003년 1월 25일 보름 동안 위촉해서 과제물을 줍니다.  월수당 지급액은 80만원에 불과합니다.  이런 가운데서 제대로된 연구물이 나올까 하는 의아심을 갖는데요.  그 점에 대해서는 원장님 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 연구원의 특성인데요.  그런 점을 이해해 주셔야겠는데요.  연구원에는 상근연구원이 있습니다.  여기 계신 박사님들이고 현재 우리가 38명의 상근연구원 박사들을 확보하고 있습니다.  그 분들이 여러 가지 연구를 하는데 한 가지 과제를, 물론 전문성이 있어서 본인이 연구한다 하더라도 그 과제와 관련된 다른 관련된 연구를 아울러서 하지 않으면 안될 경우가 많습니다.  그럴 경우에는 이 연구원에는 없지만 밖에 계신 분들의 협력을 받는 게 도움이 됩니다.  그래서 그 분들의 도움을 장기적으로 받아야 될 필요가 있다고 할 때는 초빙의 형태를 취하고 단기적으로 "당신은 chapter 1, chapter 2 이것만 해결해 주시오"  이럴 경우에는 월 80만원, 경우에 따라서 정교수급이면 100만원도 줄 수 있죠.  그렇게 해서 협조를 받습니다.  그런 경우에는 비상임연구원이라는 표현을 쓰고 있는데요.  초빙연구원은 여기 와서 한달 내내 근무하면서 일을 하시는 분도 있기 때문에 230만원 정도의 봉급이 나가는 것이고 비상임연구위원은 여기서 근무하지 않는 분들이고 자기 본직업을 가지고 계신 교수님들이 태반이기 때문에, 그 분들이 원하기 때문에 받고 참여하시는 겁니다. 
</p>
<p><b>○ 정인영 위원 </b> 그러면 자문만 구하는 겁니까?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 리포트를 냅니다. 
</p>
<p><b>○ 정인영 위원 </b> 당연히 리포트를 내는데 본 위원은 원장님께서 충분하다고 말씀하시니까 할 얘기가 없습니다.  그런 환경 하에서 더 좋은 연구원이 나오기를 바라고요. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 위원님들이 예산을 늘려주시면 더 지불하도록 하겠습니다.
</p>
<p><b>○ 정인영 위원 </b> 마지막으로 질의 하나 더 드리겠습니다.  연구년 휴직제 운영관계인데요.  2001년도에 1명, 2002년도에 2명을 보냈고, 2003년도에는 1명밖에 보내지 않았습니다.  김근수 선임연구원이 브리티쉬 콜럼비아 유니버시티에 가서 휴직기간을 1년 정도 줬는데요.  석·박사들의, 연구를 직으로 하는 사람들은 휴직기간이 필요하고 선진국에 가서 자기가 필요로 하는 문물을 받아들일 수 있는 기회를 많이 줘야된다고 생각하는데 앞으로 이 휴직제 운영과 관련해서 인원과 예산을 더 늘릴 의향은 없으신지요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 늘릴 의향이 있습니다.  더 늘렸으면 좋겠습니다. 
</p>
<p><b>○ 정인영 위원 </b> 더 늘리셔서 연구원들이 넓은 세상에 가서 인원이 상당히 많은데도 불구하고 1년에 1명 정도 보낸다는 것은. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 1년에 2명갑니다. 
</p>
<p><b>○ 정인영 위원 </b> 그런데 지금 2003년에 1명밖에 보내지 않았습니까?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 바로 연초되기 전해에 출발했기 때문에 여기에 카운트가 안 됐습니다. 
</p>
<p><b>○ 정인영 위원 </b> 인원을 늘려서 충분히 연구원들이 개인적으로 연구를 하고 공부를 해서 연구원의 발전을 위해서 노력할 수 있는 기회를 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 정 위원님 말씀에 제가 하나 붙여서 답변하고 싶은데요.  저희들 자랑도 섞여 있습니다.  최근에 한 박사가 연구를 끝내고 엊그제 귀국했습니다.  일본에 있다가 왔는데 일본에서 다른 한국에서 오신 분들을 만났는데 경기개발연구원에서 1년 동안 연구년으로 나와 있다.  그리고 한 달에 얼마씩의 지원도 받고 있다.  이런 얘기를 하고, 나 뿐만 아니라 미국에도 가있고 캐나다에도 가 있다.  이런 얘기를 하니까 그 경기개발연구원이라는 데가 뭐 하는 덴데 그렇게 잘해 주느냐?  그런 말을 하더랍니다.  자기도 가슴이 뿌듯했다는 얘기를 하는 걸 들었습니다.  물론 시작이기 때문에 아직 1년에 2명밖에 시행을 못하고 있는데 앞으로 이것을 자꾸 늘리고 연구년 가시는 분들도 아무렇게나 가는 게 아니라 정말 좋은 데 가서 휴식을 하시고 오실 수 있도록, 좋은 학교라든지, 연구원에 가서 충전하고 오실 수 있도록 그렇게 운영해 나갈 필요가 있다고 생각합니다.  정 위원께서 관심을 가져주셔서 감사합니다. 
</p>
<p><b>○ 정인영 위원 </b> 그렇습니다.  휴직연제라고 해서 완전히 가서 쉬는 게 아니고 사실 선진외국에 가서 재충전의 기회를 갖는 거거든요.  굉장히 중요한 사항인 것 같습니다.  그런 기회를 많이 부여해 주시기 바라고요.
</p>
<p style="padding-left:1.2em">  마지막으로 자료문제인데요.  앞으로는 도의원님들한테 전부 노트북이 제공돼서 노트북을 사용할 수 있는, 종이없는 프로젝트를 추진해서, 제가 정보화위원장입니다.  그래서 정보화위원회에서 종이없는 프로젝트를 추진하자, 앞으로 노트북 서버나 시디에 자료를 받아서 이런 낭비적인 요소를 없애자 이렇게 얘기를 해서 자료를 받아 봤는데요.  물론 그대로 다운로드 받은 거니까 문제가 없겠습니다만 문제가 뭐냐 하면 목차를 클릭하면 바로 본문이 나오도록 해주면 노트북 가지고도 자료를 검토할 수 있습니다.  그런 문제를 개선해 주셨으면 고맙겠습니다.  이상입니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 정인영 위원 수고하셨습니다.  이건희 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이건희 위원 </b> 저는 이건희 위원입니다.  경기도의 비전과 정책제시 그리고 중앙부처와의 대응도 모든 연구를 떠나서 정책대결까지는 경기개발연구원 이철규 원장님과 모든 분들께 고맙다는 말씀을 드립니다.  며칠 전에도 김 박사께서 국가균형특별법에 대해서 TV토론에서 선진국의 예를 들어가면서 하는 이야기들을 들었습니다.  제가 말씀드리고자 하는 것은 수많은 과제를 위탁받아서 연구하는데 지금까지 정인영 위원이나 많은 분들이 지적했듯이 연구인력에 비해서 과제가 너무 많다는 말씀을 드립니다.  연구인력에 대해서 너무나 많은 과제를 하다 보니까 도정에 대한 최선의 정책제시라든지 이런 것들이 부실할 수 있고 그 많은 연구 노력을 해서 도정정책에 반영되지 않는다는 게 아쉬움이 있다는 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  또 한 가지는 중복된 과제들이 상당히 많이 보이는 것 같습니다.  중복된 과제의 예를 들어보게 되면 팔당상수원 관련된 128페이지 제가 잠시 예를 들어서 했는데요.  이것은 중복이 어떻게 돼 있는가 하면 맨 먼저 연구기간이 1995년 7월부터 경기도 팔당상류지역 수질관리를 위한 행·재정적 지원방향에 대해서 맨 밑에 있는 수탁연구과제로 돼있는 한강수계 수질보전 및 진단방안연구가 돼 있습니다.  무슨 말씀이냐 하면 이런 것 물론 1년 한 번에 끝낼 수 없습니다.  그때 그때 한강법이 바뀌고 그러다 보면, 또 이번에 오염총량제까지 관련해서 연결을 해야 되겠지만 제가 봤을 때는 이런 내용은 중복된 연구다.  물론 지속해서 연구를 해야 되겠지만 너무 많은 분들이 같은 것을 가지고 연구하지 않았나 라는 생각이 드는데 거기에 대해서 말씀을 해주십시오. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 죄송합니다.  제가 그 부분에 전문성이 떨어지기 때문에 송미영 박사로 하여금 답변드리겠습니다.  양해해 주시겠습니까? 
</p>
<p><b>○ 이건희 위원 </b> 네.
</p>
<p><b>○ 환경정책연구부장 송미영 </b> 환경정책연구부장 송미영입니다.  위원님 말씀하시는 뜻은 제가 잘 이해하겠고요.  위원님들이 만약 팔당상수원에 시·군에서 오셨다면 저희가 연구한 과제 하나 하나에 대해서 어떤 내용을 연구했는 지를 더 자세히 아시리라고 생각합니다.  한 가지 문제점이 있다고 한다면 저희가 제목을 정할 때 차별성 있게 정해야 하는 부분이 있는데 과제를 하다보면 발주처의 의견도 있고 그때 그때 상황에 따라서 과제의 제목이 저희 연구진이 원하지 않는 방향으로 결정되는 수가 있습니다.  그래서 여기 보시면 중복된다고 하시는 그런 부분에 오해를 살 여지가 있습니다.  
</p>
<p><b>○ 이건희 위원 </b> 제가 사실은 팔당지역안 광주에서 있었기 때문에 이런 내용들을, 무슨 말씀이냐 하면 이것은 박사님 몇 분이 1년에 그쳐야할 사항이 아니거든요.  제가 말씀드리는 것은 처음에 성연찬 책임연구원부터 시작해서 최근에 유영성 연구원께서 하셨는데 이런 것들에 대한 정책방향이라든지 더 나아가서 그 지역에 어떤 식으로 개발정책을 펼쳐나갈 건가에 대한 것들이 일관성이 있으려면 한두 박사님께서 지속적으로 하는 게 좋겠다라는 말씀을 드리는 거예요.
</p>
<p><b>○ 환경정책연구부장 송미영 </b> 그것은 제가 잠깐 설명을 드리면 맨 처음에 저희가 과제를 시작할 때 연구원이 생기면서 처음에는 팔당문제나 한강특별대책이나 이런 게 없지 않았습니까?  그 부분에 대한 정책의 문제점을 던지는 걸로 시작한 연구들이 1권, 2권 연구과제고요.  3번, 4번, 5번까지는 한강법이 그 사이에 생겼습니다.  한강법을 만들 때 저희 연구원이 도하고 긴밀한 노력을 기울여서 한강법이 됐죠.  그것은 잘 아시리라고 생각합니다.  그래서 한강법이 도입되고 나서는 3번, 4번, 5번은 한강법에 있는 법의 개정에 관련된 세부사항들을 각각의 담당자들이 연구한 겁니다.  보시면 어떤 것은 측량에 관한 것이고, 어떤 것은 수질개선사업에 대한 부분을 정책제안하는 것이고, 어떤 것은 환경청정사업 그 부분에 어떤 식으로 대응하면 좋겠느냐는 논의과정입니다. 
</p>
<p><b>○ 이건희 위원 </b> 여기에 대해서 이번에 광주시가 31개 시·군 중에 오염총량제와 관련해서 하기 때문에 개발원에서 보내준 책들을 많이 참고했습니다.  제가 말씀드리는 것은 이왕이면 정확한 정책부터 시작해 나가려면, 이분 저분하다 보면 이것을 참고로 하는 사람도 헷갈리고 그래서 일관성 있게 한두 분이, 예를 들어서 팔당상수원에 대한 것은 책임자가 있어야 되겠다 그런 말씀입니다. 
</p>
<p><b>○ 환경정책연구부장 송미영 </b> 그러면 제가 이렇게 말씀드릴 수 있습니다.  제가 연구직에 있기도 하고 연구부서에서 굉장히 큰 비중을 차지해서 연구하는 부분이 팔당상수원이기 때문에 팔당상수원을 관리하는 것에는 여러 측면이 있습니다.  예를 들어 만약에 수질개선만을 중점적으로 보신다면 수질분야에서도 여러 분야가 있는데 저희 연구원에서 과제 목록을 보시면 아시겠지만 측량부분은 이기영 박사님의 독자영역입니다.  그 분이 몇 년, 제가 알기로는 거의 6년에서 7년 동안 해오셨고요.  저는 생태공학적인 측면이라든가 수질개선정책의 일반적인 부분을 해왔고요.  유영성 박사님은 전공이 환경경제십니다.  그래서 어떤 의미에서는 팔당상수원을 관리하는데 있어서 행·재정적인 측면, 환경·경제적인 측면에서 제도적으로 어떻게 접근할 수 있느냐 이 부분은 유영성 박사님이 많이 하셨습니다.  그런 측면에서 이게 나눠져 있는 거지 사실은 어떤 의미에서 사람들이 왔다갔다 한 것은 아니고요.  그 당시에 요청할 수 있는 요청수요, 연구과제의 특성에 따라서 그것을 해야 될 적임자들이 한 겁니다.  그렇게 이해를 해주시면 좋겠습니다. 
</p>
<p><b>○ 이건희 위원 </b> 제가 그렇게 이해를 하겠고요.  사실 저희가 봤을 때는 질의한 요점은 그겁니다.  우리 연구인력에 비해서 과제가 너무 과다하다 보면 실질적인 지역현안이나 과제에 대한 전문성이라든지 지역에 있는 분들의 의견을 취합하는 정도 수준의 결과물이 나오지 않을까 하는 우려에서 말씀드리고 여러 가지 팔당대책에 대해서는 전문가가 틀리고 분야가 틀렸다고 하시니까 제가 이해를 하겠습니다.  제가 다른 질의를 할 거니까 그 분야에 대해서는 거기까지 말씀드리고 사실 본 위원도 제가 국방과학연구소에서 5년 동안에 연구원 생활을 했었습니다.  사실 이 건물이 제가 그때 당시 근무할 때보다도 더 안 좋아요.  조건이라든지 원장님 방이나 여러 면에서, 제가 ''85년도부터 5년 동안 근무했었는데 그보다 못하거나 저도 연구원 생활을 해보았지만 저는 그때 당시에 기술직었습니다.  시험평가단이었는데 굉장히 많은 노력을 한 것 같은데 실질적으로 결과 쓰려고 하면 쓸 게 없는 게 연구원 생활이기 때문에 그런 고충을 많이 압니다.  들어가셔도 좋습니다.  저희 집에 오는 우체부들이 저한테 그래요.  이 많은 책이 어디서 오냐고 해서 경기개발연구원에서 온다고 그랬어요.  우체부를 가장 힘들게 하는 연구원이 경기개발연구원이 아닌가 그런 생각도 들고요.  그럼 제가 이상훈 박사님이 옆에 계시니까 물어보겠는데요.  경기개발연구원에서 지난번에 동부권에 오셔서 말씀하셨는데 1억 그루 나무 심기라는 것은 제가 그 때도 반발의 말씀을 드렸는데 충분하게 이해가 안 가서 다시 질의를 드리는데 동부권이 사실 말 그대로 청정지역이고 청소년보호권역이라든가, 공원지역이라든지, 도립공원이라든지 이렇게 되어 있는데 그쪽에  오셔서 1억그루 나무심기를 2004년도에 어떤 정책방향으로 한다는데 어떤 품종의 나무를 산에다 심는 것은 아닐 것 같은데요.  거기에 대해서 짤막하게 답변해 주시기 바랍니다.
</p>
<p><b>○ 개발부장 윤오근 </b> 1억 그루 나무심는 것은 이양주 박사님이 담당을 하시는 과제입니다.  그래서 이 부분 과제에 대한 계략적인 것은 판단을 하고 있습니다.  그 내용은 잠시 후에 전문성을 가진…….
</p>
<p><b>○ 이건희 위원 </b> 아직까지도 이해가 잘 안가요.  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 위원님 제가 대충 말씀드릴게요.  나무가 많은데다 집중적으로 또 심겠다는 그런 취지는 아닙니다.  
</p>
<p><b>○ 이건희 위원 </b> 동부권에 오셔서 그런 말씀을 하시길래 도저히 이해가 안 갑니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 적절하지 않은 것 같은데 거기야 나무 심는 게 문제가 아니고 개발규제 같은 것을 어떻게 해소하는가가 더 중요한 과제일텐데 각 지역별로 어떠한 정책이 가장 필수적인가, 긴박한가 그런 것들을 완급을 가려서 접근해 나갈 필요가 있다고 생각합니다. 
</p>
<p><b>○ 이건희 위원 </b> 그 대목은 나중에 담당하시는 박사님이 어느 분이신지 저한테 얘기를 해줬으면 좋겠다는 생각이 들고요.  또 한가지 질의드릴 것은 사실 경기개발연구원 기금내역을 쭉 보면 4페이지에 나와 있지만 도비지원이 금년도에 56억원이었습니다.  그리고 수탁보조금이 두 번째로 많은데 수탁용역사업비 분이 5억 4,200만원이고 이자수입이 있고, 환급금으로 전체예산을 꾸려나가고 계시고 현재 기금조성되고 기금이 예치된 현황이 237억원 정도 되는데 금년도에는 도비지원을 56억원을 받지 않습니까?  내년도에는 이보다 상당수 높여서 그 많은 10억원 전후의 도비를 요청하실 것 같은데 특별한 주요 사업이 별도로 있습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그러니까 기왕에 하던 사업에다가 내년도에 정원을 8명더 늘리는 계획이 보고드린 대로 그런 계획을 가지고 있고요.  그리고 크게 증액된 이유는 기금을 100억원 정도를 2006년도까지 더 늘릴 필요가 있다라는 것을 위원님들께 보고를 드렸습니다마는 그러한 보고드린 내용에 따라서 내년도에 저희들이 확보했으면 하는 기금이 35억원입니다.  그런데 저희들이 요구된 대로 다 반영되지는 않고 그 중에 일부가 기금증액분으로 반영된 것으로 그렇게 이해를 해주시고요.  또 하나 증액사유 중의 하나는 이번에 도가 교통기획단을 발족시킬 계획입니다.  대중교통을 개선하기 위한 조치인데 그 예산이 8억원됩니다.  그 예산을 연구원에다 일단 편성을 해서 지출할 방법을 택하고 있기 때문에 증액이 많이 되었습니다. 
</p>
<p><b>○ 이건희 위원 </b> 알겠습니다.  그것은 며칠 후에 다시 저희 위원회에서는 협의토록 하고 한 가지 더 말씀을 묻겠는데요.  우수연구원 확보에 대한 어떤 신진연구원이 확보되는 기준에 대해서 짤막하게 말씀해 주시기 바랍니다.  이번에도 박사급 연구원을 채용하셨는데 물론 경기도정이라든지 그런 분야에 대한 전문가를 선정하셨을 텐데 경기개발연구원의 연구원을 확보하기 위해서 어떤 노력을 하고 계신지 선정기준에 대해서 간략하게 설명해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 우선 연초가 되면 금년도에 어떠한 인력을 확보해야 되는가에 대한 수요판단을 하게 되죠.  그리고 그 수요 판단에 따라서 공개채용 절차로 들어가는데 금년도 경험에 의하니까 공개채용에 의해서 그렇게 아주 썩 좋은 인력을 확보하는 데 실패하는 경우가 많이 있었습니다.  그래서 공개채용 방법 가지고는 안 되겠다 그밖에 특별채용이라는 방법을 동원해서 좋은 분을 추천받아서 하는 그런 채용방법도 아울러서 병행해서 하고 있습니다.  다만 어떤 사람이 과연 우수하냐 하는 것을 제대로 심사를 해야 되는데 추천을 다 우수할 수 없는 것 아니겠습니까?  그리고 공개채용하게 되면 굉장히 많은 연구진들이 지원을 하는데 그 지원하는 많은 분들 중에는 희망하는 수준을 채우지 못하는 분들도 있기 때문에 그 부분을 정확하고 공정하게 가려내기 위해서 내·외부에 전형위원 또는 면접위원을 공을 들여서 선정을 합니다.  그래서 그분들이 공정한 그리고 치밀한 심사를 할 수 있도록 그런 단계를 거쳐서 선정을 합니다.  그러니까 그분들이 어떠한 기준을 가지고 하느냐 하는 것은 조금씩 다를 수 있겠죠.  학력을 중시하는 부분, 연구실적을 중시하는 부분, 전공분야를 중시하는 부분, 인성을 중시하는 부분 여러 가지가 있을 수 있겠습니다.  그런 것들을 모두 종합을 해서 판단하고 있습니다. 
</p>
<p><b>○ 이건희 위원 </b> 글쎄요.  이것도 국가적인 정책이고 경기도를 위한 정책인데 거기에 포함될 게 과연 정말 국가적이냐, 개인적이냐를 평가기준에 꼭 넣어야 된다는 생각을 갖고 있고…….
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 사명감 같은 거요? 
</p>
<p><b>○ 이건희 위원 </b> 사명감이 굉장히 중요하고 그래서 저는 요즘에 계약제 공무원이라든지 계약제 연구원 이런 쪽이 평균적으로 몇 년 안 가서 바뀌는 경우도 많고 그렇다면 제가 봤을 때는 대외연구기관이 굉장히 많을 것 같습니다.  우리만 연구기관이 있는 게 아니라 여러 군데가 있는데 그런 데와 협력하거나 아니면 상호교류하는 방법도 있을 거구요.  초빙연구원제도를 하고 있지만 그런 것을 계약제로 한다든지 하는 방법을 한 번 검토해 보시는 것도 좋을 거라는 생각을 저는 하고 있습니다.
</p>
<p style="padding-left:1.2em">  그리고 한 가지 더 말씀드리면 아까 원장님 말씀하신 대로 경기개발연구원은 공공적인 부분만 하기 때문에 민간과의 어떤 협력이나 기금마련 하는데 있어서 도비지원이나 위탁사업비로 운영할 수밖에 없다 이렇게 말씀하셨는데 본 위원 생각으로는 이제 시대도 바뀌었고 연구원에서 어떤 민간사업 비슷한 연구를 해서 판매를 하거나 기술비를 받는다든지 하는 그런 것은 안 어울리는 것이 지금까지의 관념일 수 있습니다.  본 위원은 약간 생각을 달리해서 이것을 해도 좋겠다 저희가 도비를 경기도에서 안 도와주겠다는 얘기는 아닙니다.  경기개발연구원이 자생력을 가지고 설 수 있고 사업도 시행해 나갈 수 있으면 더 좋겠다 라는 말씀을 드립니다.  예를 들어서 아까도 송미영 박사님하고 얘기를 했지만 팔당상수원 뿐만 아니라 전국, 또는 세계적으로도 하수종말폐수처리에 관련된, 쉽게 얘기해서 PPM으로 따지면 대체적으로 종말처리장 방류기준이 저희는 10PPM이고 일반적으로는 9PPM인데 5PPM 이하로 할 수 있는 기술을 갖고 대학의 연구진들이라든지 업체연구진들을 제가 실질적으로 만나봤는데 그런 저런 팀하고 경기개발연구원하고 우리 공사이름을 가지고 경기연구원의 브랜드, 지금까지 쌓아왔던 브랜드나 자금력이나 기술진하고 연합해서 환경도 살릴 수 있고 그런 것을 지속적으로 교류해서 일련의 종말처리장을 지어서 처리할 수 있는 것이 대단히 많은 것으로 알고 있는데 그렇게 해서 자체수입 사업도 올릴 수 있지 않을까 저는 한 예를 드는 겁니다.  이것말고도 다른 분야도 우리 연구진이 조금만 노력하면 가장 우수한 제품이나 기계들을 만들어서 자생력도 가질 수 있다고 봅니다.  그것이 어쩌면 연구원의 걸맞지 않는 사업이나 수익사업이라고 생각하지 않으셔도 된다는 겁니다.  그러니까 국가발전을 위해서나 경기개발연구원 자체의 자생력을 키우기 위해서도 그런 쪽의 연구를 하면 누구하나 욕할 사람 없다라는 의견을 제시하면서 아직 질의 안한 위원들이 많기 때문에 저는 이 정도로 마치고 이따 다시 하겠습니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 수고하셨습니다.  다음 질의하실 위원님 질의해 주시기 바랍니다.  질의하실 위원님 없습니까?  없으면 다른 분, 김학용 위원님 질의하시기 바랍니다. 
</p>
<p><b>○ 김학용 위원 </b> 김학용 위원입니다.  지역구에 중요한 일이 있어서 늦게 와서 죄송스럽게 생각합니다.  몇 가지만 간단하게 여쭙겠습니다.  많은 위원님들이 지적이 계셨습니다마는 사실 경기개발연구원이 인력에 비해서는 상당히 많은 과제물이 있고 또 과중한 업무에 시달리고 있는 것은 잘 알고 있습니다.  다시 한 번 열심히 일해주신 경기개발연구원 원장님을 비롯한 직원 여러분의 노고에 감사의 말씀을 드리고요.  그렇다고 하지만 실질적으로 연구원의 인력을 평상시에 무한정 늘릴 수도 없는 입장이기 때문에 초빙연구원과 비상임연구원 제도를 적절하게 활용하는 것은 필수불가결한 일이라고 생각이 됩니다. 
</p>
<p style="padding-left:1.2em">  다만 한 가지 우려하는 것은 초빙연구원이나 비상임연구원을 선정해서 과제물을 일정기간이라도 위탁할 때 선정기준이나 방법이 어떻게 되어 있는지 우선 그 부분에 대해서 간단히 답변해 주시기 바랍니다.  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 초빙연구원이나 비상임연구원은 과제로 되어 있습니다. 어떤 과제를 하면서 외부에 초빙연구원 또는 비상임연구원을 쓸 것인가 그것을 우선 판단하고 그러면 어떤 분들이 전공에 부합성이 있고 전문가인가를 연구책임자를 비롯해서 주변에 계신 분들이 같이 찾습니다.  그래서 대상자들이 여럿이 나오면 그 중에서 적절하다고 판단된 것을 연구책임자가 선정하는 그런 방법으로 하고 있습니다. 
</p>
<p><b>○ 김학용 위원 </b> 그래서 제가 말씀드리는 요지는 이런 초빙연구원이나 비상임연구원도 그저 막연하게 상근연구원, 책임연구원의 어떤 역할에만 맡길 것이 아니고 전국의 각 분야별로 우수한 인재들의 현황을 파악해서 잘 활용할 필요성이 있지 않냐 하는 말씀을 드리는 거니까 참고해 주시기 바라고요.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 분야별 인재풀은 저희들이 가지고 있습니다. 
</p>
<p><b>○ 김학용 위원 </b> 관심을 가지고 해주십사 하는 부탁의 말씀을 드리고 자료에 보면 상임고문 직제를 2002년 12월 11일로 제가 알고 있는데 정관을 개정해서 폐지를 한 것으로 나와 있습니다.  그런데 주요 업무보고에 기구 및 인력에 보면 고문제도가 지금도 유효하게 남아 있는데 상임고문과 고문의 차이는 뭐고 현재 기구 및 인력에 나와있는 고문은 어떠한 근거에 의해서 운영이 되는 건지 답변바랍니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 이것은 저희도 인사관리직제 규정에 의해서 확보하고 있는 제도인데요.  일단 어느 조직이든지 약간 명의 고문을 둘 수 있다는 규정들은 가지고 있습니다.  그런데 이제까지는 그것을 상임고문이라고 해 가지고 사무실과 차와 비서진이 모두 제공되는 그리고 적지 않은 보수가 지급되는 그러한 제도를 그 동안 우리 연구원에서 운영을 해왔었습니다.  그런데 실제로 그것이 그렇게 큰 도움이 되느냐 그런 판단이 되고 그래서 상임고문제는 일단 운영하지 않기로 하자 그리고 같은 고문이라 하더라도 쓸 필요가 있다고 그러면 비상임으로 쓰자 그런 의도에서 적용시켜 오고 있습니다.  
</p>
<p><b>○ 김학용 위원 </b> 상임고문 직제를 폐지한 것을 저는 대단히 잘했다 하는 생각을 가지고 있는 사람이고 현재 고문으로는 어느 분들이 위촉이 되어 있습니까?  아니면 현재는 공석으로 있습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 비상임 고문 두 분이 위촉되어 있습니다. 
</p>
<p><b>○ 김학용 위원 </b> 어느 분, 어느 분이시죠?
