<p><b>○ 경기개발연구원장 이철규 </b> 전에 교통개발연구원장을 하시던 분하고 전에 국립수의과학검역원장을 하시던 분하고 두 분이 위촉되어 있습니다. 
</p>
<p><b>○ 김학용 위원 </b> 위촉기간은 어떻게 되고요.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 1년입니다. 
</p>
<p><b>○ 김학용 위원 </b> 그분들에 대해서 어떻게 무슨 일정한 비용이 지불되는 것이 있습니까?  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 경력에 따라 다른데요.  월 수당이 지급됩니다. 
</p>
<p><b>○ 김학용 위원 </b> 얼마나 지급되고 있습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 한 분한테는 200만원 지급되고 한 분한테는 100만원이 지급되고 있습니다. 
</p>
<p><b>○ 김학용 위원 </b> 잘 알겠습니다.  사실 상임고문 직제에 대해서도 저희 의회입장에서 좋지 않은 시선을 보냈던 것도 역시 우리가 지불하는 비용에 비해서 역할이 제대로 되지 못하는 그런 점 때문이거든요.  그래서 역시 고문도 적다면 적고 많다면 많은 돈이 들어가는 그런 부분인데 기왕에 있는 고문제도라면 고문역할을 실질적으로 할 수 있게끔 제도를 충실하게 운영해 주십사 하는 그런 당부의 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  다음으로 자료에 보면 제가 연구원에 대한 자체감사실시 현황을 받아봤더니 2년 연속해서 전혀 지적사항도 없고 조치사항도 없는 것으로 되어 있습니다.  그리고 자료에 보면 연구원이 생긴 이래로 현재 제가 가지고 있는 자료에 보면 징계를 받은 사람이 단 한 명도, 한 건도 없는 것으로 나와 있거든요.  그래서 과연 직원들이 정말 징계 받을 사유가 없고 또 연구원이 지적 받을 일이나 조치할 사항이 없어서 이런 것인지 아니면 감사가 형식적으로 이루어지고 또 아니면 직원들에 대해서 잘못된 부분에 대해서도 덮어나가는 분위기로 인해서 그런 결과가 나오는 것은 아닌지 우려가 돼서 제가 말씀을 드리는데요.  그 부분에 대해서 원장님의 견해를 간략히 말씀해 주시기 바랍니다.  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 지금 김 위원님이 말씀하신…….
</p>
<p><b>○ 김학용 위원 </b> 367쪽입니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 367쪽요.  자체 감사라는 것이 도감사, 우리 연구원이 위촉한 감사, 정관상의 감사 이런 분들이 하는 감사를 가리켜서 자체감사라고 그럽니다.  그런데 그분들의 감사는 이제까지 제가 판단하기로는 합법성 감사가 주였습니다.  성과감사를 위주로 한다고 그러면 왜 지적사항이 없었겠습니까?  그러나 합법성 감사에 주력하다 보니까 법에 어긋나게 한 것들은 없더라 그런 취지로 이해를 하고요.  제가 이런 말씀을 이런 자리에서 드리는 것이 적절한지 모르겠습니다마는 저희들 사무처 직원들이 아주 너무 경직되어 있을 만큼 법운영에 철저를 기하고 있습니다.  굉장히 철저한 합법적인 운영을 하려고 노력을 하고 있습니다.  그러다 보니까 없는 것으로 나와 있는데 그러나 성과측면에서 본다고 그러면 미흡한 점들이 많이 있으리라고 생각합니다. 
</p>
<p><b>○ 김학용 위원 </b> 감사를 보면 경기도 감사권은 그 당시에 직을 맡는 분이 하는 것으로 되어 있는 것 같고요.  정규환 감사는 어떤 분이시죠. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 우리 연구원에 소속된 감사입니다. 
</p>
<p><b>○ 김학용 위원 </b> 연구원에서 지정한 감사? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 연구원에서 위촉한 감사…….
</p>
<p><b>○ 김학용 위원 </b> 그러면 김흥완 공인회계사는 두 분이 다 그렇죠?  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그 분은 외부에 있는…….
</p>
<p><b>○ 김학용 위원 </b> 그러니까 두 분이 공인회계사인데 여기 내부의 감사로 지정된 분이고 한 분은 외부에서 위촉해서 하는 분이다 그런 얘기죠?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네.
</p>
<p><b>○ 김학용 위원 </b> 저도 사실 경기도와 관련해서 결산검사대표위원도 맡아서 해봤습니다마는 교육청이나 도청에서 하는 공무원이 하는 것도 나중에 보면 본의 아니게 잘못된 부분이 많은데 사실 자체감사 결과 지적사항과 조치사항이 하나도 없다는 것은 석연치가 않습니다.  그리고 그 기간도 불과 3일 정도에 지나지 않은데 이것도 사실은 기간이 짧아서 형식적이지 않느냐는 노파심입니다마는 외부의 우려가 있을 수가 있거든요.  그래서 이 부분에 대해서는 원장님께서 잘못해서 그런다기 보다는 감사를 정확하게 한다는 뜻에서 관심을 가지고 제도에 대해서 변화를 줬으면 하는 그런 말씀을 드리고 한 가지만 더 여쭙고 끝내겠습니다.  작년에도 제가 와서 지적을 한 적 있는 것 같은데요.  연구간행물 판매실적을 볼 것 같으면 물론 경기개발연구원에서 하는 연구간행물이라는 것이 판매를 해서 주가 될 필요성도 없고 또 그렇게까지는 저도 바라지를 않습니다만 사실 좀 너무 지나치게 간행물 판매부수가 적은 것 같아서 이것은 다른 동료 위원님들께서도 지적이 계셨기 때문에 제가 구체적으로 말씀을 안 드립니다마는 앞으로도 관심을 가지고 해주십사 하는 당부의 말씀을 드립니다.  이상입니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 다음 질의하실 위원님, 이효선 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이효선 위원 </b> 식사도 못하고 늦게까지 앉아 계시느라 고생 많습니다.  저는 약간 시각을 바꿔서 질의를 해보겠습니다.  보수규정 제17조에 보면 자녀학비보조가 있는데 중·고등 학생에 대해서 보조하게 되어 있습니다.  명수 제한은 없습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 없습니다. 
</p>
<p><b>○ 이효선 위원 </b> 대학교는 안 합니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 대학교는 안 합니다. 
</p>
<p><b>○ 이효선 위원 </b> 이왕이면 자녀 2명에 한해서 중학교까지는 무상이니까 고등학교, 대학교를 해주는 것으로 해서 바꿔주면 그래도 좀 근무여건이 좋아지지 않을까 하는 생각이 듭니다.  그렇게 조치해 주시고요.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 2명으로 제한하라는 말씀입니까?  
</p>
<p><b>○ 이효선 위원 </b> 2명밖에 없어요.  대기업 중 5대 기업을 보면 2명에 한하여 대학교까지 학비보조가 100% 되고 있습니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 제한해서 대학교까지 다 지원해 주라는 말씀입니까?
</p>
<p><b>○ 이효선 위원 </b> 그렇죠.  그런 것들이 장기근속을 유도하는 것 같고 학비가 많으니까, 연구인원 휴직이 있는데 그게 1년에 한두 명, 몇 년 근무자라는 규정이 없습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네, 6년 이상 근무시, 
</p>
<p><b>○ 이효선 위원 </b> 그런 규정으로 했으면 좋겠고요.  이직률에 대해서는 보상이 많고, 월급이 많다고 해서 그 자리에 오래 있는 것은 아닙니다.  여기에 앉아 있는 도의원들도 명예직이고 1년에 120일을 출근해야 연평균 월 170만원을 받는 데도 많은 돈을 들여서, 시간을 보내며 이 일을 하고 있습니다.  명예직이라도 메리트가 있어야 되거든요.  그래도 경기개발연구원은 국가나 삼성, 현대 같은 연구소보다는 보수면에서 뒤쳐질 수가 있습니다.  특화되는 어떤 메리트가 있어야 되는 것 같습니다.  그래서 특화사업을 했으면 좋겠고요.  정책하면 환경이라든가, 도시개발이라든가 집이라든가 어떠한 특화된 것 한두 개를 찍어서 뭐하면 뭐하는 식으로 연구소가 발전됐으면 좋겠습니다.  또 이것은 개인적인 감정은 없는데 뭔가 알고 싶어서 묻겠습니다. 
</p>
<p style="padding-left:1.2em">  121쪽에 보면 사무처장 임용기준이 있습니다.  작년에 김봉규 처장께서 오셨는데 가, 나, 다, 라 중에서 어느 사항에 포함된 건지 묻고 싶습니다.  대답해 주십시오.  
</p>
<p style="padding-left:1.2em">  421쪽입니다.  이 질의의 취지는 그렇습니다.  전임 처장이 정치적으로 왔다 간 것 같은 생각이 들어서 이번에는 정치적이 아니고 실력으로 왔나, 규정에 맞게 왔나 보기 위한 겁니다.  지방자치단체 4급, 5년 이상은 아닌 것 같고요.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그러면 그 한 가지만 답변드리면 되겠습니까?  
</p>
<p><b>○ 이효선 위원 </b> 네, 그것만 하시면 됩니다. 가, 나, 다, 라 중 어떤 겁니까?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 다하고 라항입니다. 
</p>
<p><b>○ 이효선 위원 </b> 죄송한 얘기지만 15년 근무지가 공공기관 어디인지 얘기해 주시겠습니까?  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 위원님 이렇게 답변드리겠습니다.  지금 여기에 나와 있는 몇 가지 기준에 저는 전폭적으로 동의하지 않습니다.  이러한 기준들이 그 동안 공무원 경력을 중시하는 쪽의 입장에서 만들어진 기준들이기 때문에 이를테면 사기업체의 근무경력이라든지 공공기관에서의 근무경력 같은 것을 조금 불리하게 적용시키는 경우가 꽤 있습니다.  아직 하나하나 고쳐 나간다고는 하지만 아직까지도 관 주도적인, 관 일변적인 기준, 관 출신에게만 유리한 기준들이 아직까지도 살아있습니다.  이 경우도 그런 경우라고 생각합니다.  그러기 때문에 그와 동등한 자격 같은 것을 갖추는 경우에는 우리가 넓게 해석을 해서 적용시키는 그런 경우들이 종종 있다는 말씀을 드립니다.
</p>
<p><b>○ 이효선 위원 </b> 본 위원의 질의 의도는 이겁니다.  잘못된 것은 고쳐야 된다.  사무처장이 2대에 거쳐서 가, 나, 다에 해당되지 않은데 임용된 것은 고쳐야죠.  임용자격기준을 고치면 되는 거구요.  어찌됐든 한번 임용되면 그 임기를 채우는 모습, 정치적인 역할이 아니라 한번 맡은 임무를 끝까지 할 수 있는 동기부여를 원장님께서 해주시라는 뜻에서 질의를 했습니다.  그러니까 잘못된 것은 고쳐 나가는 모습이 좋겠고요.  또 자료 328페이지에 보면 이철규 원장님하고 송재룡 박사님이 직책이 없어서 죄송합니다만 이철규 원장님은 송재룡 박사님과 11일간 미국을 다녀옵니다.  그런데 1인당 1,166, 1,142만원 맞습니까, 숫자가?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네.
</p>
<p><b>○ 이효선 위원 </b> 두 분이 가셨습니까, 몇 명 더 가셨습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 둘이 갔습니다. 
</p>
<p><b>○ 이효선 위원 </b> 해외초빙 하는데 계약금 내고 갔어요?  이렇게 많이 들어갔습니까?  저도 해외여행을 많이 한 사람인데 이해가 안 되는 수치가 있습니다.  10박 11일 정도면 여행사 기준으로는 200만원∼300만원이고, 스페셜로 하면 400만원∼500만원 안 넘거든요.  그런데 1,166만 7,400원이면 많은 것 같아요.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 제가 생각해도 많은 것 같은데요.  자료로 나중에 제출해 드리겠습니다.
</p>
<p><b>○ 이효선 위원 </b> 이것이 맞는다면 이렇게 쓸데없는 돈을 지출하는 데에 대한 것은 지적하고 가야한다.  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그때 이코노미 좌석 타고 다녔습니다.  그때가 스카웃여행인데요.  거기에 가서 학생들을 만나서 식사하면서 또는 장소 빌려서 설명회 하는 비용들이 많이 감안됐을 것으로 됐습니다. 
</p>
<p><b>○ 이효선 위원 </b> 어느 분이 작성하셨는지 모르지만 2명이 가셨으면 이철규 원장님 외 1명 해서 토털 2,300만원 나갔으면 좋지 않았나 보고요.  내용면에서 석학을 데려오는데 1억원이면 어떻습니까?  경기도에서 필요해서 갖다 써야 되는데.  그 내용이 기억 안 나는 식으로 식사한 것 같다는 답변은 앞으로 지양해 주시기 바랍니다.  이것은 자료로 제출해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그리고 467쪽에 보면 학연네트워크 구축이 있습니다.  관내에는 아주대학교, 경원대학교, 명지대학교 등 6개 대학과 그외 하나가 있습니다.  468쪽에 보면 운영현황 및 성과가 미미합니다.  별로 한 게 없어요.  본인이 생각하기에는 지방분권과 지방정치는 정치인, 언론, 학계, 산업계가 똘똘 뭉쳐서 특화된 자기들만의 여건을 갖고 남이 하지 못하는 것을 했을 때 발전적이고 경기도가 인구만 제일 많은 게 아니라 정책이나 이런 게 앞선다고 봅니다.  왜 이런 걸 질의하느냐 하면 제가 나중에 얘기하겠지만 이것이 경기도에 있고 경기개발연구원에 경기라는 이름이 들어감에도 불구하고 경기도의 학자들이 대우를 덜 받는 것 같아서 질의를 드리는 겁니다.  형식적이 아닌 가시적, 아니면 거시적, 중장기적 그런 것들이 나타나야만 학연네트워크지 저는 영어를 모르니까 네트워크가 뭔지 모르겠습니다만 네트워크를 하기에는 너무 미흡하지 않나.  3개 과제를 수행했다, 1개 과제를 수행했다.  대학은 6개 지정해 놓고, 이런 것은 내용이 있게끔 해주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  주요 업무보고 32쪽에 보면 1시·군 1담당제라는 획기적이고 좋은 게 있습니다.  2,752만 8,000원의 예산이 있는데 내년 계획입니까, 올해 한 겁니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 내년 계획입니다.
</p>
<p><b>○ 이효선 위원 </b>  올해는 이런 것 안 했습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그 동안 과거에는 운영된 게 있고 올해는 운영이 없었습니다.
</p>
<p><b>○ 이효선 위원 </b> 시·군에 1명씩 있는데 파트너는 누구로 생각합니까?  시장입니까, 기획관리실장입니까 아니면 기타 등등 해서 경기개발연구원에서 연구하고 있는 목표는 누구와 파트너십을 해서 그 지역 발전을 위해서 일할 겁니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 보통의 경우에는 기획관리실하고 파트너십을 맺습니다. 
</p>
<p><b>○ 이효선 위원 </b> 그게 진부한 답변이거든요.  경기도와 각 시·군간은 항상 연계돼 있고 항상 정책을 협의합니다.  아까 제가 말씀드린 급료나 어떤 것보다 특화돼야지 장기근속자가 나온다고 한 것들은 잘못하면 시·군의 시장들, 단체장들에 당선된 사람들의 성과물로 압니다.  그쪽에서 도의원 제도가 있으니까 각 지역에 도의원들과 협의해서 특화된 사업, 시에서 하지 못하는 것들을 제3의 시각에서 객관적으로 봐서 그런 것들을 연결해 내는 그래서 그것을 일궈내는, 학교와 네트워크를 연결하는 차원이랑 마찬가지인데 뭔가 돈이 투입되면 결과가 나와야 합니다.  그게 자본민주주의거든요.  그래서 2,752만원이라는 돈은 31개 시·군에 100만원도 안 됩니다.  이것을 오히려 증액해서 실질적으로 사업할 수 있게끔 원장님이 배려를 해주시고요.  시 정책기획관 이런 분들하고 하지 말고 차라리 시의회와 연결해서 하든가 아니면 도의원과 해서 단체장이라는 또 다른 선출직이 갖는 시각, 그 지역의 발전방향 같은 것도 엑기스를 빼서 경기개발연구원이 역시 괜찮구나 하는 것을 했으면 좋겠습니다.  제 의견이었습니다. 
</p>
<p style="padding-left:1.2em">  이번에 처음에 한 지적이 있는 것 같은데 부원장 임용에 관한 말씀을 드리겠습니다.  여기에 앉아있는 도의원들은 각 분야에서 그래도 전문적인 사람이고 거기에 대한 배짱이 투철한 목표의식이 있어서 선거에 나와서 당선된 사람입니다.  하지만 전문가적이지 못해요.  제가 건방진 말인지 모르지만 박사된 직책은 그 분야에서 연구할 자격이 있다는 것으로 알고 있습니다.  그 박사님들도 한 분야에 수백, 수천명인데 많은 분야에 파트너 박사님이 계십니다.  저희 도의원들은 업무를 잘 모릅니다.  물량이 많은 자료를 줘도 진짜 감사다운 감사를 할 수 있는 능력이 부족한 게 있습니다.  이철규 원장님은 아주 많은 학식과 놀랄 정도의 식견을 가지고 계시고 존경스러운 분이지만 부원장 임용을 1년 동안 미뤘습니다.  구조상 적어서 그런지 몰라도 원장님과 부원장 두 분이 파트를 나눠서 했다면 경기개발연구원 1년의 성과가 부원장님한테 들어가는 임금 이상이 나오지 않을까 생각이 들고요.  그저께도 손학규 지사 3인방 해서 국회의원에 대한 것들이 수도 없이 여러 신문에 계속 나오고 있습니다.  본인의 의사와 관계없이 이렇게 실력있고 출중하신 분이 국회에 진출해서 이 나라 국정을 논하는 것에 대해서 전적으로 찬성합니다.  그렇다면 그럴 때를 대비해서 부원장을 미리 뒀어야 하지 않나 생각이 듭니다.  여기에 대한 답변 부탁합니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 원장님 답변해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 답변드리겠습니다.  첫 번째로 보수기준을 바꿔서 자녀학비 보조를 두 명으로 제한하더라도 대학까지 지원될 수 있도록 하는 것이 좋지 않겠느냐는 저희들이 한 번 연구해 보겠습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 연구원이 메리트가 있는 연구기관 그리고 특화된 연구기관이 되도록 해야 되지 않겠느냐 라는 말씀에 대해서 동의합니다.  앞으로 그런 연구기관이 될 수 있도록 노력해 나가겠습니다.  그리고 학연네트워크가 너무 형식적이지 않느냐 지적하셨는데 그러한 지적에 저도 동의합니다.  그러나 여기 제시된 6개의 성과는 학교와 우리 연구기관과 협정을 맺은 대상학교만을 열거하고 있는데 사실 학연네트워크라는 것은 종이에 사인하는 것만 가지고 네트워크가 만들어졌다고는 생각하지 않습니다.  그밖에 여기 나오는 것 이외에도 각 대학들과 각종 세미나들을 함께 하고 있고 각 대학 교수님들에게 저희들이 위탁해서 연구를 계속하고 있고, 또 그 분들도 각종 세미나라든지 토론에 참여해서 전문지식을 저희에게 제공해 주고 있고 그래서 알게 모르게 그리고 형식적이든 비형식적이든 간에 굉장히 많은 학연네트워크가 형성되어 오고 있다 라는 것을 부연해서 말씀을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 시·군 카운트파트를 의회로 하는 것이 어떠냐 하는 지적이신데요.  여기에 대해서 저는 생각을 달리합니다.  어차피 우리들이 연구를 하는데 있어서는 의원님들의 말씀은 물론 존중해 드리겠지만 집행기관과 협의를 할 수밖에 없습니다.  그래서 집행기관들이 우리 연구원에 대해서 어떠한 요구사항을 가지고 있는지 또 서비스가 어떤 점에서 부족한지 그런 것들을 지속적으로 활로업(follow up)해 나가기 위해서는 어차피 담당부서가 집행기관에 불특정부서가 될 수밖에 없다는 것이고 그러나 우리 위원님 말씀하신 대로 위원님들의 뜻이 어떠한 것인지에 대해서는 각 시·군을 담당하는 사람들이 반드시 체크해 나가도록 그렇게 동의를 하겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 마지막으로 저와 관련된 말씀을 해주셔서 몸둘 바를 모르겠습니다.  제가 행여나 다른 생각으로 연구원 경영을 소홀히 하지 않을까 하는 우려에서 그런 애정의 질의를 해주신 것으로 생각을 합니다.  하여튼 상황이 어떻게 됐든 연구원에 소홀한 원장이 되지 않도록 노력하겠습니다. 
</p>
<p><b>○ 이효선 위원 </b> 좋은 답변이었습니다.  1시·군 1담당제에 대해서 정책적 파트너로 발전로드맵에 어쩔 수 없이 하는 것은 동의하는데 그것을 갖고 경기도 하고 도의원들이 있으니 의견청취하는 것은 돈 들어가는 게 아니거든요?  모 의원께서 경기개발연구원과 기획위원회가 언제 교류가 있었느냐는 질의를 한 뜻은 잘 모르겠습니다만 제가 봐도 잘 모르겠어요.  경기개발연구원이 뭐하는 데인지, 인간적 교류하는 사람은 한두 명밖에 없고, 요새 사무처장님이 자주 안 오시데요.  경기지방공사가 없으면 여기 처장님이 잘 하는지 못하는지 모르거든요.  그런데 지방공사가 있다 보니까, 업무유대가 될 수 있도록 항상 얼굴 볼 수 있는 관계 그런 것들이 지난 1년 동안 등한시 됐다.  정치인의 인간관계는 밥먹는 거거든요.  커피 마셔도 되고 얼굴을 자주 봐야 정이 들고 뭘 도와줄까 노력하는 겁니다.  이번에 진급도 많이 되는 것 같은데 도와드리겠습니다만 각 시·군과 하면서 도의원의 의견을 청취하는 모습 그것이 경기개발연구원을 보는 104명의 도의원의 시각을 바꾸는 거라고 생각합니다.  참고해 주시고요.
</p>
<p style="padding-left:1.2em">  또 하나 질의는 포럼운영입니다.  제가 어찌됐든 의회 남북교류특위위원장이고 남북교류포럼의 패널이고 사회포럼의 패널입니다.  사회포럼에 가봤더니 서울대 교수, 중앙대 교수, 고대 교수가 많아요.  경희대 수원캠퍼스 한 명 있었고.  서울대라고 대화해 보니까 서울대라고 많이 아는 것도 아니더라고요.  지방대학의 육성차원에서 지방의 학계발전을 위해서 아주대라든가 수원대, 경기대, 성균관대 쪽으로 방향을 틀어 주시기 바랍니다.  제일 큰 문제는 뭐가 있느냐 하면 지난번에 포럼에서 지적했습니다.  저는 보좌관도 없고, 천재도 아니고, 박사도 아니고, 정규대학도 아닌 방송통신대학 나온 사람인데 아무리 자료도 주지 않고 가서 토론을 하면 만약에 내가 내공이 부족하고 준비가 안 된 사람이면 바보 만드는 거거든요.  포럼에 넣지를 말든가, 넣었으면 같이 인정해서 파트너십을 갖고 어떤 자료를 주면서 준비할 기간을 주든가 해야 하는데, 지적을 했습니다.  내일 제가 남북포럼 하러 가요.  조금 아까 오전에 여기 있다가 전화받으니까 담당자라고 하는 어느 연구원께서 "이메일을 보냈는데 받았습니까" 그러더라고요.  담당자가 누구입니까?  어느 박사님이 남북포럼을 담당하세요?
</p>
<p><b>○ 자치행정연구부장 김동성 </b> 자치행정연구부장 김동성입니다.  제가 남북포럼의 담당자입니다. 
</p>
<p><b>○ 이효선 위원 </b> 아까 얘기했던 정규직이 아닌 비정규직 연구원께서 담당하시는 것 같은 데 이메일로 보냈다고 했어요.  그런데 아까 전화받았습니다.  미리 주셨으면 얼마나 좋았을까요?  이게 그 자료입니다.  오늘도 감사하고 내일도 오전에 감사해야 하는데 나는 잠 안 잡니까?  내일 가서 포럼에 가서 뭐라고 떠들라는 거예요?  경기개발연구원의 한 단면을 보는 겁니다.  포럼 왜 해요?  돈 나눠주려고 합니까?  서울대학교 친목회 하는 데예요?  중앙대 교수고 보면, 사회포럼 가보니까 서울대 정치학 교수가 많아요.  그걸 떠나서 제발 도의원이 갈 데 없어 끼워달라는 거 아닙니다.  여러분이 역지사지해 보세요.  어느 박사가 남북교류에 대해서 별안간 주제발표를 해야 토론하는데 주제발표를 뭘 하는지 알아야 하지, 전에는 어떻게 했지만 이거 언제 공부해요.  밥도 먹어야 되고 감사도 해야 되는데, 이런 일 좀 하지 마세요.  한번 지적받은 거 또 지적받는, 박사가 수두룩하게 많은 연구원에서 이런 일 좀 하지 마십시오.  여기에 대한 답변 부탁합니다.  김동성 박사님.
</p>
<p><b>○ 자치행정연구부장 김동성 </b> 여기에 대해서 말씀드리겠습니다.  우선 위원님께 심려를 끼쳐드려서 죄송하다는 말씀을 드리겠습니다.  그런데 저희가 준비하는 과정에서 제가 알기로는 이효선 위원님한테는 지난주 수요일에 이메일로 관련분야의 발주물을 발송한 것으로 알고 있습니다.  확인을 했었고요.  다만 저희 불찰이 있었다면 책자로 만들어서 드리지 못했다는데 조금 송구스럽게 생각합니다.  이유가 있습니다.  책자를 만들려면 다른 분야 발제물이 다 합산이 돼야 하는데 발제를 맡아주신 다른 분야의 교수님들께서 원고를 늦게 주시는 바람에 이렇게 책자로 확보하는 것은…….
</p>
<p><b>○ 이효선 위원 </b> 김동성 박사님.  한국말 모르세요?  이메일로 보냈다고 했는데 보낸 자체를 모릅니다.  내 위주로 남을 보면 안되요.  김동성 박사는 나만큼 민주노총이나 노동문제에 대해서 아세요?  모르죠?  제가 김동성 박사가 아는 것하고 대화하면 대화가 안 되죠.  자기 위주로 나오면 안 됩니다.  나는 이메일을 매일 펴는 사람이 아닙니다.  이메일을 보낸 것을 말로 하는데 돈 들어갑니까?  이메일을 보냈으니 위원님께서 참고하시고 토론에 나가주시면 고맙겠습니다라고 전화하는데 경기개발연구원 전화비 아끼는 데예요?
</p>
<p><b>○ 자치행정연구부장 김동성 </b> 죄송합니다. 
</p>
<p><b>○ 이효선 위원 </b> 내가 갑자기 노동문제와 남북문제를 갖고 깊이 있는 문제를 갖고 얘기하면 답변하실 수 있을 것 같아요?  바로 그거죠.  이메일을 보냈으니 보십시오 라는 전화 한 통이면 이런 얘기가 안 나오겠죠.  3∼4일이면 충분합니다.  이틀만 줘도 충분합니다.  그런 것에 대한 질의입니다.  사람 대접 좀 합시다.  여기는 박사님들이고 우리는 배우지 못하고 우리는 수당이 170만원밖에 안 돼서 사람 무시하는 건지 모르지만 사람은 평등선상에서 대화가 돼야 해요.  보냈는지 안 보냈는지 어떻게 알아요?  이메일을 매일 보나?  그런 것을 지적을 한 거고요.  앞으로는 그러지 마십시오.  간절히 부탁합니다. 
</p>
<p><b>○ 자치행정연구부장 김동성 </b> 유념하겠습니다.
</p>
<p><b>○ 이효선 위원 </b> 마지막 질의하겠습니다.  손학규 지사께서 현 정권이 경제를 망치고 잘못해서 31개 시·군과 도가 똘똘 뭉쳐서 한국의 경제를 책임지겠다는 발표했습니다.  그것이 개인의 문제인지 참모의 발표인지 모르지만 경기개발연구원은 그것에 대한 후속조치로 바로 들어가 줘야 합니다.  학문적 로드맵을 만들어줘야 해요.  현 정부가 그러는데 손학규 지방정부가 앞으로 어떻게 어떻게 해서 해야 된다고 하는데 손 지사께서 발언을 하셨는데 어떻게 하면 숫자로 나열, 현재 경기도 경제가 내년에 얼마나 볼륨을 키울 것이며 실업자가 얼만데 얼마로 줄일 것이며, 이러한 발표가 아직 안 나왔거든요.  이것은 제가 질의가 아니라 부탁입니다.  경기개발연구원의 최대 지주는 경기도이고 경기도의 부속연구원이라면 그 장이 발표한 게 어떤 것보다도 바로 후속조치로 계획이 뒷받침돼서 지사가 그것을 발표해서 말과 행동과 계획이 딱 들어맞는 경기도의 모습이 되게끔, 원장님 이하 연구하시는 박사님들이 그러한 것들을 뒷받침해 주시기를 경기도의 도의원으로서 부탁을 하면서 질의 마치겠습니다.  이상입니다.
</p>
<p><b>○ 위원장대리 이원재 </b> 이효선 위원 수고하셨습니다.  다음 질의하실 위원 계십니까?  원활하고 활발한 감사진행을 위해서 제가 질의하고 싶은 게 있었는데 안하고 있었는데 시간을 절약하는 의미에서 제가 질의하는 내용에 대해서는 서면으로 저한테 제출해 주시기 바랍니다.  감사요구자료 160페이지에 보면 기타직 보조에서 4억 2,205만 7,000원의 예산을 세워서 도정정책연구원 230만원 3명, 특별과제위촉연구원, 도시환경자문팀 이렇게 해놨는데 보수도 과제도 채용한 바 없고 도 정책연구원 3명을 써야되는 것을 한 명을 법무담당관실의 법률자문으로 채용해서 근무시키고 있는데 이것은 어제 법무담당관실 질의시 나왔기 때문에 말씀드리는 겁니다.  예산산출 기초상 230만원 3명이라고 했는데 이것은 월급여입니다.  그런데도 불구하고 법무담당관실 보고에는 추후 3회를 근무하면서 320만원을 수용한다고 했는데 줄 수 있는 근거는 어떤 근거에서 줄 수 있는지 또 초빙연구원운영규칙에 보면 가급에 해당된다고 해서 가급 수당은 월 150만원 이상으로 정해져 있는데도 불구하고 3일을 근무하고 320만원 줬다는 것은 경기개발연구원에 경리관과 지출원이 누군지 모르겠지만 3일을 근무한 사람에게 320만원을 줄 수 있게 도장을 찍을 수 있는지, 뿐만 아니라 왜 경기개발연구원의 예산을 가지고 도에서 근무하는 사람에게 보수를 주는지 또 그 사람 제가 도청에서 어떠한 회의에 참석했을 때 10만원의 수당으로 예산이 서 있는데 9만 6,000 얼마를 준 적이 있습니다.  그것은 세금을 제하고 주는 거다 해서 그렇게 받은 적이 있는데 어느 부서는 10만원을 주고 그런데 이것은 320만원을 준다고 했는데 세금을 제하고 주는 건지, 그 당사자는 다른 직업이 없고 이것만 하고 있는 건지, 이력서 첨부해서 봉급지출 이런 것들을 소상하게, 뿐만 아니라 이것이 적법한지 여부, 회계절차상 타당성이 있는 건지 이런 사항에 대해서 소상하게 서류로 작성해서 저한테 제출해 주시기 바랍니다.  감사활동의 원활함과 효율을 위해서 서면으로 제출할 것을 바라면서 이상 질의·답변을 마치도록 하겠습니다. 
</p>
<p><b>○ 이효선 위원 </b> 김대원 위원 신청했습니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 질의를 마치겠습니다.  김대원 위원 질의하겠습니까?
</p>
<p><b>○ 김대원 위원 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 그럼 김대원 위원이 질의를 하시기 전에 제가 질의시간을 마감하기 위해서 질의했는데 그럼 다시 제가 질의하겠습니다.
</p>
<p><b>○ 김대원 위원 </b> 아니…….
</p>
<p><b>○ 위원장대리 이원재 </b> 다른 위원들이 질의를 안 한다고 해서 했는데 다른 위원이 질의를 한다면 제가 질의를 완벽하게 마치겠습니다.
</p>
<p><b>○ 김대원 위원 </b> 의사진행발언부터 들어가면서 합시다.  현재 시간이 1시 30분인데 계속 감사를 진행할 것인지, 중식 후에 할 것인지 그런 부분도 위원장이 물어보고 하셔야죠.
</p>
<p><b>○ 위원장대리 이원재 </b> 질의 없으면 마치는 거죠.
</p>
<p><b>○ 김대원 위원 </b> 그러니까 질의가 있는지 없는지도 알아보셔야 되잖아요.
</p>
<p><b>○ 위원장대리 이원재 </b> 질의가 없다고 하니까 내가 한 것이고 답변을 안 받은 것은 시간을 절약하기 위해서 그런 거니까 만약에 다른 위원님이 질의있다고 하면 제가 다시 질의하겠다는 거죠.
