</p>
<p><b>○ 김대원 위원 </b> 의사진행발언은 잠시 정회를 해서 중식 후에 진행할 것인지, 계속 진행할 것인지 물어보셔야죠. 
</p>
<p><b>○ 함진규 위원 </b> 제가 의사진행발언 드리겠습니다.  절차상 말씀드릴게요.  오전에 다 끝내고 식사를 하는 것으로 전문위원을 통해서도 이미 합의가 됐기 때문에 위원들 간에 절차적인 문제를 갖고 여기서 설왕설래하는 게 우습고요.  질의를 신청했으면 받아주고 종결하는 게 좋겠습니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 의사진행발언을 받아들이겠다 이거예요.
</p>
<p><b>○ 김대원 위원 </b> 저는 늦게 와서 죄송합니다만 저같은 경우는 오전에 질의종결을 하자는 얘기전달을 못 받았습니다.  
</p>
<p><b>○ 위원장대리 이원재 </b> 그것은 늦게 온 사람 책임이고요.
</p>
<p><b>○ 김대원 위원 </b> 어제 종일 감사를 했는데 어제 얘기를 해주든가.  
