<p style="padding-left:2.4em">    (이원재 위원장대리, 유영록 위원장과 사회교대)
</p>
<p><b>○ 위원장 유영록 </b> 감사를 진행하겠습니다.  일단은 위원님들의 질의신청이 있기 때문에 중식시간이 한참 지났지만 계속 진행하겠습니다.  원장님을 비롯한 박사님들 양해 되시죠?  그러면 질의하실 위원님 질의해 주시기 바랍니다.  김대원 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 김대원 위원 </b> 이상하게 소란스러워져서 죄송합니다.  오늘 감사 준비하시느라 신문 같은 것은 못보셨을 걸로 생각하는데 저희들 기획위원회 이슈가 사실상 경기개발공사문제로 상당한 논의를 계속하고 있는 중입니다.  그래서 오늘 경인일보 1면 톱에 나와 있을 겁니다.  그와 연관돼서 저희들 감사요구자료를 보면 연구실적 요약 및 도정에 반영된 내역과 효과 부분에 대해서 자료요구를 했는데 587쪽부터입니다.  그런데 605쪽을 보면 조응래 박사께서 산남휴게소 운영방안에 대한 연구를 하신 적이 있습니다.  2002년 9월 10일부터 2002년 11월 30일까지 해서 정책에 반영됐다고 자료를 제출하셨습니다.  그런데 그 자료내용을 보면 "산남휴게소의 운영권 협상에 경영분석 결과와 운영방안 대안이 사용됨" 이렇게 되어 있습니다.  그런데 운영권 협상에서 어떻게 결과가 나왔는지, 지금 안 계시는 관계로 답변하실 분 계시면 답변해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그때 당시에 보고서가 더욱더 정확할 것 같기는 한데요.  보고서가 없어도 제가 대략적으로 말씀드릴 수 있습니다.  그때 산남휴게소 운영권을 어느 기관에서 맞는 것이 적절하냐 그런 연구가 중요한 부분을 차지했었는데 아마 3개 기관이 경쟁을 했던 것으로 압니다.  지방공사하고 개발공사하고 파주시, 그런데 우리 쪽에서는 어느 한 곳이어야만 된다라는 결론을 피했습니다.  처음에는 그것을 어떻게 할 것인가에 대해서 고민도 많이 했는데요.  우리가 정책결정자들에게 어느 정도 결정할 여지를 남겨놔야지 우리가 A, B, C 중 A다라고 하게 되면 정책결정자는 또 다른 판단요소를 가지고 있을 수도 있는데 그 부분을 고려해야 되겠다 그래서 조금 유연하게 대응방안을 제시했던 것으로 압니다.  
</p>
<p><b>○ 김대원 위원 </b> 저희들이 보고서를 아직까지 못 봤거든요.  지금 가져오셨는데 현재 보고서를 보지 않고 전해 들은 상황에서는 경기개발공사가 아닌 것으로 예를 들어서 점수비교를 했다든가 이런 식의 우위비교를 뒀으면 경기개발공사가 우선순위가 아니었다는 걸로 전해들은 바가 있거든요.  현재 확인절차 좀 과정 중이니까 확인되는 대로 질의하도록 하겠습니다. 
</p>
<p><b>○ 김학용 위원 </b> 그 부분에 대해서는 제가 김대원 위원 지원발언을 해야 될 것 같아요.  왜냐하면 거기 보시면 아시겠지만 제가 과거에 본 기억이 있는데 그것만 정확히 말씀을 드리면 경기개발공사가 여러 가지 현재 운영상의 문제점이 있어서 경기개발공사에서 맡는 것은 적절치 않고 파주 시설관리공단에서 맡는 것이 합당하다 그런 식으로 결론을 내려줬습니다.  74페이지에 한번 봐보세요.  
</p>
<p><b>○ 김대원 위원 </b> 제가 읽어드리겠습니다.  3개 기관에 비교·분석 "경기개발공사는 경기지방공사의 설립 등 대외여건이 변화됨에 따라 1996년 12월 회사의 청산을 결의하였으나 어업피해 소송으로 인하여 청산절차가 중지됨 이에 따라 ''97년 12월부터 회사를 다시 운영하고 있으나 현재 만성적 적자운영이 이루고지고 있음, 경기개발공사는 본 휴게소 사업을 1994년부터 추진해 왔기 때문에 타기관에 비해 기득권은 인정되지만 회사경영환경이 불안정한 문제가 있음, 경기지방공사는 경기도와 위·수탁계약에 의해 휴게소 건립공사를 추진 중에 있는데 휴게소 운영과 관련하여 최근에 와서 관심갖기 시작함, 파주시는 산남휴게소 부지내에 무허가 영업을 하던 주민들에 대해 무허가 건물 행정대집행을 실시하였음 본 휴게소에 계획된 농산물판매센터로 휴게소 운영주체가 결정되면 판매상품의 종류와 판매방식에 대해 협의하여 운영할 필요가 있음 휴게소 운영과 관련하여 파주시가 직접 운영하기보다는 파주시가 전액 출자하여 1999년 6월에 설립한 파주시 시설관리공단을 운영, 관리주체로 참여시키기를 희망함" 이게 결론입니다.  그래서 결과론적으로 회사 환경이 불안정해서 문제가 있다는 데서 운영권을 따갔어요.  그런데 이게 정책에 반영이 안 된 사례죠, 결론은.  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그렇지 않습니다.  
</p>
<p><b>○ 김대원 위원 </b> 정책에 반영이 됐으면 연구한 그대로 불안정한 회사에 안 주는 게…….
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 거기에서는 일단 객관적인 사실들만 적시했을 따름이지 어디가 되어야 된다라는 것은 명확하게 얘기하고 있지 않습니다.  
</p>
<p><b>○ 김대원 위원 </b> 그러니까 불안정해서 문제가 있다고 그러고…….
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 불안정한 것은 사실입니다.  그런데 기득권 문제가 만만치 않더라고요.  
</p>
<p><b>○ 김학용 위원 </b> 분명히 연구원의 의도는 파주시의 시설관리공단에다 줘야 마땅하다는 뜻이 들어 있는 거죠.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그런 뜻으로 한 건 아닙니다.  파주시에서는 시설관리공단을 참여시키기를 희망한다 라는 사실을 알려드린 것이지 파주시가 적절하다라는 뜻을 쓴 것은 아닙니다. 
</p>
<p><b>○ 김학용 위원 </b> 많은 사람들이 읽어보고 100명이 읽어봐 가지고 99명이 이렇게 이해를 했다면 그게 맞는 거지, 여기 위원님들이 그 당시에…….
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 부의장님 맨 밑에 읽어보세요.  
</p>
<p><b>○ 함진규 위원 </b> 저도 한말씀 드리고 싶은데요.  저도 저희 지역구하고 인접해 있어서 통일로 갈 때 한번 들러보고 그랬었는데 사실 저는 그렇게 생각합니다.  위원님들이 어떻게 생각하실지 모르겠지만 제가 그렇다고 경기개발연구원을 두둔하는 것도 아니고 그렇다고 파주시를 두둔하는 것도 아니고 연구결과물은 원장님이 얘기하신 대로 하나의 결과물일 따름이지 본 위원이 지방공사 사장한테도 물어봤어요.  왜 경기개발공사가 다 넘어가는 회사고 부실한 회사인데 거기다 의뢰를 하느냐 그래서 여쭤봤는데 경기지방공사 나름대로의 어떤 논리가 있더라고요.  저도 여기 와서 연구결과물은 처음 들어보는데 어쨌든 그것은 정책결정자가 누구인지 그것은 그쪽에서 결정할 따름이라고 보고 경기개발연구원의 연구실적이 반드시 무슨 그에 따라서 정책결정을 해야 된다라고 보지는 않아요.  저도 그런 입장에서 말씀을 드리고 싶습니다. 
</p>
<p><b>○ 김대원 위원 </b> 현재 경기개발주식회사와 문제가 대두돼 있던 관계로 질의를 제가 하게 됐습니다.  그런데 76쪽 대안제시를 보면 운영방안 연구의 제일 마무리 부분인 것 같습니다.  민간위탁 추진방안, 여기에 보면 이것도 저 혼자 가지고 있으니까 다시 한 번 읽어드리겠습니다.  "민간위탁 추진방안, 휴게소운영 관리주체 선정시 민간위탁 동향과 관련해서는 도의회 건설교통위원회 승인이 공유재산 관리계획과 관련해서 도의회 자치행정위원회 승인이 있어야할 것이므로 운영관리 주체가 합리적으로 선정돼야 할 것임 산남휴게소와 관련된 3개 기관 중 운영관리주체를 선정하기 위해서는 전제조건으로 제시한 30년간 195억원, 경상가격을 경기도에 납부할 수 있는 기관을 선정하는 것이 바람직함" 195억원이라는 것은 아마 투자된 원가부분일 것입니다.  "만약 3개 기관이 상기 전제조건을 충족시키지 못할 경우에는 민간에 공개입찰을 시키는 방안에 대해서 검토할 필요가 있음.  운영관리 주체로 선정된 이후 협약내용을 이행하지 못할 경우에는 바로 계약의 해지 등을 통해 운정권을 제한할 수 있도록 하는 방안이 검토될 필요가 있음.  휴게소 및 주유소의 수지분석에 기초가 되었던 매 사업연도 실제 교통량의 90%에 미달하거나 110% 이상을 초과하는 경우에는 민간투자 사업의 사례를 참조하여 그 부족분을 보장하거나 추가분을 환수하는 방안을 운영관리주체와 협의할 필요가 있음" 이렇게 되어 있습니다.  이런 과정을 이렇게 쭉 보면 결론을 지켜보면 경기개발공사의 원장님 말씀하셨던 ''94년도부터 참여했던 기득권이 많이 인정된다고 그래도 아마 정책입안자가 정책에 반영을 할 때는 제 기준으로 봤을 때 배제돼야 될 부분인 것 같아요.  그 부분에 대해서는 어떻게 생각하십니까?  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 제가 정책결정자의 입장에 있지 않기 때문 답변하기가 곤란합니다.  
</p>
<p><b>○ 김대원 위원 </b> 이것은 문제제기로 마치는 것으로 하겠습니다.  이상입니다. 
</p>
<p><b>○ 위원장 유영록 </b> 김대원 위원님 수고하셨습니다.  다른 질의하실 위원님 계십니까? 
</p>
<p style="padding-left:0.0em"> 없습니다. 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  없으시죠.  상당히 시간이 지났기 때문에 질의가 없으실 것으로 알겠습니다.  더 이상 질의하실 위원님들이 안 계시므로 이상으로 경기개발연구원에 대한 질의와 답변을 모두 마치겠습니다.  위원님 여러분, 그리고 원장님을 비롯한 임직원 여러분!  장시간 열의를 갖고 감사에 임해주신 데 대해서 위원장으로서 감사의 말씀을 드립니다.  또 오늘 위원님들 지역구 활동도 바쁘시고 연일 계속되는 감사일정 중에서도 이렇게 참석해 주셔서 고맙다는 말씀을 드립니다.  또 오늘 여러 위원님들이 감사시 지적해 주신 사항들은 도민의 뜻이니 만큼 이를 겸허히 받아들이셔서 연구원 업무에 적극 반영될 수 있도록 원장님을 비롯한 실장님, 처장님께서 최선을 다해 주시기를 당부말씀 드립니다.  위원 여러분, 그리고 연구원 임직원 여러분!  수고하셨습니다.
</p>
<p style="padding-left:1.2em">  그러면 이상으로 경기개발연구원에 대한 2003년도행정사무감사 종료를 선언합니다. 
</p>
<p class=''ar''>(13시50분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원
</b></p>
<p class=''aMan''>유영록이원재김대원김영복김준회김학용이건희이효선정인영함진규</p>
<p class=''aMan''>나경숙</p>
