</b></p>
<p><p class=''em15''>전문위원 오태철지방행정주사 조한경지방행정주사보 김민기</p>
<p><p class=''em15''>지방기능7급 문정란지방기능9급 김선영</p>
<p><b>○ 출석증인
</b></p>
<p><p class=''em15''>경기개발연구원장 이철규사무처장 김봉규기획조정실장 이상훈</p>
