<h4>기획위원회 회의록 
</h4>제4호
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일  시 : 2002년 11월 26일(화)
</p>
<p>장  소 : 경기개발연구원
</p>
<p><hr /></p>
<p class=''ar''>(10시16분 감사개시)
</p>
<p><b>○ 위원장대리 이원재 </b> 좌석을 정돈해 주시기 바랍니다.  지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례 제2조 규정에 의해서 경기개발연구원에 대한 2002년도 행정사무감사 실시를 선언합니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 연구원장을 비롯한 임직원 여러분!  안녕하십니까?  기획위원회 유영록 위원장님의 감사를 대신한 이원재 위원입니다.  오늘부터 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다.  여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2003년도 예산안 심사자료 및 정보획득을 통해서 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 하겠습니다.  따라서 감사위원 여러분들께서는 연일 계속되는 감사일정에 노고가 많으십니다만 도민을 대표해서 도비 출연기관인 경기개발연구원의 운영실태를 감사하는 것이니 만큼 심도있는 감사활동으로 소기의 성과를 거둘 수 있게 하여 주시기를 기대하면서 아울러 감사에 임하는 연구원장님을 비롯한 임직원께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기를 당부드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다.  감사를 받는 연구원장 및 실·부장은 증인자격으로 소관업무를 보고하고 답변을 하게 됨으로써 먼저 선서를 하셔야 합니다.  증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2002년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다.  만약 증인이 허위증언을 할 때에는 지방자치법 제36조제5항 및 경기도의회행정사무감사및조사에관한조례 제8조 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부할 때는 동법 규정에 의하여 500만원 이하의 과태료가 부과될 수 있음을 알려드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 피감사기관의 증인은 모두 자리에 일어서 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (일동기립)
</p>
<p style="padding-left:1.2em">  먼저 증인출석여부를 확인하겠습니다.  경기개발연구원장 나오셨습니까?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 사무처장 나오셨습니까? 
</p>
<p><b>○ 사무처장 김봉규 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 기획조정실장 나오셨습니까? 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 도시경영연구부장 나오셨습니까?
</p>
<p><b>○ 도시경영연구부장 김동성 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 도시·지역계획부장 나오셨습니까?
</p>
<p><b>○ 도시·지역계획부장 이상대 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 교통정책연구부장 나오셨습니까?
</p>
<p><b>○ 교통정책연구부장 지우석 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 환경연구부장 나오셨습니까?
</p>
<p><b>○ 환경연구부장 이양주 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 지식산업연구부장 나오셨습니까?
</p>
<p><b>○ 지식산업연구부장 김군수 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 사회개발연구부장 나오셨습니까?
</p>
<p><b>○ 사회개발연구부장 김흥식 </b> 네.
</p>
<p><b>○ 위원장대리 이원재 </b> 다음은 선서요령을 설명드리겠습니다.  선서는 증인을 대표해서 경기개발연구원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인께서는 오른손만 들어주시면 되겠습니다.  그러면 선서를 해주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 선서!  본인은 경기도의회가 지방자치법 제36조, 동법시행령 제16조제1항, 경기도의회행정사무감사및조사에관한조례 제2조의 규정에 의하여 소관업무에 대한 2002년도 행정사무감사를 실시함에 있어 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법시행령 제17조의4제5항과 경기도의회행정사무감사및조사에관한조례 제18조의 규정에 의하여 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다.
</p>
<p class=''ar''>2002년도 11월 26일
</p>
<p class=''ar''>증인 경기개발연구원장 이철규.
</p>
<p><b>○ 위원장대리 이원재 </b> 자리에 앉아주시기 바랍니다.  경기개발연구원장님 간부소개와 업무보고를 해주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 경기개발연구원장입니다.  존경하는 유영록 기획위원장님 그리고 기획위원 여러분!  의회의 바쁘신 일정 중에도 저희 연구원을 찾아주신 데 대하여 우선 심심한 감사의 말씀을 드립니다.  저희 연구원 가족 모두는 1년에 한 차례밖에 없는 이 소중한 기회가 연구원의 성장과 발전에 유익한 초석이 되기를 바랍니다.  저희 연구원은 다른 시·도 연구원에 비해서 출발은 좀 늦었지만 짧은 기간 동안에 괄목할 만한 성장을 거듭해 왔습니다.  서울시정연구원, 즉 SDI와 함께 지방정부 출연연구기관의 선두주자가 되었고 이제는 국책연구원과도 감히 어깨를 겨루기에 이르렀습니다.  여기까지 성장하기에는 연구진 자체의 노력도 노력이지만 무엇보다 경기도청과 경기도의회 그리고 31개 시·군 모두의 사랑과 믿음이 있었음을 저희 모두는 깊이 인식하고 있습니다.  모든 분들께 정말 감사하게 생각합니다.
</p>
<p style="padding-left:1.2em">  그러나 경기개발연구원, 즉 KRI에 대한 평가가 마냥 긍정적이고 호의적이지만 않다는 것을 저희는 잘 알고 있습니다.  연구성과에 대한 불만도 그 저변에 깔려있을 것입니다.  또 성과에 비해서 비용이 너무 많이 든다는 평가도 그 이유가 됐을 것입니다.  그 동안의 경영능력이나 인사운영이 마음에 들지 않았을 수도 있을 것입니다.  어떤 이유가 되었건 저희는 KRI에 대한 지적과 비판을 겸허히 수용해야 한다고 생각하고 있습니다.  저 자신도 그 비판을 충분히 이해하고 있습니다.
</p>
<p style="padding-left:1.2em">  그러나 위원님 여러분!  저희 KRI는 이제 걸음마를 하고 있습니다.  우리나라 지방자치와 같은 동갑내기입니다.  민선3기를 맞아서 우리 지방의회가 새로운 옷을 갈아입고 있듯이 저희 KRI도 새롭고 듬직한 모습으로 다시 태어날 용트림을 하고 있습니다.  KRI비전팀이 발족해서 내년부터 적용할 수 있는 강도높은 중·장기발전방안을 수립하고 있습니다.  2003년도부터는 확실한 비전, 보강된 연구진, 달라진 자세로 여러분 앞에 그리고 도민 앞에 설 수 있으리라고 생각합니다.  저희들은 연구를 통해서 우리나라의 지방자치를 뿌리내리게 하는데 힘을 쏟겠습니다.  경기도의 비전과 전략을 제시하는 일에 심혈을 기울이겠습니다.  본질적이고 실효적인 연구가 되도록 채찍질하겠습니다.  피부에 닿는 교통, 환경, 산업, 복지, 관광대책을 제시하겠습니다.  무엇보다도 도민들의 사랑과 신뢰를 받을 수 있는 연구원이 되도록 노력하겠습니다.  이러한 말은 위원님 여러분께 드리는 약속이면서 동시에 저희들 자신에게 던지는 다짐이기도 합니다. 
</p>
<p style="padding-left:1.2em">  지난 9월 저희 KRI를 방문한 손학규 지사께서는 저희들에게 최고의 연구기관이 될 것을 지시하셨습니다.  이를 위해서 적극적인 지원도 약속하셨습니다.  그러나 저희들은 손 지사의 그러한 지시가 얼마나 엄청난 질타이고 추궁인지를 잘 알고 있습니다.  최고의 연구기관을 만들지 못하면 책임을 묻겠다는 강한 뜻이 숨겨져 있는 것입니다.  위원 여러분!  오늘의 감사를 통해서 많은 지적을 해주시기를 바랍니다.  신은 불 속에서 더욱 강해지고 국화는 설한 풍에서 향기를 발한다고 했습니다.  저는 KRI 가족모두와 힘을 합쳐서 반드시 강하고 향내나는 연구원을 일구어 놓도록 노력하겠습니다.
</p>
<p style="padding-left:1.2em">  저희 간부를 위원님 여러분께 소개해 올리겠습니다.  기획조정실장 이상훈 박사입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  사무처장 김봉규 처장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  도시경영연구부장 김동성 박사입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  도시 및 지역계획부장 이상대 박사입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  교통정책연구부장 지우석 박사입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  환경연구부장 이양주 박사입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  지식산업연구부장 김군수 박사입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  사회개발연구부장 김흥식 박사입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  그러면 위원님께서 양해해 주신다면 상세한 보고는 기획조정실장으로 하여금 드리도록 하겠습니다.  감사합니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 경기개발연구원장 수고하셨습니다.  2002 업무보고 이것 가지고 하실 것입니까?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네, 그렇습니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 보고해 주시기 바랍니다.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기획조정실장 이상훈입니다.  기 배부해 드린 자료를 중심으로 해서 우리 연구원의 업무를 보고드리도록 하겠습니다.  우선 보고순서는 일반현황과 재정운영현황 그리고 2002년도 연구사업 추진상황, 2003년도 연구사업계획 또한 2001년도 행정사무감사 처리요구사항 조치결과 순으로 보고드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  1쪽이 되겠습니다.  일반현황을 보고드리겠습니다.  이미 배부해 드렸기 때문에 간략하게 보고드리도록 하겠습니다.  우선 연혁부분입니다.  저희 연구원은 ''95년 3월 20일에 개원해서 올해로 7주년을 맞이하고 있습니다.  1995년 11월 25일에는 현 독립청사로 이전해서 연구활동을 하고 있습니다.  저희 연구원의 기능으로서는 도정의 중·장기 비전제시와 정책개발 지원부분이 되겠습니다.  기획조정실이 있고 나머지 6개 연구부서가 도정 수에 맞춰서 전문적인 연구를 수행하고 있습니다.  기타 자세한 내용은 유인물로 갈음하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  2쪽이 되겠습니다.  2쪽에서는 기구 및 인력부문입니다.  저희 연구원은 기획조정실, 사무처 1실 1처, 그 다음에 도시환경자문팀을 포함해서 7개 부서로 기구가 구성되어 있습니다.  전체 인력은 연구직 30명을 포함해서 정규직 48명이 근무하고 있고 비정규직도 52명을 운영하고 있습니다.  앞으로 부족한 연구직 8명에 대해서는 정기모집과 수시모집을 병행해서 우수인력을 채용하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  다음 페이지는 시설물 및 물자현황입니다.  저희 청사는 현재 대지 894평으로 이루어져 있고 그 중에서 건평이 851.5평입니다.  2004년 4월에는 경기도공무원교육원 신축과 더불어서 약 1,672평을 무상임대해서 사용할 계획으로 있습니다.  주요물품으로는 특히 장서부문입니다.  국내서가 약 1만 5,500권, 영서가 약 4,300여권 있습니다만 저희 연구원의 자랑은 비교적 장서규모가 크지는 않지만 최신자료 중심으로 이루어져 있고 도민, 시민, 공무원 등이 이용하도록 개방형으로 운영되고 있습니다.  앞으로 최고의 정보서비스를 제공해서 경기도 연구에 관한 연구는 경기개발연구원에서 정보를 제공하는 메카가 되도록 노력하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 4쪽 재정운영 현황입니다.  일반회계 중심으로 2002년도에는 90억 600만원입니다.  이것은 전년도에 비해서 약 5억 700만원이 증가된 규모가 되겠습니다.  일반회계 세입내역을 보면 가장 큰 규모가 도비보조금이 67.3%를 차지하고 있고 전입금, 기타 환급금 및 이자수입 순으로 적립되어 있습니다.  지출부문에 대해서는 연구부 운영을 포함한 연구사업비가 약 71억 6,800만원으로써 총 79%를 차지하고 있습니다.  향후에는 연구여건 지원에 중점을 둘 계획으로 있습니다. 
</p>
<p style="padding-left:1.2em">  기금관리 현황입니다.  5쪽이 되겠습니다.  총 기금은 214억원입니다.  이중에서 경기도출연이 64%를 차지해서 137억원, 시·군 출연이 13.5%로서 39억원 그리고 일반은행에서 약 20억원 출연되어 있고 자체적립이 17억 3,900만원으로 총 8.2%를 차지하고 있습니다.  기금예치현황은 안전성을 우선시하고 그 다음에 이자율 및 예금의 종류를 고려해서 분산예치를 원칙으로 하고 있습니다.  현재 4개 은행에 14종의 상품으로 분산 예치된 상황입니다. 
</p>
<p style="padding-left:1.2em">  6쪽부터는 2002년도 연구사업 추진상황입니다.  6쪽, 7쪽이 되겠습니다.  연구사업의 주요성과로는 지식사회에 걸맞은 행정서비스를 공급하겠습니다.  이를 위해서 경기도 주민자치센터 기능 활성화방안도 수립했고 경기도 자주재원 발굴 및 건전재정 전략을 수립 중에 있습니다.  다음은 공간계획 수립확대 및 지방정부의 계획고권 확보를 위해서 수도권정비계획 법령개선 및 시·군 도시기본계획과 지구단위계획 등을 검토 조정했습니다.  광역도시계획 수립 및 제2차 경기발전5개년계획을 현재 수립 중에 있습니다.  통근권 광역화에 따른 도시기반시설 부족에 대응하기 위해서는 교통영향평가 지침개발 및 일산대교 민자사업 실시협약 추진방안을 마련하였고, 광역교통체계 및 경기북부지역 고속화도로 사업 건설방식을 현재 수립 중에 있습니다. 
</p>
<p style="padding-left:1.2em">  수질악화 및 수량부족, 대기오염 등의 문제에 대응하기 위해서는 저희 연구원이 환경부에서 유해대기오염 물질인 다이옥신 배출측정 시스템을 개발한 바 있습니다.  한강수계관리기금의 개선방향 및 방치폐기물 처리비용에 관한 폐기물관리법 개정안을 마련했고, 건교부와 수자원공사의 시화호 지역 개발관리계획에 경기도 차원의 종합대책을 현재 수립 중에 있습니다.  지식산업의 중심지로서 경기도의 국제경제력 강화를 위해서 공업배치법령 개정안 및 판교신도시 지식산업집적단지 개발방향을 제시한 바 있고, 산업영향평가법 제정안을 현재 수립 중에 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 여가수요증가 대비 및 대 중국 협력강화를 위해서 육로관광을 통한 남·북한 관광협력 활성화 방안을 제시하였고, 중국연안지역과의 경기도의 경제교류 활성화방안을 수립 중에 있습니다.  대외 협력강화를 통한 연구원 위상제고를 위해서 건교부, 환경부 등의 중앙부처로부터 수탁과제 연구수행 및 정책대안을 제시한 바 있습니다.  또한 국책연구원 및 시·도 연구원간의 공동협력 증진을 도모하고 있고, 경기도의 경쟁력을 위해서 보다 경쟁력있는 정책개발을 도모하기 위해서 관내대학 성균관대학을 포함한 6개 대학과의 학·연 네트워크협정을 체결한 상태입니다.  또한 국제적인 협력강화를 위해서 캐나다도시연구소와 교류협정이 체결된 상태입니다.
</p>
<p style="padding-left:1.2em">  경기도정 현안토론회 개최를 위해서 경기 2020 수정계획 주민설명회 등을 포함한 서해안 포럼의 지속·운영, 향후 남북교류협력과 교육정책 포럼을 신설·운영할 계획에 있습니다.  이미 기 소개가 됐습니다만 KRI비전팀을 운영해서 연구원의 장기발전계획 수립을 위한 비전팀을 운영 중에 있습니다.  또한 수탁과제 수주를 통한 자주재원 확보를 위해서 이월과제 15건의 약 26억원을 포함해서 2002년 11월 15일까지 신규과제 22건 해서 수탁금액 20억원 등 총 46억원의 자주확충 노력을 했습니다.  앞으로 적극적인 수립활동을 펴도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  8쪽부터는 연구사업 총괄부문이 되겠습니다.  연구과제사업은 총 132개 과제의 사업량을 계획되어 있고 이중에서 130개 과제가 현재 연구 중 아니면 완료돼서 계획대비 98%가 완료된 상태입니다.  정기간행물 발간사업은 46회가 계획되어 있고 현재 34회가 완료되었고 12회가 추진 중이어서 계획대비 100% 달성할 것으로 예상되고 있습니다.  연구조성 사업부문은 총 18건이 계획되어 있습니다만 이중에서 12건이 완료되었고 2건이 추진 중이어서 총 14건이 완료될 경우 계획대비 77%가 완료되는 상태입니다. 
</p>
<p style="padding-left:1.2em">  다음 9쪽에서 17쪽까지는 저희 연구사업 세부 추진상황이 되겠습니다.  상당한 부분이 장황하기 때문에 가능한 간략히 보고드리겠습니다.  우선 기본연구과제는 총 31개 과제를 수행 중에 있습니다.  이중에서 11개 과제가 완료됐고 20개 과제가 현재 연구 중에 있습니다. 
</p>
<p style="padding-left:1.2em">  10쪽입니다.  다음은 수탁연구과제입니다.  10페이지부터 11페이지까지 수탁연구과제 37개 과제입니다.  이중에서 이미 16개 과제가 완료되었고 3개 과제는 중지된 상태이고 18개 과제가 연구 중이므로 총 21개 과제가 연구 중인 상태입니다. 
</p>
<p style="padding-left:1.2em">  다음 12쪽, 13쪽은 정책연구과제가 되겠습니다.  정책연구과제는 이월된 6개 과제를 포함해서 총 38개 과제가 추진상황이고 이중에서 22개 과제는 완료됐습니다.  그리고 13개 과제는 현재 연구 중이고 3개 과제는 저희들이 신규로 채택준비 중에 있습니다.  이상 13페이지까지 소개를 올렸습니다.
</p>
<p style="padding-left:1.2em">  14쪽부터는 위탁연구과제입니다.  위탁연구과제는 총 12개 과제를 추진하고 있고 이중에 경기도 신호교차로 운영현황 및 개선방안 연구 1개 과제가 완료되었고 현재 11개 과제가 금년 중에 완료될 예정에 있습니다.  지역연구과제는 저희들이 2개 과제를 계획수립 했습니다.  그 중에서 시흥시 지역연구가 완료됐고 현재 양평군 지역연구가 현지 현황파악까지 끝나서 연구진에 의해서 연구가 진행되고 있습니다. 
</p>
<p style="padding-left:1.2em">  15쪽에 협약연구과제 부문이 되겠습니다.  협약연구과제는 10개 과제를 추진하고 있고 이미 경기 2020 비전과 전략을 포함한 5개 과제가 완료됐습니다.  그리고 나머지 5개 과제는 현재 연구 중입니다.  정기간행물은 저희 연구원에서 총 7권을 추진하고 있습니다.  이중에서 경기연구와 연구원 안내책자 부분은 연말에 발행할 예정이고 나머지는 계간, 월간으로 해서 예정대로 발간이 진행되고 있습니다. 
</p>
<p style="padding-left:1.2em">  16쪽이 되겠습니다.  번역사업은 두 가지 종류의 번역을 추진 중에 있습니다.  표에서 보시는 것처럼 2개 도서에 대해서 추진을 하고 있습니다.  다음은 정책세미나 부문이 되겠습니다.  총 11건을 개최했습니다.  이중에서 워크숍이 8건 되고 세미나가 2건, 포럼 1건을 포함해서 총 11건을 완료했습니다.
</p>
<p style="padding-left:1.2em">  17쪽의 연구사업의 연도별 수행현황에 대해서는 유인물로 갈음하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  18쪽부터 38쪽까지는 2003년도 연구사업 계획부문이 되겠습니다.  사업방향에 대해서는 자료로 갈음하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  19쪽부터는 기본연구과제 추진계획입니다.  기본연구과제는 연구원 고유의 정기적인 연구사업이 되겠습니다.  선정절차는 도의회 및 산하기관, 관련부서 등에 공문을 시달해서 추천을 받습니다.  추천받은 과제들을 중심으로 해서 연구원 연구진과 도청의 실무자들과 간담회를 개최합니다.  그래서 연구원 수행 가능한 과제를 선정하고 경기개발연구원 자체연구심의회의 심의·의결을 거쳐서 이사회에 확정하는 순서를 밟고 있습니다.  현재 이사회에 확정되기 전 단계로서 자체연구심의회의 심의·의결을 거친 과제가 33개 과제가 되겠습니다.  기존 연구진에 의한 25개 과제와 앞으로 신규임용자가 수행하게 될 8개 과제를 포함해서 33개 과제를 수행할 계획으로 있습니다.
</p>
<p style="padding-left:1.2em">  20쪽이 되겠습니다.  협의 및 반영과제 현황은 20쪽과 21쪽에 과제명, 연구기간, 예산, 연구책임자, 과제 협의부서가 명시되어 있습니다.  자세한 내용은 유인물로 갈음하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 부서별 세부 연구사업계획 부문으로서 22쪽부터 31쪽까지입니다.  이 부분은 앞에서 명시됐던 과제에 대한 보다 상세한 연구목적, 내용부분까지 포함한 내용이 되겠습니다.  자세한 내용은 유인물로 갈음하고 32쪽부터 보고를 드리도록 하겠습니다.  기타연구사업 추진계획 부문이 되겠습니다.  32쪽에 기타연구사업 추진계획 중에서 수탁연구과제가 되겠습니다.  수탁연구과제는 외부기관이 의뢰하고 연구비를 부담하는 과제가 되겠습니다.  그래서 2003년도에는 현재 진행중인 이월과제 10건을 포함해서 각 연구부서별로 5건 내외를 수행해서 30개의 수탁과제 추진이 예상되고 있습니다.  이월과제 현황은 표에서 보시는 바와 같습니다.
</p>
<p style="padding-left:1.2em">  33쪽에 정책연구과제 부문은 경기도가 긴급 요청하는 현안연구과제 또는 연구원 자체적으로 이 부분에 대해서는 중요도가 있다고 판단해서 추진하는 과제가 되겠습니다.  당초에 계획했던 부분들이 아니기 때문에 이 부분은 현안문제가 발생할 때 수행하는 과제가 되겠습니다.  사업계획으로서는 총 51개 과제가 예상되어 현재 2003년도에 수행할 계획입니다.  이중에서 정책과제가 40개 과제가 되겠는데 이는 수시의뢰 30개 과제 그리고 연구원 자체추진 10개 과제가 돼서 40개 과제가 되겠습니다.  2003년도에 신규로 추가한 과제, 특별단기 조사분석 부문입니다.  어떤 사안이 발생했을 때 긴급하게 조사분석을 해서 정책대안을 제시하는 부분의 10개 과제를 수행할 예정입니다.  또한 도 및 도의회 전문성 강화를 위한 교육프로그램개발 1개 과제를 수행할 예정에 있습니다. 
</p>
<p style="padding-left:1.2em">  34쪽입니다.  이것은 위탁연구과제입니다.  위탁연구과제는 기초적 예비 또는 보완적 추가연구를 위해서 외부기관과의 협력적 연구가 필요한 사업입니다.  저희 연구원에 물론 연구진이 있지만 상당히 기초적이고 예비적인 부분, 또 아주 세밀한 전문분야가 필요한 부분은 위탁연구를 추진하고 있습니다.  그래서 올해는 총 12개 과제를 수행할 예정에 있습니다.  특히 학·연 네트워크 협정활성화 대학과의 공동연구가 이중에서 8개 과제가 되겠고, 관내대학·학회·연구소 등을 통한 공감대 형성 추진을 위해서 4개 과제를 추진해서 총 12개 과제가 수행될 예정에 있습니다.  지역연구과제는 34쪽에 표시되어 있습니다.  1년에 2개 과제를 수행하고 있습니다.  2003년도에도 6개월에 1건씩 해서 상반기·하반기에 2개 과제를 수행할 예정에 있습니다. 
</p>
<p style="padding-left:1.2em">  35쪽에는 정기간행물 발간사업 추진계획입니다.  이중에서 대부분 경기연구라든지 경기논단, KRI 뉴스레터, 경기도 경제동향과 전망 등은 전년도와 같습니다만 특히 알기쉬운 경기도 경제지표 부분은 일부 중복되는 부분이 있기 때문에 월간에서 계간으로 축소 발간하도록 할 계획입니다.
</p>
<p style="padding-left:1.2em">  36쪽이 되겠습니다.  다음은 연구조성사업 추진계획부문이 되겠습니다.  특히 여기에서 번역사업과 세미나, 심포지엄, 워크숍 부문을 보고드리도록 하겠습니다.  우선 번역사업으로서는 경기도 도정에 도움이 될 수 있는 최신 외국도서의 번역 및 배포를 저희들이 추진해서 적실성 있는 도서를 선정해서 3개종을 번역할 계획으로 있습니다.  세미나, 심포지엄, 워크숍 부문에 대해서는 총 15회를 계획하고 있습니다.  이중에서 세미나 3회, 심포지엄 2회, 워크숍 10회 해서 총 15회의 사업량이 2003년도에 계획돼 있습니다.
</p>
<p style="padding-left:1.2em">  37쪽의 연구자문위원회 경기연구포럼 운영부분이 되겠습니다.  이것은 자문위원회를 필요시 수시 개최하는 부분으로서 보다 내실있는 경기연구포럼을 운영하도록 추진하겠습니다.  또한 도시환경자문팀 운영부분으로서 이 부분은 도시계획과 관련된 시·군의 계획수립에 대한 방향제시 및 조정기능을 하기 때문에 이 부분에 대해서도 향후 지속적으로 추진하도록 하겠습니다.  특히 이 부분에 대해서는 현안이 발생할 때 수시 자문하는 역할을 추진하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  38쪽이 되겠습니다.  연구원에서 2003년도에 특히 심도있게 추진하는 부분이 통합정보관리시스템 구축입니다.  연구원의 연구결과에 맞고 다양한 자원 등이 있는데 이것을 통합적이고 효율적으로 조직화하여 관리하자는 차원에서 필요한 자문을 하나의 인터페이스로 이용할 수 있는 통합정보관리시스템을 구축해서 보다 업무와 관련해서 생산성 향상으로 고부가가치 창출을 도모하고자 합니다.  또한 GIS지리정보시스템을 운영해서 경기도 관련 프로젝트 지원과 지속적인 관련자료 갱신 및 관련장비 관리를 위해서 저희들이 GIS팀 운영을 보다 효율적으로 할 계획으로 있습니다. 
</p>
<p style="padding-left:1.2em">  39쪽에는 마지막으로 2001년 행정사무감사 처리요구사항 조치결과가 있습니다.  2001년도 11월 26일 행정사무감사를 수감했고요.  이중에서 처리요구사항이 4건이고 처리결과는 4건을 이미 처리 완료한 상태입니다.  상세한 처리내용은 40쪽에 요구사항 및 조치결과로 유인물로 갈음하도록 하겠습니다.  이상으로 2002년도 주요업무보고를 모두 마치겠습니다.  감사합니다.
</p>
<p><br /></p>
<p>(업무보고는 끝에 실음)
</p>
<p><br /></p>
<p><b>○ 위원장대리 이원재 </b> 이상훈 기획조정실장 수고하셨습니다.  다음은 질의·답변을 받도록 하겠습니다.  위원님들께서 양해해 주신다면 앉아서 답변하도록 하는데 이의 없으십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  감사의 원활한 진행을 위해서 질의·답변은 일문일답식으로 진행을 하도록 하겠습니다.  질의하시기 전에 위원장으로서 한 가지 부탁말씀을 드리겠습니다.  위원님의 질의사항 중 답변이 어려울 경우 담당실·부장 등 실무자가 답변해도 좋습니다.  다만 사전에 위원장에게 동의를 얻은 후 소속과 직·성명을 분명히 밝히고 답변해 주시기 바랍니다.  그러면 질의하실 위원님께서는 거수로 신청해 주시기 바랍니다.  나경숙 위원 질의해 주시기 바랍니다.
</p>
<p><b>○ 나경숙 위원 </b> 나경숙 위원입니다.  경기도 발전을 위해서 연구사업에 밤낮없이 노고가 많으신 이철규 원장님을 비롯하여 관계담당자들께 일단 수고 많으셨다고 감사 말씀드리고요.  제가 질의할 것은 감사자료 192페이지를 보면 2002년도에 대학교 등에 연구를 의뢰한 과제가 25개 과제에 13억 6,500만원이 지출된 것으로 나타났고 이는 올해 연구원에서 기본정책 수탁연구과제의 28.7%에 이르는 것으로 나타났는데 연구원에는 사회 각 분야의 우수한 연구진이 있고 지급되는 연봉이 연간 12억원에 달하고 있는데 연구원에서 연구를 수행해야 할 과제를 자체 예산과 외부에서 받은 용역비 등 연간 수십억원을 들여서 외부 연구기관에 맡기고 있는 것은 연구원들의 전문성에 혹시 문제가 있는 것이 아닌가에 대한 원장님의 견해와 인력부족이 이유라면 현재 부족한 인력을 조속히 채용해 연구인력을 보강해야 한다고 보는데 채용하지 않는 이유에 대한 원장님의 견해를 묻겠습니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 나 위원님 질의 감사합니다.  외부기관에 위탁연구를 시키는 것은 저희들 자체적인 전문성이 부족한 탓도 물론 있겠습니다만 보다 더 중요한 것은 외부위탁을 통해서 전문성 있는 연구기관이 함께 참여하도록 하는데 의미가 있는 것이라고 생각합니다.  특히 기술검토나 기초조사 같은 외부전문가의 활용이 꼭 필요한 부분에 대해서는 저희들이 스스로 참여하는 것보다는 위탁해서 함께 참여하는 것이 훨씬 효과적인 경우가 많습니다.  특히 시대의 흐름이 이제는 모든 연구를 혼자서 하는 방법보다는 아웃소싱을 통해서 연구하는 것이 연구비의 절약을 위해서도 바람직한 경우가 있습니다.  물론 위원님 지적하신 대로 우리들이 책임을 지고 연구하는 자세를 견지하겠습니다만 꼭 필요한 경우에는 대학이나 다른 연구기관의 전문가들이 함께 참여하는 위탁연구방법을 반드시 피해 나갈 필요는 없다고 생각합니다.  그리고 전문인력이 충원이 덜 되고 있는데 그 동안 여러 차례 충원계획도 발표하고 그랬었습니다만 지난번에도 109명이나 지원했었으나 저희들이 충원을 필요로 했던 12명을 채우지 못하고 7명밖에 충원을 못했던 사례가 있습니다.  그것은 저희들이 요구한 수준을 충족시키지 못했기 때문입니다.  앞으로 연구진의 모집방법도 보다 더 적극화해서 국내에서 모집할 수 없을 때는 해외에 나가서까지 스카웃하는 그런 적극적인 모집방법을 강구해서 저희들이 꼭 필요로 하는 연구진들이 충원될 수 있도록 노력하겠습니다. 
</p>
<p><b>○ 나경숙 위원 </b> 답변 감사드리고요.  이게 외부에서 같이 동참하는 것도 좋은데 저희가 일반적으로 생각해 보면 여기도 연구하고 개발하는 곳인데 28.7%라면 상당히 외부로 나간다고 원장님께서는 생각 안 하십니까?  줄일 수는 없는가요?  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 위원님, 28.7%라고 말씀하셨습니까?  어떻게 해서 28.7%입니까?
</p>
<p><b>○ 나경숙 위원 </b> 교육분야 쪽에는 거의 나가고 있는데요.  13억 6,500만원 나가는 것 중에 연간 위탁으로 나가는 게 12억원이 나갔거든요.  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 위탁연구가 13억 6,500만원.
</p>
<p><b>○ 나경숙 위원 </b> 경기개발연구원에서 나간 것의 비용에 비하면…….
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 제가 28.7%의 근거는 파악을 해보겠습니다만 기본과제, 수탁과제, 정책과제를 합해서, 이게 연구과제가 있습니다.  저희들이 자체예산으로 하는 기본연구과제가 있고요.  그리고 우리가 자체적으로 자체예산 가지고 하지만 그때그때 필요에 의해서 하고 있는 정책연구과제가 있고요.  그 다음에 외부기관의 돈으로 하는 연구과제가 있습니다.  그것은 수탁과제입니다.  경기도청의 돈으로 한다든지 시·군의 돈으로 한다든지 하는 연구과제가 수탁연구과제입니다.  그 다음에 위탁연구과제라는 것이 있습니다.  그것은 저희들 예산으로 하지만 저희들이 직접 연구하지 아니하고 밖의 외부기관에 맡겨서 하는 연구입니다.  그것은 위탁연구과제입니다.  그리고 협약과제라는 것이 있습니다.  그것은 저희들 돈 가지고 하는 게 아니고 협약을 맺은 다른 기관의 예산을 가지고 하는 연구과제인데 그것은 아주 단기 과제인 경우 예외적으로 인정이 되고 있습니다.  이런 모든 과제를 합한 것 중에서 위탁과제가 차지하는 비중은 저희들이 알기로 28.7%는 아닌 것으로 알고 있습니다.  거기에 나와있는 대로 극히 일부에 해당하는데 위탁연구과제들은 저희들 연구기관과 대학과의 협력관계를 유지하는데도 도움이 되고 아까도 말씀드렸지만 보다 전문적인 연구를 하는데 도움이 되기 때문에 그런 경우에만 예외적으로 인정해서 하고 있습니다. 
</p>
<p><b>○ 나경숙 위원 </b> 무슨 말씀인 줄 알겠고요.  저희가 판단한 것은 지금 원장님이 설명해 주셔서 이해가 가는데요.  여기 있는 것을 다 통합해서 제가 말씀드렸던 거고 저희가 지난번에 와서도 보고를 한 번 받은 적이 있지요.  지난번에 방문했을 때 설명을 제대로 못 들었고 구체적 설명을 안 해주셨기 때문에 제가 잘 모르는데 이것을 자료로 제출해 주셨으면 좋겠네요.  이상입니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네, 그렇게 하겠습니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 다음 질의하실 분, 정인영 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 정인영 위원 </b> 정인영 위원입니다.  보충질의를 드리겠습니다.  지금 나경숙 동료위원께서 아주 좋은 지적을 해주셨는데 위탁연구과제가 12개 과제고 기본연구과제가 33개 과제, 수탁연구과제 30개 과제, 정책연구과제가 52개 과제 해서 그것에 대한 퍼센티지가 28.6%라는 얘기가 아니고 예산 지출면에서 예산이 28.6%가 집행이 된다는 그런 지적인 것 같고요.  저는 다른 측면에서 질의를 드리면 지금 연구과제를 위탁하는 당위성에 대해서는 이해가 갑니다.  경기개발연구원이 가지고 있는 인력이 연구 못하는 부분도 있어서 다른 연구기관과 서로 긴밀한 협조를 통해서 사업연구물들이 나와야 하는데 그것에 대한 이해는 갑니다.  금년에 기획위원회에서 업무보고를 받을 때도 지적한 사항입니다만 인력측면에서 정원이 60명인데 현원이 48명이니까 다른 데는 다 인원이 충원됐는데 연구기관에서 정원이 38명인데 현원이 30명밖에 안 된다는 지적을 한 바가 있습니다.  거기에 대한 대책을 말씀해 주시고 그리고 위탁연구과제를 뺀 연구사업계획 총괄을 보면 총 116건이 되고 그외 정기간행물 사업이나 연구조성사업 등 많은 연구들을 하는데 과연 정원이 다 채워지지 않은 30명의 연구직으로서 이 업무가 상당히 과중하다고 봅니다.  최소한도 1인당 논문이 연간 평균 4편씩 나와야 된다고 보는데 이렇게 과제를 과중하게 주면 그 연구가 소홀해 질 수가 있습니다.  그래서 한 가지 과제를 주더라도 그게 확실하게 경기도 발전을 위한, 여러 가지 국가발전을 위한 연구결과가 도출되도록 해야 한다고 보는데 거기에 대한 답변바랍니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 정인영 위원님 감사합니다.  정인영 위원님 지적하신 부분에 대해서 저도 전폭적으로 동의가 갑니다.  우선 정원에 비해서 연구직이 8명이나 부족한 상태에 있습니다.  물론 정원책정기준이 적정하냐에 대해서는 별도 또 다른 문제제기를 할 수도 있겠습니다만 일단 우리가 필요로 하는 정원을 아직 채우지 못하고 있다는 것은 저희들한테도 책임이 있다고 생각합니다.  그러나 아까 말씀드렸듯이 저희들이 희망하는 연구원의 수준과 여기에 지원하는 연구원의 수준이 맞지 않기 때문에 그 동안 이것을 적절하게 충원을 시키지 못해 왔었습니다.  앞으로 저희들이 비전팀에서 나오는 연구결과를 보고 어떻게 하면 보다 적극적인 충원방법을 동원할 것인가 하는 것을 바탕으로 해서 빠른 시일내에 충원하도록 노력하겠습니다.  그리고 연구과제가 너무 많다는 지적은 저 역시도 동감하고 있고 연구진 자체적으로도 동감하고 있는 사항입니다.  연구가 질보다는 양 위주로 나가는 것은 결코 바람직하지 않다고 생각합니다.  이러한 문제점도 이번에 비전팀의 연구결과를 바탕으로 해서 질 본위 연구로 방향전환을 할 수 있도록 조정할 생각이고 그러기 위해서 필요하다면 기본과제를 줄인다든지 또는 연구원에 위촉연구원의 숫자를 늘린다든지 하는 방향으로 해서 연구부담을 덜어나가는 그런 노력을 병행해 나가겠습니다.
</p>
<p><b>○ 위원장대리 이원재 </b> 수고하셨습니다.  다음 질의하실 분, 김영복 위원 질의해 주시기 바랍니다.
</p>
<p><b>○ 김영복 위원 </b> 나경숙 위원님의 질의에 정인영 위원님이 보충질의 했는데 가평출신 김영복 위원입니다.  보충질의 드리겠습니다.  업무보고 자료에는 현원이 60명으로 나와있지요.  행정사무감사 자료에는 59명으로 나와있습니다.  행정사무감사 자료하고 업무보고 자료하고 틀리거든요.  그래서 항상 자료를 작성할 때는 정확한 자료를 주시기 바랍니다.  어떤 게 맞습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 60명이 맞습니다. 
</p>
<p><b>○ 김영복 위원 </b> 행정사무감사 자료에는 59명으로 돼 있는데 누가 빠지신 거지요?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 죄송합니다.  기획조정실장 이상훈입니다.  그 부분은 자료를 요청하신 시점하고 저희들이 자료를 인쇄한 시점하고의 차이 때문에 그렇습니다.  참고로 말씀드리면 11월 1일부로 퇴직한 연구원이 있기 때문에 자료제출 시점에 따라서 달라진 것입니다.  현원은 59명이 되겠습니다.  60명으로 나온 부분은 자료준비 하면서 나온 내용하고 차이가 있습니다.  
</p>
<p><b>○ 김영복 위원 </b> 본 위원이 파악한 것은 연구원 숫자는 똑같아요.  잘못 말씀하시는 것 같은데…….
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 제가 답변올리겠습니다.  정원이 이 자리에 나와있는 것처럼 60명이 맞습니다.  
</p>
<p><b>○ 행정과장 김영수 </b> 제가 답변을 올리겠습니다.  행정과장 김영수입니다.  당시 자료작성할 때 저희가 착오를 일으켰습니다.  이사회에서 앞으로 내부인사할 때 상임고문직제를 없앨 계획으로 있었습니다.  착각을 해서 상임고문직제 숫자를 못 넣었습니다.  그래서 59명입니다.  정원은 60명이 맞습니다.  저희가 잘못한 겁니다. 
</p>
<p><b>○ 김영복 위원 </b> 여러분들이 정원도 제대로 모르고 구조조정 얘기나왔을 때 숫자도 줄이려는 것이라든가 아까 상임고문 같은 문제가 거론됐잖습니까?  감사자료에도 여러 가지 나오는데 자료를 정확히 해서 행정사무감사 자료를 챙겨주시기 바라고요.  다른 것은 몰라도 전체적인 인원에 대한 현원이라든가 방향은 아셔야지요.  그리고 정인영 위원님께서도 과제가 많다고 말씀하셨는데 본 위원이 행정사무감사 자료 전체를 파악하니까 정 위원님이 4.4건이라고 그러는데 총 업무에 대한 기본연구과제까지 다하면 196과제 아닙니까?  본 위원이 계산해 보니까 1인당 연구원들 숫자에 맞춰보니까 전체적으로 4.4과제가 아니라 6.5과제가 됩니다.  나름대로 과제에 대한 연구를 하시겠지만 과다한 과제를 소화해 낼 수 있을까?  그래서 나중에 수탁업무라든지 이런 연구과제 나온 것을 보면 현실성이 떨어진다, 그러니까 지역에 가서 확인까지 하고 그래야 하는데 사실 워낙 업무가 많다 보니까 박사님들이 내려가기 쉽지 않지 않습니까?  가까우면 괜찮은데 멀면 나가면 하루종일 걸리고 그래서 앞으로는 이런 것을 재조정할, 이철규 연구원장님께서도 말씀하셨지만 인원을 아예 늘릴 계획을 가지고 장기적으로 계획을 하든가 질적으로 우리나라 어느 연구단체 못지 않게 한 과제가 나와도 경기도의 비전, 나라에 대한 비전을 제시할 수 있는 쪽으로 가야 되지 않느냐라고 본 위원도 봅니다.  그것은 꼭 연구를 통해서 해주시기 바라고요.
</p>
<p style="padding-left:1.2em">  그리고 먼저도 지적을 했습니다만 인원에서 관리직 계통에 계신 분들은 현원이 다 차있습니다.  그런데 항상 행정사무감사 자료에 보면 앞으로 계획이 나와 있던데 여태까지 연구하시면서 나름대로 앞으로 뽑을 인원이 환경이라든가 상·하수도 등 이런 꼭 필요한 연구진이 있는데 자격이 안돼서 못했다고 하는데 자격이 안된 것은 정말 그분에 대한 실력이 안돼서 안된 것인지 경기개발연구원에서 나름대로 연구진에 대해서 보수문제하고 실력하고 차이, 뽑을 적에 보수문제 때문에 그런 것인지 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 김영복 위원님 감사합니다.  우선 과제숫자와 관련해서 위원님들이 여러 숫자를 지금 예시하고 계시는데 제가 정확한 숫자를 말씀드리겠습니다.  우선 연구과제를 얘기할 때는 저희들은 정기간행물 발간사업이라든지 번역사업이나 정책세미나 이런 것은 과제숫자에 일단 포함시키지 않고 있습니다.  그래서 과제숫자를 꼬집어서 얘기할 때는 기본연구과제, 정책연구과제,  수탁연구과제, 위탁연구과제 그리고 지역연구과제, 협약연구과제 이렇게 여섯 가지만을 얘기합니다.  이렇게 봤을 때에 금년도 연구과제수는 132개 과제가 됩니다.  그래서 30명의 연구진들이 이를 수행하게 되면 1인당 4건 이상의 연구를 하게 되는 셈이 되겠습니다.
</p>
<p style="padding-left:1.2em">  그리고 두 번째로 김 위원님께서 연구진을 충원하지 못한 이유가 저희들이 제시하는 기준에 못 미쳐서냐, 아니면 저희들이 제시하는 보수가 그들에게 적절하지 않아서 그랬던 것이냐는 질의를 주셨습니다.  물론 내심으로는 보수에 대해서 불만이 없을 수 없겠지만 외부적으로 표현되는 것은 보수 때문에 불응하는 것은 아닌 것으로 생각합니다.  저희들이 자체적으로 불합격결정을 내렸던 것입니다.  저희들이 합격결정을 내렸는데 본인들이 보수 때문에 불응한 예는 한 건도 없었습니다.  다만 저희들이 생각할 때에 우리 연구진의 질을 향상시키기 위해서는 지나치게 보수를 낮게 제시한 것만이 능사가 아니라고 생각합니다.  앞으로 보다 질높은 연구진을 충원하기 위해서 보수를 경우에 따라서 지렛대로 활용하는 방법도 강구해야 하는 것 아닌가 생각합니다. 
</p>
<p><b>○ 김영복 위원 </b> 본 위원도 좀전에 말씀드렸지만 연구원분들이 정말로 거기에 열중해서 일할 수 있도록 보수를 더 드리더라도 질적 향상을 시킬 수 있는 방안을 모색해 주시고요.  그렇다면 채용을 하려고 했는데 안됐던 분야가, 앞으로 충원될 계획을 갖고 있는 인원이 여덟 분으로 알고 있는데 행정분야, 환경, 교통, 경제, 복지, 관광, 교육, 도시계획분야가 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네, 그렇습니다.
</p>
<p><b>○ 김영복 위원 </b> 이 분야에서 없었다는 얘기인지 아니면 다른 쪽에서 얘기하신 건지 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 지난번에 못 뽑은 것 말씀이십니까? 
</p>
<p><b>○ 김영복 위원 </b> 네.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 지난번에 못 뽑은 것은 12명을 모집하려고 하다가 7명밖에 모집을 못했는데요.  그때 모집 못한 5개 분야는 환경, 교통, 경제, 복지, 관광 이렇게 되는 것으로 파악되고 있습니다. 
</p>
<p><b>○ 김영복 위원 </b> 그렇다면 나름대로 설립된 지 7년이 됐기 때문에 앞으로 인력충원계획에 이제는 경력자보다는 우수한 신규 박사인력이 조직운영에 더 효율적이라고 해서 행정사무감사 자료에 줬거든요.  그러면 아까 원장님이 말씀하신 것하고 앞으로 신규박사라든가 이런 분들을 채용할 계획이라고 여기 나온 것하고 답변이 틀리신 데, 질적으로는 아까 말씀하시기를 외국에서라도 더 채용한다고 하셨는데 행정사무감사 자료하고 틀리거든요.  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 아닙니다.  외국에서 우수한 박사를 초빙한다 하더라도 신규박사 중심으로 할 계획입니다.  지금 30대후반, 40대초반 박사님들이 많이 모여있습니다.  앞으로 연구원이 계속 발전할수록 일부 연령대에 집중된 연구원들이 모여있는 것은 조직의 활력을 위해서 경우에 따라서 바람직하지 않을 수 있다고 생각합니다.  그렇기 때문에 앞으로 새로 모집하는 연구진들은 연령대가 중복되지 않는 방향에서 모집하는 것이 바람직하지 않을까 저희들은 그렇게 생각하고 있습니다.
</p>
<p><b>○ 김영복 위원 </b> 본 위원이 행정사무감사 자료 313쪽에 보면 신규박사들이 2003년 2월에 맞춰서 거의 많이 배출되기 때문에 그런 인력계획이 있다라고 자료에 나와서 말씀드린 거고요.  나름대로 계획을 세워주시고, 그 다음에 지방자치단체장이 바뀔 때마다 어떤 인사문제가 애매하게 걸려있는 사항인데 행정사무감사자료 347쪽 임·직원 채용실적에 보면 연구원분들은 공채로 했지만 다른 분들은 특채로 들어오거든요.  그런데 잘 아시겠습니다만 지방자치단체장이 바뀔 때마다 의지에 따라서 측근이라고 하는 분들이 그때 당시부터 비전을 제시하고 지사가 공약이라든지 이런 것을 했기 때문에 그 당시부터 비전을 제시하고 지사가 공약했기 때문에 들어오리라 보는데 원장님이 오신 지 얼마 안됐지만 사실 연구원분들이 어떤 과제가 잘 나오게끔 보좌를 옆에서 해줘야 될 분들이 특채로 들어오는 것으로 알고 있습니다.  그런 사항에서 과연 그때그때 시기에 따라서, 지방자치단체장이 바뀔 때마다 특채로 들어오는 게 나은지, 아니면 경험을 통해서 계속 축적해 가면서 경기개발연구원을 좋은 원장님이 관리해야 되는지 본인이 대답하시기 힘들겠지만 말씀해 주시기 바랍니다.  또 들어오시는 분들에 따라서 연구원분들의 연구과제도 틀리게 나올 수 있는 부분도 있겠지요.  지사의 정책이라든가 갖고 있는 생각, 입장 차원에서 간략히 나름대로 말씀하실 수 있는 것만 해주세요.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 어차피 제 소신을 물어보신 것 같은데 소신껏 답변드리겠습니다.  특채로 들어온 직원들이 모두 원장 아니면 사무처장의 경우입니다.  그러나 원장이나 사무처장이 공채가 가장 바람직하냐, 그것은 별개의 문제라고 생각합니다.  지금 도의 경우에도 일부 산하기관은 공채로 채용하는 경우가 있습니다.  그러나 공채가 외형상으로는 굉장히 바람직해 보이지만 그런 공채방법을 꺼려하기 때문에 응모하지 않는 많은 좋은 자원들이 있을 수 있다고 생각합니다.  그래서 적절한 인재를 채용하는 방법으로 고위직의 경우에는 공채와 특채를 융통성있게 활용하는 지혜가 필요하다고 생각합니다.
</p>
<p style="padding-left:1.2em">  그리고 저희 연구원의 경우에는 원장이나 사무처장이 임기가 있는데도 불구하고 지사가 바뀌면 바뀌는 사태가 종종 벌어지고 있는 데 대해서, 물론 인사의 예측가능성을 해친다는 측면에서 바람직하지 않은 측면이 분명히 있고 연구원의 지속적인 안정성 측면에서 바람직하지 않은 측면이 분명히 있다고 생각합니다.  다만 KRI가 어차피 도의 도정시책을 지원하는 입장에 있기 때문에 도지사와 함께 철학을 같이 하는 기관장이 연구원을 끌어가는 것도 경우에 따라서는 바람직하지 않을까 그런 생각도 듭니다.  그래서 저는 연구원장 자리가 과연 임기가 꼭 필요한 자리인지에 대해서는 별도의 검토가 필요하다고 생각하고 있습니다.
</p>
<p><b>○ 김영복 위원 </b> 대답하기 힘든 것을 원장님이 말씀하셨는데 본 위원도 개인적으로는 그런 생각을 하고 있습니다.  앞으로는 연구원이 지속적으로 경기도의 비전을 제시하는 쪽으로 가야 되지 않느냐고 생각하고, 그래야만 연구하시는 분들도 나름대로 본연의 주관을 가지고 방향을 제시하지 않을까 해서 질의드렸고요.
</p>
<p style="padding-left:1.2em">  지금 연구과제 수탁을 주는데, 사실 기본은 경기도의 정책비전을 제시하기 위해서는 여러 가지 업무가 많은데 우선적으로 경기도의 과제를 우선 해야 되지 않습니까?  그런데 시·군이라든가 다른 데서 수탁업무가 많이 들어오고 있는 것 같은데 그렇게 들어왔을 때 과제가 많아서 못 받은 적이 있는지 말씀해 주십시오.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 과제가 많아서 못 받은 경우는 없는 것으로 알고 있습니다.  다만 시·군에서 요청하는 과제들을 저희들 나름대로 자체심의를 해서 이 연구를 우리가 할 필요가 있는 것인가, 우리 연구원 성격에 맞는 것인가 하는 것에 대한 검토는 합니다.  너무 기술적이고 실무적인 연구라면 시·군과 상의해서 "이것은 저희들보다는 다른 연구기관이 적절하겠습니다" 하고 협의를 해 나가는 경우는 종종 있습니다. 
</p>
<p><b>○ 김영복 위원 </b> 마지막으로 아까 말씀드린 대로 업무가 워낙 많으니까 앞으로는 그런 것을 조정해서 현장조사 부분에서도 미진함이 없고 좋은 자료가 나오도록 연구를 해주시고요.  그래야 연구주신 분들도 그만큼 기대효과가 있으리라 봅니다.  항상 실효성있는 연구수행이 되도록 하고, 특히 경기개발연구원은 사실 경기도의 싱크탱크 아닙니까?  지금 지사가 세계화를 부르짖고 있는 가운데 일하는데 지장이 없도록 장기적인 경기도의 비전안목을 제시해 주시기 바라겠습니다.  이상입니다.
</p>
<p><b>○ 위원장대리 이원재 </b> 보충질의 있으신 분, 나경숙 위원님.
</p>
<p><b>○ 나경숙 위원 </b> 나경숙 위원입니다.  김영복 위원님께서 인력보강에 대해서 말씀하셨는데 연구원 정관 제25조에 보면 부원장을 두도록 되어 있는데 현재 부원장이 공석이지요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네.
</p>
<p><b>○ 나경숙 위원 </b> 부원장을 임명하지 않은 구체적인 사유와 임용계획 그리고 임용자격요건이 어떤 것인지 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 부원장 임용계획은 현재로서는 없습니다.  나중에 연구원의 볼륨이 커진다든지 필요성이 인정되면 별도로 검토하도록 하겠습니다.  임용자격은 별도로 정해진 게 없습니다. 
</p>
<p><b>○ 나경숙 위원 </b> 그러면 원장님 외유시에는 누가 담당하십니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 연구원 직제에 의하면 기획조정실장과 사무처장이 대행하도록 되어 있습니다.
</p>
<p><b>○ 나경숙 위원 </b> 알겠습니다. 
</p>
<p><b>○ 정인영 위원 </b> 보충질의 하나만 더 하겠어요.
</p>
<p><b>○ 위원장대리 이원재 </b> 정인영 위원님.
</p>
<p><b>○ 정인영 위원 </b> 연구진 임용과 관련해서 연령대별로 임용을 해 가지고 조직의 활성화를 기한다고 답변하셨는데 본 위원이 생각하기에는 연령은 별 의미가 없고 연구진의 전공이 어떻게 고르게 분포되어 있는 게 중요하다고 생각하는데 현재 분포되어 있는 연구진의 전공과 앞으로 채용하고자 하는 연구진의 연구분야를 답변해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 정 위원님 말씀이 전적으로 맞습니다.  저희들이 연구분야를 도외시하고 연령대를 분산시켜서 모집하겠다는 뜻은 결코 아닙니다.  전공분야에 필요한 사람을 찾다가 못 찾으면 연령대가 중복되더라도 그것은 피할 수 없고 그렇게 해 나가야 될 것입니다.  다만 같은 경우라면 연령대의 분산이 바람직하다는 뜻으로 말씀드린 겁니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 보충질의 없습니까?  김대원 위원 보충질의 해주시기 바랍니다.
</p>
<p><b>○ 김대원 위원 </b> 보충질의 하겠습니다.  기구 및 인력에 보면 1실 1처 7부로 되어 있지 않습니까?  그런데 기획조정실에 대한 7부 중 도시환경자문팀의 성격이 어떤 겁니까?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 도시환경자문팀은 솔직히 말씀드려서 저희 연구원의 필요에 의해서 생겼다기보다는 도의 필요에 의해서 만들어진 조직입니다.  그렇기 때문에 그러한 내용이 지난번 감사원감사에서도 지적된 바 있습니다.  앞으로 그 조직을 감사원 지적에 맞게 운영하는 방법은 도에서 도시환경자문팀의 운영에 필요한 예산을 별도로 지원해서 도의 업무를 수행시키는 방법이 타당하다고 결론이 났습니다.  그 조직은 그대로 유지하되 예산은 우리 연구원의 예산이 아니라 도의 예산으로 내년부터는 운영할 계획으로 있습니다.
</p>
<p><b>○ 김대원 위원 </b> 그러면 연결되니까 다른 발언까지 계속 하겠습니다.  사업보고서 37쪽에 보면 도시환경자문팀의 운영이라고 해서 사업운영의 성격이 명시되어 있습니다.  경기도를 중심으로 수도권에서 급격하게 광역화 및 교외화 현상이 발생하고 있어 토지이용계획 등에 대한 전문적인 정책방향 제시의 필요성이 증대하고 있으므로 도시계획과 관련한 시·군의 계획수립 부분으로 자문팀의 운영 성격을 표명하셨습니다.  왜 이런 지적을 하는가 하면 6부의 운영이 도시경영, 도시·지역, 환경연구부라는 별도의 부가 현재 유지하고 있지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네.
</p>
<p><b>○ 김대원 위원 </b> 그런데 업무분장의 중복성이 있는 부분을 옥상옥적인 성격으로 따로 만들어서 운영하는 것은 기본에서 맞지 않는 것 아니예요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 지금 어디하고 중복된다는 말씀이시지요?
</p>
<p><b>○ 김대원 위원 </b> 도시경영, 도시·지역계획, 환경…….
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그런 데와 중복되지 않습니다.  도시경영은 물론이거니와 도시·지역계획과도 중복되지 않습니다.  도시환경자문팀은 어디까지나 도에 제출된 각 시·군의 도시계획안을 검토하는 것이 본연의 임무입니다. 
</p>
<p><b>○ 김대원 위원 </b> 그러면 일반연구원들 중에서 현재 각 시·군의 도시계획위원회 위원으로 위촉된 분들이 상당히 망라되어 있지요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김대원 위원 </b> 그런 분들의 임무와도 중복되는 것 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그렇게 철저하게 말씀하시면 중복이 안 된다고 말할 수 없겠습니다만 연구진들이 각 시·군의 도시계획위원으로 참여하는 것은 어디까지나 자문역으로 참여하는 것이고 도시환경자문팀이 별도조직으로 존재하는 것은 자문을, 원래는 도시계획이 도에 제출되면 도의 도시계획담당자들이 검토하는 것이 정상이겠습니다만 도시계획 담당직원들의 숫자나 구성이 방대한 시·군 도시계획업무를 전문적으로 검토하기에는 미진하기 때문에 별도의 전문가들을 순전히 도시계획분석 목적으로 활용하고 있는 것이고 이러한 것은 도시계획법에 의해서 각 시·도별로 도시계획자문팀을 상설로 두도록 되어 있습니다. 
</p>
<p><b>○ 김대원 위원 </b> 그러면 이 팀의 팀장이 어떤 분이세요?  팀장 및 구성원이 어떻게 구성되어 있습니까?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 지금은 4명의 팀원으로만 구성되어 있습니다.  그 중에 선임자가 팀장역할을 하고 있습니다. 
</p>
<p><b>○ 김대원 위원 </b> 제가 이 얘기까지는 안 하려고 했는데 하겠습니다.  보통 연구과제 선정에서부터 운영에 대한 협의를 도, 도의회와 협의해서 하신다고 방침이 되어 있지요?
