<p><b>○ 김대원 위원 </b> 제가 요구한 자료에 의하면 연구원 청사외 사무실 임대현황을 자료요구를 했습니다.  그런데 결론은 외팀이 지금 말한 바로 이 팀입니다.  도시환경자문팀이 2002년 9월 26일부터 1년간 장안구 정자동에 별도 사무실을 임대해서 현재 5명으로 구성돼서 예산을 약 1억원 정도를 소요하면서 운영하고 있지요?  자료에는 그렇게 되어 있는데.
