<p><b>○ 경기개발연구원장 이철규 </b> 네, 있습니다. 
</p>
<p><b>○ 김대원 위원 </b> 그러면 별개의 외청 성격의 자문팀이라고 방금 답변하셨는데 이런 팀을 구성해서 운영하실 때에는 협의를 해야 된다고 생각하지 않습니까?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 도하고 협의해서 했습니다.  이 자문팀이 이번에 구성된 것이 아니고 원래 구성이 되어 있습니다.
</p>
<p><b>○ 김대원 위원 </b> 저희 기획위원회에서 얼마 전 조례개정 해준 게 있습니다.  옛날 경기도정책위원회라는 부분을 경기발전위원회로 조례를, 경기도정책위원회를 폐지시키고 경기발전위원회를 만들어서 운영하겠다 그랬습니다.  경기발전위원회의 세부위원회에 보면 현재 도시환경자문팀이라는 기능이 포함되어 있습니다.  그러니까 각 시·군 도시계획의 비전제시라든가 조정·자문할 수 있는 자문기구적인 성격의 또 소위원회가 구성되어 있는 것으로 기획관리실 감사에서 확인됐습니다. 
