<p><b>○ 경기개발연구원장 이철규 </b> 위원님!
</p>
<p><b>○ 김대원 위원 </b> 그런데 제가 말하고자 하는 것은 도와 협의했을 것 같으면 결과적으로 경기개발연구원은 기획위원회 소관부서로 알고 있습니다.  그래서 저희들이 감사를 나와 있고요.  지금 설치된 것 아니예요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 아닙니다.  작년 12월 24일에 설치된 겁니다.  아니, 죄송합니다.  12월 31일에 설치된 겁니다. 
</p>
<p><b>○ 김대원 위원 </b> 그런데 저한테 낸 자료 223페이지를 보십시오.  장안구 정자동에 면적 61평에 전용면적 43평짜리 사무실을 임대해서 나갔지 않습니까?  이 시기를 얘기하는 겁니다.  내부적으로 포함됐을 때는 관계없다는 얘기예요.  경기개발연구원에서 나갔다는 타당성을 설명했다든가, 9월 26일에 외청을 임대해서 나간 상황이면 도와 협의하셨다고 했는데…….
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 아닙니다.  전에는 안양 쪽에 사무실이 있었습니다.  원래 같이 있는 것이 바람직한데 본원의 스페이스가 워낙 좁기 때문에 안양 쪽에 별도 사무실을 얻어서 있었습니다.  그런데 안양 쪽에 사무실을 폐쇄하면서 도청에 가까운 정자동 쪽에 사무실을 새로 임대한 것입니다.  별개로 떼어나간 것입니다.
</p>
<p><b>○ 김대원 위원 </b> 그러면 작년 12월에 구성돼서 사무실을 안양에 개소해서 운영하다가 10개월 정도 지난 9월말쯤에 이쪽으로 옮겼다는 얘기지요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그렇습니다. 
</p>
<p><b>○ 김대원 위원 </b> 제 생각은 그렇습니다.  원장님 답변 중에 예산도 도에서 부담해야 되고 도에서 관리해야 될 성격의 부서인데 경기개발연구원에 더부살이 형식으로 붙어있었다는 것이지요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 표현은 그렇습니다만 비슷한 말씀입니다. 
</p>
<p><b>○ 김대원 위원 </b> 글쎄 이런 부분을 운영할 것 같으면, 저는 자료를 보고 개인적으로는 기분이 별로 썩 유쾌하지 못했던 부분은 말로나 형식적으로는 도와 의회에 협의를 해서 정책과제부터 경기개발연구원 운영부분에서도 협의하는 것으로 저희들은 그렇게 생각하고 있었습니다.  그런데 약 1억원 정도의 예산이 소요돼서 사무실을 별개로 만들 정도면 협의가 충분히 있어야 하지 않느냐는 게 첫 번째 유쾌하지 못했던 부분이고, 두 번째 부분은 제가 보기에는 글자 그대로 도시환경자문팀이라는 팀 자체가 업무분장에 유사성이 있다는 거예요.  이름도 그렇지 않습니까?  도시·지역개발, 환경팀 다 있는데 도시환경팀이라니까 이름 자체에서도 어떻게 믹스해 놓은 부분이지 않느냐고 생각하고 그리고 직위표에 기획조정실 사이에 도시환경팀이라 해서 별개 팀으로 되어 있어요.  실질적으로는 연구부서가 6부밖에 없습니다.  연구원도 6부 중심의 연구인원이 구성되어 있지 않습니까?  그런데 이 팀은 실체도 없는 팀이라고 봐도 됩니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 제가 다시 정리해서 답변올리겠습니다.  도시환경자문팀은 김 위원님 지적하신 대로 바람직한 방향으로 또는 조직의 원리에 맞게 만들어진 것은 아니라고 생각합니다.  그것이 조직의 원리에 맞게 만들어지기 위해서는 도시환경자문팀이 아니라 도시계획상설기획단으로 도청 안에 설치되어야 합니다.  그런데 아직 경기도는 도시계획상설기획단을 발족하지 못하고 있습니다.  그러나 도시계획업무는 계속 증가일로에 있습니다.  이것을 연구하다가 경기개발연구원의 도움을 받아서 일단 업무를 시작하게 하는 방법이 뭐가 있겠느냐 해서 임시적인 방법으로 추진하는 것으로 알고 있습니다.  그래서 명칭도 유사성이 있는 것 같기도 하지만 본질적으로는 도 도시계획과 산하의 도시계획상설기획단 업무를 하는 것으로 이해해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 아까 김 위원님께서 경기발전위원회조례에도 이러한 기능이 나와 있다라고 말씀하셨는데 그것은 상설기획단의 업무와 똑같다기보다는 거기에 나와 있는 상임위원회는 그야말로 자문적인 성격을 띠는 것이기 때문에 여기서 일하는 것처럼 전문가 집단들이 일하는 것과는 성격이 다릅니다. 
</p>
<p><b>○ 김대원 위원 </b> 구체적으로 묻겠습니다.  여기 도시계획자문팀이 정원에 포함됩니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 이 사람들은 초빙연구원들로 보임받고 있습니다. 
</p>
<p><b>○ 김대원 위원 </b> 그러니까 정원에 포함 안되어 있는 팀이지요?
