<p><b>○ 경기개발연구원장 이철규 </b> 비정규직 정원입니다. 
</p>
<p><b>○ 김대원 위원 </b> 그런데 기획조정실에 1실 1처 7부로 되어 있는데 7부의 한 팀으로 자료를 제출하셨지 않습니까?  그러면 결론은 정원외 팀은 부가 아니지요, 그렇지 않습니까?  그리고 팀장도 없다고 하는데 자료에 보면 5명이 운영하는 것으로 되어 있습니다.  지금 답변은 4명의 위탁연구원들이 연구하고 계신다고 했는데 이런 부분은, 그러면 자료로 도시환경자문팀의 팀원과 지금까지 도시환경자문팀이 했던 성과부분을 제시해 주시고요.  기구외적 부분을 기구로서 안고 갔을 때는 정말 내 식구로 만들고 과제를 줘서 충분히 활용할 수 있도록 해야 될 부분이고, 아닐 것 같으면 과감하게 폐지시켜야 됩니다.  그리고 아까 도시계획 부분을 말씀하셨는데 정원이 도시계획 부분에 과중하므로 얼마 전에 신도시개발팀이라고 해서 정식공무원 14명이 증원됐습니다.  신도시개발팀은 서기관 1명을 기준으로 해서 14명의 정상적인 팀으로 구성되어 있습니다.  정말 학술적으로 자문해 줄 수 있는 부서라면 이런 팀을 정상적인 부분에 포함시켜서 할 수 있고 기능이 중복된다면 과감하게 폐쇄시키든가 이런 부분으로 운영해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 김 위원님 뜻을 이해하고 상세한 내용은 서면으로 자료제출 하겠습니다. 
</p>
<p><b>○ 김대원 위원 </b> 알겠습니다.  이상입니다. 
