<p><b>○ 위원장대리 이원재 </b> 다음 질의하실 분, 김준회 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김준회 위원 </b> 김준회 위원입니다.  제가 질의하고자 하는 내용은 감사자료 187페이지 육성기금 운용현황에 대해서 질의하고자 합니다.  내용을 보면 예치율이 다 다르고 만기일이 다르다 보니까 이런 현상이 있는지 모르겠는데 4개 은행의 이자율을 보면 들쭉날쭉 해요.  7.11%가 있는가 하면 5.05%도 있고, 이런 부분에 대해서 만기일이 남았기 때문에 고율로 예치할 수 없는지요?  또 같은 은행에도 이렇게 금리차이가 나는 것은 왜 이런지 저로서는 이해가 안가고, 금년 9월 27일에 예치한 한미은행 알뜰분리과세신탁에 10억원이 실적배당이라고 연이율이 나왔는데 이것에 대한 것을 구체적으로 일단 설명해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 저희들도 김 위원님 말씀대로 육성기금을 어떻게 하면 보다 효율적으로 한 푼이라도 증식해 나갈 수 있을 것인가에 대해서 항상 걱정하고 있고 노심초사하고 있습니다.  다만 기금의 성격상 저희들이 적극적으로 관리하지 아니하고 금융기관만을 상대로 소극적으로 관리하고 보수적으로 관리한다는 것이 저희들로서는 안타까운 점으로 있습니다.  여하간에 안정성을 최우선으로 하다 보니까 제1금융권을 저희들이 거래하게 됩니다.  그런데 유감스럽게도 제1금융권의 금리가 거의 매일 하락하고 있습니다.  그래서 만기가 도래하면 가장 금리가 높은 곳으로 찾아서 옮겨다니는데 그때그때마다 금리가 달라지고 있습니다.  그래서 나중에 예금을 한 상품일수록 금리가 낮아집니다.  옮겨다니면 옮겨다닐수록 금리가 점점 낮아지고 있습니다.  그렇기 때문에 금리가 들쭉날쭉하다는 것을 이해해 주시기 바라고, 연도별로 보시더라도 연도가 지날수록 ''99년보다 2000년, 2000년보다 2001년, 2001년보다 2002년의 이자수입이 낮아지고 있습니다.  이런 것은 시중금리의 지속적인 하락현상에 기인하고 있고 금리가 항상 고정적이 아니고 매일매일 달라지고 있는데 기인하고 있다는 것을 이해해 주시기 바랍니다.
</p>
<p><b>○ 김준회 위원 </b> 한미은행에 알뜰분리과세신탁 종류에 실적배당이라고 있는데 그러면 10억원에 대한 것을 그 은행 자체에서 운용해서 실적을 배당한다는 얘기입니까?  내용이 어떤 내용입니까?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 이해해 주시면 재정과장이 말씀드리겠습니다. 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 재정지원과장 강윤구입니다.  실적배당상품은 투자신탁상품으로서 만기일이 도래되면 만기일에 펀드의 총수익률을 가지고 실적을 배당하는 상품으로서 정기예금 금리보다 통산 0.7% 높은 상품입니다. 
</p>
<p><b>○ 김준회 위원 </b> 알겠습니다.  다음 질의드리겠습니다.  경기개발연구원 직원현황 자료를 받았는데 여기 보면 임용기간이 들쭉날쭉합니다.  1년이 있는가 하면 1년 4개월도 있고 3년도 나타나고 있습니다.  왜 이런 근거가 나왔는지 그것에 대한 설명을 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 연구직의 경우에 말씀하시는 겁니까? 
</p>
<p><b>○ 김준회 위원 </b> 연구직도 그렇습니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 관리직은 계약직이 아니기 때문에 임용된 날로부터 근무기간을 따지는 거고요.  연구직의 경우는 계약직이기 때문에 계약기간이 만료되면 새로 갱신계약을 맺고 새로 임명이 됩니다.  계약날짜에 따라서 임용시기나 임용기간이 달라질 수 있습니다. 
</p>
<p><b>○ 김준회 위원 </b> 임용기간이 어떤 조례나 이런 것에 있습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 임용기간은 1년 단위로 재계약을 하고 있습니다.  
</p>
<p><b>○ 김준회 위원 </b> 도시·지역계획부, 교통정책연구부, 도시경영연구부는 여기 계신 분만 보더라도 임용기간이 1년, 2년 또 원장님 같은 경우에는 3년, 딱 3년은 아니더라도 2년 4개월인가 나와있습니다.  이런 부분이 어떤 조례에 의해서 그러는지 아니면 임용권자가 임의로 그때그때 결정하는지요.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그러니까 결원이 생기면 연구직을 새로 충원하지 않습니까?  충원한 날로부터 그 사람은 1년 단위로 계약을 맺어서 임용이 되는데 어떤 분은 그렇게 계약을 두 번 계약, 세 번 계약을 맺으면서 임용기간이 3년, 4년 늘어날 수도 있고 최근에 임용되신 분은 아직 재계약을 안 맺은 상태에서 몇 개월 단위로 있을 수 있고, 그러니까 처음에 여기 임용된 날짜가 다르기 때문에 어차피 다를 수밖에 없습니다. 
</p>
<p><b>○ 김준회 위원 </b> 알겠습니다.  다른 질의드리겠습니다.  지금 인적 사항을 볼 적에 연구직 임원에 박사가 26분이 되는데 아까 나경숙 위원이나 다른 두 분 위원님께서 지적했습니다만 수탁용역사업 수입이 너무나 저조하다는 생각이 들어요.  1년에 도에서 지원되는 도비보조가 약 67%, 약 60억원 정도를 지원받는데 이런 인력이나 도에서 지원받는 규모에 비해서 수탁용역사업비가 예산의 4.4%에 불과한 거고 그리고 아까도 나 위원님께서 지적했습니다만 외부에 용역을 준다는 것은 제가 생각이 부족한지 모르지만 뭔가 아쉬운 부분이 있습니다.  지원받는 도비보조나 박사분이 26분이나 되는데 왜 외부에 줘야 되는지, 여러 가지 형평이 맞지 않은 아쉬운 부분이 있는데 그런 부분에 대해서 답변해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 수탁용역사업 수입이 적은 것은 사실입니다.  그런데 수탁용역사업을 늘리는 것도 저희로서는 한계가 있습니다.  저희들은 이미 위원님들께서 이해하고 계시는 것처럼 공공연구기관이지 않습니까?  그러다 보니까 기업체에서 요청하는 수탁과제들은 저희들이 받아들일 수가 없는 한계가 있지요.  도나 시·군의 수탁과제들만 저희들이 받아들이다 보니까 수탁과제가 제한적일 수밖에 없다는 아쉬움이 있고요.  다만 저희들이 앞으로 도나 시·군과 보다 긴밀한 유대관계를 맺으면서 적극적으로 수주활동을 벌이면서 도나 시·군의 과제들이 저희들 연구기관이 아닌 다른 연구기관으로 발주되는 것을 최소화시켜 나갈 책임과 의무가 있다고 생각합니다.  그런 점에서 더욱더 열심히 노력하겠습니다. 
</p>
<p><b>○ 김준회 위원 </b> 그래서 본 위원이 바라는 것은 ''95년도에 경기개발연구원이 개원됐기 때문에 8년 가까운 세월이 흘렀으니 재원에 대해서도 자급자족하는 형태로 많이 해주셨으면 하는 바람으로 말씀을 드리는 겁니다.  이만 마치겠습니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 노력하겠습니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 회의도중 좀전에 김영복 위원께서 저에게 정회를 요청한 바 있습니다.  잠깐 5분 동안 정회하고자 하는데 여러 위원님들 어떻습니까?
</p>
<p style="padding-left:2.4em">    (「좋습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  우선 이효선 위원께서 먼저 질의 한 건만 하고 정회를 하도록 하겠습니다.  
</p>
<p><b>○ 이효선 위원 </b> 식사시간이 다 됐는데 정회할 필요가 있나요?  
</p>
<p><b>○ 위원장대리 이원재 </b> 그러니까 이효선 위원 먼저 질의해 주세요.
</p>
<p><b>○ 이효선 위원 </b> 몇 가지만 질의하겠습니다.  목 수술로 목이 불편해서 죄송하게 생각하고요.  먼저 기금관리에 있어서 전에 10월에 지적했습니다.  신한은행 만리동지점은 경기도가 아니거든요.  금리가 높은 것은 만기일이 2008년 장기이기 때문에 그렇습니다.  같은 상품이 신한은행 수원지점이나 안양지점, 광명지점이 있을 수 있습니다.  이것을 지적했는데 여기에 대한 아무런 조치가 없어요.  주인의식이 없는 이런 사고가 경기개발연구원의 한계라고 봅니다.  그때 지적했을 때 바로 후속조치를 했으면 큰 문제가 없는데 여기에 대한 답변을 저는 못 들었습니다.  그리고 그 당시 6억원이면 7월에 이전을 했으나 한 달밖에 안됐을 때고 원장님이 안 계실 때입니다.  오지 않았을 때 얘기니까 원장님 말고 다른 사람이 답변해 주세요.  
</p>
<p><b>○ 재정지원과장 강윤구 </b> 재정지원과장 강윤구입니다.  위원님께서 질의하신 내용에 대해서 답변올리겠습니다.  저희가 먼저 지적해 주신 당시에 바로 관리처를 신한은행 수원지점으로 옮기고자 협의를 하였으나 후순위채권의 관리가 이쪽으로 이전이 안되기 때문에 바꾸지 못하였고요.  만리동지점에서 후순위채권을 사게 된 경위를 말씀드리면 사실 1, 2순위의 시중은행들은 후순위채권 발매가 되면 통산 하루나 1시간 이내에 매진되는 사태가 있습니다.  사실 사고 싶어도 살 수가 없는 경우가 대부분입니다.  그래서 만리동지점장이 본사의 후순위팀과 긴밀히 관계를 맺고 있어서 일시에 사줄 수 있는 여력이 있었기 때문에 사게 됐습니다.  그런 점은 이해해 주시기 바랍니다.  5분만에 매진되기 때문에 저희가 그것을 사고 싶어도 살 수가 없습니다. 
</p>
<p><b>○ 이효선 위원 </b> 알겠습니다.  답변이 된 것 같은데 이렇게 말씀드릴게요.  경기개발연구원은 이자를 따지는데 주목적인 연구소가 아닙니다.  그렇다면 후순위채권이 아닌 다른 방법의 채권이라도 고금리가 있으면 제주도고 강원도고 쫓아가겠습니까?  이런 것들은 바로 뭘 의미하냐면 나의 위치는 뭐고 나는 무엇을 할 것이며 행위에 대한 결과가 뭔지를 분석하지 못한 가벼운, 돈 몇 푼에 목적을 잃어버린 것 같습니다.  됐고요.  두 번째는 번역사업을 하는데 책이 3권입니까, 3개종에 몇 십권입니까?  여기 자료에 보면 36페이지에 있습니다.  추진방향이 있고 사업량이 있습니다.  ''적실성 있는 3종 번역''으로 돼 있습니다.  책이 몇 권입니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 3권입니다. 
</p>
<p><b>○ 이효선 위원 </b> 책 3권에 3,630만원을 지출하십니까?  업무 아시는 분이 답변하세요.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기획조정실장 이상훈입니다.  3종의 번역은 책이 3권입니다.  3권에 3,600만원이 지급이 됐는데 이 부분은 번역료가 있고 그 다음 번역을 해서 인쇄비가 들어갑니다.  경우에 따라서는 인세의 문제가 있습니다.  저작권 문제가 있어 경우에 따라서 협약을 맺어서 번역을 하고 있습니다.  그래서 책이 3권에 3,630만원이라고 말씀드리겠습니다. 
</p>
<p><b>○ 이효선 위원 </b> 그러면 이것을 일반시판을 목적으로 번역합니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 특히 번역서의 경우는 저작권 문제로 아직까지는 시판할 목적으로 번역을 안 했고요. 
</p>
<p><b>○ 이효선 위원 </b> 그렇다면 번역료는 문제가 안됩니다.  왜냐하면 원서를 볼 때 원서 자체를 머리에 습득하고 그것으로 연구목적을 발표한다는 것이지 그것을 번역해서 일반 시판하지 않는 한 큰 문제는 안 된다고 봅니다.  그리고 여기는 박사들이 많이 계신데 책 3권 번역에 3,600만원을 계상한 것이라면 문제가 되겠지만 그것을 번역해서 팔지 않고 사업에 자료 몇 쪽, 몇 쪽 하면서 인용만 하면 되거든요.  번원을 인용하든 원문을 인용하든 번역에 토를 달든 이런 것들은 문제가 있습니다.  이런 데 너무 과다 편성됐다 이겁니다.  지적을 하는 거니까 하지 말아주시기 바랍니다.  번역해서 팔 것이 아니고 책으로 남길 것이 아니라면 그런 것들은 형식이거든요.  아무 종이에다가 아니면 개인의 PC를 때려서라도 중요한 데만 번역해서 그것을 인용해 결과물만 나오면 되지, 무슨 번역료를 따지십니까,  그렇지 않습니까?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 위원님, 생각을 달리 하는데요.  저희들이 기본과제연구를 하지 않습니까?  한 건당 4,000만원 정도 되는 그런 경우가 있거든요.  그 중에 발간비가 보통 경우에도 800만원 이렇게 됩니다.  
</p>
<p><b>○ 이효선 위원 </b> 발간 안 하면 되잖아요.  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 연구를 했는데 연구한 것을 책으로 발간을 해야죠.  
</p>
<p><b>○ 이효선 위원 </b> 연구한 것을 발간하는 것은 좋은데 자료로 쓸 도서를 발간할 필요는 없잖아요.  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그런데 저 책이 저희들이 볼 때는 나름대로 책으로서의 가치가 있다고 보는 겁니다.  저것을 빨리 번역해서 우리 연구진들은 물론이거니와 관련되시는 분들한테도 정보제공을 해주는 것이 바람직하다고 생각되는 책들이거든요.
</p>
<p><b>○ 이효선 위원 </b> 알겠습니다.  전문적이 아니고 일반적 상식을 갖고 지적했습니다.  조금 디테일한 것을 질의하겠습니다.  원장님이나 사무처장 임용에 대한 문제인데요.  전직 유지준 처장이 10월 1일부로 관두었습니다.  그렇죠?  그 기준이 무엇입니까?  이것은 관훈토론회에서 나왔던 질의사항입니다.  원장님 임용문제도 나왔는데 도지사가 말씀하시기를 도지사 임기와 맞추면 큰 문제가 없겠다라는 이야기가 나왔습니다.  유지준 처장이 관둔 배경은 뭡니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 본인의 사직의사에 의해서 그만 두었습니다. 
</p>
<p><b>○ 이효선 위원 </b> 그것은 거짓말 같고요.  제가 알기로는 그것은 아닌 것 같습니다.  관둔 것에 대해서는 동의합니다.  그리고 임용부분이 임창열 지사 때 들어왔기 때문에 관둔 것에 대해서는 저는 정치적으로나 도의적으로나 동의하고 관둔 것에 대해서 잘 관두었다고 생각합니다.  그런데 새로운 김봉규 처장님의 임용배경은 뭡니까?  제가 알기로는 임창열 지사 때 공보관을 하셨고 손학규 지사 들어와서 공보관을 했습니다.  손학규 도지사 사람도 아닌데 임용이 됐습니다.  그 배경을 알고 싶습니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 원장이나 사무처장의 임용은 사람을 찾는 것은 아니고요.  어차피 그 조직을 이끌어 가는데 적임이냐, 아니냐를 중심으로 해서 판단하게 될 것입니다.  이번에 김봉규 사무처장을 임용한 배경도 그분의 그 동안의 경륜이나 또 우리 사무처가 요구하는 사무처장의 임용요건에 적임이라고 판단했기 때문에 임용한 것이고 앞으로 그런 점에서 충분히 우리 연구원에 도움이 되리라고 생각하고 있습니다. 
</p>
<p><b>○ 이효선 위원 </b> 기준이야 임용권자의 마음인데요.  여기는 싱크탱크들이 있는 곳입니다.  최소한 연구소에서 근무한 경력이 있던가, 임용기준을 보면 행정가로서의 10년이상 경력이나 임용기준을 보면 부교수로 되어 있습니다.  부교수 정도의 임용기준은 맞춰줘야 사무처장 자리에 맞지 않습니까?  최소한 행정을 6년이상 했어야 하는데 기자를 했었고 공보관이 다입니다.  이런 것들을 서포터 입장에서 저는 적절한 사람이 온 것이라고 생각하지 않습니다.  이건 세상이 다 아는 거고요.  누가 어떻게, 원장님이 공보관 하셨을 때 알았는지 잘 모르겠습니다만 이런 것들이 한점 부끄러움이 없는 인사가 돼야만 도정이든 국정이든, 내일 모레면 대통령 선거합니다.  창피한 것은 탈당을 했다 돌아왔다 다시 갔다, 철새는 갔다 다시 오는 게 철새라고 해서, 진짜 철새가 많이 생기는 것 같아요.  이제 자그마한 인사에서도 철저하고 원칙과 명분이 있는, 상식과 법이 통하는 그런 인사가 이루어졌으면 좋겠습니다.  그것은 답변은 필요없고요.  과장님, 여기 월급기준일이 며칠입니까?
</p>
<p><b>○ 행정지원과장 김영수 </b> 20일입니다.  
</p>
<p><b>○ 이효선 위원 </b> 14일에 임용된 김 처장이 20일에 월급을 타는데 259만원을 받았습니다.  인사규정에 맞습니까?  저도 월급쟁이입니다.  보통 월급은 16일부터 익월 15일까지 아니면 1일부터 29일 기준이 있습니다.  일주일 근무하고 259만원을 지급해도 됩니까? 
</p>
<p><b>○ 행정지원과장 김영수 </b> 그것은 이렇습니다.  제가 아까 말씀드린 봉급기준 지급일은 20일이고 봉급을 지급한 기준은 말일입니다.  향후 말일까지 근무할 것을 봐 가지고 계산한 것입니다.
</p>
<p><b>○ 이효선 위원 </b> 이상입니다.  저는 목이 아파서 하루에 10분이상 말을 하면 안 되는데 질의하는 이유는 경기개발연구원이 어떤 정파나 도지사의 문제가 아니라 본연의 자세로 일천만 도민을 위한 연구가 현장에서 묻어 나와 최고의 연구기관으로 남고 그것에 하자가 있으면 안되겠기에 몇 가지 질의를 한 겁니다.  이상입니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 그러면 효율적인 감사진행을 위해서 5분만 정회를 하겠습니다. 
</p>
<p class=''ar''>(12시05분 감사중지)
</p>
<p class=''ar''>(12시20분 감사계속)
</p>
<p><b>○ 위원장대리 이원재 </b> 좌석을 정돈해 주시기 바랍니다.  감사를 계속하겠습니다.  위원님들 질의해 주시기 바랍니다.  나경숙 위원 질의해 주시기 바랍니다.
</p>
<p><b>○ 나경숙 위원 </b> 나경숙 위원입니다.  오전 처음에 위탁연구 추진관련 28.7%에 대해서 그것을 설명을 드렸었는데 아까 그 퍼센티지가 어디서 나왔느냐고 물으셔서 2002년도 연구과제는 25건으로 되어 있거든요.  올해 경기개발연구원의 기본과제 추진실적에 보면 31건, 수탁과제가 27건, 정책과제가 29건, 총 87건으로 그것을 제가 비교해서 28.7%로 말씀드렸는데요.  원장님의 설명인 수탁과제는 별도로 계산하신다는 얘기는 제가 이해가 갔고요.  그것을 아까 말씀드리면서 위탁연구기준에 보면 연구예산을 비교해 봐도 올해 연구부 운영예산이 31억원인데 위탁연구비가 13억 6,000만원이 들어갔거든요.  그래서 연구부 운영예산의 44%에 이르는 연구사업비가 위탁연구비로 지출되고 있는 것으로 알고 있어요.  그래서 본 위원은 연구원에서 사실은 또 다른 데다가 위탁연구를 너무 많이 주는 게 아닌가 김준회 위원님도 같은 말씀주셨지만 28.7%는 거기서 나온 거고요.  쉽게 말하면 연구부에서 다른 복덕방으로 넘겨주는, 말에 어패가 있을지 모르지만 그런 이미지로 보이거든요.  될 수 있으면 충원을 많이 하셔서 위탁사업을 줄였으면 해서 아까 말씀에 마무리 드립니다.  이상입니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 다음 질의하실 위원님, 김대원 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김대원 위원 </b> 김대원 위원입니다.  처음부터 위탁연구가 도마 위에 올라서 말이 되는데 이게 제가 요구한 자료입니다.  이 부분에 대해서 간단하게 짚고 넘어가겠습니다.  제가 요구한 자료에 의하면 연구과제, 위탁사유, 위탁기관, 추진현황, 계획 이렇게 자료를 요구했습니다.  그런데 한 가지만 묻겠습니다.  위탁기관을 선정하실 때 어떤 기준을 가지고 선정하시는지 간단하게 답변해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 우선은 연구과제와 직접적인 연관관계가 있는 대학이나 연구기관, 연구과제를 수행하기에 적절하다고 판단되는 대학이나 연구기관을 선정합니다. 
</p>
<p><b>○ 김대원 위원 </b> 선정을 하실 때 특별한 기준이나 위원회가 있는 것은 아니예요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그것은 과제선정용역사업심의위원회에서 결정합니다. 
</p>
<p><b>○ 김대원 위원 </b> 경기개발연구원 자체에 용역사업심의위원회라는 부분이 있습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네, 있습니다.
</p>
<p><b>○ 김대원 위원 </b> 그 부분은 어떤 분들로 구성돼 있는지요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 내부박사들로 구성돼 있습니다. 
</p>
<p><b>○ 김대원 위원 </b> 사안별로 구성을 하시는지 아니면 상설화 되어 있는 건지요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 상설화 되어 있습니다.  
</p>
<p><b>○ 김대원 위원 </b> 상설화돼 있으시면 나중에 심의건수와 실적사항 이런 부분을 자료로 제출해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네, 알겠습니다. 
</p>
<p><b>○ 김대원 위원 </b> 한 가지만 더 질의하겠습니다.  삼성 에버랜드에 외국인전용 골프장 타당성 평가를 위한 개발계획평가 및 타당성 분석을 에버랜드에서 줬어요.  완료된 사항인데 이런 부분이 상당히 애매해요.  왜 이런 부분을 지적하냐면 지금 말씀하신 사항이라면 삼성에버랜드 경우는 자기들이 수익을 위한, 사실상 수익단체거든요.  수익단체에서 용역을 줬을 경우에는 학술적으로 과연 결과가 타당성이 있는 것인지, 객관성이 있는 것인지 그런 부분에 의심의 소지가 충분히 있는 부분도 있거든요.  위원회가 상설화돼 있다고 그러지만 위탁기관을 선정할 때 사안별로 선정하셔서 내부 전문가적인 분들이 전문적으로 제일 잘 알 것이니까, 그런 부분으로 상설화돼 있지 않더라도 전문가에게 전문부분에 대해서 자문을 구해서 위탁기관을 선정하시는 그런 부분이 필요하지 않을까 생각합니다.  이상입니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 알겠습니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 감사위원님들께서 질의하실 때는 여러 실무담당들께서 파악하고 계시다가 원장님이 모르시면 답변을 해서 감사의 진행이 원활히 될 수 있도록 협조해 주시기 바랍니다.  위원님들께서 질의하실 게 있으시면 질의를 하고 말씀하실 게 없으시면 감사를 종결하고 더 하려면 중지를 하려고 합니다. 
</p>
<p><b>○ 김대원 위원 </b> 원활한 감사를 위해서 잠깐 정회를 요구합니다. 
</p>
<p><b>○ 위원장대리 이원재 </b> 그러면 잠깐 정회를 하겠습니다. 
</p>
<p class=''ar''>(12시29분 감사중지)
</p>
<p class=''ar''>(12시30분 감사계속)
</p>
<p><b>○ 위원장대리 이원재 </b> 자리를 정돈해 주시기 바랍니다.  감사를 중지하고 중식 후에 계속해서 감사를 진행하고자 하는데 여러 위원님들 의견은 어떠신지요?  
</p>
<p style="padding-left:2.4em">    (「좋습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 중식을 위해서 14시까지 감사를 중지하겠습니다. 
</p>
<p class=''ar''>(12시31분 감사중지)
</p>
<p class=''ar''>(14시12분 감사계속)
</p>
<p style="padding-left:2.4em">    (이원재 위원장대리, 나경숙 간사와 사회교대)
</p>
<p><b>○ 위원장대리 나경숙 </b> 좌석을 정돈해 주시기 바랍니다.  감사를 계속 하겠습니다.  계속해서 감사질의·답변을 진행토록 하겠습니다.  그러면 질의하실 위원님 거수로 신청해 주시기 바랍니다.  김영복 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김영복 위원 </b> 김영복 위원입니다.  몇 가지 궁금한 사항이 있기 때문에 먼저 질의한 것에 대한 보충질의를 드리겠습니다.  행정감사자료 191쪽에 보면 위탁연구 추진현황이 나오는데 2002년도 위탁에서 일반회계 12건에 대해서 4억 3,740만원, 특별회계 13건에 대해서 8억 2,835만 6,000원에 대한 계약금액이 나오는데 일반회계와 특별회계의 위탁관계에서 나누는 기준이 무엇인지 아시는 대로 답변 부탁드리겠습니다.  아시는 분에게 답변을 부탁드립니다. 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기획조정실장 이상훈입니다.  일반회계 부분은 경기개발연구원 예산에서 위탁이 나간 부분이고, 특별회계 부분은 저희들이 수탁을 체결할 때 발주처에서 이러이러한 부분은 이 기관을 포함해서 연구를 해줬으면 좋겠다 하는 요청이 있을 수도 있고 또 연구용역이 저희는 학술용역 중심으로 추진하는데 경우에 따라서는 설계를 한다든지 기술부분이 있습니다.  구체적으로 그런 내용이 있을 때 저희들이 수탁을 받아서 재위탁 나가는 부분이 특별회계 부분에 해당되겠습니다.  이상입니다.
</p>
<p><b>○ 김영복 위원 </b> 본 위원이 왜 질의드리냐 하면 행정감사자료에는 나타나지 않고 있습니다.  과제라든가 거의 똑같은, 어떤 기준을 정하지 않고 아까 말씀하신 대로, 요구했는데 행정감사자료가 없었기 때문에 질의드린 거고요.  그렇다면 행정감사자료 351쪽에 연구원 용역비 수입현황이 나오거든요.  현황을 보면 2001년도 총 과제 29건의 용역 중에서 계약용역이 25억 2,402만 3,000원이고 전출금은 4억 3,771만 3,000원이고, 2002년도 총 과제 중 27건의 연구용역을 줬는데 연구계약이 26억 7,191만 9,000원인데 전출금은 4억 315만 9,000원이거든요.  이렇게 전출되었는데 일단 두 가지 측면을 말씀드리면 계약금액과 전출금이 차이나는 게 나머지 기본적으로 소요되는 경비를 빼고 이익금에서 전출금이 된 것인지 하는 부분과 전출금이 가면 이 돈을 특별회계로 활용하는지 일반회계로 활용하는지, 활용하는 비율이 어떤지 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 제가 답변드리겠습니다.  우선 이 부분은 수탁연구과제로 해서 분석을 한 현황입니다.  수탁연구과제를 받으면 저희들은 과제만 받는 게 아니라 예산도 같이 받습니다.  그리고 예산을 받으면 그 중에 30% 정도를 전출금으로 공제하게 됩니다.  그런데 어떤 경우에는 30%를 공제하는 경우도 있고 수탁계약 금액이 적을 때는 20%를 공제하는 경우도 있습니다.  그러니까 2001년도 경우에는 계약금액이 적은 데도 불구하고 전출금이 많고 2002년도 경우에는 계약금액이 많음에도 불구하고 전출금이 적은 상황이 생길 수가 있습니다.  그렇게 이해를 해주시면 되고요.
</p>
<p style="padding-left:1.2em">  왜 어떤 것은 일반회계로 들어가고 어떤 것은 특별회계로 들어가느냐고 지적을 해주셨는데 일단 수탁용역을 받은 것은 다 특별회계로 처리합니다.  191쪽에서 지적하신 위탁용도라는 것은 어떤 것은 수탁을 받은 것 중에서 위탁이 나가는 경우가 있고 어떤 것은 우리 스스로 위탁을 하는 경우가 있습니다.  우리 스스로 위탁하는 경우에는 일반회계에서 위탁하는 것입니다.  그리고 수탁을 받은 과제 중에서 우리가 일부를 떼어서 수탁을 하는 게 있습니다.  그것은 특별회계로 됩니다. 
</p>
<p><b>○ 김영복 위원 </b> 본 위원이 보니까 191쪽에는 위탁기관에 대해서 나오는데 특별회계로 구별이 안되어 있지 않습니까?  그래서 질의드린 겁니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그런 것은 수탁과제를 가지고 위탁한 케이스입니다. 
</p>
<p><b>○ 김영복 위원 </b> 일반회계, 특별회계 된 것만 구분되어 있지 행정감사자료에는 구분이 안되어 있는 거지요.  그래서 질의드렸으니까 앞으로 자료 낼 때 참고해 주시고요.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 알겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 좀전에 본 위원이 351쪽에 연구비 용역 수입현황 질의드렸던 것에 대한 답변 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 제가 답변드린 것 같은데 계약금액과 전출금액이 왜 2001년과 2002년도에 차이나냐는 말씀 아니십니까? 
</p>
<p><b>○ 김영복 위원 </b> 아니, 그게 아니고 용역별로 계약받은 금액이 전체, 아까 금액을 말씀드렸지 않습니까?  그런데 전출금은 적잖아요.  그렇다면 차이금액이 연구하는 필수경비를 제외하고 나머지 남은 게 전출금으로 해서 특별회계로 가는지…….
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 일단 이렇게 이해하시면 되겠습니다.  수탁을 저희들이 받으면 우선적으로 전출금을 뗍니다.  오버헤드라고 하는데 도에서 만약에 1억원의 수탁과제를 저희들한테 발주하면 3,000만원을 전출금으로 우선적으로 떼어서 특별회계에 수입으로 잡습니다.  그리고 나머지 7,000만원만 가지고 연구를 하게 됩니다. 
</p>
<p><b>○ 김영복 위원 </b> 그 기준이 어디에 근거해서 몇 % 떼는지 말씀해 주세요.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 자체 수탁과제 용역사업 심의규정에 나와 있습니다. 
</p>
<p><b>○ 김영복 위원 </b> 전출금이 특별회계로 넘어가면 계속 특별회계 관리가 되나요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그 동안에 기금관리한 실적을 보시면 17억원 정도를 자체기금으로 적립한 게 있는데 이런 수입을 가지고 기금을 늘려나가고 있는 것입니다.
</p>
<p><b>○ 김영복 위원 </b> 본 위원이 대안을 드리는데 앞으로 자체전출금, 수익금 배분율을 조정해서 경기개발연구원이 안정적인 관리가 될 수 있도록 기금확보가 필요할 때는 조금 더 높여서, 지금 IMF 이후 은행금리가 낮아서 마이너스 효과도 있겠지만 경기개발연구원이 안정적으로 가려면 기금확보가 충분히 돼서 자체적으로 운영될 수 있을 때 좋은 것 아닙니까?  본 위원은 그런 것이 조정이 가능하고 큰 문제가 없다면 비율을 조정해서 특별회계 관리가 될 수 있도록 안정적인 운영에 대안을 드리고 싶은데 조금 이따 말씀해 주시고요.
</p>
<p style="padding-left:1.2em">  여기 위탁연구에 관해서 행정감사는 아니고 감사받은 실적이 있을 겁니다.  본 위원이 보니까 위탁연구에서 연구비 성과에 따라서 성과급 지급한 게 잘못돼서 지적된 사항이 있는데 지금은 그렇게 안하고 있는지 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 우선 기금확보 방안에 대해서 김 위원님 걱정해 주신 데 대해서 감사의 말씀을 드립니다.  연구원의 지속적이고 안정적인 발전을 위해서 충분한 규모의 기금을 확보하고 있다면 그것처럼 바람직한 것은 없다고 생각합니다.  그러나 그 동안 경기도나 시·군 또는 은행에서 예산상 어려움에도 불구하고 많이 출연해 주신 데 대해서 기금적립을 했는데 이뤄내서 기금출연을 부탁드리는 것은 저희들로서는 요구할 수 있는 자세가 아니라고 생각합니다.  물론 예산을 관장하고 있는 부서에서 그런 필요성을 판단해서 기금을 출연한다고 하면 고맙게 받을 용의는 있습니다.  다만 기금을 늘린다 하더라도 금리가 하도 저금리이기 때문에 기금 가지고는 독자적으로 연구원을 운영해 나간다는 것이 쉬운 일은 아닙니다.  그래서 기금만이 능사이냐, 아니면 보조금과 같이 병행해서 나가는 것이 바람직하냐는 것은 논자에 따라서 생각이 다를 수도 있다고 봅니다.  저희들로서는 기금에 의한 안정적인 성장과 보조금에 의한 도와 유대를 돈독히 하는, 양자가 병립해서 나가는 것도 연구원으로서는 바람직한 방향이라고 일단 생각하고 있고요.
</p>
<p style="padding-left:1.2em">  그리고 전출금을 증액해서 기금을 획기적으로 증액할 수 있는 방안을 강구할 수 없는 취지의 말씀은 앞으로 연구원의 브랜드 가치를 높여서 연구원을 통해서 나가는 연구가 굉장히 사회적으로도 인정받을 수 있다면 저희들이 충분히 전출금을 더 많이 계상하더라도 많은 희망위탁기관들이 나타날 것으로 생각합니다.  그러나 현재로서는 저희들이 30% 이상의 전출금을 확보하면서까지 수탁을 늘려나간다는 것은 아직까지 쉬운 일은 아닙니다.  어떤 일부기관에서 전출금 30% 떼는 것을 우려해서 다른 기관에 위탁주려는 경우도 있습니다.  그런 것은 앞으로 저희 연구원의 발전과 같이 병행해서 검토해 나가도록 하겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 본 위원이 아까 금액은 말씀드렸지만 지금 말씀하신 대로 30% 전출금을 뗀 것은 2001년도나 2002년도 금액으로 안 나타나고 그것보다 낮은 것으로 보는데 조금 전 질의에서도 경기도에서 나름대로 연구해야 될 부분 이외에 다른 데서 연구용역이 들어온 것으로도 연구원들이 일하는데 벅차서, 전문성이 떨어져서 다른 데 하는 게 없느냐는 질의를 드렸던 게 지금도 보면 그런 결과가 나오거든요.  연구 못한 것은 없는데 다른 시·군에서 용역을 개인용역 회사에 줘도 일반적인 이익금은 주거든요.  경기개발연구원은 사실 그런 게 없지 않느냐, 그게 어떻게 보면 이익금이 전출금으로 떨어질 수 있는 부분이 경영논리에서 있습니다.  저는 몇 % 보다는 그런 쪽에 나름대로 연구에 대한 실적이 쌓이면 경기개발연구원이 인정을 받지 않겠습니까?  앞으로 그런 금액이 나오는 전출금을 특별회계 관리할 수 있도록, 안정적인 연구활동이 되도록 그런 쪽으로 방향을 돌리면 어떠냐는 것인데 잘못 해석하신 것 같아요.  그런 의향이 없으신 지와 연구원들 성과급 지급하는 기준배분에 있어서 수탁용역 실적까지 감사에 지적된 사항이 있습니다.  알고 계십니까?  이철규 원장님이 나중에 오셔서 잘 모르시나 본데 그런 사항이 지금은 그렇지 않고 있는지 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 수탁연구는 이미 예산지원을 받아서 연구하고 위탁한 기관에 납품하는 것이 우선적인 임무이기 때문에 수탁과제에 대해서는 연구장려금을 평가도 하지 아니하고 지급하지 않는 것이 원칙인데 지난번에 그런 잘못을 저질렀기 때문에 지적받은 적이 있습니다만 일시적인 현상이었고 지금은 그런 사례가 있을 수 없습니다.
</p>
<p style="padding-left:1.2em">  그리고 참고로 하나 부가해서 말씀드릴 것은 저희들이 전출금을 전에는 20%밖에 안 떼다가 30%까지 떼고 있습니다.  그것만 하더라도 연구원의 브랜드 가치가 높아졌다고 생각합니다.  그러나 외국 같은 경우는 전출금을 50%까지 떼는 사례들이 얼마든지 있습니다.  저희 연구기관이 앞으로 브랜드 가치를 높여갈 수 있다면 전출금은 계속 높여갈 수 있는 소지가 있습니다. 
</p>
<p><b>○ 김영복 위원 </b> KRI의 장기비전에 대한 목표가 사실 그런 게 아닙니까?  경기도뿐만 아니라 우리나라를 선도해 나가는 싱크탱크라고 제가 아까 말씀드렸는데 이런 게 갖춰지면 충분히 가능하리라 봅니다.  저는 장기비전에 대한 앞으로 경기개발연구원의 창의성이라든가 연구진들을 믿고 있거든요.  앞으로 얼마든지 좋아질 수 있다는 비전도 갖고요.  그래서 질의를 드리는 것이니까 연구과제를 너무 많이 하는 것보다 적정하게 해서 질적으로 봤을 때 더 효과가 크지 않느냐는 대안을 제시하면서 앞으로 전체적인 검토를 하셔서 반영이 가능하면 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 감사합니다. 
</p>
<p><b>○ 김영복 위원 </b> 거기에 따라서 한 가지 질의드리면 조금 전에도 성과급 지급현황에 대해서 언급을 했습니다만 사실 다 뛰어나신 연구원분들이신데 여기 성과급 지급에 어떤 기준을 나름대로 정해서 평가하고 있는데 연구실적, 연구수행능력, 연구수행태도라든가 이런 것을 종합평가해서 근무성적표의 90%를 반영하고 기관단체장이 평가해서 10%가 반영되고 있지 않습니까?  사실 연구원분들이 이런 것을 평가받을 때 제가 알기로는 관계공무원도 그렇지만 받는 자체가 뭐라고 할까, 나름대로 그렇게 좋게 느껴지지는 않을 것 같습니다.  그런데 어차피 기준을 정해서 운영하고 있는데 이런 데서 원장님이 느끼는 문제점이라든가 앞으로 더 발전되게끔 나갈 수 있는 방향이 있으면 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 위원님 매우 중요한 문제를 지적해 주셨습니다.  사실 평가는 하는 사람이나 받는 사람이나 기피종목입니다.  그렇지만 조직의 경쟁력이라든지 조직을 발전시키기 위해서 경쟁체제로 돌입하는 것은 불가피한 선택이라고 봅니다.  사회가 모두 시장경제원리라든지 경쟁원리에 의해서 이기는 자만이 살아남을 수 있는 정도로 경쟁이 치열해 지고 있기 때문에 우리 연구원도 경쟁원리가 도입되는 것은 불가피한 상황이라고 볼 수밖에 없습니다.  다만 중요한 것은 경쟁을 하기 위해서는 평가가 선결과제인데 평가가 과연 공정하냐, 모두가 납득할 수 있는 평가를 하고 있냐가 핵심입니다.  저는 KRI에 온 지 얼마 되지 않았습니다만 제가 우선적으로 지적하고 싶은 것은 위원님 모두가 말씀하셨지만 양 위주의 평가를 너무 지나치게 강조해 왔습니다.  이번에 비전팀이 발족돼서 평가제도까지 같이 검토하고 있습니다만 이것을 보다 객관적이고 공정한 평가제도로 바꿀 필요가 있는 것이 아니냐 생각해서 중요한 연구과제로 채택해서 연구하고 있습니다.  앞으로 평가를 하는 사람이나 평가를 받는 사람이나 모두가 공감할 수 있는 평가시스템을 구축하는데 최선을 다하겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 본 위원도 나름대로 대안을 가지고 질의드리는 것인데 여기에서 하나 더 질의드리고 말씀드리겠습니다.  여기서 10%에 반영되는 평가결과에 대해서 평가하는 분들이 누구인지 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 기관장은 원장입니다. 
</p>
<p><b>○ 김영복 위원 </b> 제가 원장을 무시하는 게 아니라 아까도 원장님이 양 위주, 질적평가라든가 평가기준의 방향을 말씀하셨습니다.  본 위원은 연구하시는 분들이 거의 박사님이신데 나름대로 객관적이고 주관적인 자기의 관점으로 연구를 했는데 이런 것을 가지고 남이 평가하고 그래도 어떤 게 나오겠습니다만 어떤 기준을 앞으로 발전적인 쪽으로 정립해 나갈 필요성이 있지 않느냐, 총괄적으로 연구하셔서 연구하는 분들의 사기가 저하되지 않게끔 할 수 있는 기회부여를 해주시기 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 감사합니다. 
</p>
<p><b>○ 김영복 위원 </b> 마지막으로 이것은 질의가 아니고 기획위원회에 속해 있는 경기개발연구원 연구하시는 분들에 대한 한 가지 참고사항으로 들으려는 질의를 한번 드리겠습니다.  원장님한테 질의드리는 게 아니라 누가 답변하실까요?  기획조정실장님, 연구하시는 분 중에서 애로사항이 있으면 간략하게 말씀해 주시기 바랍니다.  저희가 참고하고 도에서 반영해서 도와드릴 것이 있으면 있는 그대로 말씀해 주시기 바랍니다.  아니면 다른 분, 하실 수 있는 분이 말씀해 주시기 바랍니다.
</p>
<p><b>○ 위원장대리 나경숙 </b> 평소에 속으로 참고 계셨던 분이 말씀하시지요.
</p>
<p><b>○ 김영복 위원 </b> 허심탄회하게 말씀해 주시지요.  연구원분 중에서 말씀해 주세요.  애로사항이라든가…….
</p>
<p><b>○ 위원장대리 나경숙 </b> 서로 미루시니까 실장님이 하십시오.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기획조정실장 이상훈입니다.  위원님들께서 많이 지적해 주셨는데 저희들이 연구하다 보면 연구원 수는 한정되어 있고 과제 수행할 내용도 한정되어 있는데 역시 과제 수가 많아지면 전체적으로 부실해 지는 것은 저희들도 인정하고 있습니다만 그렇다고 자기 과제를 한다고 해서 수시로 경기도 관련된 사안들이 쏟아져 내려오는데 경기개발연구원에서는 모른 채 할 수도 없거든요.  이런 부분들에 사실 연구진들이 고민하는 부분이라 생각하고요.
</p>
<p style="padding-left:1.2em">  저희들이 고민하는 게 항상 실사구시를 하라고 하면서 동시에 연구원 개인적인 캐리어라든지 외부적으로 인정받는 부분은 꼭 그런 부분만은 아니고 저희는 정책대안을 제시해야 되는 입장에 있고 연구원들이 각자 자기의 능력을 발휘할 수 있는 부분은 이론적인 접근부분도 있고 항상 그런 부분에서 저희들은 갈등을 하고 있습니다.  이 문제는 어제오늘의 문제가 아니기 때문에 앞으로 저희들이 계속 고민해 가면서 해결해야 될 부분이라고 저는 봅니다. 
</p>
<p style="padding-left:1.2em">  그리고 경기개발연구원이 박사님들과 연구진들이 굉장히 바쁘게 일하고 있는데 아까 인력채용 문제도 말씀하셨지만 저희들이 요구하는 기준은 사실 일당백 식으로 일하기 때문에 그런 수준의 연구원을 요구하고 있고 단순히 어느 학교를 나왔고 어느 학력수준만은 아닙니다.  막상 지원하는 인력을 보면 그에 못 미치는 것 같은 것이 저희들 고민입니다.  겉으로는 국책연구원 이상 가는 연구를 수행해야 하는 연구진을 구성하고 모집해야 되는 입장에서는 그에 못 쫓아가고 지원이 미진할 수도 있어서 그런 부분은 항상 어렵게 생각하고 있습니다.  제 수준에서 이 정도로 보고드리겠습니다. 
</p>
<p><b>○ 김영복 위원 </b> 기회드릴 때 더 말씀하실 분 안 계신가요, 없으세요?  말씀하시기 어려운 것 같습니다.  잘 알겠습니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 제가 한 말씀 드리겠습니다.  연구원이 안고 있는 고민이 많이 있을 텐데 연구진들이 짧은 시간에 얘기하기 어려워서 안 하시는 것 같은데 제가 대신 해서라도 말씀드리고 싶습니다.  먼저 한 가지는 실장도 언뜻 말씀하셨지만 도, 도의회나 도민들은 보다 실용적인 연구가 이루어지기를 바랍니다.  반면에 여기 박사님들은 한 문제에 대해서 보다 깊숙이 연구하는 분들이기 때문에 비록 범위는 줬지만 심층적으로 연구하기를 바랍니다.  그러다 보니까 보다 학문적이고 기본적인 쪽의 연구가 되는 경향이 있습니다.  이것을 조화를 이루는 것이 하나의 고민거리입니다.  또 하나의 고민거리는 경기도가 요구하는 가치와 국가가 요구하는 가치가 상충될 경우가 생깁니다.  수도권문제 같은 것은 대표적인 케이스입니다.  이러한 경우에 경기도의 요구와 국가적인 요구를 어떻게 조화할 것인가, 지난번에 도지사께서 오셨을 때도 연구진들이 그런 문제는 제기했었던 문제입니다.
</p>
<p style="padding-left:1.2em">  그리고 이것은 저 혼자 미루어 생각해 보는 것인데 우리 연구진들은 나름대로 자부심을 가지고 KRI에 왔습니다.  그런데 신분이 굉장히 불안정한 상태입니다.  매년 신분계약을 해야 됩니다.  연구실적이 있고 경륜이 쌓였음에도 불구하고 매년 신분계약을 해야 한다는 것은 나름대로는 스트레스입니다.  이것은 연구실적에 따라서 연구경력에 따라서 계약기간을 연장해서 2년, 3년, 경우에 따라서는 교수직처럼 테뉴얼(tenure)을 인정한다든지 해서 안정적인 직장생활을 할 수 있도록 어느 정도 실적이 인정된 분에 한해서 그렇게 되겠습니다만 안정적인 직장분위기를 제공하는 것도 연구원이 풀어나가야 할 과제라고 생각합니다. 
</p>
<p><b>○ 김영복 위원 </b> 잘 들었습니다.  본 위원도 도정질문이든 어떤 것을 통해서 대안을 도출해 보겠습니다.  고생하시는 것에 대해서 격려드리고 이상 마치겠습니다. 
</p>
<p><b>○ 위원장대리 나경숙 </b> 김영복 위원님 수고하셨습니다.  다음 질의하실 위원님, 김학용 위원님 질의하시기 바랍니다. 
</p>
<p><b>○ 김학용 위원 </b> 김학용입니다.  이철규 원장님이 새로 부임해 오셔서 여러 가지로 일을 해보시려고 하는 느낌을 많이 받습니다.  좋은 결실이 맺어지기를 기원드리면서 중복을 피해서 간단하게 몇 가지만 여쭤보겠습니다.  사실 제가 질의하려고 적어놓은 것을 원장님이 조금 전에 그대로 말씀하시더라고요.  양적인 것보다도 질적인 위주로 평가시스템 확립에 대해서 말씀해 주셨고 답변이 미리 나왔기 때문에 생략을 합니다.  다만 제가 늘 가지고 있는 것이지만 자유경쟁체제에서 상당히 고민스러운 부분이 평가하는 부분이고 소위 성과급과 관련한 부분인데 분명한 것은 경각심을 주고 선의의 경쟁을 이끌어내기 위해서 불가피하게 필요한 것이 성과급제도라고 생각합니다.  이것이 평가를 받는 분들이 납득하고 인정받을 수 있도록 평가시스템을 재정비 하신다니까 기대하는 것으로 갈음하고요.  
</p>
<p style="padding-left:1.2em">  다음은 어떻게 보면 사소한 내용이 되겠습니다만 저같이 경기도내에서도 수부도시와 멀리 떨어져 있는 의원의 한 사람으로서 늘 관심을 갖고 있는 부분이 경기도에서 운영하는 것에 대해서 상당히 많은 부분이 수원을 중심으로 이루어지기 때문에 본의 아니게 소위 경기도의 외곽지역에 있는 시·군에서는 상대적인 박탈감 내지는 불만을 가지고 있습니다.  그것은 구구절절 예를 들지 않더라도 여러 가지 문화적인 측면이라든가 교육적인 측면, 다양한 측면에서 그럽니다.  사실 경기개발연구원은 시·군에서도 출자해서 만들어진 기관으로 알고 있는데 금년도에 각종 세미나나 워크숍 하는 것을 제가 자료를 받아봤습니다만 11회를 개최했는데 그 중에서 서해안포럼은 성격상 충남 안면도에 있는 모 호텔에서 한 것으로 되어 있는데 그것은 업무의 성격상 그렇고, 한번정도만 지역에서 한 것으로 나와 있는데 경기개발연구원에 대해서 아직까지도 도민들이 많은 부분을 제대로 이해 못하는 부분이 상당히 많습니다.  그래서 이런 세미나나 워크숍을 통해서 도민들에게 자연스럽게 홍보할 수 있는 기회를 갖기 위해서라도, 물론 여러 가지 애로사항이 있겠습니다만 지역을 순회하면서 세미나나 워크숍을 했으면 하는 생각을 가지고 있는데 원장님 생각은 어떠신 지 듣고 싶습니다.
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 김 위원님 말씀에 저도 전폭적으로 동감합니다.  수원은 도청소재지일 따름이지 경기도 전체를 전적으로 대표하는 도시일 수는 없습니다.  그러니까 경기개발연구원에서 이루어지는 일들이 불가피하게 수원을 중심으로 이루어지는 일이 있다 하더라도 앞으로 기회 닿는 대로 수원 외적인 장소에서 이루어질 수 있도록 조금 더 저희들이 신중하고 각별하게 검토해서 위원님의 뜻이 반영될 수 있도록 노력하겠습니다. 
</p>
<p><b>○ 김학용 위원 </b> 잘 알겠습니다.  다음은 좀전에 경기개발연구원의 고충에 대해서 말씀을 들었습니다.  상당부분은 공감을 하고 있습니다.  특히 연구원들 입장에서 봤을 때는 소위 학구적이고 학문적인 연구를 원하는 경향이 실제 있고 또 저희 의원이나 경기도에서 경기개발연구원을 바라보는 입장에서는 솔직히 실용적인 결과물들이 도출되기를 많이 바라고 있습니다.  그런 관점에서 제가 한 가지 평소 가지고 있는 생각을 말씀드리면 경기개발연구원에서 하는 일이 인력도 부족하고 여러 가지 열악한 여건이라고 말씀은 그렇게 하시면서도 실질적으로 자료를 보거나 하면 과다할 정도로 많은 각 분야의 연구과제사업들을, 연구조성사업을 수행하고 있습니다.  본의는 아니겠습니다만 과시적인 연구원의 활동이 혹시라도 질적으로 떨어지는 결과를 초래하는 것이 아닌지 하는 의구심을 가지고 있습니다.  연구과제와 관련해서 그렇고요.  
</p>
<p style="padding-left:1.2em">  또 하나 각종 자문위원회라든지 포럼을 운영하는 문제도 최근 들어서 의욕적으로 상당히 많이 늘리고 있는데 이것이 공연히 일만 벌이고 용두사미적인 성격이 되지 않을까 하는 우려의 생각을 갖습니다.  이와 관련해서 경기연구포럼이라고 현재 소위 연구자문기능을 하는 그런 단체가 구성돼 있는 것으로 알고 있는데 자료에 보면 운영실적이 극히 미비한 것으로 나와있습니다.  그리고 자문위원회 위원의 임기도 2년으로 돼있는데 임기가 언제까지인지 그리고 연구자문위원회 기능이라는 것은 어떻게 보면 필요하다고 일견 생각은 되는데 이것을 그야말로 경기개발연구원의 방향을 제시하고 제대로 된 자문기능을 하는 그런 위원회로 발전시키기 위한 복안이 있으시면 그 부분에 대한 답변을 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 김 위원님 지적하신 대로 연구자문위원회라든지 또는 연구자문위원회의 발족과 더불어서 같이 발족된 경기연구포럼이라든지 하는 것이 이름에 걸맞지 않게 운영되는 것을 저는 전적으로 인정합니다.  발족하는 것으로 만족했을 따름이지 큰 연구실적이 없습니다.  이런 점은 우리 연구원이 빠른 시일내에 고쳐나가야 될 과제라고 생각합니다.  이번에 KRI비전팀이 연구하는 과제 중에서도 이러한 불필요하고 형식적인, 과시적인 행태는 없었는가 이것도 분명히 짚고 넘어갈 것이고 그래서 정말 연구에 도움이 되는 그리고 실질적인 위원회라든지 포럼을 구성 또는 운영하도록 시정해 나가겠습니다.  참고로 이번에 저희들이 교육관계포럼과 남북교류협력관계포럼을 계획하고 있습니다.  이것은 저희들이 절실한 필요에 의해서 준비하고 있습니다.  경기도가 또는 경기도의회가 분명히 교육에 대해서 또는 남북관계에 대해서 관심을 가져야 되고 의사결정을 해야 됨에도 불구하고 법적으로 그런 권한이 없다는 것이 저희들로서는 굉장히 안타깝게 생각합니다.  그러나 그런 법적인 미비점이 있다고 해서 준비 안 해도 되는 것은 아니라고 생각합니다.  그러한 뒷받침을 저희 연구원에서 나름대로 하기 위해서라도 이번에 연구진을 확보하는 것까지는 어렵다 하더라도 일단 포럼을 발족시켜서 포럼이 정상적으로 발전되면 경우에 따라서는 상근 연구직의 임용으로까지 그렇게 발전시켜 나갈 생각을 가지고 있습니다.  그 동안에 잘못된 운영패턴에 대해서는 위원님 여러분께 심심한 사죄를 드리고 앞으로 새롭게 탄생하는 기구라든지 포럼에 대해서는 명실공히 제대로 기능을 발휘할 수 있도록 심혈을 다하겠습니다. 
</p>
<p><b>○ 김학용 위원 </b> 잘 알겠습니다.  교육정책포럼이나 남북교류협력포럼도 사실 현시기적으로 봤을 때 꼭 필요하고 적절한 과제라고 생각합니다.  용두사미가 되는 일이 없도록 제대로 운영이 됐으면 하고요.  특히 남북교류협력포럼은 원장님께서도 아시는 것처럼 남북교류협력기금이 2004년도까지 200억원으로 증액시키는 것으로 추진을 하고 있기 때문에 그것과 관련해서도 연구를 해주시기 바랍니다.  그리고 좀전에 제가 말씀드린 것처럼 제가 느끼는 것이 경기개발연구원이 그 동안에 물론 과정이겠습니다만 아직까지도 독자적인 정체성과 방향성 없이 휘둘려나가는 듯한 그런 느낌을 많이 받고 있는데 그런 측면에서도 이철규 원장님이 새로 부임을 해오셨고 여러 가지 행정에 대해서 능통하신 분이니까 경기개발연구원이 정체성과 방향성을 가지고 아까 말씀드린 것처럼 외부의 압력에 의해서 그저 많은 보고서만 양산하는데 치우치는 그런 기관이 아니고 실질적으로 우리 경기도에 보탬이 되는 그러한 기관으로 발전해 주시기를 부탁드리겠습니다.  
</p>
<p style="padding-left:1.2em">  한 가지만 더 여쭙겠습니다.  영어마을과 관련해서 정책토론회 운영사업이라고 해서 2,000만원을 집행한 것으로 나와 있는데요.  주관하신 주무연구원이 어느 분이십니까?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기조실입니다. 
</p>
<p><b>○ 김학용 위원 </b> 지금 우리가 영어마을 정책토론회를 통해서 심포지엄도 했고 토론회도 계속 갖고 있는 것으로 알고 있는데 경기개발연구원에서 주관해서 하는 것이 맞지요? 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 맞습니다. 
</p>
<p><b>○ 김학용 위원 </b> 우문일지 모르겠지만 현재까지 나온 결과가 뭡니까? 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 당초 영어마을토론회가 세 가지 유형으로 출발된 것은 위원님께서도 알고 계실 것 같고요.  그러다 보니까 이것은 저희들이 협약과제로 추진하고 있습니다.  협약과제라고 하면 일반수탁하고는 다르게 경기도내 주무부서에서 추진할 수도 있지만 전문성이 사실 부족하기 때문에 토론장 구성이라든지 앞으로 방향설정하는 부분이라든지 토론회 이후의 앞으로 그 다음 단계에서 우리가 뭘 추진할 것인가 하는 부분에 대해서 저희들이 협약과제로 해서 사실은 위탁관리형식으로 추진하는 부분입니다.  그래서 현재 28일에 한 차례 또 있습니다.  마지막 세 번째 토론회를 갖게 되고요.  세 번째까지 토론회가 개최된 이후에 저희들이 그 결과를 최종적으로 정리하고 앞으로 추진해야 할 사업에 대해서도 정리한 상태에서 도에 건의하고 다음사업을 추진할 예정입니다. 
</p>
<p><b>○ 김학용 위원 </b> 제가 왜 이 말씀을 드리느냐 하면 영어마을에 상당히 도민들이 관심을 많이 갖고 있고 참신한 아이디어로 받아들이는데도 불구하고 실행과정에서 이것이 제대로 뒷받침이 안되고 있는 그런 느낌을 많이 받습니다.  그리고 영어마을이라는 개념정리도 제대로 안돼 있는 것 같고 또 제대로 된 마스터플랜을 경기개발연구원에서 마련해서 그런 바탕 위에 그림을 그려나가야 하는데 어떻게 보면 기존에 하고 있는 학원이나 학교의 수준을 뛰어넘지 못하는 그런 정도로 상당히 많은 예산만 낭비하는 듯한 느낌을 받고 있어서 제가 걱정이 돼서 드리는 말씀인데 기왕 경기개발연구원에서 손을 댄 것이면 제대로 영어마을이 추진될 수 있게끔 심혈을 기울여 주시기를 부탁드리겠습니다.  
</p>
<p style="padding-left:1.2em">  그리고 시간이 많이 지났기 때문에 제가 경기개발연구원에서 보내주신 각종 자료와 관련해서 평상시 가지고 있던 생각인데 물론 연구원에서 봤을 때는 소위 연구의 성과라든가 이런 결과물들을 기록으로 남기는 것이 대단히 중요하다는 것을 모르는 바는 아니지만 어쩐지 너무 체계화돼 있지 못한 느낌을 받고 어떻게 보면 예산을 더 줄일 수 있지 않느냐는 생각을 가져보는데요.  예를 들어서 아주 간단한 것들은 굳이 우편을 통해서 보낼 것이 아니고 기존에 보내는 분들이 다 컴퓨터를 가지고 있는 분들이니까 e-메일을 통해서 활용하고 또 보관물 정도는 만들어 놓는다고 하지만 그런 것도 하나의 방법이고 그리고 유사한 연구지가 있습니다.  예를 들어서 "경기논단" 같은 것은 1년에 4번 발행한 거고 "경기연구"같은 것은 1년에 1번 발행하는 건데 이것도 사실 제가 내용을 봤습니다만 얼마든지 이 2권을 1권으로 만들어서 4권에 소화시킬 수 있을 거라는 생각이 들고 "경기도 경제지표"와 "경제동향과 전망" 같은 것도 잘만 아이디어를 내면 역시 하나로 해서 효율적으로 할 수 있을 것 같은 생각이 드는데 이 부분에 대해서는 관계되시는 분들이 효율적으로 발송하고 받아볼 수 있는 방법에 대해서 검토해 주셨으면 합니다.  이상입니다.
</p>
<p><b>○ 위원장대리 나경숙 </b> 김학용 위원님 수고하셨습니다.  김준회 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김준회 위원 </b> 저는 간단한 질의입니다.  여기 기구 및 인력을 보고 경기개발연구원 직원현황을 다 봤는데 현재 노춘희 님이 여기 계십니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 그만 두셨습니다. 
</p>
<p><b>○ 김준회 위원 </b> 그만 두셨어요, 언제 그만 두었지요?
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 지난 8월 13일자로 그만 두었습니다.  
</p>
<p><b>○ 김준회 위원 </b> 그 분은 여기 정식 관리직이 아니었습니까, 관리직이었습니까? 
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 상임고문으로 있었습니다. 
</p>
<p><b>○ 김준회 위원 </b> 여기 보니까 직원현황에 관리직인 것 같은데 지금 연봉이 제일 높은 수준으로 받고 계신 분인데 명단에 안 나와서 궁금해서 여쭤봤습니다.  그리고 현재 비정규직 52명에 대한 인적사항은 유인물에 안 나왔지요?  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 네, 안 나왔습니다. 
</p>
<p><b>○ 김준회 위원 </b> 일부 자료는 받았는데 기왕이면 생년월일까지 포함해서 자료를 주셨으면 좋겠습니다.  그리고 현재 전체 계신 분들의 평균연봉은 어느 정도나 됩니까?  지금 답변하기 곤란하시면 자료로 보내주시기 바랍니다.  제 질의는 이것으로 마치겠습니다. 
</p>
<p><b>○ 위원장대리 나경숙 </b> 김준회 위원님 수고하셨습니다.  또 보충질의 있으십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 오늘 4일째 감사를 하고 있는데 오늘 마지막으로 아쉬운 점, 안타까운 점을 말씀드립니다.  저희가 오늘 이 자료를 미리 받아봤는데 전에 한번 저희가 방문한 적이 있거든요.  그때 그대로 이번에 자료로 보내주셨고요.  그리고 저희가 감사자료를 보면 거의 제목만 있지 구체적인 자료가 첨부가 안돼 있습니다.  아까 이효선 위원께서 질의했듯이 번역료 같은 것도 구체적으로 인쇄면에 표시를 해주셨으면 여쭤보지 않아도 될 거고 17쪽에 보면 연구실적에 따른 성과급 지급현황을 봐도 연구직이 27명이 있는데 27명에 대한 평가등급이라든가 기준이라든가 이런 것에 대해서 기재가 없거든요.  사실 기획위원회는 연구원하고 같이 경기개발연구원을 위해서 도의회에서도 함께 하는 그런 기관이라고 생각하고 있어요.  그런데 저희가 판단했을 때에는 글쎄요, 박사님들이 많이 계셔서 그런지 모르지만 자료가 엄청 불충분하게 저희한테 제출하신 것 같고 그러다 보니까 본의 아니게 자꾸 질의아닌 질의를 드리게 되기 때문에 될 수 있으면 저희도 경기개발연구원을 위해서 함께 하는, 도에서도 특별히 기획위원회는 함께 하는 위원회라고 봐주시면 좋겠고요.  저희가 도와드릴 수 있는 대로 최대한 힘을 발휘해서 경기도에서도 힘을 쓸 것이고 또 경기개발연구원에서도 기획위원회 위원만큼이라도 개발원이 어떻게 돌아가느냐에 대해서 상세히 알 수 있도록 기회가 된다면 자주 상담도 할 수 있는 기회를 만드셔서 이해를 할 수 있도록 많이 도와주셨으면 좋겠고요.  다음부터는 충분한 이해가 갈 수 있도록 협조를 해주셨으면 감사하겠습니다. 
</p>
<p><b>○ 이효선 위원 </b> 보충질의보다 부탁의 말씀을 드리고 싶습니다.  민선에 들어오면서 경기개발연구원이 생기고 집행부가 누가 들어가냐에 따라서 경기개발연구원의 방향이 결정되는 것 같습니다.  여기 많은 브레인들이 계신데 독자적으로 경기도의 방향을 제시하고 집행부의 부탁이 아닌 먼저 독자적인 경기도 마인드 개발을 위한, 발전을 위한 프로젝트를 만들어 주시고요.  그것을 갖고 기획위원회 위원들과 같이 프리토킹의 좌담회를 가져서 우리가 거꾸로 집행부에다가 경기개발연구원과 기획위원회가 어떤 프로젝트를 만들어서 요구하는 새로운 방향을 만들었으면 좋겠습니다.  형식을 떠나서 점심때 컵라면 먹고도 좋으니까 연구하는 모습, 연구하는 위원회상, 그런 것들을 개발원과 기획위원회가 같이 합작으로 제시를 해 줬으면 하는 아쉬움을 부탁드리고 싶습니다.  이상입니다.  
</p>
<p><b>○ 위원장대리 나경숙 </b> 이효선 위원님 수고하셨습니다.  마지막으로 원장님 하실 말씀 있으면 하시지요.  
</p>
<p><b>○ 경기개발연구원장 이철규 </b> 원장입니다.  장시간 저희 KRI의 발전을 위해서 정말 많은 지도와 편달을 해주신 도의원 여러분들께 진심으로 감사의 말씀을 드립니다.  오늘 지적하신 그리고 질의해 주신 많은 문제점들에 대해서는 저희들이 하나 하나 대책도 강구하고 또 시정도 하고 그렇게 하면서 우리 연구원의 질적 수준을 한 단계 높이는 그런 계기로 삼아나가고자 합니다.  앞으로도 위원장님 말씀하신 대로 공적이든 사적이든 간에 기획위원 여러분과 수시로 접촉하고 그리고 허심탄회한 토론을 진행시켜 나감으로써 의회 위원 여러분들의 관심사항도 저희들이 충족시키고 저희가 도나 도의회에 대한 요망사항들도 위원 여러분들을 통해서 충족시켜 나가는 그러한 시스템을 견지해 나가도록 노력하겠습니다.  장시간 감사합니다. 
</p>
<p><b>○ 위원장대리 나경숙 </b> 원장님 수고하셨습니다.  위원님들 더 질의사항 없으십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원이 안 계시면 이상으로 경기개발연구원에 대한 질의와 답변을 모두 마치겠습니다.  위원 여러분 그리고 경기개발연구원장을 비롯한 임·직원 여러분!  장시간 열의를 갖고 감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료준비와 위원님들의 질의에 성실히 답변해 주신 이철규 연구원장을 비롯한 연구원 관계자 여러분에게 감사를 드리며 오늘 여러 위원님들께서 감사시에 지적해 주신 사항은 도민의 뜻이니 만큼 이를 겸허히 받아들여서 연구원 업무에 적극 반영될 수 있도록 연구원에서는 최선의 노력을 다해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 연구원 임·직원 여러분!  수고하셨습니다.  그러면 이상으로 경기개발연구원에 대한 2002년도 행정사무감사 종료를 선언합니다.
</p>
<p class=''ar''>(15시07분 감사종료)
</p>
<p><hr /></p>
